1	// Cyrus Texture Studio: how painted pixels are stored (R1b). Pure + client-safe.
2	//
3	// PERSISTENCE DECISION. A studio texture is a TextureDoc: the locked generated BASE (an ordinary DSL TextureSpec,
4	// bounded by MAX_OPS = 400) plus an optional sparse PAINT LAYER on top. Painting never turns into DSL ops, so the
5	// 400-op limit never applies to strokes: a 64x64 texture can have every pixel painted (4096 entries) and the spec
6	// keeps its own ops. The paint layer is stored WITH the asset (CyrusProjectAsset provenance, mime TEXTURE_DOC_MIME)
7	// and composited everywhere the pixels matter: the studio canvas, the quality checks, the pack builder
8	// (lib/cyrus/textures/pack.ts accepts a doc) and the PNG. Composite = render(spec), then each painted pixel replaces
9	// the base pixel (always fully opaque) and each "clear" pixel erases it to alpha 0.
10	//   colors: up to 256 distinct "#rrggbb" (paint is opaque only: the quality bar forbids semi-transparency)
11	//   set:    flat [pixelIndex, colorIndex, ...] sorted by pixel index, pixelIndex = y * size + x
12	//   clear:  sorted pixel indices the paint layer erases from the base
13	// A doc with spec null is all paint (an upload used in a project): its base is transparent.
14	import { checkSpec, SKIN_TEXTURE_SIZES, TEXTURE_SIZES, type TextureSpec } from "../textures/dsl";
15	import { render, type Raster } from "../textures/render";
16	import { textureQuality, type QualityReport } from "../textures/quality";
17	
18	/** Item/block sizes plus the creature skin sheet sizes (a skin spec can reach the studio; editing skins is "coming soon" in the UI, but the types must hold). */
19	export type TextureSize = (typeof TEXTURE_SIZES)[number] | (typeof SKIN_TEXTURE_SIZES)[number];
20	export type PaintLayer = { size: TextureSize; colors: string[]; set: number[]; clear: number[] };
21	/** What a doc decided about a Cyrus candidate (kept in history; the pixels are the doc's own). */
22	export type DocDecision = { candidate: string; accepted: boolean };
23	export type TextureDoc = {
24	  v: 1;
25	  name: string;
26	  size: TextureSize;
27	  /** the locked base; null = no base (all paint) */
28	  spec: TextureSpec | null;
29	  paint: PaintLayer | null;
30	  /**
31	   * sha256 (canonical JSON) of generated / candidate SPECS this doc was derived from or rejected. A later build that
32	   * returns one of them unchanged keeps this doc (lib/cyrus/assets/sync.ts studioDocFor), so studio edits survive
33	   * unrelated change builds.
34	   */
35	  supersedes?: string[];
36	  decision?: DocDecision;
37	  /** quality profile: item (default) or a tile (block faces, swatches; lib/cyrus/textures/quality.ts) */
38	  tile?: { tileable: boolean; framed: boolean };
39	};
40	
41	export const TEXTURE_DOC_MIME = "application/vnd.nxeon.texture-doc+json";
42	export const MAX_PAINT_COLORS = 256;
43	export const MAX_SUPERSEDES = 32;
44	const NAME = /^[a-z][a-z0-9_]{1,31}$/;
45	const HEX = /^#[0-9a-f]{6}$/;
46	const SHA = /^[0-9a-f]{64}$/;
47	
48	const int = (v: unknown, lo: number, hi: number): v is number => typeof v === "number" && Number.isInteger(v) && v >= lo && v <= hi;
49	
50	export type DocCheck = { ok: true; doc: TextureDoc } | { ok: false; error: string };
51	
52	export function checkPaint(raw: unknown, size: TextureSize): { ok: true; paint: PaintLayer } | { ok: false; error: string } {
53	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: "paint must be an object" };
54	  const r = raw as Record<string, unknown>;
55	  if (r.size !== size) return { ok: false, error: "paint size must match the texture size" };
56	  if (!Array.isArray(r.colors) || r.colors.length > MAX_PAINT_COLORS) return { ok: false, error: `paint needs at most ${MAX_PAINT_COLORS} colours` };
57	  const colors: string[] = [];
58	  for (const c of r.colors) { if (typeof c !== "string" || !HEX.test(c.toLowerCase())) return { ok: false, error: "paint colours must be #rrggbb" }; colors.push(c.toLowerCase()); }
59	  const n = size * size;
60	  if (!Array.isArray(r.set) || r.set.length % 2 !== 0 || r.set.length > n * 2) return { ok: false, error: "paint.set must be [pixel, colour] pairs" };
61	  if (!Array.isArray(r.clear) || r.clear.length > n) return { ok: false, error: "paint.clear must be a list of pixels" };
62	  const seen = new Uint8Array(n);
63	  let last = -1;
64	  const set: number[] = [];
65	  for (let k = 0; k < r.set.length; k += 2) {
66	    const i = r.set[k], c = r.set[k + 1];
67	    if (!int(i, 0, n - 1) || !int(c, 0, colors.length - 1)) return { ok: false, error: "paint.set has a pixel or colour out of range" };
68	    if (i <= last) return { ok: false, error: "paint.set must be sorted by pixel, each pixel once" };
69	    last = i; seen[i] = 1; set.push(i, c);
70	  }
71	  last = -1;
72	  const clear: number[] = [];
73	  for (const i of r.clear) {
74	    if (!int(i, 0, n - 1)) return { ok: false, error: "paint.clear has a pixel out of range" };
75	    if (i <= last) return { ok: false, error: "paint.clear must be sorted, each pixel once" };
76	    if (seen[i]) return { ok: false, error: "a pixel cannot be both painted and cleared" };
77	    last = i; clear.push(i);
78	  }
79	  return { ok: true, paint: { size, colors, set, clear } };
80	}
81	
82	/** Validate an untrusted doc (the API runs this on every save). */
83	export function checkDoc(raw: unknown): DocCheck {
84	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return { ok: false, error: "texture doc must be an object" };
85	  const r = raw as Record<string, unknown>;
86	  for (const k of Object.keys(r)) if (!["v", "name", "size", "spec", "paint", "supersedes", "decision", "tile"].includes(k)) return { ok: false, error: `unknown field ${k}` };
87	  if (r.v !== 1) return { ok: false, error: "texture doc version must be 1" };
88	  if (typeof r.name !== "string" || !NAME.test(r.name)) return { ok: false, error: "name must be lowercase letters, digits and underscores (2-32 chars)" };
89	  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size as number)) return { ok: false, error: "size must be 16, 32 or 64" };
90	  const size = r.size as TextureSize;
91	  let spec: TextureSpec | null = null;
92	  if (r.spec !== null && r.spec !== undefined) {
93	    const c = checkSpec(r.spec);
94	    if (!c.ok) return { ok: false, error: `base: ${c.error}` };
95	    if (c.spec.size !== size) return { ok: false, error: "the base spec size must match the doc size" };
96	    spec = { ...c.spec, name: r.name };
97	  }
98	  let paint: PaintLayer | null = null;
99	  if (r.paint !== null && r.paint !== undefined) {
100	    const p = checkPaint(r.paint, size);
101	    if (!p.ok) return p;
102	    paint = p.paint.set.length || p.paint.clear.length ? p.paint : null;
103	  }
104	  if (!spec && !paint) return { ok: false, error: "a texture needs a base spec or painted pixels" };
105	  const doc: TextureDoc = { v: 1, name: r.name, size, spec, paint };
106	  if (r.supersedes !== undefined) {
107	    if (!Array.isArray(r.supersedes) || r.supersedes.length > MAX_SUPERSEDES || !r.supersedes.every((s) => typeof s === "string" && SHA.test(s))) return { ok: false, error: "supersedes must be up to 32 sha256 values" };
108	    if (r.supersedes.length) doc.supersedes = [...new Set(r.supersedes as string[])].sort();
109	  }
110	  if (r.decision !== undefined) {
111	    const d = r.decision as Record<string, unknown> | null;
112	    if (!d || typeof d.candidate !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(d.candidate) || typeof d.accepted !== "boolean") return { ok: false, error: "decision must be { candidate, accepted }" };
113	    doc.decision = { candidate: d.candidate, accepted: d.accepted };
114	  }
115	  if (r.tile !== undefined) {
116	    const t = r.tile as Record<string, unknown> | null;
117	    if (!t || typeof t.tileable !== "boolean" || typeof t.framed !== "boolean") return { ok: false, error: "tile must be { tileable, framed }" };
118	    doc.tile = { tileable: t.tileable, framed: t.framed };
119	  }
120	  return { ok: true, doc };
121	}
122	
123	/** The tq-1 quality bar on the COMPOSITE (same check ids and thresholds as the build service). */
124	export function docQuality(doc: Pick<TextureDoc, "size" | "spec" | "paint" | "tile">): QualityReport {
125	  return textureQuality(renderDoc(doc), doc.tile ? { profile: "tile", tileable: doc.tile.tileable, framed: doc.tile.framed } : {});
126	}
127	
128	export const docFromSpec = (spec: TextureSpec): TextureDoc => ({ v: 1, name: spec.name, size: spec.size, spec, paint: null });
129	
130	/** Composite: paint replaces base pixels (opaque), clear erases them. Returns a NEW raster. */
131	export function applyPaint(base: Raster, paint: PaintLayer | null): Raster {
132	  const px = new Uint8ClampedArray(base.px);
133	  if (!paint) return { size: base.size, px };
134	  if (paint.size !== base.size) throw new Error("paint size does not match the base");
135	  const rgb = paint.colors.map((h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]);
136	  for (let k = 0; k < paint.set.length; k += 2) {
137	    const o = paint.set[k] * 4, c = rgb[paint.set[k + 1]];
138	    px[o] = c[0]; px[o + 1] = c[1]; px[o + 2] = c[2]; px[o + 3] = 255;
139	  }
140	  for (const i of paint.clear) { const o = i * 4; px[o] = px[o + 1] = px[o + 2] = px[o + 3] = 0; }
141	  return { size: base.size, px };
142	}
143	
144	export const blankRaster = (size: number): Raster => ({ size, px: new Uint8ClampedArray(size * size * 4) });
145	
146	/** The doc's pixels: what the canvas shows, the quality bar checks and the pack ships. */
147	export function renderDoc(doc: Pick<TextureDoc, "size" | "spec" | "paint">): Raster {
148	  return applyPaint(doc.spec ? render(doc.spec) : blankRaster(doc.size), doc.paint);
149	}
150	
151	/** Editor buffers (RGBA paint + erase mask) -> stored layer. Null when nothing is painted or erased. */
152	export function paintFromBuffers(size: TextureSize, rgba: Uint8ClampedArray, cut: Uint8Array): PaintLayer | null {
153	  const n = size * size;
154	  const colors: string[] = [];
155	  const index = new Map<string, number>();
156	  const set: number[] = [];
157	  const clear: number[] = [];
158	  for (let i = 0; i < n; i++) {
159	    const o = i * 4;
160	    if (rgba[o + 3]) {
161	      const h = "#" + [rgba[o], rgba[o + 1], rgba[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");
162	      let c = index.get(h);
163	      if (c === undefined) { if (colors.length >= MAX_PAINT_COLORS) throw new Error(`the paint layer holds at most ${MAX_PAINT_COLORS} colours`); c = colors.length; colors.push(h); index.set(h, c); }
164	      set.push(i, c);
165	    } else if (cut[i]) clear.push(i);
166	  }
167	  return set.length || clear.length ? { size, colors, set, clear } : null;
168	}
169	
170	/** Stored layer -> editor buffers. */
171	export function paintToBuffers(size: number, paint: PaintLayer | null): { rgba: Uint8ClampedArray; cut: Uint8Array } {
172	  const rgba = new Uint8ClampedArray(size * size * 4), cut = new Uint8Array(size * size);
173	  if (!paint) return { rgba, cut };
174	  for (let k = 0; k < paint.set.length; k += 2) {
175	    const o = paint.set[k] * 4, h = paint.colors[paint.set[k + 1]];
176	    rgba[o] = parseInt(h.slice(1, 3), 16); rgba[o + 1] = parseInt(h.slice(3, 5), 16); rgba[o + 2] = parseInt(h.slice(5, 7), 16); rgba[o + 3] = 255;
177	  }
178	  for (const i of paint.clear) cut[i] = 1;
179	  return { rgba, cut };
180	}
181	
182	/** A full raster as an all-paint doc (an uploaded PNG used in a project). Semi-transparent pixels are refused. */
183	export function docFromRaster(name: string, r: Raster): DocCheck {
184	  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size)) return { ok: false, error: "size must be 16, 32 or 64" };
185	  const cut = new Uint8Array(r.size * r.size);
186	  for (let i = 0; i < r.size * r.size; i++) { const a = r.px[i * 4 + 3]; if (a !== 0 && a !== 255) return { ok: false, error: "semi-transparent pixels are not allowed" }; }
187	  const paint = paintFromBuffers(r.size as TextureSize, r.px, cut);
188	  return checkDoc({ v: 1, name, size: r.size, spec: null, paint });
189	}
190	
191	/** Pixels touched by the paint layer (painted or erased). */
192	export const paintCount = (p: PaintLayer | null) => (p ? p.set.length / 2 + p.clear.length : 0);
193	// Cyrus Texture Studio: the editor's pure logic (R1b). Client-safe, unit-tested, no React.
194	//   - layers: locked generated base (TextureSpec) + paint layer (RGBA + erase mask) + an optional candidate
195	//   - tools: pencil / eraser / fill / line / rect with mirror and selection clipping
196	//   - history: every stroke, fill or accepted candidate is ONE step; undo / redo / jump
197	//   - compare: changed pixels, change regions (partial apply), apply inside a selection
198	//   - palette: ramps grouped from the spec palette, generated 5-shade ramps, Style DNA summary
199	import type { TextureSpec } from "../textures/dsl";
200	import { render, type Raster } from "../textures/render";
201	import type { QualityReport } from "../textures/quality";
202	import { blankRaster } from "./paint";
203	
204	// ---------------------------------------------------------------------------- history
205	
206	export type Step<T> = { label: string; snap: T };
207	export type History<T> = { steps: Step<T>[]; at: number };
208	export const MAX_STEPS = 200;
209	
210	export const historyInit = <T>(label: string, snap: T): History<T> => ({ steps: [{ label, snap }], at: 0 });
211	/** Push a step after the current one (drops any redo branch). Keeps the newest MAX_STEPS. */
212	export function historyPush<T>(h: History<T>, label: string, snap: T, max = MAX_STEPS): History<T> {
213	  const steps = [...h.steps.slice(0, h.at + 1), { label, snap }];
214	  const drop = Math.max(0, steps.length - max);
215	  return { steps: steps.slice(drop), at: steps.length - 1 - drop };
216	}
217	export const canUndo = (h: History<unknown>) => h.at > 0;
218	export const canRedo = (h: History<unknown>) => h.at < h.steps.length - 1;
219	export const historyJump = <T>(h: History<T>, i: number): History<T> => ({ ...h, at: Math.max(0, Math.min(h.steps.length - 1, i)) });
220	export const historyUndo = <T>(h: History<T>) => historyJump(h, h.at - 1);
221	export const historyRedo = <T>(h: History<T>) => historyJump(h, h.at + 1);
222	export const current = <T>(h: History<T>) => h.steps[h.at].snap;
223	
224	// ---------------------------------------------------------------------------- layers + composite
225	
226	/** One editor snapshot: the base spec (null = none) and the paint layer. Treated as immutable. */
227	export type Layers = { spec: TextureSpec | null; size: number; paint: Uint8ClampedArray; cut: Uint8Array };
228	export type Visibility = { base: boolean; paint: boolean };
229	export const ALL_VISIBLE: Visibility = { base: true, paint: true };
230	
231	const baseCache = new WeakMap<TextureSpec, Raster>();
232	/** Render a spec once per object (specs are immutable in the editor). */
233	export function baseOf(spec: TextureSpec | null, size: number): Raster {
234	  if (!spec) return blankRaster(size);
235	  let r = baseCache.get(spec);
236	  if (!r) { r = render(spec); baseCache.set(spec, r); }
237	  return r;
238	}
239	
240	export function composite(l: Layers, vis: Visibility = ALL_VISIBLE, specOverride?: TextureSpec | null): Raster {
241	  const n = l.size, base = baseOf(specOverride === undefined ? l.spec : specOverride, n), out = new Uint8ClampedArray(n * n * 4);
242	  for (let i = 0; i < n * n; i++) {
243	    const o = i * 4;
244	    if (vis.paint && l.cut[i]) continue;
245	    if (vis.paint && l.paint[o + 3]) { out[o] = l.paint[o]; out[o + 1] = l.paint[o + 1]; out[o + 2] = l.paint[o + 2]; out[o + 3] = 255; continue; }
246	    if (vis.base) { out[o] = base.px[o]; out[o + 1] = base.px[o + 1]; out[o + 2] = base.px[o + 2]; out[o + 3] = base.px[o + 3]; }
247	  }
248	  return { size: n, px: out };
249	}
250	
251	export const paintedPixels = (l: Layers) => { let c = 0; for (let i = 0; i < l.size * l.size; i++) if (l.paint[i * 4 + 3] || l.cut[i]) c++; return c; };
252	
253	// ---------------------------------------------------------------------------- tools
254	
255	export type Pt = [number, number];
256	export type Sel = { x: number; y: number; w: number; h: number } | null;
257	export const TOOLS = [
258	  { id: "pencil", label: "Pencil", key: "B" },
259	  { id: "eraser", label: "Eraser", key: "E" },
260	  { id: "fill", label: "Fill", key: "G" },
261	  { id: "picker", label: "Colour picker", key: "I" },
262	  { id: "select", label: "Select", key: "M" },
263	  { id: "line", label: "Line", key: "L" },
264	  { id: "rect", label: "Rectangle", key: "U" },
265	] as const;
266	export type ToolId = (typeof TOOLS)[number]["id"];
267	export const toolForKey = (k: string): ToolId | null => TOOLS.find((t) => t.key.toLowerCase() === k.toLowerCase())?.id ?? null;
268	
269	export function linePts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
270	  const pts: Pt[] = [];
271	  let x0 = a.x, y0 = a.y;
272	  const dx = Math.abs(b.x - x0), dy = -Math.abs(b.y - y0), sx = x0 < b.x ? 1 : -1, sy = y0 < b.y ? 1 : -1;
273	  let err = dx + dy;
274	  for (let guard = 0; guard < 8192; guard++) {
275	    pts.push([x0, y0]);
276	    if (x0 === b.x && y0 === b.y) break;
277	    const e2 = 2 * err;
278	    if (e2 >= dy) { err += dy; x0 += sx; }
279	    if (e2 <= dx) { err += dx; y0 += sy; }
280	  }
281	  return pts;
282	}
283	
284	export function rectPts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
285	  const pts: Pt[] = [];
286	  const x0 = Math.min(a.x, b.x), x1 = Math.max(a.x, b.x), y0 = Math.min(a.y, b.y), y1 = Math.max(a.y, b.y);
287	  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) if (y === y0 || y === y1 || x === x0 || x === x1) pts.push([x, y]);
288	  return pts;
289	}
290	
291	export const inSel = (sel: Sel, x: number, y: number) => !sel || (x >= sel.x && y >= sel.y && x < sel.x + sel.w && y < sel.y + sel.h);
292	export const selFrom = (a: { x: number; y: number }, b: { x: number; y: number }): Sel => ({ x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x) + 1, h: Math.abs(b.y - a.y) + 1 });
293	
294	export const hexRgb = (h: string): [number, number, number] => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
295	export const rgbHex = (p: ArrayLike<number>, o: number) => "#" + [0, 1, 2].map((j) => p[o + j].toString(16).padStart(2, "0")).join("");
296	
297	/**
298	 * Paint (color) or erase (null) a set of points on a COPY of the layers: mirror adds the reflected x, the selection
299	 * clips. Painting clears the erase mark; erasing drops the paint and marks the pixel clear (it erases the base too).
300	 */
301	export function stroke(l: Layers, pts: readonly Pt[], color: string | null, o: { mirror?: boolean; sel?: Sel } = {}): Layers {
302	  const n = l.size, paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
303	  const rgb = color ? hexRgb(color) : null;
304	  const put = (x: number, y: number) => {
305	    if (x < 0 || y < 0 || x >= n || y >= n || !inSel(o.sel ?? null, x, y)) return;
306	    const i = y * n + x, q = i * 4;
307	    if (rgb) { paint[q] = rgb[0]; paint[q + 1] = rgb[1]; paint[q + 2] = rgb[2]; paint[q + 3] = 255; cut[i] = 0; }
308	    else { paint[q] = paint[q + 1] = paint[q + 2] = paint[q + 3] = 0; cut[i] = 1; }
309	  };
310	  for (const [x, y] of pts) { put(x, y); if (o.mirror) put(n - 1 - x, y); }
311	  return { ...l, paint, cut };
312	}
313	
314	/** Flood fill: the 4-connected region of the composite's colour at (x, y) (clear counts as a colour), inside the selection. */
315	export function floodPts(img: Raster, x: number, y: number, sel: Sel = null): Pt[] {
316	  const n = img.size;
317	  if (x < 0 || y < 0 || x >= n || y >= n) return [];
318	  const key = (i: number) => (img.px[i * 4 + 3] ? (img.px[i * 4] << 16) | (img.px[i * 4 + 1] << 8) | img.px[i * 4 + 2] : -1);
319	  const target = key(y * n + x);
320	  const seen = new Uint8Array(n * n), out: Pt[] = [], q: Pt[] = [[x, y]];
321	  while (q.length) {
322	    const [a, b] = q.pop()!;
323	    if (a < 0 || b < 0 || a >= n || b >= n) continue;
324	    const i = b * n + a;
325	    if (seen[i] || !inSel(sel, a, b)) continue;
326	    seen[i] = 1;
327	    if (key(i) !== target) continue;
328	    out.push([a, b]);
329	    q.push([a + 1, b], [a - 1, b], [a, b + 1], [a, b - 1]);
330	  }
331	  return out;
332	}
333	
334	export function pickColor(img: Raster, x: number, y: number): string | null {
335	  const o = (y * img.size + x) * 4;
336	  return img.px[o + 3] ? rgbHex(img.px, o) : null;
337	}
338	
339	// ---------------------------------------------------------------------------- compare + partial apply
340	
341	export function changedMask(a: Raster, b: Raster): Uint8Array {
342	  const n = a.size, m = new Uint8Array(n * n);
343	  for (let i = 0; i < n * n; i++) { const o = i * 4; if (a.px[o + 3] !== b.px[o + 3] || (b.px[o + 3] && (a.px[o] !== b.px[o] || a.px[o + 1] !== b.px[o + 1] || a.px[o + 2] !== b.px[o + 2]))) m[i] = 1; }
344	  return m;
345	}
346	
347	export type Region = { id: number; pixels: number[]; x: number; y: number; w: number; h: number; colors: string[]; cleared: number };
348	export const MAX_REGIONS = 8;
349	
350	/**
351	 * Changed pixels grouped into 8-connected regions (biggest first): one checkbox each for a partial apply. Regions
352	 * past MAX_REGIONS merge into the last one so the list stays short.
353	 */
354	export function changeRegions(before: Raster, after: Raster): Region[] {
355	  const n = before.size, m = changedMask(before, after), seen = new Uint8Array(n * n), regions: number[][] = [];
356	  for (let s = 0; s < n * n; s++) {
357	    if (!m[s] || seen[s]) continue;
358	    const px: number[] = [], q = [s];
359	    seen[s] = 1;
360	    while (q.length) {
361	      const i = q.pop()!; px.push(i);
362	      const x = i % n, y = (i / n) | 0;
363	      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
364	        const a = x + dx, b = y + dy;
365	        if ((dx || dy) && a >= 0 && b >= 0 && a < n && b < n) { const j = b * n + a; if (m[j] && !seen[j]) { seen[j] = 1; q.push(j); } }
366	      }
367	    }
368	    regions.push(px.sort((a, b) => a - b));
369	  }
370	  regions.sort((a, b) => b.length - a.length || a[0] - b[0]);
371	  if (regions.length > MAX_REGIONS) { const rest = regions.splice(MAX_REGIONS - 1).flat().sort((a, b) => a - b); regions.push(rest); }
372	  return regions.map((px, id) => {
373	    let x0 = n, y0 = n, x1 = -1, y1 = -1, cleared = 0;
374	    const colors = new Set<string>();
375	    for (const i of px) {
376	      const x = i % n, y = (i / n) | 0;
377	      x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
378	      if (after.px[i * 4 + 3]) colors.add(rgbHex(after.px, i * 4)); else cleared++;
379	    }
380	    return { id, pixels: px, x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, colors: [...colors].slice(0, 4), cleared };
381	  });
382	}
