384	/** Write the candidate's pixels for the given indices into the paint layer (a non-destructive, partial apply). */
385	export function applyPixels(l: Layers, cand: Raster, pixels: Iterable<number>): Layers {
386	  const paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
387	  for (const i of pixels) {
388	    const o = i * 4;
389	    if (cand.px[o + 3]) { paint[o] = cand.px[o]; paint[o + 1] = cand.px[o + 1]; paint[o + 2] = cand.px[o + 2]; paint[o + 3] = 255; cut[i] = 0; }
390	    else { paint[o] = paint[o + 1] = paint[o + 2] = paint[o + 3] = 0; cut[i] = 1; }
391	  }
392	  return { ...l, paint, cut };
393	}
