409	const hsl = (hex: string) => {
410	  const [r, g, b] = hexRgb(hex).map((v) => v / 255);
411	  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn, l = (mx + mn) / 2;
412	  const s = d ? d / (1 - Math.abs(2 * l - 1)) : 0;
413	  let h = 0;
414	  if (d) h = mx === r ? ((g - b) / d) % 6 : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
415	  return { h: (h * 60 + 360) % 360, s, l };
416	};
417	const fromHsl = (H: number, S: number, L: number) => {
418	  const c = (1 - Math.abs(2 * L - 1)) * S, x = c * (1 - Math.abs(((H / 60) % 2) - 1)), m = L - c / 2;
419	  const [R, G, B] = H < 60 ? [c, x, 0] : H < 120 ? [x, c, 0] : H < 180 ? [0, c, x] : H < 240 ? [0, x, c] : H < 300 ? [x, 0, c] : [c, 0, x];
420	  return "#" + [R, G, B].map((v) => Math.round(Math.max(0, Math.min(1, v + m)) * 255).toString(16).padStart(2, "0")).join("");
421	};
