423	/** 5-shade ramp from one colour: darker shades shift cooler, lighter warmer (classic pixel-art hue shifting). */
424	export function generateRamp(hex: string): string[] {
425	  const { h, s, l } = hsl(hex);
426	  return [-2, -1, 0, 1, 2].map((k) => fromHsl((h + k * -8 + 360) % 360, Math.min(1, s * (1 + Math.abs(k) * 0.04)), Math.max(0.06, Math.min(0.94, l + k * 0.12))));
427	}
