429	const HUES: [number, string][] = [[15, "Red"], [45, "Amber"], [70, "Yellow"], [160, "Green"], [200, "Teal"], [255, "Blue"], [290, "Violet"], [335, "Pink"], [360, "Red"]];
430	const hueName = (h: number) => HUES.find(([lim]) => h < lim)![1];
431	const luminance = (hex: string) => { const [r, g, b] = hexRgb(hex); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
