433	export type RampGroup = { label: string; keys: string[] };
434	/**
435	 * Group a spec palette into ramps for the strip. Library templates name their slots (m1-m5 primary, h1-h5 secondary,
436	 * x1-x5 accent, f* fixed); any other palette is grouped by hue (low saturation = Neutral), dark to light.
437	 */
438	export function paletteRamps(palette: Record<string, string>): RampGroup[] {
439	  const keys = Object.keys(palette);
440	  const slot = (k: string) => (/^m\d$/.test(k) ? "Primary" : /^h\d$/.test(k) ? "Secondary" : /^x\d$/.test(k) ? "Accent" : /^f[a-z]$/.test(k) ? "Fixed" : null);
441	  const named = keys.length > 0 && keys.every((k) => slot(k));
442	  const groups = new Map<string, string[]>();
443	  for (const k of keys) {
444	    const { h, s } = hsl(palette[k]);
445	    const g = named ? slot(k)! : s < 0.18 ? "Neutral" : hueName(h);
446	    groups.set(g, [...(groups.get(g) ?? []), k]);
447	  }
448	  const order = ["Primary", "Secondary", "Accent", "Neutral", "Fixed"];
449	  return [...groups.entries()]
450	    .map(([label, ks]) => ({ label, keys: ks.sort((a, b) => luminance(palette[a]) - luminance(palette[b])) }))
451	    .sort((a, b) => (order.indexOf(a.label) + 1 || 9) - (order.indexOf(b.label) + 1 || 9) || b.keys.length - a.keys.length);
452	}
