79	export function mergeDisplay(base: FullDisplay, ...overrides: (DisplayOverride | undefined)[]): FullDisplay {
80	  const out = clone(base);
81	  for (const o of overrides) if (o) for (const c of DISPLAY_CONTEXTS) {
82	    const t = o[c]; if (!t) continue;
83	    if (t.rotation) out[c].rotation = [...t.rotation] as Vec3;
84	    if (t.translation) out[c].translation = [...t.translation] as Vec3;
85	    if (t.scale) out[c].scale = [...t.scale] as Vec3;
86	  }
87	  for (const c of DISPLAY_CONTEXTS) out[c] = { rotation: capV(out[c].rotation, ITEMMODEL_CAPS.rotation), translation: capV(out[c].translation, ITEMMODEL_CAPS.translation), scale: capV(out[c].scale, ITEMMODEL_CAPS.scale) };
88	  return out;
89	}
90	// Cyrus item model states: the Texture Studio's CONTEXT switcher + STATE scrubber, pure + client-safe (no DOM).
91	// For the current texture it finds the mod's ItemModelSpec (or derives the default the pack uses for a texture without
92	// one: tool = handheld, a handgun name = gun), lists its states, and draws the extruded item through the SAME display
93	// transforms the pack writes (./emit.ts stateDisplays) in six views: hotbar slot (gui), dropped (ground), first and
94	// third person (lib/cyrus/studios/held.ts with the transform), item frame (fixed), head. Cameras, the slot / frame /
95	// shadow / head backdrops and the head-layer offset are Cyrus's approximation of the game renderer: "approximate".
96	import type { Raster } from "../textures/render";
97	import { applyDisplay, gripKindOf, type DisplayTransform, type Vec3 } from "../textures/display";
98	import { heldScene, type Poly } from "../studios/held";
99	import { stateDisplays } from "./emit";
100	import type { DisplayContext, ItemModelSpec, ItemState } from "./spec";
101	import type { FullDisplay } from "./display";
102	
103	export type PreviewContext = "gui" | "ground" | "firstperson" | "thirdperson" | "fixed" | "head";
104	export const PREVIEW_CONTEXTS: { id: PreviewContext; label: string; display: DisplayContext; hint: string }[] = [
105	  { id: "gui", label: "Hotbar", display: "gui", hint: "In an inventory slot, with the gui transform" },
106	  { id: "ground", label: "Dropped", display: "ground", hint: "Dropped on the ground, with the ground transform" },
107	  { id: "firstperson", label: "First person", display: "firstperson_righthand", hint: "First person, right hand, with the pack's display transform" },
108	  { id: "thirdperson", label: "Third person", display: "thirdperson_righthand", hint: "Third person, right hand, with the pack's display transform" },
109	  { id: "fixed", label: "Item frame", display: "fixed", hint: "In an item frame, with the fixed transform" },
110	  { id: "head", label: "Head", display: "head", hint: "Worn on the head, with the head transform" },
111	];
112	
113	export type PreviewState = { id: string; label: string; texture: string };
114	export type PreviewModel = { spec: ItemModelSpec; derived: boolean; states: PreviewState[] };
115	
116	const cap = (s: string) => s.replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());
117	/** Scrubber label: the spec's label, else from the condition (Pull 1-3, Use, Reload...). */
118	export function stateLabel(st: ItemState, all: ItemState[]): string {
119	  if (st.label) return st.label;
120	  const w = st.when;
121	  if (w.type === "pull") { const i = all.filter((x) => x.when.type === "pull").sort((a, b) => (a.when as { from: number }).from - (b.when as { from: number }).from).indexOf(st); return `Pull ${i + 1}`; }
122	  if (w.type === "using") return "Use";
123	  if (w.type === "mode") return cap(w.value);
124	  if (w.type === "flag") return cap(w.name);
125	  if (w.type === "charged") return w.charge === "arrow" ? "Loaded" : "Rocket";
126	  return cap(st.id);
127	}
128	
129	/** The item model a texture belongs to (as idle or as a state texture), else the pack's default for it. */
130	export function previewModel(cur: string, specs: readonly ItemModelSpec[]): PreviewModel {
131	  const spec = specs.find((s) => s.name === cur) ?? specs.find((s) => (s.states ?? []).some((x) => x.texture === cur));
132	  if (!spec) return { spec: { schemaVersion: 1, name: cur, category: gripKindOf(cur) === "handgun" ? "gun" : "tool" }, derived: true, states: [{ id: "idle", label: "Idle", texture: cur }] };
133	  const st = spec.states ?? [];
134	  return { spec, derived: false, states: [{ id: "idle", label: "Idle", texture: spec.name }, ...st.map((s) => ({ id: s.id, label: stateLabel(s, st), texture: s.texture }))] };
135	}
136	
137	/** The display of every state of the model (needs the idle raster for the gun grip). */
138	export const previewDisplays = (m: PreviewModel, idle?: Raster): Record<string, FullDisplay> => stateDisplays(m.spec, idle);
139	
140	export const ARM = { skin: "#6152b8", skinTop: "#8676dc", skinSide: "#4a3e94", edge: "#120d26", slot: "#8b8b8b", slotHi: "#ffffff", slotLo: "#373737", slotIn: "#8b8b8b", frame: "#8a5a32", frameIn: "#b38a5e", shadow: "#000000" };
141	
142	const rad = (d: number) => (d * Math.PI) / 180;
143	const shade = (hex: string, k: number) => "#" + [1, 3, 5].map((i) => Math.max(0, Math.min(255, Math.round(parseInt(hex.slice(i, i + 2), 16) * k))).toString(16).padStart(2, "0")).join("");
144	const hexOf = (p: Uint8ClampedArray, o: number) => "#" + [p[o], p[o + 1], p[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");
145	
146	type Q = { w: Vec3[]; fill: string; part: Poly["part"]; bias: number; stroke?: string; screen?: boolean };
147	
148	/** The extruded item (one slab per opaque texel: both faces + open edges), in context space (1/16 block, y up). */
149	function itemQuads(r: Raster, place: (v: Vec3) => Vec3): Q[] {
150	  const n = r.size, k = 16 / n, out: Q[] = [];
151	  const op = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && r.px[(y * n + x) * 4 + 3] > 0;
152	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
153	    if (!op(x, y)) continue;
154	    const col = hexOf(r.px, (y * n + x) * 4);
155	    const x0 = x * k, x1 = (x + 1) * k, y0 = 16 - (y + 1) * k, y1 = 16 - y * k;
156	    const V = (a: number, b: number, z: number) => place([a, b, z]);
157	    out.push({ w: [V(x0, y0, 8.5), V(x1, y0, 8.5), V(x1, y1, 8.5), V(x0, y1, 8.5)], fill: col, part: "item", bias: 0 });
158	    out.push({ w: [V(x0, y0, 7.5), V(x0, y1, 7.5), V(x1, y1, 7.5), V(x1, y0, 7.5)], fill: shade(col, 0.62), part: "item", bias: 0 });
159	    if (!op(x, y - 1)) out.push({ w: [V(x0, y1, 7.5), V(x0, y1, 8.5), V(x1, y1, 8.5), V(x1, y1, 7.5)], fill: shade(col, 0.92), part: "item", bias: 0 });
160	    if (!op(x, y + 1)) out.push({ w: [V(x0, y0, 7.5), V(x1, y0, 7.5), V(x1, y0, 8.5), V(x0, y0, 8.5)], fill: shade(col, 0.55), part: "item", bias: 0 });
161	    if (!op(x - 1, y)) out.push({ w: [V(x0, y0, 7.5), V(x0, y0, 8.5), V(x0, y1, 8.5), V(x0, y1, 7.5)], fill: shade(col, 0.78), part: "item", bias: 0 });
162	    if (!op(x + 1, y)) out.push({ w: [V(x1, y0, 7.5), V(x1, y1, 7.5), V(x1, y1, 8.5), V(x1, y0, 8.5)], fill: shade(col, 0.68), part: "item", bias: 0 });
163	  }
164	  return out;
165	}
166	
167	const box = (c: Vec3, s: Vec3, fills: { top: string; side: string; front: string }): Q[] => {
168	  const [x0, y0, z0] = [c[0] - s[0] / 2, c[1] - s[1] / 2, c[2] - s[2] / 2], [x1, y1, z1] = [c[0] + s[0] / 2, c[1] + s[1] / 2, c[2] + s[2] / 2];
169	  return [
170	    { w: [[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], fill: fills.top, part: "arm", bias: 0, stroke: ARM.edge },
171	    { w: [[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], fill: fills.front, part: "arm", bias: 0, stroke: ARM.edge },
172	    { w: [[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], fill: fills.side, part: "arm", bias: 0, stroke: ARM.edge },
173	    { w: [[x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [x1, y0, z1]], fill: fills.side, part: "arm", bias: 0, stroke: ARM.edge },
174	    { w: [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], fill: fills.front, part: "arm", bias: 0, stroke: ARM.edge },
175	  ];
176	};
