178	/**
179	 * One context view as depth-sorted canvas polygons. `t` = the context's display transform. First / third person reuse
180	 * the studio's "In hand" scene (glove and sleeve included) with this transform.
181	 */
182	export function contextScene(r: Raster, name: string, ctx: PreviewContext, t: DisplayTransform, W: number, H: number, gun = false): { polys: Poly[] } {
183	  if (ctx === "firstperson" || ctx === "thirdperson") return { polys: heldScene(r, name, ctx, W, H, t, gun ? "handgun" : "tool").polys };
184	  // camera: yaw (around y) then pitch (around x), orthographic; z toward the camera
185	  const cam = { gui: [0, 0], ground: [-35, 22], fixed: [0, 0], head: [-38, 14] }[ctx] as [number, number];
186	  const view = (p: Vec3): Vec3 => {
187	    const [yw, pt] = [rad(cam[0]), rad(cam[1])];
188	    let [x, y, z] = p;
189	    [x, z] = [x * Math.cos(yw) + z * Math.sin(yw), -x * Math.sin(yw) + z * Math.cos(yw)];
190	    [y, z] = [y * Math.cos(pt) - z * Math.sin(pt), y * Math.sin(pt) + z * Math.cos(pt)];
191	    return [x, y, z];
192	  };
193	  // where the context puts the model: the display transform, then the renderer's own placement (approximate)
194	  const place = (v: Vec3): Vec3 => {
195	    const p = applyDisplay(t, v);
196	    if (ctx === "fixed") return [-p[0], p[1], -p[2]]; // the frame faces the viewer from the item's back side (vanilla fixed has a 180 y turn)
197	    if (ctx === "head") return [p[0] * 0.625, p[1] * 0.625 + 4, p[2] * 0.625]; // head layer: scale 0.625 about the neck pivot
198	    return p;
199	  };
200	  const quads = itemQuads(r, place);
201	  const back: Q[] = [];
202	  if (ctx === "gui") {
203	    const s = 9, z = -12;
204	    back.push({ w: [[-s, -s, z], [s, -s, z], [s, s, z], [-s, s, z]], fill: ARM.slotLo, part: "arm", bias: -2 });
205	    back.push({ w: [[-s + 1, -s, z + 0.1], [s, -s, z + 0.1], [s, s - 1, z + 0.1], [-s + 1, s - 1, z + 0.1]], fill: ARM.slotHi, part: "arm", bias: -2 });
206	    back.push({ w: [[-s + 1, -s + 1, z + 0.2], [s - 1, -s + 1, z + 0.2], [s - 1, s - 1, z + 0.2], [-s + 1, s - 1, z + 0.2]], fill: ARM.slotIn, part: "arm", bias: -2 });
207	  } else if (ctx === "ground") {
208	    let lo = Infinity; for (const q of quads) for (const p of q.w) lo = Math.min(lo, p[1]);
209	    const gy = (Number.isFinite(lo) ? lo : 0) - 2;
210	    const pts: Vec3[] = Array.from({ length: 20 }, (_, i) => [Math.cos((i / 20) * 2 * Math.PI) * 5, gy, Math.sin((i / 20) * 2 * Math.PI) * 5]);
211	    back.push({ w: pts, fill: "#00000055", part: "arm", bias: -2 });
212	  } else if (ctx === "fixed") {
213	    const s = 8, z = -2;
214	    back.push({ w: [[-s, -s, z], [s, -s, z], [s, s, z], [-s, s, z]], fill: ARM.frame, part: "arm", bias: -2, stroke: ARM.edge });
215	    back.push({ w: [[-s + 2, -s + 2, z + 0.1], [s - 2, -s + 2, z + 0.1], [s - 2, s - 2, z + 0.1], [-s + 2, s - 2, z + 0.1]], fill: ARM.frameIn, part: "arm", bias: -2 });
216	  } else if (ctx === "head") {
217	    back.push(...box([0, 4, 0], [8, 8, 8], { top: ARM.skinTop, side: ARM.skinSide, front: ARM.skin }).map((q) => ({ ...q, bias: 0 })));
218	    back.push(...box([0, -6, 0], [8, 12, 4], { top: ARM.skinTop, side: shade(ARM.skinSide, 0.85), front: shade(ARM.skin, 0.85) }).map((q) => ({ ...q, bias: -1 })));
219	  }
220	  const all = [...back, ...quads].map((q) => {
221	    const ps = q.w.map(view);
222	    return { pts: ps.map((p) => [p[0], -p[1]] as [number, number]), fill: q.fill, depth: ps.reduce((s2, p) => s2 + p[2], 0) / ps.length, part: q.part, bias: q.bias, ...(q.stroke ? { stroke: q.stroke } : {}) };
223	  }).sort((a, b) => a.bias - b.bias || a.depth - b.depth);
224	  // fit (the backdrop included, so the slot / frame / head stay in frame)
225	  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
226	  for (const p of all) for (const [x, y] of p.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
227	  const m = 12, sc = Math.min((W - 2 * m) / (x1 - x0 || 1), (H - 2 * m) / (y1 - y0 || 1));
228	  const ox = (W - (x1 - x0) * sc) / 2 - x0 * sc, oy = (H - (y1 - y0) * sc) / 2 - y0 * sc;
229	  return { polys: all.map((p) => ({ pts: p.pts.map(([x, y]) => [x * sc + ox, y * sc + oy] as [number, number]), fill: p.fill, depth: p.depth, part: p.part, ...(p.stroke ? { stroke: p.stroke } : {}) })) };
230	}
231	// Cyrus R3 item model states: ItemModelSpec v1. How ONE custom item looks in each display context (hotbar/gui,
232	// dropped, item frame, head, first/third person hands) and which texture it shows in which STATE (a bow idle vs
233	// pulled back in stages, a gun idle / aiming / reloading). The build model writes one spec per stateful item at
234	// assets/itemmodels/<name>.json; ./emit.ts turns it into the 1.21.4+ item model definition (assets/<ns>/items/<name>.json)
235	// plus one model JSON per state, inside the mod's normal resource pack (lib/cyrus/textures/pack.ts).
236	//
237	// Every condition below is a VERIFIED vanilla item model property (checked 2026-10-10 against the vanilla client jars
238	// 1.21.4 / 1.21.11 / 26.2 and the vanilla asset mirror; exact names and thresholds in docs/DOCUMENTATION.md "Cyrus item
239	// model states (R3)"). Nothing is free-form: closed condition set, hard caps, the display numbers are capped like the
240	// game caps them (translation +-80 = 5 blocks, scale +-4; rotation is not capped by the game, Cyrus caps it at +-360).
241	// Validation never throws: { ok, spec, needs, warnings } | { ok: false, errors }.
242	// The JSON Schema (itemmodel.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-itemmodel-artifacts.ts;
243	// a test fails while it is stale).
244	import { z } from "zod";
245	import { getVersion } from "../versions/registry";
246	
247	export const ITEMMODEL_SPEC_VERSION = 1;
248	
249	/** The 8 display contexts every vanilla version since 1.21.4 has (1.21.9+ adds `on_shelf`: not emitted, vanilla items do not define it either). */
250	export const DISPLAY_CONTEXTS = ["gui", "ground", "fixed", "head", "firstperson_righthand", "firstperson_lefthand", "thirdperson_righthand", "thirdperson_lefthand"] as const;
251	export type DisplayContext = (typeof DISPLAY_CONTEXTS)[number];
252	/** Per-category display defaults (./defaults.ts). */
253	export const CATEGORIES = ["sword", "tool", "bow", "crossbow", "gun", "wand", "shield", "flat"] as const;
254	export type Category = (typeof CATEGORIES)[number];
255	
256	export const ITEMMODEL_CAPS = {
257	  maxStates: 8, maxTextures: 9, maxPullStages: 4, maxModes: 6, maxFlags: 4, maxDamageStages: 4, maxContextStates: 3,
258	  rotation: 360, translation: 80, scale: 4, pullFrom: 100, maxSpecBytes: 16 * 1024, maxSpecsPerMod: 12, labelChars: 24,
259	} as const;
260	
261	const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/; // = a texture name (lib/cyrus/textures/dsl.ts)
262	const KEY_RE = /^[a-z][a-z0-9_]{0,23}$/;
263	const C = ITEMMODEL_CAPS;
264	
265	const vec = (cap: number) => z.tuple([z.number().min(-cap).max(cap), z.number().min(-cap).max(cap), z.number().min(-cap).max(cap)]);
266	export const TransformOverrideSchema = z.object({ rotation: vec(C.rotation).optional(), translation: vec(C.translation).optional(), scale: vec(C.scale).optional() }).strict();
267	export const DisplayOverrideSchema = z.object(Object.fromEntries(DISPLAY_CONTEXTS.map((c) => [c, TransformOverrideSchema.optional()])) as Record<DisplayContext, z.ZodOptional<typeof TransformOverrideSchema>>).strict();
268	export type DisplayOverride = z.infer<typeof DisplayOverrideSchema>;
269	
270	/**
271	 * The closed condition set. Layer order in the emitted definition (outermost first, the first that matches wins):
272	 * broken -> damage -> mode -> flag -> charged -> using / pull -> selected -> context -> the idle model.
273	 */
274	export const ConditionSchema = z.discriminatedUnion("type", [
275	  /** the item is being used (bow drawn, shield raised, a consumable-style gun being aimed): condition minecraft:using_item */
276	  z.object({ type: z.literal("using") }).strict(),
277	  /** a pull stage while used. use_duration: range_dispatch minecraft:use_duration scale 0.05 (20 ticks = 1.0; vanilla bow 0.65 / 0.9);
278	   *  crossbow: minecraft:crossbow/pull (0..1 of the crossbow's charge time; vanilla 0.58 / 1.0, crossbow base only). from 0 = the first stage. */
279	  z.object({ type: z.literal("pull"), from: z.number().min(0).max(C.pullFrom), source: z.enum(["use_duration", "crossbow"]).optional() }).strict(),
280	  /** a loaded crossbow: select minecraft:charge_type (crossbow base only) */
281	  z.object({ type: z.literal("charged"), charge: z.enum(["arrow", "rocket"]) }).strict(),
282	  /** plugin-set: select minecraft:custom_model_data on strings[0] (one mode at a time: reloading, aiming, empty...) */
283	  z.object({ type: z.literal("mode"), value: z.string().regex(KEY_RE) }).strict(),
284	  /** plugin-set: condition minecraft:custom_model_data on flags[index] (index assigned in declaration order) */
285	  z.object({ type: z.literal("flag"), name: z.string().regex(KEY_RE) }).strict(),
286	  /** in the selected hotbar slot: condition minecraft:selected */
287	  z.object({ type: z.literal("selected") }).strict(),
288	  /** where it is drawn: select minecraft:display_context */
289	  z.object({ type: z.literal("context"), contexts: z.array(z.enum(DISPLAY_CONTEXTS)).min(1).max(7) }).strict(),
290	  /** one use from breaking: condition minecraft:broken */
291	  z.object({ type: z.literal("broken") }).strict(),
292	  /** worn down: range_dispatch minecraft:damage (normalised 0..1, so 0.5 = half the durability used) */
293	  z.object({ type: z.literal("damage"), from: z.number().gt(0).max(1) }).strict(),
294	]);
295	export type Condition = z.infer<typeof ConditionSchema>;
296	
297	export const StateSchema = z.object({
298	  /** "idle" is the base look (the spec's own texture), so a state cannot be called idle */
299	  id: z.string().regex(KEY_RE),
300	  label: z.string().min(1).max(C.labelChars).optional(),
301	  /** a texture of the same mod (a TextureSpec name) */
302	  texture: z.string().regex(NAME_RE),
303	  when: ConditionSchema,
304	  /** per-state display overrides on top of the item's display */
305	  display: DisplayOverrideSchema.optional(),
306	}).strict();
307	export type ItemState = z.infer<typeof StateSchema>;
308	
309	export const ItemModelSpecSchema = z.object({
310	  schemaVersion: z.literal(ITEMMODEL_SPEC_VERSION),
311	  /** = the idle texture's name AND the item model key (<ns>:<name>, what ItemMeta#setItemModel points at) */
312	  name: z.string().regex(NAME_RE),
313	  category: z.enum(CATEGORIES),
314	  /** owner/studio overrides on top of the category defaults (any subset of contexts and fields) */
315	  display: DisplayOverrideSchema.optional(),
316	  states: z.array(StateSchema).max(C.maxStates).optional(),
317	  /** the vanilla re-equip bob when the item's components change; default: off when plugin-set states exist (a mode change would bob otherwise) */
318	  handAnimationOnSwap: z.boolean().optional(),
319	}).strict();
320	export type ItemModelSpec = z.infer<typeof ItemModelSpecSchema>;
321	
322	export type ImIssue = { path: string; code: string; message: string };
323	export type ItemModelNeeds = {
324	  /** custom_model_data strings[0] values the plugin may set (one at a time) */
325	  modes: string[];
326	  /** custom_model_data flags, index = position */
327	  flags: string[];
328	  /** the item must be usable (bow/crossbow base, or a consumable-style aim) for using/pull states to ever show */
329	  use: boolean;
330	  textures: string[];
331	};
332	export type ItemModelResult = { ok: true; spec: ItemModelSpec; needs: ItemModelNeeds; warnings: ImIssue[] } | { ok: false; errors: ImIssue[]; warnings: ImIssue[] };
333	
334	const issue = (path: string, code: string, message: string): ImIssue => ({ path, code, message });
335	
336	/** Where the 1.21.4 item model definitions exist (registry capability). 1.21.1 is refused with the registry's message (no legacy emitter). */
337	export function itemModelVersionOk(version: string): { ok: true } | { ok: false; error: string } {
338	  const v = getVersion(version);
339	  if (!v) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
340	  if (!v.capabilities.includes("itemModelDefinitions")) return { ok: false, error: `${version} has no item model definitions (needs 1.21.4+); a legacy custom-model-data emitter is not built yet` };
341	  return { ok: true };
342	}
343	
344	const USABLE: readonly Category[] = ["bow", "crossbow", "gun", "wand", "shield"];
345	
346	/**
347	 * Validate an untrusted spec. `textures` = the texture names the mod has (absent = not checked); `version` = the
348	 * exact target version (absent = not checked).
349	 */
350	export function validateItemModel(raw: unknown, opts: { textures?: readonly string[]; version?: string } = {}): ItemModelResult {
351	  const warnings: ImIssue[] = [];
352	  if (raw !== null && typeof raw === "object" && new TextEncoder().encode(JSON.stringify(raw)).length > C.maxSpecBytes) return { ok: false, errors: [issue("(file)", "too_big", `an item model spec is at most ${C.maxSpecBytes / 1024} KB`)], warnings };
353	  const p = ItemModelSpecSchema.safeParse(raw);
354	  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 12).map((i) => issue(i.path.join(".") || "(root)", "schema", i.message)), warnings };
355	  const s = p.data;
356	  const errors: ImIssue[] = [];
357	  if (opts.version) { const v = itemModelVersionOk(opts.version); if (!v.ok) errors.push(issue("(version)", "version", v.error)); }
358	  const states = s.states ?? [];
359	  const ids = new Set<string>();
360	  const modes: string[] = [], flags: string[] = [], pulls: { from: number; source: string; i: number }[] = [], damage: number[] = [], contexts = new Set<string>();
361	  let using = 0, charged = new Set<string>(), selected = 0, broken = 0, ctxStates = 0;
362	  states.forEach((st, i) => {
363	    const at = `states[${i}]`;
364	    if (st.id === "idle") errors.push(issue(`${at}.id`, "reserved_id", `"idle" is the item's own look; name the state something else`));
365	    if (ids.has(st.id)) errors.push(issue(`${at}.id`, "dup_state", `two states are called ${st.id}`));
366	    ids.add(st.id);
367	    const w = st.when;
368	    switch (w.type) {
369	      case "using": using++; break;
370	      case "pull": {
371	        const source = w.source ?? "use_duration";
372	        if (pulls.some((x) => x.from === w.from)) errors.push(issue(`${at}.when.from`, "dup_pull", `two pull stages start at ${w.from}`));
373	        if (source === "crossbow" && s.category !== "crossbow") errors.push(issue(`${at}.when.source`, "crossbow_only", "crossbow pull only works on a crossbow (category crossbow)"));
374	        if (source === "crossbow" && w.from > 1) errors.push(issue(`${at}.when.from`, "crossbow_range", "crossbow pull runs from 0 to 1"));
375	        pulls.push({ from: w.from, source, i });
376	        break;
377	      }
378	      case "charged":
379	        if (s.category !== "crossbow") errors.push(issue(`${at}.when`, "crossbow_only", "a charged state only works on a crossbow (category crossbow)"));
380	        if (charged.has(w.charge)) errors.push(issue(`${at}.when.charge`, "dup_charged", `two states for a crossbow charged with ${w.charge}`));
381	        charged = new Set([...charged, w.charge]);
382	        break;
383	      case "mode": if (modes.includes(w.value)) errors.push(issue(`${at}.when.value`, "dup_mode", `two states for mode ${w.value}`)); else modes.push(w.value); break;
384	      case "flag": if (flags.includes(w.name)) errors.push(issue(`${at}.when.name`, "dup_flag", `two states for flag ${w.name}`)); else flags.push(w.name); break;
385	      case "selected": selected++; break;
386	      case "broken": broken++; break;
387	      case "damage": if (damage.includes(w.from)) errors.push(issue(`${at}.when.from`, "dup_damage", `two damage stages start at ${w.from}`)); else damage.push(w.from); break;
388	      case "context": {
389	        ctxStates++;
390	        for (const c of w.contexts) { if (contexts.has(c)) errors.push(issue(`${at}.when.contexts`, "context_overlap", `${c} is claimed by two states`)); contexts.add(c); }
391	        break;
392	      }
393	    }
394	  });
395	  if (using > 1) errors.push(issue("states", "dup_using", "at most one using state"));
396	  if (using && pulls.length) errors.push(issue("states", "using_and_pull", "use either one using state or pull stages, not both"));
397	  if (selected > 1) errors.push(issue("states", "dup_selected", "at most one selected state"));
398	  if (broken > 1) errors.push(issue("states", "dup_broken", "at most one broken state"));
399	  if (pulls.length) {
400	    if (!pulls.some((x) => x.from === 0)) errors.push(issue("states", "pull_no_start", "pull stages need one stage with from 0 (shown as soon as the item is used)"));
401	    if (new Set(pulls.map((x) => x.source)).size > 1) errors.push(issue("states", "pull_mixed", "all pull stages must use the same source"));
402	    if (pulls.length > C.maxPullStages) errors.push(issue("states", "too_many_pull", `at most ${C.maxPullStages} pull stages`));
403	  }
404	  if (modes.length > C.maxModes) errors.push(issue("states", "too_many_modes", `at most ${C.maxModes} modes`));
405	  if (flags.length > C.maxFlags) errors.push(issue("states", "too_many_flags", `at most ${C.maxFlags} flags`));
406	  if (damage.length > C.maxDamageStages) errors.push(issue("states", "too_many_damage", `at most ${C.maxDamageStages} damage stages`));
407	  if (ctxStates > C.maxContextStates) errors.push(issue("states", "too_many_context", `at most ${C.maxContextStates} context states`));
408	  if (contexts.size === DISPLAY_CONTEXTS.length) errors.push(issue("states", "context_all", "context states cover every context, so the item's own look would never show"));
409	  const textures = [s.name, ...states.map((x) => x.texture)].filter((t, i, a) => a.indexOf(t) === i);
410	  if (textures.length > C.maxTextures) errors.push(issue("states", "too_many_textures", `at most ${C.maxTextures} textures per item`));
411	  if (opts.textures) for (const [i, t] of [s.name, ...states.map((x) => x.texture)].entries()) if (!opts.textures.includes(t)) errors.push(issue(i === 0 ? "name" : `states[${i - 1}].texture`, "texture_unknown", `this mod has no texture "${t}"`));
412	  if ((using || pulls.length) && !USABLE.includes(s.category)) warnings.push(issue("states", "use_needs_usable_base", `using/pull states only show when the item can be used (a bow or crossbow base, or a gun/wand the plugin makes aimable); category ${s.category}`));
413	  if (errors.length) return { ok: false, errors, warnings };
414	  return { ok: true, spec: s, needs: { modes, flags, use: !!(using || pulls.length), textures }, warnings };
415	}
