417	/** Several specs of one mod: each valid, names unique, at most maxSpecsPerMod. */
418	export function validateItemModels(raws: unknown[], opts: { textures?: readonly string[]; version?: string } = {}): { ok: boolean; results: ItemModelResult[]; errors: ImIssue[] } {
419	  const errors: ImIssue[] = [];
420	  if (raws.length > C.maxSpecsPerMod) errors.push(issue("(mod)", "too_many_specs", `at most ${C.maxSpecsPerMod} stateful items per mod`));
421	  const results = raws.map((r) => validateItemModel(r, opts));
422	  const names = results.flatMap((r) => (r.ok ? [r.spec.name] : []));
423	  for (const n of names) if (names.indexOf(n) !== names.lastIndexOf(n)) { errors.push(issue("(mod)", "dup_name", `two item model specs for ${n}`)); break; }
424	  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
425	}
