// Item model DISPLAY transforms (how a held item is placed in the hand), pure + client-safe.
// The pack builder (./pack.ts) writes them into every item model it emits, and the Texture Studio's "In hand"
// preview applies the SAME numbers (lib/cyrus/studios/held.ts), so the preview and the pack cannot drift apart.
//
// HANDHELD_DISPLAY / GENERATED_DISPLAY are the game's own `item/handheld` and `item/generated` values, checked
// 2026-10-10 against the Minecraft 1.21.4 asset mirror (github.com/InventivetalentDev/minecraft-assets, branch 1.21.4,
// assets/minecraft/models/item/{handheld,generated}.json). Numbers only: no Mojang asset is committed.
// Units: rotation in degrees (applied X, then Y, then Z: JOML rotationXYZ), translation in 1/16 block (clamped to
// +-80 by the game), scale per axis; the model (0..16 per axis) is transformed about its centre (8, 8, 8).
import type { Raster } from "./render";

export type Vec3 = [number, number, number];
export type DisplayTransform = { rotation: Vec3; translation: Vec3; scale: Vec3 };
export type DisplayView = "thirdperson_righthand" | "thirdperson_lefthand" | "firstperson_righthand" | "firstperson_lefthand";
export type Display = Record<DisplayView, DisplayTransform>;

export const HANDHELD_DISPLAY: Display = {
  thirdperson_righthand: { rotation: [0, -90, 55], translation: [0, 4.0, 0.5], scale: [0.85, 0.85, 0.85] },
  thirdperson_lefthand: { rotation: [0, 90, -55], translation: [0, 4.0, 0.5], scale: [0.85, 0.85, 0.85] },
  firstperson_righthand: { rotation: [0, -90, 25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
  firstperson_lefthand: { rotation: [0, 90, -25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
};
/** `item/generated` (flat items that are not tools: food, gems, drops): the hand views only. */
export const GENERATED_DISPLAY: Pick<Display, "thirdperson_righthand" | "firstperson_righthand"> = {
  thirdperson_righthand: { rotation: [0, 0, 0], translation: [0, 3, 1], scale: [0.55, 0.55, 0.55] },
  firstperson_righthand: { rotation: [0, -90, 25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
};

/**
 * Where the hand holds the item, in model units (x right, y UP, 0..16).
 * DOCUMENTED DEFAULTS per item category (no texture marks a grip anchor yet):
 *  - "tool" (swords, pickaxes, axes, wands: anything drawn on the diagonal like vanilla): the handle end at the
 *    bottom-left, TOOL_HANDLE = (2.5, 1.5), i.e. texel (2, 14) of 16. The vanilla transforms are tuned for exactly
 *    this point, so a tool keeps the vanilla display unchanged.
 *  - "handgun" (a pistol drawn side-on, barrel to the right, grip hanging below the back of the slide): the centre of
 *    the opaque pixels in the lowest 40 % of the item's height, within its left 60 %.
 */
export type GripKind = "tool" | "handgun";
export const TOOL_HANDLE: [number, number] = [2.5, 1.5];
const GUN = /(^|_)(glock|pistol|handgun|revolver|gun|blaster|rifle|smg|shotgun|musket|flintlock|deagle|uzi)(_|$|\d)/;
export const gripKindOf = (name: string): GripKind => (GUN.test(name) ? "handgun" : "tool");

export function gripPoint(r: Raster, kind: GripKind): [number, number] {
  if (kind === "tool") return TOOL_HANDLE;
  const n = r.size, k = 16 / n;
  let x0 = n, x1 = -1, y0 = n, y1 = -1;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3]) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  if (x1 < 0) return TOOL_HANDLE;
  const yCut = y1 - (y1 - y0 + 1) * 0.4, xCut = x0 + (x1 - x0 + 1) * 0.6;
  let sx = 0, sy = 0, c = 0;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3] && y >= yCut && x <= xCut) { sx += x + 0.5; sy += y + 0.5; c++; }
  if (!c) return TOOL_HANDLE;
  return [round3((sx / c) * k), round3(16 - (sy / c) * k)];
}

const round3 = (v: number) => Math.round(v * 1000) / 1000;
const rad = (d: number) => (d * Math.PI) / 180;

/** R = Rx * Ry * Rz (JOML rotationXYZ) applied to a vector. */
export function rotate(rot: Vec3, v: Vec3): Vec3 {
  const [ax, ay, az] = rot.map(rad);
  let [x, y, z] = v;
  // Rz
  [x, y] = [x * Math.cos(az) - y * Math.sin(az), x * Math.sin(az) + y * Math.cos(az)];
  // Ry
  [x, z] = [x * Math.cos(ay) + z * Math.sin(ay), -x * Math.sin(ay) + z * Math.cos(ay)];
  // Rx
  [y, z] = [y * Math.cos(ax) - z * Math.sin(ax), y * Math.sin(ax) + z * Math.cos(ax)];
  return [x, y, z];
}

/** A model point (0..16 units) through a display transform, in 1/16 block units relative to the hand. */
export function applyDisplay(t: DisplayTransform, v: Vec3): Vec3 {
  const s: Vec3 = [(v[0] - 8) * t.scale[0], (v[1] - 8) * t.scale[1], (v[2] - 8) * t.scale[2]];
  const r = rotate(t.rotation, s);
  return [r[0] + t.translation[0], r[1] + t.translation[1], r[2] + t.translation[2]];
}

const clampT = (v: number) => round3(Math.max(-80, Math.min(80, v))) || 0; // `|| 0`: no -0 in the model JSON
/** Move a transform so that model point `g` lands where `h` did: T' = T + R S (h - g). */
export function regrip(t: DisplayTransform, g: [number, number], h: [number, number]): DisplayTransform {
  const d = rotate(t.rotation, [(h[0] - g[0]) * t.scale[0], (h[1] - g[1]) * t.scale[1], 0]);
  return { rotation: [...t.rotation], translation: [clampT(t.translation[0] + d[0]), clampT(t.translation[1] + d[1]), clampT(t.translation[2] + d[2])], scale: [...t.scale] };
}

/**
 * Handguns are drawn side-on (barrel to the right, grip below), tools on the 45 degree diagonal the vanilla transforms
 * assume, so vanilla handheld would point a pistol's barrel up / back. Cyrus's handgun rotations (right hand; the left
 * hand mirrors y and z like the game does) point the barrel forward, grip down: first person up-left toward the
 * crosshair with the pistol's side facing the camera, third person straight ahead. Found by projecting the muzzle,
 * back and grip of a side-on pistol through the same math as the preview (test/cyrus-studios.test.ts checks the
 * directions). Translation is then re-gripped. UNVERIFIED in a real client: check on the real-client test day.
 */
export const GUN_ROTATION = { firstperson: [-10, 150, 30] as Vec3, thirdperson: [0, 90, 10] as Vec3 };

/** The display block the pack writes for one item texture (tools: exactly vanilla handheld; handguns: GUN_ROTATION + re-gripped). */
export function displayFor(name: string, r: Raster): Display {
  const kind = gripKindOf(name);
  if (kind === "tool") return HANDHELD_DISPLAY;
  const g = gripPoint(r, kind);
  const H = HANDHELD_DISPLAY;
  const R = (t: DisplayTransform, r: Vec3): DisplayTransform => ({ ...t, rotation: [r[0], r[1], r[2]] });
  const L = (t: DisplayTransform, r: Vec3): DisplayTransform => ({ ...t, rotation: [r[0], -r[1], -r[2]] }); // the game mirrors y and z for the left hand
  return {
    thirdperson_righthand: regrip(R(H.thirdperson_righthand, GUN_ROTATION.thirdperson), g, TOOL_HANDLE),
    thirdperson_lefthand: regrip(L(H.thirdperson_lefthand, GUN_ROTATION.thirdperson), g, TOOL_HANDLE),
    firstperson_righthand: regrip(R(H.firstperson_righthand, GUN_ROTATION.firstperson), g, TOOL_HANDLE),
    firstperson_lefthand: regrip(L(H.firstperson_lefthand, GUN_ROTATION.firstperson), g, TOOL_HANDLE),
  };
}
// Cyrus Texture Studio (R1b): the "In hand" preview scene. Pure + client-safe (unit-tested), no DOM.
// It applies the SAME display transforms the pack writes into the item model (lib/cyrus/textures/display.ts
// displayFor: vanilla `item/handheld` for tools, re-gripped for handguns) to the extruded item, then projects it.
// The transforms are the game's verified values; the hand position, camera and arm are Cyrus's approximation of the
// game's renderer, so the panel is labelled "approximate". Output: depth-sorted polygons in canvas pixels.
import type { Raster } from "../textures/render";
import { applyDisplay, displayFor, gripKindOf, gripPoint, type DisplayTransform, type GripKind, type Vec3 } from "../textures/display";

export type HeldView = "firstperson" | "thirdperson";
export type Poly = { pts: [number, number][]; fill: string; depth: number; part: "arm" | "item" | "fingers"; stroke?: string };
export type HeldScene = { polys: Poly[]; grip: [number, number]; kind: "tool" | "handgun"; transform: DisplayTransform };

const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a: Vec3, k: number): Vec3 => [a[0] * k, a[1] * k, a[2] * k];
const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec3): Vec3 => { const l = Math.hypot(...a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const shade = (hex: string, k: number) => "#" + [1, 3, 5].map((i) => Math.max(0, Math.min(255, Math.round(parseInt(hex.slice(i, i + 2), 16) * k))).toString(16).padStart(2, "0")).join("");
const hexOf = (p: Uint8ClampedArray, o: number) => "#" + [p[o], p[o + 1], p[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");

/**
 * Camera conventions (blocks, y up). First person: the vanilla right-hand item origin (ItemInHandRenderer
 * applyItemArmTransform: 0.56, -0.52, -0.72 with no swing) seen through a 70 degree perspective camera looking down -z.
 * Third person: the right hand of a standing player seen from the side (orthographic), the item in the hand frame the
 * player model gives it (hand pointing forward, palm inwards); screen x = forward.
 */
const FP_HAND: Vec3 = [0.56, -0.52, -0.72];
/** third person: hand frame -> world (side view): the arm points forward and down; item x stays forward. */
const TP_HAND: Vec3 = [0, 0, 0];
const tpBasis = (v: Vec3): Vec3 => [-v[2], v[1], v[0]]; // item frame z (toward the camera in first person) = player forward

/** Glove + sleeve: the brand's deep violet, lit from the top-left like the art. */
export const ARM_COLOURS = { sleeve: "#3a2f78", sleeveTop: "#5144a0", cuff: "#7c4dff", cuffTop: "#a68bff", glove: "#6152b8", gloveTop: "#8676dc", edge: "#120d26" };

type Pt3 = Vec3;
function boxFaces(center: Pt3, axis: Pt3, len: number, w: number, h: number, up: Pt3): { quad: Pt3[]; normal: Pt3; face: "top" | "side" | "end" | "bottom" | "start" | "back" }[] {
  const a = norm(axis), u0 = norm(sub(up, mul(a, a[0] * up[0] + a[1] * up[1] + a[2] * up[2]))), s = norm(cross(a, u0));
  const c0 = center, c1 = add(center, mul(a, len));
  const corner = (c: Pt3, i: number, j: number) => add(add(c, mul(s, (i * w) / 2)), mul(u0, (j * h) / 2));
  const P = (end: 0 | 1, i: number, j: number) => corner(end ? c1 : c0, i, j);
  return [
    { quad: [P(0, -1, 1), P(1, -1, 1), P(1, 1, 1), P(0, 1, 1)], normal: u0, face: "top" },
    { quad: [P(0, -1, -1), P(0, 1, -1), P(1, 1, -1), P(1, -1, -1)], normal: mul(u0, -1), face: "bottom" },
    { quad: [P(0, 1, -1), P(0, 1, 1), P(1, 1, 1), P(1, 1, -1)], normal: s, face: "side" },
    { quad: [P(0, -1, -1), P(1, -1, -1), P(1, -1, 1), P(0, -1, 1)], normal: mul(s, -1), face: "back" },
    { quad: [P(1, -1, -1), P(1, 1, -1), P(1, 1, 1), P(1, -1, 1)], normal: a, face: "end" },
    { quad: [P(0, -1, -1), P(0, -1, 1), P(0, 1, 1), P(0, 1, -1)], normal: mul(a, -1), face: "start" },
  ];
}

/** `transform` (Cyrus item model states): draw with this display transform instead of the pack's default for the name. */
export function heldScene(r: Raster, name: string, view: HeldView, W: number, H: number, transform?: DisplayTransform, grip?: GripKind): HeldScene {
  const kind = grip ?? gripKindOf(name);
  const disp = transform ? null : displayFor(name, r);
  const t = transform ?? (view === "firstperson" ? disp!.firstperson_righthand : disp!.thirdperson_righthand);
  const n = r.size, k = 16 / n;
  // model point (0..16) -> world (blocks)
  const world = (v: Vec3): Vec3 => { const p = mul(applyDisplay(t, v), 1 / 16); return view === "firstperson" ? add(FP_HAND, p) : add(TP_HAND, tpBasis(p)); };
  // world -> screen (before fitting) + depth (bigger = nearer the camera)
  const f = 1 / Math.tan((35 * Math.PI) / 180);
  const proj = (p: Vec3): { x: number; y: number; d: number } =>
    view === "firstperson" ? { x: (f * p[0]) / -p[2], y: (-f * p[1]) / -p[2], d: p[2] } : { x: p[0], y: -p[1], d: p[2] };
  const camDir = (p: Vec3): Vec3 => (view === "firstperson" ? norm(mul(p, -1)) : [0, 0, 1]);

  type Q = { w: Pt3[]; fill: string; part: Poly["part"]; bias: number };
  const quads: Q[] = [];
  const visible = (quad: Pt3[], normal: Pt3) => { const c = mul(quad.reduce((s, q) => add(s, q), [0, 0, 0] as Vec3), 1 / quad.length); const d = camDir(c); return normal[0] * d[0] + normal[1] * d[1] + normal[2] * d[2] > 0; };
  // the item: one voxel slab per opaque texel (front, back and the outer edges), like builtin/generated
  const op = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && r.px[(y * n + x) * 4 + 3] > 0;
  const fN = sub(world([8, 8, 9]), world([8, 8, 8]));
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (!op(x, y)) continue;
    const col = hexOf(r.px, (y * n + x) * 4);
    const x0 = x * k, x1 = (x + 1) * k, y0 = 16 - (y + 1) * k, y1 = 16 - y * k;
    const V = (a: number, b: number, z: number) => world([a, b, z]);
    const front = [V(x0, y0, 8.5), V(x1, y0, 8.5), V(x1, y1, 8.5), V(x0, y1, 8.5)];
    const back = [V(x0, y0, 7.5), V(x0, y1, 7.5), V(x1, y1, 7.5), V(x1, y0, 7.5)];
    if (visible(front, fN)) quads.push({ w: front, fill: col, part: "item", bias: 0 });
    else quads.push({ w: back, fill: shade(col, 0.62), part: "item", bias: 0 });
    const edges: [boolean, Pt3[], number][] = [
      [!op(x, y - 1), [V(x0, y1, 7.5), V(x0, y1, 8.5), V(x1, y1, 8.5), V(x1, y1, 7.5)], 0.92],
      [!op(x, y + 1), [V(x0, y0, 7.5), V(x1, y0, 7.5), V(x1, y0, 8.5), V(x0, y0, 8.5)], 0.55],
      [!op(x - 1, y), [V(x0, y0, 7.5), V(x0, y0, 8.5), V(x0, y1, 8.5), V(x0, y1, 7.5)], 0.78],
      [!op(x + 1, y), [V(x1, y0, 7.5), V(x1, y1, 7.5), V(x1, y1, 8.5), V(x1, y0, 8.5)], 0.68],
    ];
    for (const [open, q, s] of edges) if (open) quads.push({ w: q, fill: shade(col, s), part: "item", bias: 0 });
  }
  // the grip in world space, and the hand around it
  const g = gripPoint(r, kind);
  const G = world([g[0], g[1], 8]);
  const upW = view === "firstperson" ? [0, 1, 0] as Vec3 : [0, 1, 0] as Vec3;
  // forearm: from the wrist (just behind the grip) away from the item, toward the bottom right of the view
  // (first person: never toward the camera plane, which would blow the perspective up)
  const armDir: Vec3 = view === "firstperson" ? norm([0.38, -0.8, 0.22]) : norm([-0.5, 0.86, 0.06]);
  const scale = view === "firstperson" ? 1 : 0.85;
  const glove = 0.13 * scale, sleeveW = 0.21 * scale;
  const wrist = add(G, mul(armDir, glove * 0.6));
  for (const f of boxFaces(add(wrist, mul(armDir, 0.05 * scale)), armDir, 0.7 * scale, sleeveW, sleeveW, upW)) if (visible(f.quad, f.normal))
    quads.push({ w: f.quad, fill: f.face === "top" ? ARM_COLOURS.sleeveTop : f.face === "back" ? shade(ARM_COLOURS.sleeve, 0.8) : ARM_COLOURS.sleeve, part: "arm", bias: -1 });
  // cuff band at the wrist
  for (const f of boxFaces(wrist, armDir, 0.05 * scale, sleeveW * 1.12, sleeveW * 1.12, upW)) if (visible(f.quad, f.normal)) quads.push({ w: f.quad, fill: f.face === "top" ? ARM_COLOURS.cuffTop : ARM_COLOURS.cuff, part: "arm", bias: -0.5 });
  // fist: a box centred on the grip; its near half is drawn OVER the item so the grip reads as held
  const fistAxis = mul(armDir, -1);
  for (const f of boxFaces(add(G, mul(armDir, glove * 0.55)), fistAxis, glove * 1.1, glove * 1.05, glove * 0.95, upW)) if (visible(f.quad, f.normal))
    quads.push({ w: f.quad, fill: f.face === "top" ? ARM_COLOURS.gloveTop : f.face === "side" || f.face === "back" ? ARM_COLOURS.glove : shade(ARM_COLOURS.glove, 0.82), part: "fingers", bias: 1 });

  // depth sort: arm behind, item, then the fist in front (the hand closes over the grip)
  const polys = quads.map((q) => {
    const ps = q.w.map(proj);
    return { pts: ps.map((p) => [p.x, p.y] as [number, number]), fill: q.fill, depth: ps.reduce((s, p) => s + p.d, 0) / ps.length, part: q.part, bias: q.bias, ...(q.part !== "item" ? { stroke: ARM_COLOURS.edge } : {}) };
  }).sort((a, b) => a.bias - b.bias || a.depth - b.depth);

  // fit everything into the stage (keep the item big: the arm may run off the bottom-right edge like in game)
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const p of polys) if (p.part === "item") for (const [x, y] of p.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
  const m = 10, sc = Math.min((W - 2 * m) / (x1 - x0 || 1), (H - 2 * m) / (y1 - y0 || 1));
  const ox = (W - (x1 - x0) * sc) / 2 - x0 * sc, oy = (H - (y1 - y0) * sc) / 2 - y0 * sc;
  const gp = proj(G);
  return {
    polys: polys.map((p) => ({ pts: p.pts.map(([x, y]) => [x * sc + ox, y * sc + oy] as [number, number]), fill: p.fill, depth: p.depth, part: p.part, ...(p.stroke ? { stroke: p.stroke } : {}) })),
    grip: [gp.x * sc + ox, gp.y * sc + oy], kind, transform: t,
  };
}
// Cyrus item model states: the deterministic GENERATOR. ItemModelSpec -> the 1.21.4+ item model definition
// (assets/<ns>/items/<name>.json: condition / select / range_dispatch nodes) + one model JSON per state with its full
// display block (assets/<ns>/models/item/<name>.json for idle, models/item/<name>/<state>.json for the others). The
// textures are the mod's normal TextureSpecs (the pack writes textures/item/<texture>.png as before).
// Key order follows the vanilla data generator ("type" first, then alphabetical), indentation 2 spaces like vanilla, so
// a definition built from vanilla's own states is BYTE-identical to vanilla's file (test: the vanilla bow).
// The same bytes for every version with item model definitions (1.21.4 ... 26.x): the fields Cyrus uses did not change
// (26.x only adds an optional `transformation`, 1.21.9+ an `on_shelf` context, neither emitted); 1.21.1 is refused.
import type { Raster } from "../textures/render";
import { categoryDisplay, mergeDisplay, type FullDisplay } from "./display";
import { DISPLAY_CONTEXTS, itemModelVersionOk, validateItemModel, type DisplayContext, type ItemModelSpec, type ItemModelNeeds, type ImIssue } from "./spec";

export const ITEMMODEL_EMITTER_VERSION = "cyrus-itemmodel-1";
/** vanilla bow's scale on use_duration: 20 ticks of use = 1.0 */
export const USE_DURATION_SCALE = 0.05;

type Json = null | boolean | number | string | Json[] | { [k: string]: Json };

/** Recursively order keys like vanilla's generator: "type" first, then the rest alphabetically. */
export function vanillaOrder(v: Json): Json {
  if (Array.isArray(v)) return v.map(vanillaOrder);
  if (v && typeof v === "object") {
    const keys = Object.keys(v).sort((a, b) => (a === "type" ? -1 : b === "type" ? 1 : a < b ? -1 : a > b ? 1 : 0));
    return Object.fromEntries(keys.map((k) => [k, vanillaOrder((v as Record<string, Json>)[k])]));
  }
  return v;
}

/** The definition's `model` node. `ref(stateId)` names the model of a state ("idle" = the item's own look). */
export function definitionNode(spec: ItemModelSpec, ref: (stateId: string) => string): Json {
  const st = spec.states ?? [];
  const M = (id: string): Json => ({ type: "minecraft:model", model: ref(id) });
  const of = (t: string) => st.filter((s) => s.when.type === t);
  let node: Json = M("idle");
  const ctx = of("context");
  if (ctx.length) node = { type: "minecraft:select", property: "minecraft:display_context", cases: ctx.map((s) => { const c = (s.when as { contexts: DisplayContext[] }).contexts; return { model: M(s.id), when: c.length === 1 ? c[0] : [...c] }; }), fallback: node };
  const sel = of("selected")[0];
  if (sel) node = { type: "minecraft:condition", property: "minecraft:selected", on_true: M(sel.id), on_false: node };
  const using = of("using")[0];
  const pulls = of("pull").map((s) => ({ s, from: (s.when as { from: number }).from, source: (s.when as { source?: string }).source ?? "use_duration" })).sort((a, b) => a.from - b.from);
  if (using) node = { type: "minecraft:condition", property: "minecraft:using_item", on_true: M(using.id), on_false: node };
  else if (pulls.length) {
    const start = pulls.find((p) => p.from === 0)!;
    const range: Json = {
      type: "minecraft:range_dispatch",
      property: pulls[0].source === "crossbow" ? "minecraft:crossbow/pull" : "minecraft:use_duration",
      ...(pulls[0].source === "crossbow" ? {} : { scale: USE_DURATION_SCALE }),
      entries: pulls.filter((p) => p.from > 0).map((p) => ({ model: M(p.s.id), threshold: p.from })),
      fallback: M(start.s.id),
    };
    node = { type: "minecraft:condition", property: "minecraft:using_item", on_true: range, on_false: node };
  }
  const charged = of("charged");
  if (charged.length) node = { type: "minecraft:select", property: "minecraft:charge_type", cases: charged.map((s) => ({ model: M(s.id), when: (s.when as { charge: string }).charge })), fallback: node };
  const flags = of("flag");
  // flags[i] in declaration order: the first declared flag is the outermost (wins when two are set)
  const flagIndex = (name: string) => flags.findIndex((s) => (s.when as { name: string }).name === name);
  for (const s of [...flags].reverse()) node = { type: "minecraft:condition", property: "minecraft:custom_model_data", index: flagIndex((s.when as { name: string }).name), on_true: M(s.id), on_false: node };
  const modes = of("mode");
  if (modes.length) node = { type: "minecraft:select", property: "minecraft:custom_model_data", index: 0, cases: modes.map((s) => ({ model: M(s.id), when: (s.when as { value: string }).value })), fallback: node };
  const damage = of("damage").map((s) => ({ s, from: (s.when as { from: number }).from })).sort((a, b) => a.from - b.from);
  if (damage.length) node = { type: "minecraft:range_dispatch", property: "minecraft:damage", entries: damage.map((d) => ({ model: M(d.s.id), threshold: d.from })), fallback: node };
  const broken = of("broken")[0];
  if (broken) node = { type: "minecraft:condition", property: "minecraft:broken", on_true: M(broken.id), on_false: node };
  return vanillaOrder(node);
}

/** The whole items/<name>.json object. */
export function definitionJson(spec: ItemModelSpec, ref: (stateId: string) => string): Json {
  const pluginSet = (spec.states ?? []).some((s) => s.when.type === "mode" || s.when.type === "flag");
  const swap = spec.handAnimationOnSwap ?? !pluginSet;
  return vanillaOrder({ model: definitionNode(spec, ref), ...(swap ? {} : { hand_animation_on_swap: false }) });
}

export const stringify = (v: Json) => JSON.stringify(v, null, 2);

/** One display transform per context, Cyrus key order. */
const displayJson = (d: FullDisplay): Json => Object.fromEntries(DISPLAY_CONTEXTS.map((c) => [c, { rotation: [...d[c].rotation], translation: [...d[c].translation], scale: [...d[c].scale] }]));

export type EmittedFile = { path: string; text: string };

export type EmittedFile = { path: string; text: string };
export type EmittedItemModel = { name: string; model: string; files: EmittedFile[]; states: { id: string; texture: string; model: string }[]; needs: ItemModelNeeds; display: Record<string, FullDisplay> };
export type EmitResult = { ok: true; item: EmittedItemModel; warnings: ImIssue[] } | { ok: false; errors: ImIssue[] };

/** The model path of a state: idle = models/item/<name>, the others models/item/<name>/<state> (no clash with texture names, which have no "/"). */
export const modelRefOf = (ns: string, name: string, stateId: string) => (stateId === "idle" ? `${ns}:item/${name}` : `${ns}:item/${name}/${stateId}`);
export const modelPathOf = (ns: string, name: string, stateId: string) => (stateId === "idle" ? `assets/${ns}/models/item/${name}.json` : `assets/${ns}/models/item/${name}/${stateId}.json`);

/** The display of every state (idle + each state), as the pack writes it and the studio previews it. */
export function stateDisplays(spec: ItemModelSpec, idle?: Raster): Record<string, FullDisplay> {
  const base = mergeDisplay(categoryDisplay(spec.category, idle, spec.name), spec.display);
  return { idle: base, ...Object.fromEntries((spec.states ?? []).map((s) => [s.id, mergeDisplay(base, s.display)])) };
}

/** ItemModelSpec -> files. `idle` = the idle texture's raster (the gun category finds its grip on it). */
export function emitItemModel(raw: unknown, opts: { namespace: string; version: string; textures?: readonly string[]; idle?: Raster }): EmitResult {
  const v = validateItemModel(raw, { textures: opts.textures, version: opts.version });
  if (!v.ok) return { ok: false, errors: v.errors };
  const vv = itemModelVersionOk(opts.version);
  if (!vv.ok) return { ok: false, errors: [{ path: "(version)", code: "version", message: vv.error }] };
  const s = v.spec, ns = opts.namespace;
  const disp = stateDisplays(s, opts.idle);
  const texOf = (id: string) => (id === "idle" ? s.name : s.states!.find((x) => x.id === id)!.texture);
  const ids = ["idle", ...(s.states ?? []).map((x) => x.id)];
  const files: EmittedFile[] = [{ path: `assets/${ns}/items/${s.name}.json`, text: stringify(definitionJson(s, (id) => modelRefOf(ns, s.name, id))) }];
  for (const id of ids) files.push({ path: modelPathOf(ns, s.name, id), text: stringify({ parent: "minecraft:item/generated", textures: { layer0: `${ns}:item/${texOf(id)}` }, display: displayJson(disp[id]) }) });
  return {
    ok: true, warnings: v.warnings,
    item: { name: s.name, model: `${ns}:${s.name}`, files, states: ids.map((id) => ({ id, texture: texOf(id), model: modelRefOf(ns, s.name, id) })), needs: v.needs, display: disp },
  };
}

// ------------------------------------------------------------------------------------------------ the evaluator
/** What the client knows about one stack at render time (only the properties Cyrus emits, plus custom_model_data floats). */
export type ItemRenderInput = {
  context?: DisplayContext; using?: boolean; useTicks?: number; crossbowPull?: number; charge?: "arrow" | "rocket" | null;
  strings?: string[]; flags?: boolean[]; floats?: number[]; selected?: boolean; broken?: boolean; damage?: number;
};

/**
 * Walk a definition node (ours OR vanilla's) the way the client selects a model, for the properties above. Returns the
 * model id, or null for a node it does not understand (special/composite/other properties). Semantics per vanilla:
 * condition -> on_true/on_false; select -> the first case whose `when` (a value or a list) matches, else fallback;
 * range_dispatch -> the entry with the highest threshold <= value*scale, else fallback.
 */
export function evalNode(node: unknown, input: ItemRenderInput): string | null {
  const n = node as Record<string, unknown>;
  if (!n || typeof n !== "object") return null;
  switch (n.type) {
    case "minecraft:model": return String(n.model);
    case "minecraft:condition": {
      let v: boolean;
      switch (n.property) {
        case "minecraft:using_item": v = !!input.using; break;
        case "minecraft:selected": v = !!input.selected; break;
        case "minecraft:broken": v = !!input.broken; break;
        case "minecraft:custom_model_data": v = !!input.flags?.[Number(n.index ?? 0)]; break;
        default: return null;
      }
      return evalNode(v ? n.on_true : n.on_false, input);
    }
    case "minecraft:select": {
      let v: string | null;
      switch (n.property) {
        case "minecraft:display_context": v = input.context ?? "gui"; break;
        case "minecraft:charge_type": v = input.charge ?? "none"; break;
        case "minecraft:custom_model_data": v = input.strings?.[Number(n.index ?? 0)] ?? null; break;
        default: return null;
      }
      for (const c of (n.cases as { when: unknown; model: unknown }[]) ?? []) if (v !== null && (Array.isArray(c.when) ? c.when.includes(v) : c.when === v)) return evalNode(c.model, input);
      return evalNode(n.fallback, input);
    }
    case "minecraft:range_dispatch": {
      let v: number;
      switch (n.property) {
        case "minecraft:use_duration": v = input.using ? input.useTicks ?? 0 : 0; break;
        case "minecraft:crossbow/pull": v = input.crossbowPull ?? 0; break;
        case "minecraft:damage": v = input.damage ?? 0; break;
        case "minecraft:custom_model_data": v = input.floats?.[Number(n.index ?? 0)] ?? 0; break;
        default: return null;
      }
      v *= typeof n.scale === "number" ? n.scale : 1;
      const es = [...((n.entries as { threshold: number; model: unknown }[]) ?? [])].sort((a, b) => a.threshold - b.threshold);
      let pick: unknown = n.fallback;
      for (const e of es) if (e.threshold <= v) pick = e.model;
      return evalNode(pick, input);
    }
    default: return null;
  }
}

/** Which state of a spec shows for an input (the studio's state scrubber + tests). */
export function resolveState(spec: ItemModelSpec, input: ItemRenderInput): string {
  const r = evalNode(definitionNode(spec, (id) => id), input);
  return r ?? "idle";
}

/** A preview input that selects exactly this state (the studio scrubber): the cheapest input whose evaluation is the state. */
export function inputForState(spec: ItemModelSpec, stateId: string, context: DisplayContext): ItemRenderInput {
  const s = (spec.states ?? []).find((x) => x.id === stateId);
  const base: ItemRenderInput = { context };
  if (!s) return base;
  const w = s.when;
  const flagIdx = (spec.states ?? []).filter((x) => x.when.type === "flag").findIndex((x) => x.id === stateId);
  switch (w.type) {
    case "using": return { ...base, using: true, useTicks: 1 };
    case "pull": return w.source === "crossbow" ? { ...base, using: true, crossbowPull: w.from } : { ...base, using: true, useTicks: Math.ceil(w.from / USE_DURATION_SCALE) };
    case "charged": return { ...base, charge: w.charge };
    case "mode": return { ...base, strings: [w.value] };
    case "flag": return { ...base, flags: Array.from({ length: flagIdx + 1 }, (_, i) => i === flagIdx) };
    case "selected": return { ...base, selected: true };
    case "context": return { ...base, context: w.contexts.includes(context) ? context : w.contexts[0] };
    case "broken": return { ...base, broken: true };
    case "damage": return { ...base, damage: w.from };
  }
}
