/** Render the contact sheet as a square PNG (cell px each). Negative `time` = a fraction of the clip length. */
export function previewSheet(spec: RigSpec, layout: SkinLayout, skin: Raster, opts: { cell?: number; cells?: PreviewCell[] } = {}): { png: Buffer; raster: Raster } {
  const cells = opts.cells ?? DEFAULT_CELLS;
  const cols = Math.ceil(Math.sqrt(cells.length));
  const cellSize = opts.cell ?? 200;
  const size = cols * cellSize;
  const canvas: Raster = { size, px: new Uint8ClampedArray(size * size * 4) };
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const k = (y * size + x) * 4, cx = Math.floor(x / cellSize), cy = Math.floor(y / cellSize);
    const g = (cx + cy) % 2 ? 40 : 46;
    canvas.px[k] = g; canvas.px[k + 1] = g + 2; canvas.px[k + 2] = g + 10; canvas.px[k + 3] = 255;
  }
  // one fit for every cell (rest pose bounds over all view yaws) so sizes are comparable
  const mats = poseMatrices(spec);
  let minY = Infinity, maxY = -Infinity, maxR = 0;
  for (const b of spec.bones) for (const c of b.cubes) for (const x of [c.from[0], c.to[0]]) for (const y of [c.from[1], c.to[1]]) for (const z of [c.from[2], c.to[2]]) {
    const p = apply(mats.get(b.name)!, [x, y, z]).map((v) => v * spec.scale);
    minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]); maxR = Math.max(maxR, Math.hypot(p[0], p[2]));
  }
  const ext = Math.max(maxY - minY + 8 * spec.scale, 2 * maxR + 4);
  const fit = { k: (cellSize * 0.86) / ext, cx: 0, cy: (minY + maxY) / 2 + 2 * spec.scale };
  for (const [i, c] of cells.entries()) {
    const cell = { x: (i % cols) * cellSize, y: Math.floor(i / cols) * cellSize, size: cellSize };
    const len = c.clip ? spec.animations[c.clip]?.length ?? 1 : 1;
    const time = c.time != null && c.time < 0 ? -c.time * len : c.time;
    drawView(canvas, cell, spec, layout, skin, { yaw: c.yaw, pitch: c.pitch }, { clip: c.clip, time }, fit);
  }
  return { png: encodePng(canvas), raster: canvas };
}

/** The skin sheet scaled up (nearest neighbour) on a checkerboard, for review. */
export function skinSheetPng(skin: Raster, scale = 4): Buffer {
  const n = skin.size * scale;
  const out: Raster = { size: n, px: new Uint8ClampedArray(n * n * 4) };
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const k = (y * n + x) * 4, s = ((Math.floor(y / scale) * skin.size) + Math.floor(x / scale)) * 4;
    const chk = (Math.floor(x / 8) + Math.floor(y / 8)) % 2 ? 60 : 80;
    if (skin.px[s + 3]) { out.px[k] = skin.px[s]; out.px[k + 1] = skin.px[s + 1]; out.px[k + 2] = skin.px[s + 2]; }
    else { out.px[k] = chk; out.px[k + 1] = chk; out.px[k + 2] = chk; }
    out.px[k + 3] = 255;
  }
  return encodePng(out);
}
