export type { LibraryItem, TextureEntry, SaveResult, SoundSetEntry, SoundRenderView, SoundSaveResult };
export const API = "/api/cyrus/assets/v1";

export class ApiError extends Error { constructor(public status: number, public code: string, message: string, public body: Record<string, unknown>) { super(message); } }

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(API + path, { cache: "no-store", ...init, headers: { ...(init?.body && !(init.body instanceof FormData) ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
  return j as T;
}
const post = <T,>(path: string, body: unknown) => call<T>(path, { method: "POST", body: JSON.stringify(body) });

export const studioApi = {
  assets: (root: string) => call<AssetsView>(`/projects?root=${encodeURIComponent(root)}`),
  save: (projectId: string, key: string, body: { doc: TextureDoc; baseAssetId: string | null; expectedHeadId: string | null; acceptCandidate?: string }) => post<SaveResult>(`/projects/${projectId}/textures/${key}/revisions`, body),
  quality: (doc: TextureDoc) => post<QualityReport>(`/quality`, { doc }),
  requestCandidate: (projectId: string, key: string, prompt: string) => post<{ requestId: string; backend: string }>(`/projects/${projectId}/textures/${key}/candidates`, { prompt }),
  pollCandidate: (projectId: string, key: string, requestId: string) => call<CandidatePoll & { quality?: QualityReport }>(`/projects/${projectId}/textures/${key}/candidates/${requestId}`),
  rejectCandidate: (projectId: string, key: string, requestId: string, expectedHeadId: string | null) => post<SaveResult>(`/projects/${projectId}/textures/${key}/candidates/${requestId}/reject`, { expectedHeadId }),
  browse: (q: Record<string, string | number | undefined>) => call<{ total: number; items: LibraryItem[]; facets: { category: Record<string, number>; subcategory: Record<string, number>; descriptors: Record<string, Record<string, number>> }; denied: { kind: string; source: string; code: string; reason: string; needs?: string }[]; offset: number; limit: number }>(
    `/library?${new URLSearchParams(Object.entries(q).filter(([, v]) => v !== undefined && v !== "").map(([k, v]) => [k, String(v)])).toString()}`),
  use: (body: { projectId: string; ref: string; key: string; expectedHeadId: string | null }) => post<SaveResult>(`/library/use`, body),
  upload: (form: FormData) => call<{ assetId: string }>(`/library/upload`, { method: "POST", body: form }),
  // Sound Studio
  saveSound: (projectId: string, set: string, body: { spec: SoundSpec; baseAssetId: string | null; expectedHeadId: string | null; acceptCandidate?: string; mode?: Exclude<SoundDecision["mode"], "reject"> }) => post<SoundSaveResult>(`/projects/${projectId}/sounds/${set}/revisions`, body),
  renderSound: (projectId: string, set: string, spec: SoundSpec, event: string) => post<SoundRenderView>(`/projects/${projectId}/sounds/${set}/render`, { spec, event }),
  requestSoundCandidate: (projectId: string, set: string, event: string, prompt: string) => post<{ requestId: string; backend: string }>(`/projects/${projectId}/sounds/${set}/candidates`, { event, prompt }),
  pollSoundCandidate: (projectId: string, set: string, requestId: string) => call<SoundCandidatePoll>(`/projects/${projectId}/sounds/${set}/candidates/${requestId}`),
  rejectSoundCandidate: (projectId: string, set: string, requestId: string, expectedHeadId: string | null) => post<SoundSaveResult>(`/projects/${projectId}/sounds/${set}/candidates/${requestId}/reject`, { expectedHeadId }),
  useSound: (body: { projectId: string; ref: string; key: string; event: string }) => post<{ layer: SoundLayer; identifier: string }>(`/library/use`, { ...body, expectedHeadId: null }),
  /** a short processed WAV of one library layer (403 library_not_cleared while the licence is open) */
  preview: async (r: PreviewRequest): Promise<ArrayBuffer> => {
    const res = await fetch(API + "/sound/preview", { method: "POST", cache: "no-store", headers: { "content-type": "application/json" }, body: JSON.stringify(r) });
    if (!res.ok) { const j = (await res.json().catch(() => ({}))) as Record<string, unknown>; throw new ApiError(res.status, String(j.code ?? res.status), String(j.error ?? "No preview."), j); }
    return res.arrayBuffer();
  },
};
