type Cand = { requestId: string; status: "pending" | "ready" | "failed"; doc?: TextureDoc; summary: string; picks: Record<number, boolean>; show: boolean; error?: string; persisted: boolean };
type Ed = { entry: TextureEntry; hist: History<Layers>; vis: Visibility; dirty: boolean; accepted: string | null; cand: Cand | null; layer: "paint" | "base" };
type Backdrop = "checker" | "dark" | "light";
type CmpMode = "split" | "onion" | "diff" | "after";

const layersOf = (doc: TextureDoc): Layers => { const b = paintToBuffers(doc.size, doc.paint); return { spec: doc.spec, size: doc.size, paint: b.rgba, cut: b.cut }; };
const docOf = (key: string, l: Layers, tile: TextureDoc["tile"]): TextureDoc => ({ v: 1, name: key, size: l.size as TextureDoc["size"], spec: l.spec, paint: paintFromBuffers(l.size as TextureDoc["size"], l.paint, l.cut), ...(tile ? { tile } : {}) });
const qOf = (r: Raster, tile: TextureDoc["tile"]) => textureQuality(r, tile ? { profile: "tile", tileable: tile.tileable, framed: tile.framed } : {});
const vClass = (v: string) => (v === "pass" ? "ok" : v === "warn" ? "warn" : v === "fail" ? "bad" : "dim");
const kindOf = (e: TextureEntry) => (e.doc.tile ? "block texture" : "item texture");
function edFor(entry: TextureEntry, label: string, summaries: Record<string, string> = {}): Ed {
  const c = entry.candidates[entry.candidates.length - 1];
  return {
    entry, hist: historyInit(label, layersOf(entry.doc)), vis: { ...ALL_VISIBLE }, dirty: false, accepted: null, layer: "paint",
    cand: c ? { requestId: c.buildId, status: "ready", doc: c.doc, summary: summaries[c.buildId] ?? "Cyrus edit from a change build", picks: {}, show: false, persisted: true } : null,
  };
}

