/** Orbit camera (y up): yaw around +y, pitch up, distance from the target; vertical fov in degrees. */
export type OrbitCam = { yaw: number; pitch: number; dist: number; target: V3; fov: number };

export function camEye(c: OrbitCam): V3 {
  const y = rad(c.yaw), p = rad(c.pitch);
  return [c.target[0] + c.dist * Math.cos(p) * Math.sin(y), c.target[1] + c.dist * Math.sin(p), c.target[2] + c.dist * Math.cos(p) * Math.cos(y)];
}

/**
 * The ray through pixel (px, py) of a W x H viewport (pixel centres at +0.5), perspective, for an orbit camera.
 * The same ray three.js's Raycaster.setFromCamera gives for a PerspectiveCamera at camEye looking at the target.
 */
export function rayFromOrbit(c: OrbitCam, px: number, py: number, W: number, H: number): Ray {
  const eye = camEye(c);
  const f = norm3(sub3(c.target, eye));
  const up: V3 = Math.abs(f[1]) > 0.999 ? [0, 0, -Math.sign(f[1])] : [0, 1, 0];
  const r = norm3(cross3(f, up)), u = cross3(r, f);
  const t = Math.tan(rad(c.fov) / 2);
  const nx = (2 * px) / W - 1, ny = 1 - (2 * py) / H;
  const d = norm3(add3(f, add3(scale3(r, nx * t * (W / H)), scale3(u, ny * t))));
  return { o: eye, d };
}

