export function m4FromTrs(t: V3 = [0, 0, 0], q: [number, number, number, number] = [0, 0, 0, 1], s: V3 = [1, 1, 1]): M4 {
  const [x, y, z, w] = q;
  const xx = x * x, yy = y * y, zz = z * z, xy = x * y, xz = x * z, yz = y * z, wx = w * x, wy = w * y, wz = w * z;
  return [
    (1 - 2 * (yy + zz)) * s[0], 2 * (xy + wz) * s[0], 2 * (xz - wy) * s[0], 0,
    2 * (xy - wz) * s[1], (1 - 2 * (xx + zz)) * s[1], 2 * (yz + wx) * s[1], 0,
    2 * (xz + wy) * s[2], 2 * (yz - wx) * s[2], (1 - 2 * (xx + yy)) * s[2], 0,
    t[0], t[1], t[2], 1,
  ];
}

export const add3 = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const sub3 = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
export const scale3 = (a: V3, k: number): V3 => [a[0] * k, a[1] * k, a[2] * k];
export const dot3 = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross3 = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
export const len3 = (a: V3) => Math.hypot(a[0], a[1], a[2]);
export const norm3 = (a: V3): V3 => { const l = len3(a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };

export type Ray = { o: V3; d: V3 };

/**
 * Ray / triangle (Moller-Trumbore, two-sided). Returns the distance t and the barycentric weights of B and C
 * (u, v; A = 1 - u - v), or null. `eps` rejects grazing hits; points ON an edge count as inside (u, v >= 0).
 */
export function rayTri(r: Ray, a: V3, b: V3, c: V3, eps = 1e-9): { t: number; u: number; v: number } | null {
  const e1 = sub3(b, a), e2 = sub3(c, a);
  const p = cross3(r.d, e2);
  const det = dot3(e1, p);
  if (Math.abs(det) < eps) return null;
  const inv = 1 / det;
  const s = sub3(r.o, a);
  const u = dot3(s, p) * inv;
  if (u < -1e-12 || u > 1 + 1e-12) return null;
  const q = cross3(s, e1);
  const v = dot3(r.d, q) * inv;
  if (v < -1e-12 || u + v > 1 + 1e-12) return null;
  const t = dot3(e2, q) * inv;
  if (t <= eps) return null;
  return { t, u, v };
}

/** Barycentric weights [wa, wb, wc] of point p in triangle abc (p assumed on the plane). */
export function barycentric(p: V3, a: V3, b: V3, c: V3): V3 {
  const v0 = sub3(b, a), v1 = sub3(c, a), v2 = sub3(p, a);
  const d00 = dot3(v0, v0), d01 = dot3(v0, v1), d11 = dot3(v1, v1), d20 = dot3(v2, v0), d21 = dot3(v2, v1);
  const den = d00 * d11 - d01 * d01 || 1;
  const v = (d11 * d20 - d01 * d21) / den, w = (d00 * d21 - d01 * d20) / den;
  return [1 - v - w, v, w];
}

/** Interpolate a UV from the three corner UVs with barycentric weights. */
export const lerpUv = (w: V3, a: V2, b: V2, c: V2): V2 => [w[0] * a[0] + w[1] * b[0] + w[2] * c[0], w[0] * a[1] + w[1] * b[1] + w[2] * c[1]];

/**
 * UV -> texel. Convention (glTF, and our box UVs): (0, 0) = the TOP-LEFT of the image, v grows downward; texel x =
 * floor(u * w). `wrap` = glTF REPEAT (u mod 1); otherwise clamped. A UV exactly on the right/bottom edge (u = 1) is
 * the last texel. A tiny epsilon keeps a UV that is mathematically on a texel border (bary interpolation of an exact
 * edge) on the texel it belongs to.
 */
export function uvToTexel(uv: V2, w: number, h: number, wrap = false): V2 {
  let u = uv[0], v = uv[1];
  if (wrap) { u -= Math.floor(u); v -= Math.floor(v); }
  const x = Math.floor(u * w + 1e-7), y = Math.floor(v * h + 1e-7);
  return [Math.max(0, Math.min(w - 1, x)), Math.max(0, Math.min(h - 1, y))];
}

/** Inverse of a general 4x4 (column-major); null when singular. */
export function invert4(m: M4): M4 | null {
  const a = m, inv = new Array<number>(16);
  inv[0] = a[5] * a[10] * a[15] - a[5] * a[11] * a[14] - a[9] * a[6] * a[15] + a[9] * a[7] * a[14] + a[13] * a[6] * a[11] - a[13] * a[7] * a[10];
  inv[4] = -a[4] * a[10] * a[15] + a[4] * a[11] * a[14] + a[8] * a[6] * a[15] - a[8] * a[7] * a[14] - a[12] * a[6] * a[11] + a[12] * a[7] * a[10];
  inv[8] = a[4] * a[9] * a[15] - a[4] * a[11] * a[13] - a[8] * a[5] * a[15] + a[8] * a[7] * a[13] + a[12] * a[5] * a[11] - a[12] * a[7] * a[9];
  inv[12] = -a[4] * a[9] * a[14] + a[4] * a[10] * a[13] + a[8] * a[5] * a[14] - a[8] * a[6] * a[13] - a[12] * a[5] * a[10] + a[12] * a[6] * a[9];
  inv[1] = -a[1] * a[10] * a[15] + a[1] * a[11] * a[14] + a[9] * a[2] * a[15] - a[9] * a[3] * a[14] - a[13] * a[2] * a[11] + a[13] * a[3] * a[10];
  inv[5] = a[0] * a[10] * a[15] - a[0] * a[11] * a[14] - a[8] * a[2] * a[15] + a[8] * a[3] * a[14] + a[12] * a[2] * a[11] - a[12] * a[3] * a[10];
  inv[9] = -a[0] * a[9] * a[15] + a[0] * a[11] * a[13] + a[8] * a[1] * a[15] - a[8] * a[3] * a[13] - a[12] * a[1] * a[11] + a[12] * a[3] * a[9];
  inv[13] = a[0] * a[9] * a[14] - a[0] * a[10] * a[13] - a[8] * a[1] * a[14] + a[8] * a[2] * a[13] + a[12] * a[1] * a[10] - a[12] * a[2] * a[9];
  inv[2] = a[1] * a[6] * a[15] - a[1] * a[7] * a[14] - a[5] * a[2] * a[15] + a[5] * a[3] * a[14] + a[13] * a[2] * a[7] - a[13] * a[3] * a[6];
  inv[6] = -a[0] * a[6] * a[15] + a[0] * a[7] * a[14] + a[4] * a[2] * a[15] - a[4] * a[3] * a[14] - a[12] * a[2] * a[7] + a[12] * a[3] * a[6];
  inv[10] = a[0] * a[5] * a[15] - a[0] * a[7] * a[13] - a[4] * a[1] * a[15] + a[4] * a[3] * a[13] + a[12] * a[1] * a[7] - a[12] * a[3] * a[5];
  inv[14] = -a[0] * a[5] * a[14] + a[0] * a[6] * a[13] + a[4] * a[1] * a[14] - a[4] * a[2] * a[13] - a[12] * a[1] * a[6] + a[12] * a[2] * a[5];
  inv[3] = -a[1] * a[6] * a[11] + a[1] * a[7] * a[10] + a[5] * a[2] * a[11] - a[5] * a[3] * a[10] - a[9] * a[2] * a[7] + a[9] * a[3] * a[6];
  inv[7] = a[0] * a[6] * a[11] - a[0] * a[7] * a[10] - a[4] * a[2] * a[11] + a[4] * a[3] * a[10] + a[8] * a[2] * a[7] - a[8] * a[3] * a[6];
  inv[11] = -a[0] * a[5] * a[11] + a[0] * a[7] * a[9] + a[4] * a[1] * a[11] - a[4] * a[3] * a[9] - a[8] * a[1] * a[7] + a[8] * a[3] * a[5];
  inv[15] = a[0] * a[5] * a[10] - a[0] * a[6] * a[9] - a[4] * a[1] * a[10] + a[4] * a[2] * a[9] + a[8] * a[1] * a[6] - a[8] * a[2] * a[5];
  const det = a[0] * inv[0] + a[1] * inv[4] + a[2] * inv[8] + a[3] * inv[12];
  if (!det || !Number.isFinite(det)) return null;
  return inv.map((v) => v / det);
}

/** Orbit camera (y up): yaw around +y, pitch up, distance from the target; vertical fov in degrees. */
export type OrbitCam = { yaw: number; pitch: number; dist: number; target: V3; fov: number };

export function camEye(c: OrbitCam): V3 {
  const y = rad(c.yaw), p = rad(c.pitch);
  return [c.target[0] + c.dist * Math.cos(p) * Math.sin(y), c.target[1] + c.dist * Math.sin(p), c.target[2] + c.dist * Math.cos(p) * Math.cos(y)];
}

/**
 * The ray through pixel (px, py) of a W x H viewport (pixel centres at +0.5), perspective, for an orbit camera.
 * The same ray three.js's Raycaster.setFromCamera gives for a PerspectiveCamera at camEye looking at the target.
 */
export function rayFromOrbit(c: OrbitCam, px: number, py: number, W: number, H: number): Ray {
  const eye = camEye(c);
  const f = norm3(sub3(c.target, eye));
  const up: V3 = Math.abs(f[1]) > 0.999 ? [0, 0, -Math.sign(f[1])] : [0, 1, 0];
  const r = norm3(cross3(f, up)), u = cross3(r, f);
  const t = Math.tan(rad(c.fov) / 2);
  const nx = (2 * px) / W - 1, ny = 1 - (2 * py) / H;
  const d = norm3(add3(f, add3(scale3(r, nx * t * (W / H)), scale3(u, ny * t))));
  return { o: eye, d };
}

