// Cyrus Model Studio: a small, bounded glTF 2.0 reader (GLB, or .gltf JSON with embedded data: URIs) for the Layer 1
// viewport, and a minimal GLB writer for fixtures. Pure + client-safe (no DOM, no node: imports). The input is
// UNTRUSTED (an AI-mesh worker output or, later, a user template): every offset and count is bounds-checked before it
// is read, sizes are capped BEFORE copying, external URIs are refused (no network, no file references), and every
// failure is a structured error, never a throw. Only what Layer 1 needs is read: triangle positions, TEXCOORD_0,
// indices, the node hierarchy of the default scene and the base-colour image of the first textured material.
// Accepted: float32 positions/UVs; uint8/uint16/uint32 indices; mode 4 (triangles). Refused with a reason: sparse
// accessors, quantised UVs, Draco/meshopt compression (required extensions), more than MAX_TRIANGLES.
import { I4, m4From, m4FromTrs, mul4, type M4, type V3 } from "./math";

export const GLTF_LIMITS = { maxBytes: 32 * 1024 * 1024, maxTriangles: 150_000, maxNodes: 2048, maxDepth: 32, maxMeshes: 512, maxImageBytes: 16 * 1024 * 1024 } as const;

export type GltfMesh = { name: string; pos: Float32Array; uv: Float32Array | null; idx: Uint32Array; matrix: M4; material: number | null };
export type GltfImage = { mime: string; bytes: Uint8Array; w: number | null; h: number | null };
export type GltfParsed = {
  meshes: GltfMesh[];
  images: GltfImage[];
  /** index into images of the first material with a base colour texture */
  baseColorImage: number | null;
  /** sampler wrap of that texture: true = REPEAT (glTF default) */
  wrap: boolean;
  triCount: number;
  warnings: string[];
};
export type GltfResult = { ok: true; gltf: GltfParsed } | { ok: false; code: string; error: string };

type J = Record<string, unknown>;
const obj = (v: unknown): J => (v && typeof v === "object" && !Array.isArray(v) ? (v as J) : {});
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const int = (v: unknown, lo = 0, hi = Number.MAX_SAFE_INTEGER): number | null => (typeof v === "number" && Number.isInteger(v) && v >= lo && v <= hi ? v : null);
const fail = (code: string, error: string): GltfResult => ({ ok: false, code, error });

const COMP: Record<number, { bytes: number; read: (dv: DataView, o: number) => number }> = {
  5121: { bytes: 1, read: (dv, o) => dv.getUint8(o) },
  5123: { bytes: 2, read: (dv, o) => dv.getUint16(o, true) },
  5125: { bytes: 4, read: (dv, o) => dv.getUint32(o, true) },
  5126: { bytes: 4, read: (dv, o) => dv.getFloat32(o, true) },
};
const WIDTH: Record<string, number> = { SCALAR: 1, VEC2: 2, VEC3: 3, VEC4: 4 };

/** PNG / JPEG pixel size from the header bytes only (no decoding). */
export function imageSize(b: Uint8Array): { w: number; h: number } | null {
  if (b.length >= 24 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) {
    const dv = new DataView(b.buffer, b.byteOffset, b.byteLength);
    return { w: dv.getUint32(16), h: dv.getUint32(20) };
  }
  if (b.length > 4 && b[0] === 0xff && b[1] === 0xd8) {
    let o = 2;
    while (o + 9 < b.length) {
      if (b[o] !== 0xff) return null;
      const m = b[o + 1], l = (b[o + 2] << 8) | b[o + 3];
      if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) return { h: (b[o + 5] << 8) | b[o + 6], w: (b[o + 7] << 8) | b[o + 8] };
      o += 2 + l;
    }
  }
  return null;
}

function b64ToBytes(s: string): Uint8Array | null {
  try {
    if (typeof atob === "function") { const bin = atob(s); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
  } catch { return null; }
  return null;
}

/** Parse a GLB container or a .gltf JSON (UTF-8 bytes) with data: URI buffers. */
export function parseGltf(input: Uint8Array): GltfResult {
  if (input.byteLength > GLTF_LIMITS.maxBytes) return fail("too_large", `the model is ${input.byteLength} bytes; the limit is ${GLTF_LIMITS.maxBytes}`);
  const dv = new DataView(input.buffer, input.byteOffset, input.byteLength);
  let json: J;
  let bin: Uint8Array | null = null;
  if (input.byteLength >= 12 && dv.getUint32(0, true) === 0x46546c67) {
    if (dv.getUint32(4, true) !== 2) return fail("bad_version", "only glTF 2.0 is supported");
    const total = dv.getUint32(8, true);
    if (total > input.byteLength) return fail("truncated", "the GLB is shorter than its header says");
    let o = 12, jsonText: string | null = null;
    while (o + 8 <= total) {
      const len = dv.getUint32(o, true), type = dv.getUint32(o + 4, true);
      if (o + 8 + len > total) return fail("truncated", "a GLB chunk runs past the end");
      const body = input.subarray(o + 8, o + 8 + len);
      if (type === 0x4e4f534a && jsonText === null) jsonText = new TextDecoder().decode(body);
      else if (type === 0x004e4942 && !bin) bin = body;
      o += 8 + len + ((4 - (len % 4)) % 4);
    }
    if (jsonText === null) return fail("no_json", "the GLB has no JSON chunk");
    try { json = obj(JSON.parse(jsonText)); } catch { return fail("bad_json", "the GLB JSON chunk is not valid JSON"); }
  } else {
    try { json = obj(JSON.parse(new TextDecoder().decode(input))); } catch { return fail("not_gltf", "not a GLB or glTF JSON file"); }
  }
  if (String(obj(json.asset).version ?? "").split(".")[0] !== "2") return fail("bad_version", "only glTF 2.0 is supported");
  const required = arr(json.extensionsRequired).map(String);
  if (required.length) return fail("extension_required", `required extensions are not supported: ${required.slice(0, 4).join(", ")}`);

  const warnings: string[] = [];
  // buffers: [0] may be the GLB BIN chunk; others must be data: URIs
  const buffers: (Uint8Array | null)[] = arr(json.buffers).map((b, i) => {
    const uri = obj(b).uri;
    if (uri === undefined) return i === 0 ? bin : null;
    if (typeof uri === "string") {
      const m = /^data:[a-z/+.-]*;base64,([A-Za-z0-9+/=]+)$/.exec(uri);
      if (m) return b64ToBytes(m[1]);
    }
    return null; // external file / http URI: refused (no network, no file references)
  });
  const views = arr(json.bufferViews).map(obj);
  const viewBytes = (vi: number): Uint8Array | null => {
    const v = views[vi];
    if (!v) return null;
    const buf = buffers[int(v.buffer) ?? -1];
    const off = int(v.byteOffset ?? 0), len = int(v.byteLength, 1);
    if (!buf || off === null || len === null || off + len > buf.byteLength) return null;
    return buf.subarray(off, off + len);
  };
  const accessors = arr(json.accessors).map(obj);
  const readAccessor = (ai: unknown, want: string[], comps: number[]): { data: number[] | Float32Array | Uint32Array; width: number; count: number } | string => {
    const a = accessors[int(ai) ?? -1];
    if (!a) return "missing accessor";
    if (a.sparse) return "sparse accessors are not supported";
    const type = String(a.type), width = WIDTH[type], ct = int(a.componentType), count = int(a.count, 1, 10_000_000);
    if (!want.includes(type) || ct === null || !comps.includes(ct) || !width || count === null) return `accessor of type ${type}/${ct} is not supported here`;
    if (a.normalized === true && ct !== 5126) return "quantised (normalized) attributes are not supported";
    const c = COMP[ct];
    const bv = viewBytes(int(a.bufferView) ?? -1);
    if (!bv) return "accessor has no readable buffer view";
    const stride = int(views[int(a.bufferView)!].byteStride ?? 0) || width * c.bytes;
    const off = int(a.byteOffset ?? 0) ?? -1;
    if (off < 0 || off + stride * (count - 1) + width * c.bytes > bv.byteLength) return "accessor runs past its buffer view";
    const d = new DataView(bv.buffer, bv.byteOffset, bv.byteLength);
    const out = ct === 5126 ? new Float32Array(count * width) : new Uint32Array(count * width);
    for (let i = 0; i < count; i++) for (let k = 0; k < width; k++) out[i * width + k] = c.read(d, off + i * stride + k * c.bytes);
    return { data: out, width, count };
  };

  // the default scene's node tree (or every root node when there is no scene)
  const nodes = arr(json.nodes).map(obj);
  if (nodes.length > GLTF_LIMITS.maxNodes) return fail("too_many_nodes", `more than ${GLTF_LIMITS.maxNodes} nodes`);
  const scenes = arr(json.scenes).map(obj);
  const sceneIdx = int(json.scene) ?? 0;
  let roots = arr(scenes[sceneIdx]?.nodes).map((n) => int(n)).filter((n): n is number => n !== null && n < nodes.length);
  if (!scenes.length) { const child = new Set(nodes.flatMap((n) => arr(n.children).map((c) => int(c)))); roots = nodes.map((_, i) => i).filter((i) => !child.has(i)); }
  const meshesJ = arr(json.meshes).map(obj);
  const out: GltfMesh[] = [];
  let tris = 0;
  const seen = new Set<number>();
  const walk = (ni: number, parent: M4, depth: number): string | null => {
    if (depth > GLTF_LIMITS.maxDepth) return "the node tree is too deep";
    if (seen.has(ni)) return "the node tree has a cycle or a node used twice";
    seen.add(ni);
    const n = nodes[ni];
    const local = Array.isArray(n.matrix) && n.matrix.length === 16 && n.matrix.every((x) => typeof x === "number") ? m4From(n.matrix as number[])
      : m4FromTrs(arr(n.translation).length === 3 ? (n.translation as V3) : undefined, arr(n.rotation).length === 4 ? (n.rotation as [number, number, number, number]) : undefined, arr(n.scale).length === 3 ? (n.scale as V3) : undefined);
    const world = mul4(parent, local);
    const mi = int(n.mesh);
    if (mi !== null && meshesJ[mi]) {
      for (const [pi, pr] of arr(meshesJ[mi].primitives).map(obj).entries()) {
        const mode = int(pr.mode ?? 4);
        if (mode !== 4) { warnings.push(`mesh ${mi} primitive ${pi}: mode ${mode} is not triangles; skipped`); continue; }
        const at = obj(pr.attributes);
        const pos = readAccessor(at.POSITION, ["VEC3"], [5126]);
        if (typeof pos === "string") return `mesh ${mi}: POSITION ${pos}`;
        let uv: Float32Array | null = null;
        if (at.TEXCOORD_0 !== undefined) {
          const u = readAccessor(at.TEXCOORD_0, ["VEC2"], [5126]);
          if (typeof u === "string") return `mesh ${mi}: TEXCOORD_0 ${u}`;
          if (u.count !== pos.count) return `mesh ${mi}: TEXCOORD_0 count differs from POSITION`;
          uv = u.data as Float32Array;
        } else warnings.push(`mesh ${mi} primitive ${pi} has no UVs; it cannot be painted`);
        let idx: Uint32Array;
        if (pr.indices !== undefined) {
          const ix = readAccessor(pr.indices, ["SCALAR"], [5121, 5123, 5125]);
          if (typeof ix === "string") return `mesh ${mi}: indices ${ix}`;
          idx = ix.data as Uint32Array;
          if (idx.length % 3) return `mesh ${mi}: index count is not a multiple of 3`;
          for (let i = 0; i < idx.length; i++) if (idx[i] >= pos.count) return `mesh ${mi}: an index points past the vertex list`;
        } else {
          if (pos.count % 3) return `mesh ${mi}: vertex count is not a multiple of 3`;
          idx = Uint32Array.from({ length: pos.count }, (_, i) => i);
        }
        tris += idx.length / 3;
        if (tris > GLTF_LIMITS.maxTriangles) return `more than ${GLTF_LIMITS.maxTriangles} triangles (the viewport budget)`;
        if (out.length >= GLTF_LIMITS.maxMeshes) return `more than ${GLTF_LIMITS.maxMeshes} mesh primitives`;
        out.push({ name: String(meshesJ[mi].name ?? `mesh_${mi}`).slice(0, 48), pos: pos.data as Float32Array, uv, idx, matrix: world, material: int(pr.material) });
      }
    }
    for (const c of arr(n.children)) { const ci = int(c); if (ci === null || ci >= nodes.length) return "a node child is out of range"; const e = walk(ci, world, depth + 1); if (e) return e; }
    return null;
  };
  for (const r of roots) { const e = walk(r, I4(), 0); if (e) return fail("bad_mesh", e); }
  if (!out.length) return fail("no_triangles", "the model has no triangle meshes");

  // images (bufferView or data: URI), and the first textured material's base colour
  const images: GltfImage[] = arr(json.images).map(obj).map((im) => {
    let bytes: Uint8Array | null = null;
    const bvi = int(im.bufferView);
    if (bvi !== null) bytes = viewBytes(bvi);
