  quad(p: [V3, V3, V3, V3], u: [V2, V2, V2, V2], part: number, f: SceneFace) {
    for (const [a, b, c] of [[0, 1, 2], [0, 2, 3]]) {
      this.pos.push(...p[a], ...p[b], ...p[c]);
      this.uv.push(...u[a], ...u[b], ...u[c]);
      this.part.push(part); this.face.push(faceIdx(f));
    }
  }
  done(kind: ModelKind, name: string, tex: ModelScene["tex"], parts: ScenePart[], regions: Record<string, Spans>, mirrorX: number | null, extra: Partial<ModelScene> = {}): ModelScene {
    const pos = Float32Array.from(this.pos);
