// Cyrus Model Studio (Layer 1): 3D pick -> UV -> texel. Pure + client-safe, golden-tested (test/cyrus-modelstudio.test.ts).
// pickScene casts a ray against every triangle (two-sided Moller-Trumbore, ./math.ts), keeps the NEAREST hit (ties:
// the lower triangle index, so the answer never depends on iteration quirks), interpolates the UV with the
// barycentric weights and floors it to a texel (./math.ts uvToTexel: (0,0) = top-left). Brute force is inside the
// budget: <= 150k triangles is a few ms per pointer move (measured in the test log), cuboid models are trivial.
import { add3, barycentric, lerpUv, rayTri, scale3, sub3, uvToTexel, type Ray, type V2, type V3 } from "./math";
import { SCENE_FACES, triPos, triUv, type ModelScene, type SceneFace, type Spans } from "./scene";

export type Hit = {
  tri: number;
  t: number;
  point: V3;
  /** barycentric weights of the triangle's corners A, B, C */
  bary: V3;
  uv: V2;
  texel: V2;
  part: number;
  face: SceneFace;
};

export type PickOpts = {
  /** item3d: alpha of a texel; a transparent texel is not part of the item, so the ray passes through it */
  alphaAt?: (x: number, y: number) => number;
};

export function pickScene(s: ModelScene, r: Ray, o: PickOpts = {}): Hit | null {
  const cand: { tri: number; t: number; u: number; v: number }[] = [];
  for (let t = 0; t < s.triCount; t++) {
    const [a, b, c] = triPos(s, t);
    const h = rayTri(r, a, b, c);
    if (h) cand.push({ tri: t, ...h });
  }
  cand.sort((x, y) => x.t - y.t || x.tri - y.tri);
  for (const h of cand) {
    const hit = hitOf(s, r, h);
    if (o.alphaAt && s.kind === "item3d" && hit.face !== "edge" && o.alphaAt(hit.texel[0], hit.texel[1]) === 0) continue;
    return hit;
  }
  return null;
}

function hitOf(s: ModelScene, r: Ray, h: { tri: number; t: number; u: number; v: number }): Hit {
  const bary: V3 = [1 - h.u - h.v, h.u, h.v];
  const [ua, ub, uc] = triUv(s, h.tri);
  const uv = lerpUv(bary, ua, ub, uc);
  return { tri: h.tri, t: h.t, point: add3(r.o, scale3(r.d, h.t)), bary, uv, texel: uvToTexel(uv, s.tex.w, s.tex.h, s.tex.wrap), part: s.part[h.tri], face: SCENE_FACES[s.face[h.tri]] };
}

/** Texel of a known surface point on a known triangle (the golden cases use this as the inverse of pick). */
export function texelAt(s: ModelScene, tri: number, p: V3): V2 {
  const [a, b, c] = triPos(s, tri);
  const [ua, ub, uc] = triUv(s, tri);
  return uvToTexel(lerpUv(barycentric(p, a, b, c), ua, ub, uc), s.tex.w, s.tex.h, s.tex.wrap);
}

/**
 * Mirror (X): the same brush on the other side of the model. The hit point and the ray are reflected across the
 * plane x = scene.mirrorX and cast again, so the mirrored texel is wherever the OTHER side's UVs put it (cube nets
 * are not mirrored in UV space, so a texel-space flip would be wrong). Null when the reflected ray hits nothing.
 */
export function mirrorHit(s: ModelScene, r: Ray, h: Hit, o: PickOpts = {}): Hit | null {
  const m = s.mirrorX;
  const flip = (p: V3): V3 => [2 * m - p[0], p[1], p[2]];
  const p = flip(h.point);
  const d: V3 = [-r.d[0], r.d[1], r.d[2]];
  // start just in front of the reflected point, so the hit is the mirrored surface, not something between
  const back = Math.max(1e-3, h.t * 0.01);
  const hit = pickScene(s, { o: sub3(p, scale3(d, back)), d }, o);
  return hit && Math.abs(hit.t - back) < Math.max(1e-3, back * 0.5) ? hit : hit && hit.t < back * 4 ? hit : null;
}

// ------------------------------------------------------------------------------------------------ regions

const key = (h: Pick<Hit, "part" | "face">) => `${h.part}:${SCENE_FACES.indexOf(h.face)}`;

/** Rasterise triangles (in texel space) into row spans: a texel is inside when its centre is (top-left rule-free, inclusive edges). */
export function rasterTris(tris: [V2, V2, V2][], w: number, h: number): Spans {
  const rows = new Map<number, Uint8Array>();
  for (const [a, b, c] of tris) {
    const P = [a, b, c].map(([u, v]) => [u * w, v * h] as V2);
    const y0 = Math.max(0, Math.floor(Math.min(P[0][1], P[1][1], P[2][1]))), y1 = Math.min(h - 1, Math.ceil(Math.max(P[0][1], P[1][1], P[2][1])));
    const x0 = Math.max(0, Math.floor(Math.min(P[0][0], P[1][0], P[2][0]))), x1 = Math.min(w - 1, Math.ceil(Math.max(P[0][0], P[1][0], P[2][0])));
    const e = (p: V2, q: V2, x: number, y: number) => (q[0] - p[0]) * (y - p[1]) - (q[1] - p[1]) * (x - p[0]);
    const area = e(P[0], P[1], P[2][0], P[2][1]);
    if (!area) continue;
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
      const cx = x + 0.5, cy = y + 0.5;
      const w0 = e(P[1], P[2], cx, cy) * Math.sign(area), w1 = e(P[2], P[0], cx, cy) * Math.sign(area), w2 = e(P[0], P[1], cx, cy) * Math.sign(area);
      if (w0 >= 0 && w1 >= 0 && w2 >= 0) { let row = rows.get(y); if (!row) rows.set(y, (row = new Uint8Array(w))); row[x] = 1; }
    }
  }
  return rowsToSpans(rows, w);
}

export function rowsToSpans(rows: Map<number, Uint8Array>, w: number): Spans {
  const out: Spans = [];
  for (const y of [...rows.keys()].sort((a, b) => a - b)) {
    const row = rows.get(y)!;
    let x = 0;
    while (x < w) { if (!row[x]) { x++; continue; } const s0 = x; while (x < w && row[x]) x++; out.push([y, s0, x]); }
  }
  return out;
}

/** UV islands of a mesh: triangles joined when they share an edge with the same UVs (cached per scene). */
const islandCache = new WeakMap<ModelScene, Int32Array>();
export function uvIslands(s: ModelScene): Int32Array {
  const hit = islandCache.get(s);
  if (hit) return hit;
  const parent = Int32Array.from({ length: s.triCount }, (_, i) => i);
  const find = (i: number): number => { while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; } return i; };
  const q = (v: number) => Math.round(v * 1e5);
  const vkey = (t: number, k: number) => `${q(s.pos[t * 9 + k * 3])},${q(s.pos[t * 9 + k * 3 + 1])},${q(s.pos[t * 9 + k * 3 + 2])}/${q(s.uv[t * 6 + k * 2])},${q(s.uv[t * 6 + k * 2 + 1])}`;
  const edges = new Map<string, number>();
  for (let t = 0; t < s.triCount; t++) {
    const ks = [vkey(t, 0), vkey(t, 1), vkey(t, 2)];
    for (const [i, j] of [[0, 1], [1, 2], [2, 0]]) {
      const e = ks[i] < ks[j] ? `${ks[i]}|${ks[j]}` : `${ks[j]}|${ks[i]}`;
      const o = edges.get(e);
      if (o === undefined) edges.set(e, t); else { const a = find(o), b = find(t); if (a !== b) parent[Math.max(a, b)] = Math.min(a, b); }
    }
  }
  for (let t = 0; t < s.triCount; t++) parent[t] = find(t);
  islandCache.set(s, parent);
  return parent;
}

/** The region "Fill face" fills for a hit: the cube face / item side, or the mesh triangle's whole UV island. */
export function regionOf(s: ModelScene, h: Pick<Hit, "part" | "face" | "tri">): Spans {
  const r = s.regions[key(h)];
  if (r) return r;
  if (h.face === "edge") return [];
  const isl = uvIslands(s), id = isl[h.tri];
  const tris: [V2, V2, V2][] = [];
  for (let t = 0; t < s.triCount; t++) if (isl[t] === id) tris.push(triUv(s, t));
  return rasterTris(tris, s.tex.w, s.tex.h);
}

export const spansCount = (sp: Spans) => sp.reduce((n, [, a, b]) => n + (b - a), 0);
export const inSpans = (sp: Spans, x: number, y: number) => sp.some(([yy, a, b]) => yy === y && x >= a && x < b);

