// Cyrus Model Studio (Layer 1): per-CHANNEL lossless paint layers and their composite. Pure + client-safe.
// The research decision (H-3d-games.md section 3) is "store channels as separate lossless layers, pack only at
// export"; this is that store for painting. A layer is a full RGBA buffer of the texture's size for ONE channel
// (alpha = how much of the layer covers the texel), with opacity and a blend mode. Composite per channel = the base
// image of that channel (albedo: the generated texture; the others: the channel default), then every visible layer
// of that channel bottom to top. Integer maths only (Math.round on exact integer ratios), so the composite is
// byte-identical in every browser, on the server and in the tests.
// Storage: run-length encoded (varint run, then RGBA) and base64'd ("rle1"): sparse paint on a 2048^2 sheet is a few
// KB, a fully painted 64^2 item a few hundred bytes. Lossless both ways (round-trip tested).
import type { Img } from "./scene";

export const PAINT_CHANNELS = ["albedo", "normal", "roughness", "metallic", "emissive", "mask"] as const;
export type PaintChannel = (typeof PAINT_CHANNELS)[number];
export const BLEND_MODES = ["normal", "multiply", "screen", "add", "overlay"] as const;
export type BlendMode = (typeof BLEND_MODES)[number];

