/** RGBA pixels -> "rle1" base64: [varint run length, r, g, b, a]... Fully transparent texels always encode as 0,0,0,0. */
export function encodePixels(px: Uint8ClampedArray): string {
  const out: number[] = [];
  const n = px.length / 4;
  const same = (i: number, j: number) => {
    const ai = px[i * 4 + 3], aj = px[j * 4 + 3];
    if (!ai && !aj) return true;
    return ai === aj && px[i * 4] === px[j * 4] && px[i * 4 + 1] === px[j * 4 + 1] && px[i * 4 + 2] === px[j * 4 + 2];
