// Cyrus Model Studio (Layer 1): the PAINT ENGINE. Pure + client-safe, deterministic, unit-tested.
// Every edit is an OP in texel space (the 3D pick -> texel step happens before, in ./pick.ts, so an op replays
// without the scene): brush, eraser, fill (a resolved region: cube face, item side, UV island, or a flood area),
// decal stamp, and the layer operations (add / set opacity, blend, visibility, name / delete / move). Symmetry is
// resolved at input time (the mirrored texels are part of the op), so the log alone reproduces the pixels.
// Session = base layers + the op log + a cursor: undo/redo move the cursor and replay from the nearest checkpoint.
// One stroke, one fill, one stamp or one layer change = ONE step (the Texture Studio's History rule); at most
// MAX_STEPS steps are undoable, older ones are folded into the base.
import { inSpans, type Spans } from "./pick";
import type { Img } from "./scene";
import { BLEND_MODES, cloneSet, decodePixels, LAYER_ID, MAX_LAYERS, newLayer, PAINT_CHANNELS, type BlendMode, type LayerSet, type PaintChannel } from "./layers";

export type RGB = [number, number, number];
export type Px = [number, number];
export const BRUSH_SHAPES = ["square", "round"] as const;
export type BrushShape = (typeof BRUSH_SHAPES)[number];
export const MAX_BRUSH = 64;
export const MAX_OP_POINTS = 4096;
export const MAX_SPANS = 16384;

export type Op =
  | { t: "brush"; layer: string; color: RGB; size: number; shape: BrushShape; pts: Px[] }
  | { t: "erase"; layer: string; size: number; shape: BrushShape; pts: Px[] }
  | { t: "fill"; layer: string; color: RGB; spans: Spans }
  | { t: "decal"; layer: string; x: number; y: number; stamp: { w: number; h: number; rle: string }; clip?: Spans }
  | { t: "layer.add"; id: string; name: string; channel: PaintChannel }
  | { t: "layer.set"; id: string; name?: string; opacity?: number; blend?: BlendMode; visible?: boolean }
  | { t: "layer.del"; id: string }
  | { t: "layer.move"; id: string; to: number };

export const OP_LABEL: Record<Op["t"], string> = { brush: "Brush stroke", erase: "Erase", fill: "Fill", decal: "Decal", "layer.add": "New layer", "layer.set": "Layer change", "layer.del": "Delete layer", "layer.move": "Move layer" };

/** Texels a brush of `size` covers around (x, y). Square: a size x size block centred like pixel-art brushes; round: centres within size/2. */
export function footprint(x: number, y: number, size: number, shape: BrushShape): Px[] {
  const out: Px[] = [];
  const s = Math.max(1, Math.min(MAX_BRUSH, Math.floor(size)));
  const o = Math.floor((s - 1) / 2);
  const r2 = (s / 2) * (s / 2);
  for (let j = 0; j < s; j++) for (let i = 0; i < s; i++) {
    const dx = i - o, dy = j - o;
    if (shape === "round" && s > 2) { const cx = dx + 0.5 - (s % 2 ? 0.5 : 0), cy = dy + 0.5 - (s % 2 ? 0.5 : 0); if (cx * cx + cy * cy > r2) continue; }
    out.push([x + dx, y + dy]);
  }
  return out;
}

const put = (px: Uint8ClampedArray, i: number, c: RGB | null) => {
  const o = i * 4;
  if (c) { px[o] = c[0]; px[o + 1] = c[1]; px[o + 2] = c[2]; px[o + 3] = 255; } else { px[o] = px[o + 1] = px[o + 2] = px[o + 3] = 0; }
};

/** Apply one op IN PLACE (the caller owns `set`). Unknown layers / invalid ops are ignored (validated before). */
export function applyOpMut(set: LayerSet, op: Op, wrap = false): void {
  const { w, h } = set;
  const idx = (x: number, y: number): number => {
    if (wrap) { x = ((x % w) + w) % w; y = ((y % h) + h) % h; }
    return x < 0 || y < 0 || x >= w || y >= h ? -1 : y * w + x;
  };
  switch (op.t) {
    case "layer.add": if (set.layers.length < MAX_LAYERS && !set.layers.some((l) => l.id === op.id)) set.layers.push(newLayer(op.id, op.name, op.channel, w, h)); return;
    case "layer.del": set.layers = set.layers.filter((l) => l.id !== op.id); return;
    case "layer.move": { const i = set.layers.findIndex((l) => l.id === op.id); if (i < 0) return; const [l] = set.layers.splice(i, 1); set.layers.splice(Math.max(0, Math.min(set.layers.length, op.to)), 0, l); return; }
    case "layer.set": {
      const l = set.layers.find((x) => x.id === op.id); if (!l) return;
      if (op.name !== undefined) l.name = op.name;
      if (op.opacity !== undefined) l.opacity = op.opacity;
      if (op.blend !== undefined) l.blend = op.blend;
      if (op.visible !== undefined) l.visible = op.visible;
      return;
    }
  }
  const l = set.layers.find((x) => x.id === op.layer);
  if (!l) return;
  if (op.t === "brush" || op.t === "erase") {
    const c = op.t === "brush" ? op.color : null;
    for (const [x, y] of op.pts) for (const [a, b] of footprint(x, y, op.size, op.shape)) { const i = idx(a, b); if (i >= 0) put(l.px, i, c); }
  } else if (op.t === "fill") {
    for (const [y, x0, x1] of op.spans) for (let x = x0; x < x1; x++) { const i = idx(x, y); if (i >= 0) put(l.px, i, op.color); }
  } else if (op.t === "decal") {
    const st = decodePixels(op.stamp.rle, op.stamp.w * op.stamp.h);
    if (!st) return;
    for (let j = 0; j < op.stamp.h; j++) for (let i = 0; i < op.stamp.w; i++) {
      const s = (j * op.stamp.w + i) * 4;
      if (!st[s + 3]) continue;
      const x = op.x + i, y = op.y + j;
      if (op.clip && !inSpans(op.clip, x, y)) continue;
      const d = idx(x, y);
