// Cyrus Model Studio (Layer 1): PBR channel VIEW MODES, profile-aware. Pure + client-safe.
// A game's asset profile (lib/cyrus/adapters/asset-profile.ts channelMap) says which channel roles it can ship.
// Channels it cannot ship are shown DISABLED with the reason (plan section 4: "Minecraft Java item: albedo only"),
// never silently hidden, and they cannot be painted on that model either. A model with no game profile (a glTF
// mesh before an adapter claims it) gets the full glTF metallic-roughness set.
import type { AssetProfile, ChannelRole } from "../adapters/asset-profile";
import { CHANNEL_DEFAULT, compositeChannel, PAINT_CHANNELS, solidImg, type LayerSet, type PaintChannel } from "./layers";
import type { Img } from "./scene";

export const VIEW_MODES = ["lit", "albedo", "normal", "roughness", "metallic", "ao", "emissive", "mask"] as const;
export type ViewMode = (typeof VIEW_MODES)[number];
export const VIEW_LABEL: Record<ViewMode, string> = { lit: "Lit", albedo: "Albedo", normal: "Normal", roughness: "Rough", metallic: "Metal", ao: "AO", emissive: "Emissive", mask: "Mask" };

export type ModeState = { id: ViewMode; label: string; enabled: boolean; reason: string | null };
export type ChannelState = { channel: PaintChannel; paintable: boolean; reason: string | null };

const ROLE: Record<PaintChannel, ChannelRole> = { albedo: "albedo", normal: "normal", roughness: "roughness", metallic: "metallic", emissive: "emissive", mask: "mask" };
const engineName = (p: AssetProfile) => (p.engineFamily === "minecraft-java" ? "Minecraft Java" : p.game);

/** Which channels may be painted for this profile (mask is an authoring aid: never shipped, always paintable). */
export function paintChannels(profile: AssetProfile | null): ChannelState[] {
  return PAINT_CHANNELS.map((c) => {
    if (!profile || c === "mask" || profile.channelMap[ROLE[c]]) return { channel: c, paintable: true, reason: null };
    return { channel: c, paintable: false, reason: `${engineName(profile)} models have no ${c} map, so it would never reach the game` };
  });
}

export function viewModes(profile: AssetProfile | null): ModeState[] {
  const pc = new Map(paintChannels(profile).map((c) => [c.channel as string, c]));
  return VIEW_MODES.map((id) => {
    if (id === "lit") return { id, label: VIEW_LABEL[id], enabled: true, reason: null };
    if (id === "ao") return { id, label: VIEW_LABEL[id], enabled: false, reason: "Ambient occlusion is baked from the mesh at export, not painted (Layer 3/4)" };
    const c = pc.get(id)!;
    return { id, label: VIEW_LABEL[id], enabled: c.paintable, reason: c.reason };
  });
}

/** The image a view mode shows: the channel's composite (grey channels read R), albedo as is. */
export function channelImage(set: LayerSet, mode: Exclude<ViewMode, "lit" | "ao">, albedoBase: Img | null): Img {
  const ch = mode as PaintChannel;
  const img = compositeChannel(set, ch, ch === "albedo" ? albedoBase : null);
  if (ch === "roughness" || ch === "metallic" || ch === "mask") for (let i = 0; i < img.w * img.h; i++) { const v = img.px[i * 4]; img.px[i * 4 + 1] = v; img.px[i * 4 + 2] = v; img.px[i * 4 + 3] = 255; }
  return img;
}

/** Every channel's composite (what the Lit material and the server renderer use). */
export function allChannels(set: LayerSet, albedoBase: Img | null): Record<PaintChannel, Img> {
  return Object.fromEntries(PAINT_CHANNELS.map((c) => [c, compositeChannel(set, c, c === "albedo" ? albedoBase : null)])) as Record<PaintChannel, Img>;
}

/** True when nothing is painted on a channel (the material can skip that map). */
export const channelUntouched = (set: LayerSet, c: PaintChannel) => !set.layers.some((l) => l.channel === c && l.visible && l.opacity > 0 && l.px.some((v, i) => i % 4 === 3 && v > 0));

/** A deterministic UV checker: 8 x 8 cells, two tones, plus a 1-texel grid line per cell (shows stretching and seams). */
export function uvChecker(w: number, h: number): Img {
  const img = solidImg(w, h, CHANNEL_DEFAULT.normal);
  const cw = Math.max(1, Math.floor(w / 8)), chh = Math.max(1, Math.floor(h / 8));
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const o = (y * w + x) * 4, cx = Math.floor(x / cw), cy = Math.floor(y / chh);
    const on = (cx + cy) % 2 === 0, line = x % cw === 0 || y % chh === 0;
    const v = line ? [255, 255, 255] : on ? [124, 77, 255] : [32, 26, 58];
    img.px[o] = v[0]; img.px[o + 1] = v[1]; img.px[o + 2] = v[2]; img.px[o + 3] = 255;
  }
  return img;
}

