// Cyrus Model Studio (Layer 1): the CONFLICT RULE between a person's unsaved paint and a newer revision (an AI edit, or
// the same model saved elsewhere). Pure + client-safe. Plan section 2: "AI never touches the working copy. It returns a
// candidate built from base revision R. If the user has unsaved edits: 3-way merge per node id; disjoint changes merge,
// overlaps listed; human wins by default; Apply / Apply part / Reject."
// For paint, the node is a LAYER (by id) and inside a layer a TEXEL: per texel, whoever changed it from the base wins;
// both changed it differently = an overlap, resolved by `prefer` (default "ours" = the human). Layer properties merge
// the same way per field. A layer one side deleted and the other did not touch is deleted; deleted vs changed is an
// overlap. "Apply part" = take the other side only for the chosen layer ids.
import { cloneLayer, type Layer, type LayerSet } from "./layers";

export type MergeOverlap = { layer: string; texels: number; props: string[]; deleted?: "ours" | "theirs" };
export type MergeResult = { set: LayerSet; overlaps: MergeOverlap[]; fromTheirs: number; overlapTexels: number };

const same = (a: Uint8ClampedArray, b: Uint8ClampedArray, o: number) => {
  if (!a[o + 3] && !b[o + 3]) return true;
  return a[o] === b[o] && a[o + 1] === b[o + 1] && a[o + 2] === b[o + 2] && a[o + 3] === b[o + 3];
};
const changed = (base: Layer | undefined, l: Layer) => !base || l.px.some((v, i) => v !== base.px[i]) || PROPS.some((p) => base[p] !== l[p]);
const PROPS = ["name", "opacity", "blend", "visible", "channel"] as const;

export function mergeLayerSets(base: LayerSet, ours: LayerSet, theirs: LayerSet, o: { prefer?: "ours" | "theirs"; only?: ReadonlySet<string> } = {}): MergeResult {
  if (base.w !== ours.w || base.w !== theirs.w || base.h !== ours.h || base.h !== theirs.h) throw new Error("the layer sets have different sizes");
  const prefer = o.prefer ?? "ours";
  const B = new Map(base.layers.map((l) => [l.id, l])), O = new Map(ours.layers.map((l) => [l.id, l])), T = new Map(theirs.layers.map((l) => [l.id, l]));
  const overlaps: MergeOverlap[] = [];
  let fromTheirs = 0, overlapTexels = 0;
  const out: Layer[] = [];
  const take = (id: string) => !o.only || o.only.has(id);
  // ours' order first, then layers only theirs has (in their order)
  const ids = [...ours.layers.map((l) => l.id), ...theirs.layers.map((l) => l.id).filter((id) => !O.has(id) && !B.has(id))];
  // layers ours deleted (present in base + theirs, absent in ours)
  for (const id of theirs.layers.map((l) => l.id)) if (B.has(id) && !O.has(id) && take(id) && changed(B.get(id), T.get(id)!)) overlaps.push({ layer: id, texels: 0, props: [], deleted: "ours" });
  for (const id of ids) {
    const b = B.get(id), ol = O.get(id), tl = T.get(id);
    if (ol && !tl) {
      // theirs deleted it (or never had it)
      if (b && take(id)) {
        if (!changed(b, ol)) continue; // untouched by us, deleted by them: deleted
        overlaps.push({ layer: id, texels: 0, props: [], deleted: "theirs" });
        if (prefer === "theirs") continue;
      }
      out.push(cloneLayer(ol));
      continue;
    }
    if (!ol && tl) { if (take(id)) { out.push(cloneLayer(tl)); fromTheirs += tl.px.length / 4; } continue; }
    if (!ol || !tl) continue;
    if (!take(id)) { out.push(cloneLayer(ol)); continue; }
    const m = cloneLayer(ol);
    let ov = 0;
    const props: string[] = [];
    for (const p of PROPS) {
      const bv = b?.[p], ov2 = ol[p], tv = tl[p];
      if (ov2 === tv || tv === bv) continue;
      if (ov2 === bv) { (m as Record<string, unknown>)[p] = tv; continue; }
      props.push(p);
      if (prefer === "theirs") (m as Record<string, unknown>)[p] = tv;
    }
    const n = m.px.length / 4;
    for (let i = 0; i < n; i++) {
      const q = i * 4;
      if (same(ol.px, tl.px, q)) continue;
      const bp = b?.px;
      const tChanged = !bp || !same(tl.px, bp, q), oChanged = !bp || !same(ol.px, bp, q);
      if (!tChanged) continue;
      if (!oChanged || prefer === "theirs") { m.px[q] = tl.px[q]; m.px[q + 1] = tl.px[q + 1]; m.px[q + 2] = tl.px[q + 2]; m.px[q + 3] = tl.px[q + 3]; fromTheirs++; if (oChanged) ov++; continue; }
      ov++;
    }
    if (ov || props.length) { overlaps.push({ layer: id, texels: ov, props }); overlapTexels += ov; }
    out.push(m);
  }
  return { set: { w: ours.w, h: ours.h, layers: out }, overlaps, fromTheirs, overlapTexels };
}

