// Portal half of the creature specs a build returns (Cyrus R3). The build service validated them with its generated
// JS copy of ./spec.ts; the portal never trusts that: it re-validates, compiles (.bbmodel + skin), runs the skin
// quality bar and identifies each RigSpec by the sha256 of its canonical JSON as WRITTEN (template form stays small).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { compileCreature, type CompiledCreature } from "./compile";
import { skinQuality, type SkinQuality } from "./quality";
import { checkRigSpec, MAX_CREATURES, MAX_RIG_SPEC_BYTES, modelKey, NAME_RE, type RigSpec } from "./spec";

export const RIG_SPEC_MIME = "application/vnd.nxeon.rig-spec+json";

export type CheckedCreature =
  | { ok: true; name: string; key: string; input: unknown; spec: RigSpec; specSha256: string; canonical: string; compiled: CompiledCreature; quality: SkinQuality; warnings: string[] }
  | { ok: false; name: string; reason: string };

export function checkReturnedCreature(c: { name?: unknown; spec?: unknown }, namespace: string): CheckedCreature {
  const name = typeof c.name === "string" && NAME_RE.test(c.name) ? c.name : "?";
  const canonical = canonicalJson(c.spec ?? null);
  if (Buffer.byteLength(canonical) > MAX_RIG_SPEC_BYTES) return { ok: false, name, reason: `the creature spec is larger than ${MAX_RIG_SPEC_BYTES / 1024} KB` };
  const chk = checkRigSpec(c.spec, { namespace });
  if (!chk.ok) return { ok: false, name, reason: chk.error };
  if (chk.spec.name !== name) return { ok: false, name, reason: `spec name ${chk.spec.name} does not match ${name}` };
  const r = compileCreature(chk.spec, namespace);
  if (!r.ok) return { ok: false, name, reason: r.error };
  const quality = skinQuality(r.creature.raster, r.creature.layout);
  if (quality.verdict === "fail") return { ok: false, name, reason: `the skin failed Nxeon's skin checks (${quality.checks.filter((q) => q.verdict === "fail").map((q) => q.id).join(", ")})` };
  return { ok: true, name, key: modelKey(namespace, name), input: c.spec, spec: chk.spec, specSha256: sha256Hex(canonical), canonical, compiled: r.creature, quality, warnings: chk.warnings };
}

/** Re-check every returned creature (at most MAX_CREATURES, first wins on a duplicate name). */
export function checkReturnedCreatures(list: { name?: unknown; spec?: unknown }[] | undefined, namespace: string): { ok: Extract<CheckedCreature, { ok: true }>[]; dropped: { name: string; reason: string }[] } {
  const ok: Extract<CheckedCreature, { ok: true }>[] = [];
  const dropped: { name: string; reason: string }[] = [];
  for (const c of (list ?? []).slice(0, MAX_CREATURES)) {
    const r = checkReturnedCreature(c, namespace);
    if (!r.ok) { dropped.push({ name: r.name, reason: r.reason }); continue; }
    if (ok.some((x) => x.name === r.name)) continue;
    ok.push(r);
  }
  return { ok, dropped };
}
  });
}

// ---------------------------------------------------------------------------
// Assets (content-addressed; recording the same content twice returns the first row)
// ---------------------------------------------------------------------------

export type RecordAssetInput = {
  revisionId: string; assetKey: string; kind: "texture" | "sound" | "model" | "ui" | "datapack" | "design" | "itemmodel"; sha256: string; size: number;
  origin: "generated" | "library" | "upload" | "edited" | "imported"; mime?: string | null; path?: string | null; provenance?: Record<string, unknown> | null;
};

export async function recordAsset(projectId: string, a: RecordAssetInput) {
  if (!/^[0-9a-f]{64}$/.test(a.sha256)) throw new EngineStoreError("bad_input", "sha256 must be 64 lowercase hex characters");
  const rev = await getRevision(a.revisionId);
  if (!rev || rev.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const where = { projectId_kind_assetKey_sha256: { projectId, kind: a.kind, assetKey: a.assetKey, sha256: a.sha256 } };
  try {
    return await db.cyrusProjectAsset.create({
      data: { projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ? (a.provenance as Prisma.InputJsonValue) : Prisma.DbNull },
    });
  } catch (e) {
    if (isUniqueViolation(e)) { const row = await db.cyrusProjectAsset.findUnique({ where }); if (row) return row; }
    throw e;
  }
}
export const listProjectAssets = (projectId: string) => db.cyrusProjectAsset.findMany({ where: { projectId }, orderBy: { createdAt: "asc" } });

// ---------------------------------------------------------------------------
// Identifier registry
// ---------------------------------------------------------------------------

/**
 * Reserve an identifier in the project's namespace. Idempotent: reserving the same (kind, key) again returns the
 * existing row. Glyphs get the first free codepoint from the namespace's home block (unique across all projects).
 */
export async function reserveIdentifier(projectId: string, kind: IdentifierKind, key: string): Promise<CyrusIdentifier> {
  const p = await getProject(projectId);
  if (!p) throw new EngineStoreError("not_found", "project not found");
  const built = buildIdentifier(p.namespace, kind, key);
  if (!built.ok) throw new EngineStoreError("bad_identifier", built.error);
  const where = { namespace_kind_key: { namespace: p.namespace, kind, key } };
  const existing = await db.cyrusIdentifier.findUnique({ where });
  if (existing) return existing;
  const base = { projectId, namespace: p.namespace, kind, key, fullId: built.id };
  if (kind !== "glyph") {
    try {
      return await db.cyrusIdentifier.create({ data: base });
    } catch (e) {
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  const home = glyphHomeBlock(p.namespace);
  let tries = 0;
  for (let b = 0; b < GLYPH_BLOCKS && tries < 64; ) {
    const start = glyphBlockStart(home + b);
    const taken = new Set((await db.cyrusIdentifier.findMany({ where: { codepoint: { gte: start, lt: start + GLYPH_BLOCK } }, select: { codepoint: true } })).map((r) => r.codepoint));
    let cp = -1;
    for (let c = start; c < start + GLYPH_BLOCK; c++) if (!taken.has(c)) { cp = c; break; }
    if (cp < 0) { b++; continue; }
    tries++;
    try {
      return await db.cyrusIdentifier.create({ data: { ...base, codepoint: cp } });
    } catch (e) {
      if (isUniqueViolation(e, "codepoint")) continue; // another project took it: look again
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  throw new EngineStoreError("glyphs_exhausted", "no free glyph codepoint");
}

export const listIdentifiers = (projectId: string) => db.cyrusIdentifier.findMany({ where: { projectId }, orderBy: [{ kind: "asc" }, { key: "asc" }] });

