// Cyrus Model Studio: the SERVER-SIDE PREVIEW RENDER interface (plan section 5, mesh/PBR lane). Pure + client-safe
// types and request building; the implementation is injected (./playwright.ts on node-2: headless Chromium + three.js
// on SwiftShader; tests use fakes). Deterministic by construction: fixed camera presets, DPR 1, no clocks, no
// animation loop, no tone mapping, antialias off, the same three.js build the client ships.
// What it is for: the phone fallback when WebGL fails, the 6-context + turntable shots a reviewer or the look check
// sees, and golden-image tests. It never runs on the primary and never in a request path without the renderer flag.
import { canonical, sha256Text } from "../hash";
import { b64encode } from "../layers";
import type { ModelScene, Img } from "../scene";
import type { M4, OrbitCam } from "../math";

export const PREVIEW_RENDERER_VERSION = "cyrus-preview-r1";
export const PREVIEW_SIZES = [256, 512] as const;
export type PreviewSize = (typeof PREVIEW_SIZES)[number];
/** fixed camera presets (yaw / pitch in degrees around the model's bounds centre; distance fits the bounds) */
export const PREVIEW_PRESETS = {
  front: { yaw: 0, pitch: 8 }, three_quarter: { yaw: -35, pitch: 18 }, side: { yaw: -90, pitch: 6 }, back: { yaw: 180, pitch: 10 }, top: { yaw: 0, pitch: 80 },
  turn_0: { yaw: 0, pitch: 12 }, turn_1: { yaw: 45, pitch: 12 }, turn_2: { yaw: 90, pitch: 12 }, turn_3: { yaw: 135, pitch: 12 },
  turn_4: { yaw: 180, pitch: 12 }, turn_5: { yaw: 225, pitch: 12 }, turn_6: { yaw: 270, pitch: 12 }, turn_7: { yaw: 315, pitch: 12 },
} as const;
export type PreviewPreset = keyof typeof PREVIEW_PRESETS;
export const TURNTABLE: PreviewPreset[] = ["turn_0", "turn_1", "turn_2", "turn_3", "turn_4", "turn_5", "turn_6", "turn_7"];
/** the server renderer's texture cap: bigger channel textures are downsampled (nearest) before they are sent */
export const PREVIEW_MAX_TEX = 1024;

export type PreviewMaterial = "pixel" | "pbr";
export type PreviewRequest = {
  name: string;
  /** base64 Float32Array: 9 per triangle / 6 per triangle */
  pos: string; uv: string; triCount: number;
  tex: { w: number; h: number };
  /** base64 raw RGBA per channel (albedo required) */
  maps: { albedo: string; normal?: string; roughness?: string; metallic?: string; emissive?: string };
  material: PreviewMaterial;
  preset: PreviewPreset;
  size: PreviewSize;
  /** optional model matrix (a display context); default: none */
  model?: M4;
  /** explicit camera (a context rig); default: the preset around the bounds */
  cam?: OrbitCam & { proj: "persp" | "ortho" };
  background: [number, number, number];
};

export type PreviewResult =
  | { ok: true; png: Uint8Array; width: number; height: number; ms: number; renderer: string; key: string }
  | { ok: false; code: "unavailable" | "timeout" | "crashed" | "bad_request" | "too_large"; error: string };

export interface PreviewRenderer {
  readonly id: string;
  render(req: PreviewRequest): Promise<PreviewResult>;
}

const f32b64 = (a: Float32Array) => b64encode(new Uint8Array(a.buffer, a.byteOffset, a.byteLength));

/** Nearest-neighbour downsample to at most `max` per edge (keeps the aspect). */
export function capImg(img: Img, max = PREVIEW_MAX_TEX): Img {
  if (img.w <= max && img.h <= max) return img;
  const k = Math.max(img.w, img.h) / max, w = Math.max(1, Math.round(img.w / k)), h = Math.max(1, Math.round(img.h / k));
  const px = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const sx = Math.min(img.w - 1, Math.floor(x * k)), sy = Math.min(img.h - 1, Math.floor(y * k)); px.set(img.px.subarray((sy * img.w + sx) * 4, (sy * img.w + sx) * 4 + 4), (y * w + x) * 4); }
  return { w, h, px };
}

/** Build a request from a scene + its channel composites. */
export function previewRequest(scene: ModelScene, maps: { albedo: Img } & Partial<Record<"normal" | "roughness" | "metallic" | "emissive", Img>>, o: { preset: PreviewPreset; size?: PreviewSize; material?: PreviewMaterial; background?: [number, number, number]; model?: M4; cam?: PreviewRequest["cam"] }): PreviewRequest {
  const a = capImg(maps.albedo);
  const enc = (m?: Img) => (m ? b64encode(new Uint8Array(capImg(m).px.buffer)) : undefined);
  const extra = Object.fromEntries((["normal", "roughness", "metallic", "emissive"] as const).flatMap((k) => (maps[k] && capImg(maps[k]!).w === a.w ? [[k, enc(maps[k])]] : [])));
  return {
    name: scene.name, pos: f32b64(scene.pos), uv: f32b64(scene.uv), triCount: scene.triCount, tex: { w: a.w, h: a.h },
    maps: { albedo: b64encode(new Uint8Array(a.px.buffer)), ...extra }, material: o.material ?? (scene.kind === "mesh" ? "pbr" : "pixel"),
    preset: o.preset, size: o.size ?? 512, background: o.background ?? [18, 14, 38], ...(o.model ? { model: o.model } : {}), ...(o.cam ? { cam: o.cam } : {}),
  };
}

/** Cache key = sha256(canonical request + renderer id + renderer version): the same inputs never render twice. */
export const previewKey = (req: PreviewRequest, rendererId: string) => sha256Text(canonical({ req, rendererId, v: PREVIEW_RENDERER_VERSION }));

/** Validate an untrusted request's shape and budget (the renderer runs this before launching anything). */
export function checkPreviewRequest(r: PreviewRequest, maxTris = 150_000): string | null {
  if (!r || typeof r !== "object") return "request must be an object";
  if (!(PREVIEW_SIZES as readonly number[]).includes(r.size)) return "size must be 256 or 512";
  if (!(r.preset in PREVIEW_PRESETS)) return "unknown camera preset";
  if (!Number.isInteger(r.triCount) || r.triCount < 1 || r.triCount > maxTris) return `1 to ${maxTris} triangles`;
  if (r.pos.length > Math.ceil((r.triCount * 36) / 3) * 4 + 8 || r.uv.length > Math.ceil((r.triCount * 24) / 3) * 4 + 8) return "geometry does not match the triangle count";
  if (!Number.isInteger(r.tex.w) || !Number.isInteger(r.tex.h) || r.tex.w < 1 || r.tex.h < 1 || r.tex.w > PREVIEW_MAX_TEX || r.tex.h > PREVIEW_MAX_TEX) return `textures up to ${PREVIEW_MAX_TEX} px`;
  for (const v of Object.values(r.maps)) if (v !== undefined && v.length > Math.ceil((r.tex.w * r.tex.h * 4) / 3) * 4 + 8) return "a map is larger than the texture size";
  if (r.material !== "pixel" && r.material !== "pbr") return "material must be pixel or pbr";
  return null;
}

/** An in-memory LRU of rendered previews (the CyrusPreviewRender table is plan task F1; until then, per process). */
export function memoryPreviewCache(max = 64) {
  const m = new Map<string, Uint8Array>();
  return {
    get: (k: string) => { const v = m.get(k); if (v) { m.delete(k); m.set(k, v); } return v ?? null; },
    put: (k: string, v: Uint8Array) => { m.set(k, v); while (m.size > max) m.delete(m.keys().next().value!); },
    size: () => m.size,
  };
}

