// Cyrus Model Studio: LIGHTING PRESETS and material constants, as plain data shared by the client viewport
// (components/cyrus/studios/model-viewport.ts) and the server preview page (./preview/page-script.ts), so the two
// light a model the same way. Directions point FROM the light toward the scene centre's opposite (three.js
// DirectionalLight position, normalised). Colours are sRGB hex.
export type LightRig = { label: string; ambient: { color: number; intensity: number }; key: { color: number; intensity: number; dir: [number, number, number] }; fill: { color: number; intensity: number; dir: [number, number, number] }; rim: { color: number; intensity: number; dir: [number, number, number] } };

export const LIGHTING_PRESETS = {
  studio: { label: "Studio", ambient: { color: 0xffffff, intensity: 0.6 }, key: { color: 0xffffff, intensity: 1.7, dir: [-0.45, 0.8, 0.4] }, fill: { color: 0xa78bfa, intensity: 0.35, dir: [0.7, 0.25, -0.6] }, rim: { color: 0x67e8f9, intensity: 0.25, dir: [0.1, 0.4, -1] } },
  daylight: { label: "Daylight", ambient: { color: 0xdde8ff, intensity: 0.75 }, key: { color: 0xfff4e0, intensity: 2.0, dir: [0.35, 0.9, 0.25] }, fill: { color: 0x9ec5ff, intensity: 0.3, dir: [-0.6, 0.3, -0.5] }, rim: { color: 0xffffff, intensity: 0, dir: [0, 1, 0] } },
  night: { label: "Night", ambient: { color: 0x6e74c8, intensity: 0.45 }, key: { color: 0xc8d0ff, intensity: 0.9, dir: [-0.3, 0.7, 0.5] }, fill: { color: 0x7c4dff, intensity: 0.4, dir: [0.7, 0.1, -0.5] }, rim: { color: 0x22d3ee, intensity: 0.5, dir: [0.2, 0.3, -1] } },
  /** unlit: albedo exactly as stored (what painting on a pixel profile wants to check) */
  flat: { label: "Flat", ambient: { color: 0xffffff, intensity: 3.14159 }, key: { color: 0xffffff, intensity: 0, dir: [0, 1, 0] }, fill: { color: 0xffffff, intensity: 0, dir: [0, 1, 0] }, rim: { color: 0xffffff, intensity: 0, dir: [0, 1, 0] } },
} as const satisfies Record<string, LightRig>;
export type LightingPreset = keyof typeof LIGHTING_PRESETS;

/** Pixel profile (Minecraft): nearest filtering, no mipmaps, alpha test at 0.5 (vanilla cutout), rough + non-metal. */
export const PIXEL_MATERIAL = { alphaTest: 0.5, roughness: 1, metalness: 0 } as const;

