// Cyrus Model Studio (Layer 1): the SERVER service behind /api/cyrus/models/v1. Every dependency is injected: the
// Cyrus tables through the Texture Studio's StudioStore (lib/cyrus/studios/service.ts), the plan through planOf,
// drafts through DraftStore, the preview renderer through PreviewRenderer. ./deps.ts wires the real ones; tests use
// fakes. No Nxeon internals here.
//
// What a project holds that Model Studio paints (nothing new is invented):
//   creature  the newest CyrusProjectAsset kind "model" / RIG_SPEC_MIME row per key (a build's RigSpec), plus the
//             newest ModelDoc row (kind "model", MODELDOC_MIME) for that key = the saved paint layers
//   item3d    every item texture (not a block tile) = an extruded item, with the mod's ItemModelSpec contexts + states
// SAVE (one paint session = one revision, the Texture Studio's rules: expectedHeadId -> 409 stale_head, the plan gate
// first, fail closed):
//   creature  -> a NEW revision kind "asset" + a ModelDoc row. The paint is stored; compiling it into the delivered
//                BetterModel skin is NOT wired yet (next task, documented).
//   item3d    -> the albedo composite becomes the item's TextureDoc (spec untouched + paint layer) through the Texture
//                Studio's own saveTexture, so it ships in the pack exactly like a Texture Studio edit; the layers ride
//                along in the row's provenance so the next session reopens them losslessly.
import { canonicalJson, sha256Hex } from "../assets/textures";
import { canModelStudio, normalizePlan, PLAN_LABEL, type AssetDecision, type AssetPlan, type ModelStudioAction } from "../engine-core/asset-gate";
import type { ManifestEntry } from "../engine-core/revisions";
import { checkRigSpec, type RigSpec } from "../creature/spec";
import { layoutSkin, skinTextureSpec, type SkinLayout } from "../creature/compile";
import { RIG_SPEC_MIME } from "../creature/portal";
import type { TextureSpec } from "../textures/dsl";
import { render } from "../textures/render";
import { renderDoc, paintFromBuffers, MAX_PAINT_COLORS, type TextureDoc, type TextureSize } from "../studios/paint";
import { previewModel, type PreviewModel } from "../itemmodel/preview";
import {
  resolveItemModels, resolveTextures, saveTexture, soundCandidateIds, StudioError, textureCandidateIds,
  type AssetRow, type ProjectRow, type SaveResult, type StudioServiceDeps, type TextureEntry,
} from "../studios/service";
import { checkModelDoc, MODELDOC_MIME, type ModelDoc } from "./doc";
import { compositeChannel, type LayerSet } from "./layers";
import { checkOp, replay, type Op } from "./paint";
import { canonical, sha256Text } from "./hash";
import { encodeLayers } from "./doc";
import type { Img } from "./scene";
import type { PreviewRenderer } from "./preview/types";

// ---------------------------------------------------------------------------- deps

export type DraftRow = { projectId: string; ownerRef: string; assetKey: string; baseAssetId: string | null; baseHeadId: string | null; doc: unknown; updatedAt: Date | string };
export interface DraftStore {
  get(projectId: string, ownerRef: string, assetKey: string): Promise<DraftRow | null>;
  put(row: Omit<DraftRow, "updatedAt">): Promise<{ updatedAt: Date | string }>;
  drop(projectId: string, ownerRef: string, assetKey: string): Promise<void>;
}
export type ModelServiceDeps = StudioServiceDeps & {
  drafts: DraftStore;
  /** null = the server preview renderer is not configured here (the phone fallback then says so) */
  renderer: () => PreviewRenderer | null;
};

/** In-memory drafts (tests, and devhost when the table is not pushed). */
export function memoryDraftStore(): DraftStore & { rows: Map<string, DraftRow> } {
  const rows = new Map<string, DraftRow>();
  const k = (p: string, o: string, a: string) => `${p}|${o}|${a}`;
  return {
    rows,
    get: async (p, o, a) => rows.get(k(p, o, a)) ?? null,
    put: async (r) => { const updatedAt = new Date(); rows.set(k(r.projectId, r.ownerRef, r.assetKey), { ...r, updatedAt }); return { updatedAt }; },
    drop: async (p, o, a) => { rows.delete(k(p, o, a)); },
  };
}

// ---------------------------------------------------------------------------- the models view

const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();
const iso = (d: Date | string) => new Date(d).toISOString();

export type PaintState = { assetId: string; revisionId: string; createdAt: string; doc: ModelDoc; stale: string | null };
export type CreatureModel = {
  kind: "creature"; key: string; label: string; assetId: string; sha256: string; revisionId: string; createdAt: string;
  /** the expanded RigSpec (rest pose geometry) + its skin layout + the skin's generated base spec (render it client side) */
  spec: RigSpec; layout: SkinLayout; skin: TextureSpec;
  stats: { bones: number; cubes: number };
  paint: PaintState | null;
  history: { assetId: string; revisionId: string; createdAt: string; label: string }[];
};
export type ItemModel = {
  kind: "item3d"; key: string; label: string; texture: TextureEntry;
  /** the doc the paint layers sit on (the current texture, or the base a Model Studio save started from) */
  base: { assetId: string; doc: TextureDoc };
  /** layers restored from the last Model Studio save of this texture (null = start with an empty layer) */
  paint: { doc: ModelDoc; assetId: string } | null;
  preview: PreviewModel;
};
export type ModelEntry = CreatureModel | ItemModel;
export type ModelsView = {
  project: { id: string; namespace: string; title: string | null; rootBuildId: string | null } | null;
  access: { plan: AssetPlan | null; planLabel: string; edit: AssetDecision; view: AssetDecision };
  headRevisionId: string | null;
  models: ModelEntry[];
  revisionSeq: Record<string, number>;
  mcVersion: string | null;
  renderer: string | null;
};

/** The current ModelDoc rows per key (newest first per key). */
function modelDocRows(rows: readonly AssetRow[]) {
  const out = new Map<string, { row: AssetRow; doc: ModelDoc }[]>();
  for (const r of rows) {
    if (r.kind !== "model" || r.mime !== MODELDOC_MIME) continue;
    const c = checkModelDoc(obj(r.provenance).doc);
    if (!c.ok) continue;
    out.set(r.assetKey, [...(out.get(r.assetKey) ?? []), { row: r, doc: c.doc }]);
  }
  for (const v of out.values()) v.sort((a, b) => ts(b.row.createdAt) - ts(a.row.createdAt) || (a.row.id < b.row.id ? 1 : -1));
  return out;
}

/** Pure: the models of a project from its asset rows. */
export function resolveModels(rows: readonly AssetRow[], candidateBuildIds: ReadonlySet<string>, ignoreBuildIds: ReadonlySet<string>): ModelEntry[] {
  const out: ModelEntry[] = [];
  const docs = modelDocRows(rows);
  // creatures: newest RigSpec row per key
  const rigs = new Map<string, AssetRow[]>();
  for (const r of rows) if (r.kind === "model" && r.mime === RIG_SPEC_MIME) rigs.set(r.assetKey, [...(rigs.get(r.assetKey) ?? []), r]);
  for (const [key, list] of rigs) {
    list.sort((a, b) => ts(b.createdAt) - ts(a.createdAt) || (a.id < b.id ? 1 : -1));
    const cur = list[0];
    const chk = checkRigSpec(obj(cur.provenance).spec);
    if (!chk.ok) continue;
    const lay = layoutSkin(chk.spec);
    if (!lay.ok) continue;
    const d = docs.get(key) ?? [];
    const latest = d[0];
    let paint: PaintState | null = null;
    if (latest) {
      const base = latest.doc.base;
      const stale = base.type !== "rigspec" ? "this paint was not made on a creature" : latest.doc.tex.w !== lay.layout.size ? `the creature's skin sheet changed size (${latest.doc.tex.w} -> ${lay.layout.size}); the paint was kept in history but not reapplied` : base.sha256 !== cur.sha256 ? "the creature changed in a later build; the paint is reapplied on the new shape and may not line up everywhere" : null;
      // a size change makes the layers unusable on this sheet: start fresh (the old doc stays in history)
      if (!(stale && latest.doc.tex.w !== lay.layout.size)) paint = { assetId: latest.row.id, revisionId: latest.row.revisionId, createdAt: iso(latest.row.createdAt), doc: latest.doc, stale };
    }
    out.push({
      kind: "creature", key, label: String(obj(chk.spec).displayName ?? key), assetId: cur.id, sha256: cur.sha256, revisionId: cur.revisionId, createdAt: iso(cur.createdAt),
      spec: chk.spec, layout: lay.layout, skin: skinTextureSpec(chk.spec, lay.layout),
      stats: { bones: chk.spec.bones.length, cubes: chk.spec.bones.reduce((n, b) => n + b.cubes.length, 0) },
      paint, history: d.slice(0, 20).map((x) => ({ assetId: x.row.id, revisionId: x.row.revisionId, createdAt: iso(x.row.createdAt), label: "Painted in Model Studio" })),
    });
  }
  // items: every item texture (block tiles are not held items)
  const textures = resolveTextures(rows, candidateBuildIds, ignoreBuildIds);
  const specs = resolveItemModels(rows);
  const byId = new Map(rows.map((r) => [r.id, r]));
  for (const t of textures) {
    if (t.doc.tile) continue;
    const row = byId.get(t.assetId);
    const ms = obj(obj(row?.provenance).modelStudio);
    let base: ItemModel["base"] = { assetId: t.assetId, doc: t.doc };
    let paint: ItemModel["paint"] = null;
    // reopen the layers of the last Model Studio save, only when its pixels are still exactly this texture's
    const md = checkModelDoc(ms.doc);
    const baseRow = typeof ms.baseAssetId === "string" ? byId.get(ms.baseAssetId) : undefined;
    const baseEntry = baseRow ? [...t.history].find((h) => h.assetId === baseRow.id) : undefined;
    if (md.ok && baseEntry && md.doc.tex.w === baseEntry.doc.size) {
      const comp = compositeChannel(md.layers, "albedo", imgOf(renderDoc(baseEntry.doc)));
      if (sameAlbedo(comp, imgOf(renderDoc(t.doc)))) { base = { assetId: baseEntry.assetId, doc: baseEntry.doc }; paint = { doc: md.doc, assetId: t.assetId }; }
    }
    out.push({ kind: "item3d", key: t.key, label: t.key, texture: t, base, paint, preview: previewModel(t.key, specs) });
  }
  return out;
}

export const imgOf = (r: { size: number; px: Uint8ClampedArray }): Img => ({ w: r.size, h: r.size, px: r.px });
/** Equal as the game sees it: alpha snapped at 128 (cutout), colour compared where opaque. */
function sameAlbedo(a: Img, b: Img): boolean {
  if (a.w !== b.w || a.h !== b.h) return false;
  for (let i = 0; i < a.w * a.h; i++) {
    const o = i * 4, oa = a.px[o + 3] >= 128, ob = b.px[o + 3] >= 128;
    if (oa !== ob) return false;
    if (oa && (a.px[o] !== b.px[o] || a.px[o + 1] !== b.px[o + 1] || a.px[o + 2] !== b.px[o + 2])) return false;
  }
  return true;
}

async function ownedProject(deps: StudioServiceDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}
const planOf = async (deps: StudioServiceDeps, userId: string) => deps.planOf(userId).catch(() => null);
const gateOrThrow = (d: AssetDecision) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };
export async function gateModel(deps: StudioServiceDeps, userId: string, action: ModelStudioAction) { gateOrThrow(canModelStudio(await planOf(deps, userId), action)); }

export async function modelsView(deps: ModelServiceDeps, userId: string, rootBuildId: string): Promise<ModelsView> {
  const chain = await deps.chain(userId, rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const raw = await planOf(deps, userId);
  const plan = normalizePlan(raw);
  const access = { plan, planLabel: plan ? PLAN_LABEL[plan] : "Unknown", edit: canModelStudio(raw, "paint"), view: canModelStudio(raw, "view") };
  const renderer = deps.renderer()?.id ?? null;
  const p = await deps.store.projectForRoot(chain.rootBuildId);
  if (!p || p.userId !== userId) return { project: null, access, headRevisionId: null, models: [], revisionSeq: {}, mcVersion: chain.mcVersion, renderer };
  const revs = await deps.store.revisions(p.id);
  const rows = await deps.store.assets(p.id);
  return {
    project: { id: p.id, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId }, access, headRevisionId: p.headRevisionId,
    models: resolveModels(rows, textureCandidateIds(chain), soundCandidateIds(chain)), revisionSeq: Object.fromEntries(revs.map((r) => [r.id, r.seq])), mcVersion: chain.mcVersion, renderer,
  };
}

// ---------------------------------------------------------------------------- save

export const MAX_LOG_OPS = 2000;
export type SaveModelInput = {
  userId: string; projectId: string; key: string; doc: unknown;
  /** the row the session started from (creature: the ModelDoc row, or null for the first paint; item: the texture row) */
  baseAssetId: string | null;
  expectedHeadId: string | null;
  /** the applied op log since the session's starting layers (optional; replayed and checked when sent and not folded) */
  log?: unknown[];
  message?: string | null;
};
export type SaveModelResult = { revisionId: string; seq: number; assetId: string; kind: "creature" | "item3d"; logVerified: boolean | null; pack?: SaveResult["pack"]; warnings: string[] };

/**
 * Check the op log against the layers: replaying `log` on the session's starting layers must give exactly the saved
 * layers (lossless encodings compared). Returns the log record for the doc, or throws 400 log_mismatch.
 */
export function verifyLog(start: LayerSet, doc: ModelDoc, layers: LayerSet, log: unknown[] | undefined, folded: number): { record: ModelDoc["log"]; verified: boolean | null } {
  if (!log) return { record: doc.log, verified: null };
  if (!Array.isArray(log) || log.length > MAX_LOG_OPS) throw new StudioError(400, "bad_log", `the op log holds at most ${MAX_LOG_OPS} steps`);
  for (const [i, op] of log.entries()) { const e = checkOp(op, doc.tex.w, doc.tex.h); if (e) throw new StudioError(400, "bad_log", `op ${i}: ${e}`); }
  const record = { ops: log.length, folded, sha256: sha256Text(canonical(log)) };
  if (folded > 0) return { record, verified: null }; // older steps were folded into the start: not replayable here
  const out = replay(start, log as Op[], false);
  const a = encodeLayers(out), b = encodeLayers(layers);
  if (canonical(a) !== canonical(b)) throw new StudioError(400, "log_mismatch", "The paint does not match its edit log, so it was not saved. Reload and try again.");
  return { record, verified: true };
}

/** Item albedo composite -> the item's TextureDoc: spec untouched, every texel that differs from the spec render is paint. */
export function textureDocFromComposite(base: TextureDoc, albedo: Img): { doc: TextureDoc; snapped: number } {
  const size = base.size;
  if (albedo.w !== size || albedo.h !== size) throw new StudioError(400, "bad_doc", "the paint size does not match the item texture");
  const specPx = base.spec ? render(base.spec).px : new Uint8ClampedArray(size * size * 4);
  const rgba = new Uint8ClampedArray(size * size * 4), cut = new Uint8Array(size * size);
  let snapped = 0;
  for (let i = 0; i < size * size; i++) {
    const o = i * 4, a = albedo.px[o + 3];
    if (a !== 0 && a !== 255) snapped++;
    const opaque = a >= 128; // vanilla cutout: the quality bar forbids semi-transparency, so it is snapped
    const sOpaque = specPx[o + 3] > 0;
    if (opaque) {
      if (sOpaque && specPx[o] === albedo.px[o] && specPx[o + 1] === albedo.px[o + 1] && specPx[o + 2] === albedo.px[o + 2] && specPx[o + 3] === 255) continue;
      rgba[o] = albedo.px[o]; rgba[o + 1] = albedo.px[o + 1]; rgba[o + 2] = albedo.px[o + 2]; rgba[o + 3] = 255;
    } else if (sOpaque) cut[i] = 1;
  }
  let paint;
  try { paint = paintFromBuffers(size as TextureSize, rgba, cut); } catch { throw new StudioError(422, "too_many_colours", `An item texture holds at most ${MAX_PAINT_COLORS} painted colours.`); }
  const doc: TextureDoc = { ...base, paint };
  if (!doc.spec && !doc.paint) throw new StudioError(422, "empty", "This would leave the item with no pixels.");
  return { doc, snapped };
}

export async function saveModel(deps: ModelServiceDeps, input: SaveModelInput): Promise<SaveModelResult> {
  await gateModel(deps, input.userId, "save");
  const project = await ownedProject(deps, input.userId, input.projectId);
  const c = checkModelDoc(input.doc);
  if (!c.ok) throw new StudioError(400, "bad_doc", c.error);
  if (Buffer.byteLength(JSON.stringify(input.doc)) > 8 * 1024 * 1024) throw new StudioError(413, "too_large", "This paint is too large to save in one revision.");
  if (c.doc.name !== input.key) throw new StudioError(400, "bad_doc", "the model name must match its key");
  const chain = project.rootBuildId ? await deps.chain(input.userId, project.rootBuildId) : null;
  const rows = await deps.store.assets(project.id);
  const models = resolveModels(rows, textureCandidateIds(chain), soundCandidateIds(chain));
  const m = models.find((x) => x.key === input.key && x.kind === c.doc.kind);
  if (!m) throw new StudioError(404, "not_found", `No ${c.doc.kind === "creature" ? "creature" : "item"} called ${input.key} in this mod.`);
  const folded = Math.max(0, c.doc.log?.folded ?? 0);
  const warnings: string[] = [];

  if (m.kind === "item3d") {
    if (c.doc.base.type !== "texture" || c.doc.base.key !== m.key) throw new StudioError(400, "bad_doc", "an item paint must name its texture as the base");
    if (input.baseAssetId !== m.texture.assetId) throw new StudioError(409, "stale_head", "This item changed since you opened it. Reload to see the latest version, then save again.");
    if (c.doc.tex.w !== m.base.doc.size || c.doc.tex.h !== m.base.doc.size) throw new StudioError(400, "bad_doc", "the paint size does not match the item texture");
    const start = m.paint ? checkModelDoc(m.paint.doc) : null;
    const { record, verified } = verifyLog(start && start.ok ? start.layers : { w: c.doc.tex.w, h: c.doc.tex.h, layers: [] }, c.doc, c.layers, input.log, folded);
    const albedo = compositeChannel(c.layers, "albedo", imgOf(renderDoc(m.base.doc)));
    const { doc: tdoc, snapped } = textureDocFromComposite(m.base.doc, albedo);
    if (snapped) warnings.push(`${snapped} half-transparent texels were snapped to solid or clear (Minecraft items are cutout).`);
    const saved = await saveTexture(deps, {
      userId: input.userId, projectId: project.id, key: m.key, doc: tdoc, baseAssetId: m.texture.assetId, expectedHeadId: input.expectedHeadId,
      message: (input.message ?? `Painted ${m.key} in Model Studio`).slice(0, 200),
      provenance: { modelStudio: { doc: { ...c.doc, ...(record ? { log: record } : {}) }, baseAssetId: m.base.assetId, logVerified: verified } },
    });
    await deps.drafts.drop(project.id, input.userId, m.key).catch(() => undefined);
    return { revisionId: saved.revisionId, seq: saved.seq, assetId: saved.assetId, kind: "item3d", logVerified: verified, pack: saved.pack, warnings };
  }

  // creature
  if (c.doc.base.type !== "rigspec") throw new StudioError(400, "bad_doc", "a creature paint must name its RigSpec as the base");
  if (c.doc.base.assetId !== m.assetId || c.doc.base.sha256 !== m.sha256) throw new StudioError(409, "stale_head", "This creature changed in a newer build since you opened it. Reload to see the latest version, then save again.");
  if (c.doc.tex.w !== m.layout.size || c.doc.tex.h !== m.layout.size) throw new StudioError(400, "bad_doc", "the paint size does not match the creature's skin sheet");
  if ((input.baseAssetId ?? null) !== (m.paint?.assetId ?? null)) throw new StudioError(409, "stale_head", "This creature's paint was saved somewhere else since you opened it. Reload, then save again.");
  const start = m.paint ? checkModelDoc(m.paint.doc) : null;
  const { record, verified } = verifyLog(start && start.ok ? start.layers : { w: c.doc.tex.w, h: c.doc.tex.h, layers: [] }, c.doc, c.layers, input.log, folded);
  const doc: ModelDoc = { ...c.doc, base: { ...c.doc.base, spec: obj(rows.find((r) => r.id === m.assetId)?.provenance).spec ?? c.doc.base.spec }, ...(record ? { log: record } : {}) };
  if (m.paint?.stale) warnings.push(m.paint.stale);
  const canonicalDoc = canonicalJson(doc), sha256 = sha256Hex(canonicalDoc);
  const revs = await deps.store.revisions(project.id);
  const head = revs.length ? revs[revs.length - 1] : null;
  if ((head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const path = `assets/models/${m.key}.modeldoc.json`;
  const manifest: ManifestEntry[] = [...(head?.manifest ?? []).filter((e) => e.path !== path), { path, sha256, role: "asset" }];
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, { kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: "cyrus-model-studio L1" }, message: (input.message ?? `Painted ${m.key} in Model Studio`).slice(0, 200) });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const asset = await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: m.key, kind: "model", sha256, size: Buffer.byteLength(canonicalDoc), origin: "edited", mime: MODELDOC_MIME, path,
    provenance: { generator: "cyrus-model-studio", layer: 1, doc, basedOn: m.paint?.assetId ?? null, rigAssetId: m.assetId, logVerified: verified, delivered: false },
  });
  await deps.drafts.drop(project.id, input.userId, m.key).catch(() => undefined);
  warnings.push("Saved as a revision. Painted creature skins are not compiled into the delivered model yet: the in-game creature keeps its generated skin until that step ships.");
  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, kind: "creature", logVerified: verified, warnings };
}

// ---------------------------------------------------------------------------- drafts (autosave)

export type DraftView = { doc: ModelDoc; baseAssetId: string | null; baseHeadId: string | null; updatedAt: string } | null;

export async function getDraft(deps: ModelServiceDeps, userId: string, projectId: string, key: string): Promise<DraftView> {
  // reading your own draft back is viewing: never gated
  await ownedProject(deps, userId, projectId);
  const d = await deps.drafts.get(projectId, userId, key);
  if (!d) return null;
  const c = checkModelDoc(d.doc);
  return c.ok ? { doc: c.doc, baseAssetId: d.baseAssetId, baseHeadId: d.baseHeadId, updatedAt: iso(d.updatedAt) } : null;
}

export async function putDraft(deps: ModelServiceDeps, i: { userId: string; projectId: string; key: string; doc: unknown; baseAssetId: string | null; baseHeadId: string | null }): Promise<{ updatedAt: string }> {
  await gateModel(deps, i.userId, "draft");
  await ownedProject(deps, i.userId, i.projectId);
  const c = checkModelDoc(i.doc);
  if (!c.ok) throw new StudioError(400, "bad_doc", c.error);
  if (c.doc.name !== i.key) throw new StudioError(400, "bad_doc", "the model name must match its key");
  const r = await deps.drafts.put({ projectId: i.projectId, ownerRef: i.userId, assetKey: i.key, baseAssetId: i.baseAssetId, baseHeadId: i.baseHeadId, doc: c.doc });
  return { updatedAt: iso(r.updatedAt) };
}

export async function dropDraft(deps: ModelServiceDeps, userId: string, projectId: string, key: string): Promise<void> {
  await ownedProject(deps, userId, projectId);
  await deps.drafts.drop(projectId, userId, key);
}

