// Cyrus Model Studio: the HTTP handlers of /api/cyrus/models/v1/** (versioned). Framework-free (Request -> Response),
// tested with fakes; app/api/cyrus/models/v1/** are one-line wrappers with modelApiDeps() (./deps.ts).
// Every handler: viewer (a Cyrus user who may see Model Studio: studios gate + cyrus_model_studio_enabled or a preview
// account; anyone else gets a 404 as if the route did not exist) -> rate limit -> input validation -> the plan gate
// (paint / draft / save only, server side, fail closed; viewing and previews are never gated) -> the service.
import { StudioError } from "../studios/service";
import type { StudioViewer } from "../studios/http";
import { dropDraft, getDraft, modelsView, putDraft, renderModelPreview, saveModel, type ModelServiceDeps } from "./service";
import { PREVIEW_PRESETS, PREVIEW_SIZES, type PreviewPreset, type PreviewSize } from "./preview/types";
import { VIEW_CONTEXTS, type ViewContext } from "./contexts";
import { MAX_DOC_BYTES } from "./doc";

export type ModelApiDeps = {
  viewer: () => Promise<StudioViewer | null>;
  service: ModelServiceDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
};

const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
const NOT_FOUND = () => json(404, { error: "Not found" });
const RE = { root: /^[A-Za-z0-9_-]{1,64}$/, project: /^cp[0-9a-f]{20}$/, key: /^[a-z][a-z0-9_]{1,31}$/, id: /^[A-Za-z0-9_-]{1,64}$/, state: /^[a-z][a-z0-9_]{0,23}$/ };
const MAX_BODY = MAX_DOC_BYTES + 1024 * 1024;
const need = (ok: boolean, msg: string) => { if (!ok) throw new StudioError(400, "bad_request", msg); };

async function readJson(req: Request): Promise<Record<string, unknown>> {
  const len = Number(req.headers.get("content-length") ?? 0);
  if (len > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  const text = await req.text();
  if (text.length > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  try { const v = JSON.parse(text || "{}"); if (v && typeof v === "object" && !Array.isArray(v)) return v; } catch { /* fallthrough */ }
  throw new StudioError(400, "bad_json", "Send a JSON object.");
}

async function run(deps: ModelApiDeps, limit: { key: string; max: number }, body: (v: StudioViewer) => Promise<Response>): Promise<Response> {
  const viewer = await deps.viewer().catch(() => null);
  if (!viewer) return NOT_FOUND();
  const rl = deps.rateLimit(`model:${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try {
    return await body(viewer);
  } catch (e) {
    if (e instanceof StudioError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    console.error("[cyrus-model-studio]", limit.key, (e as Error).message);
    return json(500, { error: "Something went wrong on our side. Nothing was changed.", code: "server_error" });
  }
}

type P = { projectId?: string; key?: string };
const params = (p: P) => { need(RE.project.test(p.projectId ?? ""), "projectId is not valid"); need(RE.key.test(p.key ?? ""), "key is not valid"); return p as Required<P>; };
const idOrNull = (v: unknown, name: string): string | null => { if (v === null || v === undefined) return null; need(typeof v === "string" && RE.id.test(v), `${name} is not valid`); return v as string; };

/** GET /api/cyrus/models/v1/projects?root=<rootBuildId>: the mod's models + the viewer's Model Studio access. */
export const handleModels = (req: Request, deps: ModelApiDeps) => run(deps, { key: "read", max: 120 }, async (v) => {
  const root = new URL(req.url).searchParams.get("root") ?? "";
  need(RE.root.test(root), "root must be a build id");
  return json(200, await modelsView(deps.service, v.userId, root));
});

/** POST .../projects/:projectId/models/:key/revisions { doc, baseAssetId, expectedHeadId, log? }: save one paint session. */
export const handleSaveModel = (req: Request, p: P, deps: ModelApiDeps) => run(deps, { key: "save", max: 30 }, async (v) => {
  const { projectId, key } = params(p);
  const b = await readJson(req);
  need(b.log === undefined || Array.isArray(b.log), "log must be a list of ops");
  const r = await saveModel(deps.service, {
    userId: v.userId, projectId, key, doc: b.doc, baseAssetId: idOrNull(b.baseAssetId, "baseAssetId"), expectedHeadId: idOrNull(b.expectedHeadId, "expectedHeadId"),
    log: b.log as unknown[] | undefined, message: typeof b.message === "string" ? b.message.slice(0, 200) : null,
  });
  return json(201, r);
});

/** GET / PUT / DELETE .../models/:key/draft: the autosaved working copy (never built, never shared). */
export const handleDraft = (req: Request, p: P, deps: ModelApiDeps) => run(deps, { key: req.method === "GET" ? "read" : "draft", max: req.method === "GET" ? 120 : 40 }, async (v) => {
  const { projectId, key } = params(p);
  if (req.method === "GET") return json(200, { draft: await getDraft(deps.service, v.userId, projectId, key) });
  if (req.method === "DELETE") { await dropDraft(deps.service, v.userId, projectId, key); return json(200, { ok: true }); }
  const b = await readJson(req);
  return json(200, await putDraft(deps.service, { userId: v.userId, projectId, key, doc: b.doc, baseAssetId: idOrNull(b.baseAssetId, "baseAssetId"), baseHeadId: idOrNull(b.baseHeadId, "baseHeadId") }));
});

/** GET .../models/:key/preview?preset=&size=&source=saved|draft&context=&state=: the deterministic server render (PNG). */
export const handlePreview = (req: Request, p: P, deps: ModelApiDeps) => run(deps, { key: "preview", max: 30 }, async (v) => {
  const { projectId, key } = params(p);
  const q = new URL(req.url).searchParams;
  const preset = (q.get("preset") ?? "three_quarter") as PreviewPreset;
  need(preset in PREVIEW_PRESETS, "unknown preset");
  const size = Number(q.get("size") ?? 512) as PreviewSize;
  need((PREVIEW_SIZES as readonly number[]).includes(size), "size must be 256 or 512");
  const source = q.get("source") === "draft" ? "draft" : "saved";
  const context = (q.get("context") ?? "studio") as ViewContext;
  need(VIEW_CONTEXTS.some((c) => c.id === context), "unknown context");
  const state = q.get("state") ?? undefined;
  need(state === undefined || RE.state.test(state), "state is not valid");
  const r = await renderModelPreview(deps.service, { userId: v.userId, projectId, key, preset, size, source, context, state });
  return new Response(Buffer.from(r.png), { status: 200, headers: { ...H, "content-type": "image/png", "x-cyrus-preview-key": r.key, "x-cyrus-preview-cached": r.cached ? "1" : "0", "x-cyrus-renderer": r.renderer } });
});

