  renderer.setClearColor(new THREE.Color(bg[0] / 255, bg[1] / 255, bg[2] / 255).convertSRGBToLinear(), 1);
  const scene = new THREE.Scene();
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(f32(req.pos), 3));
  geo.setAttribute("uv", new THREE.BufferAttribute(f32(req.uv), 2));
  geo.computeVertexNormals();
  const pixel = req.material === "pixel";
  const tex = (s, srgb, swz) => {
    if (!s) return null;
    const px = b64(s);
    if (swz !== undefined) for (let i = 0; i < px.length; i += 4) px[i + swz] = px[i];
    const t = new THREE.DataTexture(px, req.tex.w, req.tex.h, THREE.RGBAFormat);
    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.magFilter = pixel ? THREE.NearestFilter : THREE.LinearFilter;
    t.minFilter = pixel ? THREE.NearestFilter : THREE.LinearFilter;
    t.generateMipmaps = false; t.flipY = false; t.needsUpdate = true;
    return t;
  };
  const m = req.maps;
  const mat = new THREE.MeshStandardMaterial({
    map: tex(m.albedo, true), side: THREE.DoubleSide, alphaTest: LOOK.pixel.alphaTest,
    roughness: pixel ? LOOK.pixel.roughness : 1, metalness: pixel ? LOOK.pixel.metalness : (m.metallic ? 1 : 0),
  });
  if (!pixel) {
    if (m.normal) mat.normalMap = tex(m.normal, false);
    if (m.roughness) mat.roughnessMap = tex(m.roughness, false, 1);
    if (m.metallic) mat.metalnessMap = tex(m.metallic, false, 2);
    if (m.emissive) { mat.emissiveMap = tex(m.emissive, true); mat.emissive = new THREE.Color(1, 1, 1); }
  }
  const mesh = new THREE.Mesh(geo, mat);
  if (req.model) { mesh.matrixAutoUpdate = false; mesh.matrix.fromArray(req.model); }
  scene.add(mesh);
  const L = LOOK.light;
  scene.add(new THREE.AmbientLight(L.ambient.color, L.ambient.intensity));
  for (const k of ["key", "fill", "rim"]) { const d = new THREE.DirectionalLight(L[k].color, L[k].intensity); d.position.set(L[k].dir[0], L[k].dir[1], L[k].dir[2]); scene.add(d); }
  mesh.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(mesh);
  const sphere = box.getBoundingSphere(new THREE.Sphere());
  const r = Math.max(1e-3, sphere.radius), c = sphere.center;
  let camera;
  const cam = req.cam;
  const P = LOOK.presets[req.preset] || LOOK.presets.three_quarter;
  const yaw = THREE.MathUtils.degToRad(cam ? cam.yaw : P.yaw), pitch = THREE.MathUtils.degToRad(cam ? cam.pitch : P.pitch);
  const dir = new THREE.Vector3(Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch), Math.cos(pitch) * Math.cos(yaw));
  if (cam && cam.proj === "persp") {
    camera = new THREE.PerspectiveCamera(cam.fov, 1, 0.01, 100);
    const t = new THREE.Vector3(cam.target[0], cam.target[1], cam.target[2]);
    camera.position.copy(t).addScaledVector(dir, cam.dist);
    camera.lookAt(t);
  } else if (cam && cam.proj === "ortho") {
    const e = r * 1.15;
    camera = new THREE.OrthographicCamera(-e, e, e, -e, 0.01, r * 8 + 10);
    camera.position.copy(c).addScaledVector(dir, r * 3 + 1);
    camera.lookAt(c);
  } else {
    const fov = 30;
    camera = new THREE.PerspectiveCamera(fov, 1, Math.max(0.001, r * 0.05), r * 20);
    const dist = (r / Math.sin(THREE.MathUtils.degToRad(fov) / 2)) * 1.08;
    camera.position.copy(c).addScaledVector(dir, dist);
    camera.lookAt(c);
  }
  renderer.render(scene, camera);
  const url = canvas.toDataURL("image/png");
  geo.dispose(); mat.dispose(); renderer.dispose(); renderer.forceContextLoss();
  return url.slice(url.indexOf(",") + 1);
};
window.__cyrusReady = true;
</script></body></html>`;
}

