// Cyrus Model Studio: the node-2 PREVIEW RENDERER (plan section 5, mesh/PBR lane): headless Chromium (Playwright,
// already on node-2) + three.js on SwiftShader. SERVER ONLY, and only on the build host: it launches a browser, so it
// must never run in the primary's web process (./select.ts refuses that). Budgets per render:
//   time     hard timeout (default 60 s): the browser server is KILLED, not asked to close
//   memory   V8 heap capped (--max-old-space-size), one renderer process, no /dev/shm; the systemd slice caps the rest
//   network  none: every request is intercepted; only the page and two three.js files from node_modules are served,
//            everything else is aborted; DNS resolves nothing (--host-resolver-rules)
//   output   PNG only, size-capped
// One fresh browser per render (no shared state between jobs). Renders are deterministic for a pinned Chromium build
// (golden-image test: test/cyrus-modelstudio-render.test.ts, tolerance in ./golden.ts).
import { readFileSync } from "node:fs";
import path from "node:path";
import { checkPreviewRequest, previewKey, PREVIEW_RENDERER_VERSION, type PreviewRenderer, type PreviewRequest, type PreviewResult } from "./types";
import { pageHtml, RENDER_ORIGIN } from "./page-script";

export type PlaywrightRendererOptions = { timeoutMs?: number; heapMb?: number; maxPngBytes?: number; threeDir?: string; executablePath?: string };

export const CHROMIUM_ARGS = [
  "--headless=new", "--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist",
  "--disable-dev-shm-usage", "--renderer-process-limit=1", "--disable-extensions", "--disable-background-networking",
  "--disable-component-update", "--disable-default-apps", "--disable-sync", "--no-first-run", "--mute-audio",
  "--host-resolver-rules=MAP * ~NOTFOUND", "--force-color-profile=srgb", "--disable-lcd-text", "--font-render-hinting=none",
];

function threeFiles(dir?: string): Record<string, Buffer> {
  const d = dir ?? path.join(process.cwd(), "node_modules", "three", "build");
  return { "/three.module.js": readFileSync(path.join(d, "three.module.js")), "/three.core.js": readFileSync(path.join(d, "three.core.js")) };
}

export function playwrightRenderer(o: PlaywrightRendererOptions = {}): PreviewRenderer {
  const timeoutMs = Math.min(120_000, Math.max(5_000, o.timeoutMs ?? 60_000));
  const heap = Math.min(1024, Math.max(128, o.heapMb ?? 512));
  const maxPng = o.maxPngBytes ?? 4 * 1024 * 1024;
  let files: Record<string, Buffer> | null = null;
  const id = `playwright:${PREVIEW_RENDERER_VERSION}`;
  return {
    id,
    async render(req: PreviewRequest): Promise<PreviewResult> {
      const bad = checkPreviewRequest(req);
      if (bad) return { ok: false, code: "bad_request", error: bad };
      const t0 = Date.now();
      let pw: typeof import("playwright");
      try { pw = await import("playwright"); } catch { return { ok: false, code: "unavailable", error: "Playwright is not installed here" }; }
      try { files ??= threeFiles(o.threeDir); } catch { return { ok: false, code: "unavailable", error: "three.js build files not found" }; }
      let server: Awaited<ReturnType<typeof pw.chromium.launchServer>> | null = null;
      let timer: NodeJS.Timeout | null = null;
      const html = pageHtml();
      const job = (async (): Promise<PreviewResult> => {
        server = await pw.chromium.launchServer({ headless: true, args: [...CHROMIUM_ARGS, `--js-flags=--max-old-space-size=${heap}`], timeout: timeoutMs, ...(o.executablePath ? { executablePath: o.executablePath } : {}) });
        const browser = await pw.chromium.connect(server.wsEndpoint(), { timeout: timeoutMs });
        const ctx = await browser.newContext({ viewport: { width: req.size, height: req.size }, deviceScaleFactor: 1, javaScriptEnabled: true, serviceWorkers: "block" });
        await ctx.route("**/*", async (route) => {
          const u = new URL(route.request().url());
          if (u.origin !== RENDER_ORIGIN) return route.abort("blockedbyclient");
          if (u.pathname === "/" || u.pathname === "/index.html") return route.fulfill({ status: 200, contentType: "text/html", body: html });
          const f = files![u.pathname];
          return f ? route.fulfill({ status: 200, contentType: "text/javascript", body: f }) : route.abort("blockedbyclient");
        });
        const page = await ctx.newPage();
        await page.goto(`${RENDER_ORIGIN}/index.html`, { waitUntil: "load", timeout: timeoutMs });
        await page.waitForFunction(() => (window as unknown as { __cyrusReady?: boolean }).__cyrusReady === true, undefined, { timeout: timeoutMs });
        const b64 = await page.evaluate((r) => (window as unknown as { __cyrusRender: (x: unknown) => string }).__cyrusRender(r), req as unknown as Record<string, unknown>);
        await browser.close();
        const png = Buffer.from(b64, "base64");
        if (png.length > maxPng) return { ok: false, code: "too_large", error: "the preview image is too large" };
        if (png.length < 8 || png[0] !== 0x89) return { ok: false, code: "crashed", error: "the renderer returned no image" };
        return { ok: true, png: new Uint8Array(png), width: req.size, height: req.size, ms: Date.now() - t0, renderer: id, key: previewKey(req, id) };
      })();
      const timeout = new Promise<PreviewResult>((res) => { timer = setTimeout(() => res({ ok: false, code: "timeout", error: `the preview render took longer than ${timeoutMs / 1000}s` }), timeoutMs); });
      try {
        return await Promise.race([job.catch((e: Error): PreviewResult => ({ ok: false, code: "crashed", error: String(e.message).slice(0, 300) })), timeout]);
      } finally {
        if (timer) clearTimeout(timer);
        // always a hard kill: the browser never outlives the job
        try { await (server as unknown as { kill(): Promise<void> } | null)?.kill(); } catch { /* already gone */ }
      }
    },
  };
}

