cd /tank/dev-worktrees/cyrus-r16 && sed -i 's/  "--headless=new", "--use-gl=angle"/  "--use-gl=angle"/' lib/cyrus/modelstudio/preview/playwright.ts && cat > lib/cyrus/modelstudio/preview/select.ts <<'EOF'
// Which preview renderer this process may use. SERVER ONLY. OFF unless CYRUS_MODEL_PREVIEW=local, and "local" (a
// browser launched in THIS process) is refused in production: production web and worker run on the primary, which
// never runs Chromium (BUILD-HOST.md). The production path is a node-2 job behind a transport like the sound render
// host's relay; that transport is not built yet (OWNER-ACTIONS), so production says so instead of rendering.
import type { PreviewRenderer } from "./types";
import { playwrightRenderer } from "./playwright";

export type RendererSelection = { ok: true; renderer: PreviewRenderer } | { ok: false; reason: string };
const G = globalThis as { __cyrusModelPreview?: PreviewRenderer };

export function selectPreviewRenderer(env: Record<string, string | undefined> = process.env): RendererSelection {
  const mode = (env.CYRUS_MODEL_PREVIEW ?? "").trim();
  if (!mode || mode === "off") return { ok: false, reason: "the server preview renderer is not switched on here (CYRUS_MODEL_PREVIEW)" };
  if (mode !== "local") return { ok: false, reason: `unknown CYRUS_MODEL_PREVIEW=${mode}` };
  if (env.NODE_ENV === "production") return { ok: false, reason: "production never launches a browser on this server; the node-2 preview job transport is not built yet" };
  return { ok: true, renderer: (G.__cyrusModelPreview ??= playwrightRenderer({ timeoutMs: Number(env.CYRUS_MODEL_PREVIEW_TIMEOUT_MS) || 60_000 })) };
}
