// Golden-image comparison for the server preview renderer (plan section 5: "golden images with tolerance, <= 0.5 %
// pixels off by > 2/255"). SERVER ONLY (PNG decode uses node:zlib through lib/cyrus/library/png-decode.ts).
import { decodePng } from "../../library/png-decode";
import type { Raster } from "../../textures/render";

export const GOLDEN_TOLERANCE = { channel: 2, maxFraction: 0.005 } as const;

export function decodePreviewPng(png: Uint8Array, size: number): Raster | null {
  const d = decodePng(Buffer.from(png), { maxBytes: 8 * 1024 * 1024, sizes: [size], maxChunks: 64 });
  return d.ok ? d.raster : null;
}

export type GoldenDiff = { ok: boolean; off: number; total: number; fraction: number; maxDelta: number };

/** Pixels whose any channel differs by more than `channel`; ok when their share is at most `maxFraction`. */
export function compareRasters(a: Raster, b: Raster, tol: { channel: number; maxFraction: number } = GOLDEN_TOLERANCE): GoldenDiff {
  if (a.size !== b.size) return { ok: false, off: a.size * a.size, total: a.size * a.size, fraction: 1, maxDelta: 255 };
  const n = a.size * a.size;
  let off = 0, maxDelta = 0;
  for (let i = 0; i < n; i++) {
    let d = 0;
    for (let k = 0; k < 4; k++) d = Math.max(d, Math.abs(a.px[i * 4 + k] - b.px[i * 4 + k]));
    if (d > tol.channel) off++;
    maxDelta = Math.max(maxDelta, d);
  }
  const fraction = off / n;
  return { ok: fraction <= tol.maxFraction, off, total: n, fraction, maxDelta };
}

