  const def = CHANNEL_DEFAULT[channel];
  const ls = set.layers.filter((l) => l.visible && l.channel === channel && l.opacity > 0);
  for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
    const o = (y * w + x) * 4;
    let c0: number, c1: number, c2: number, c3: number;
    if (base) { c0 = base.px[o]; c1 = base.px[o + 1]; c2 = base.px[o + 2]; c3 = base.px[o + 3]; } else { c0 = def[0]; c1 = def[1]; c2 = def[2]; c3 = def[3]; }
