    }
    out.px[o] = c0; out.px[o + 1] = c1; out.px[o + 2] = c2; out.px[o + 3] = c3;
  }
  void h;
}

/** The texel rectangle an op can change (brush / erase / fill / decal); null = layer ops (recomposite everything). */
export function opRect(op: { t: string; size?: number; pts?: [number, number][]; spans?: [number, number, number][]; x?: number; y?: number; stamp?: { w: number; h: number } }): Rect | null {
  if ((op.t === "brush" || op.t === "erase") && op.pts?.length) {
    const s = op.size ?? 1;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const [x, y] of op.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
    return { x: x0 - s, y: y0 - s, w: x1 - x0 + 2 * s + 1, h: y1 - y0 + 2 * s + 1 };
  }
  if (op.t === "fill" && op.spans?.length) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const [y, a, b] of op.spans) { y0 = Math.min(y0, y); y1 = Math.max(y1, y); x0 = Math.min(x0, a); x1 = Math.max(x1, b); }
    return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 + 1 };
  }
  if (op.t === "decal" && op.stamp) return { x: op.x ?? 0, y: op.y ?? 0, w: op.stamp.w, h: op.stamp.h };
  return null;
}
