import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { ASSET_KINDS } from "../lib/cyrus/engine-core/spec";
import { ASSET_OPS, ASSET_PLANS, canAsset, canModelStudio, GATED_OPS, MODEL_STUDIO_ACTIONS, MODEL_STUDIO_OP } from "../lib/cyrus/engine-core/asset-gate";
import { studioPlanView, PLAN_MATRIX, MODEL_STUDIO_MATRIX_ROW } from "../lib/cyrus/studios/access";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { TEXTURE_SPEC_MIME } from "../lib/cyrus/assets/sync";
import { docFromSpec, renderDoc } from "../lib/cyrus/studios/paint";
import { buildIdentifier } from "../lib/cyrus/engine-core/identifiers";
import type { AssetRow, ChainInfo, ProjectRow, RevRow, StudioStore } from "../lib/cyrus/studios/service";
import { apply4, barycentric, camEye, invert4, m4FromTrs, mul4, rayFromOrbit, rayTri, uvToTexel, type V3 } from "../lib/cyrus/modelstudio/math";
import { cubeFaceCorners, restMatrices, sceneFromGltf, sceneFromItem, sceneFromRig, triPos, type Img } from "../lib/cyrus/modelstudio/scene";
import { encodeGlb, parseGltf, imageSize } from "../lib/cyrus/modelstudio/gltf";
import { mirrorHit, pickScene, rasterTris, regionOf, spansCount, texelAt, uvIslands } from "../lib/cyrus/modelstudio/pick";
import { b64decode, b64encode, CHANNEL_DEFAULT, compositeChannel, compositeRegion, decodePixels, encodePixels, newLayer, opRect, paintedCount, type LayerSet } from "../lib/cyrus/modelstudio/layers";
import { applyOp, applyOpMut, appliedOps, canRedoS, canUndoS, checkOp, floodSpans, footprint, MAX_STEPS, replay, sessionInit, sessionPush, sessionRedo, sessionState, sessionUndo, type Op } from "../lib/cyrus/modelstudio/paint";
import { mergeLayerSets } from "../lib/cyrus/modelstudio/merge";
import { checkModelDoc, decodeLayers, encodeLayers, MODELDOC_MIME, startLayers, type ModelDoc } from "../lib/cyrus/modelstudio/doc";
import { channelImage, paintChannels, uvChecker, viewModes } from "../lib/cyrus/modelstudio/channels";
import { contextRig, contextTransform, displayMatrix, gripChecks, gripInHand, gripReference, gripSummary, HAND_ANCHOR, IDENTITY_DISPLAY, VIEW_CONTEXTS } from "../lib/cyrus/modelstudio/contexts";
