const FX = path.join(__dirname, "fixtures", "cyrus-creatures");
const banshee = () => { const c = checkRigSpec(JSON.parse(fs.readFileSync(path.join(FX, "banshee.json"), "utf8"))); if (!c.ok) throw new Error(c.error); return c.spec; };
const near = (a: number, b: number, e = 1e-6) => Math.abs(a - b) <= e;
const nearV = (a: readonly number[], b: readonly number[], e = 1e-6) => a.every((v, i) => near(v, b[i], e));
const imgOf = (r: Raster): Img => ({ w: r.size, h: r.size, px: r.px });

// ------------------------------------------------------------------------------------------------ math
describe("model studio math", () => {
  it("ray/triangle: hits inside and on edges, misses outside, returns barycentrics", () => {
    const a: V3 = [0, 0, 0], b: V3 = [1, 0, 0], c: V3 = [0, 1, 0];
    const h = rayTri({ o: [0.25, 0.25, 5], d: [0, 0, -1] }, a, b, c)!;
    assert.ok(near(h.t, 5) && near(h.u, 0.25) && near(h.v, 0.25));
    assert.ok(rayTri({ o: [0.5, 0, 1], d: [0, 0, -1] }, a, b, c), "edge counts as inside");
    assert.equal(rayTri({ o: [0.8, 0.8, 1], d: [0, 0, -1] }, a, b, c), null);
    assert.equal(rayTri({ o: [0.2, 0.2, -1], d: [0, 0, -1] }, a, b, c), null, "behind the origin");
    assert.ok(rayTri({ o: [0.2, 0.2, -1], d: [0, 0, 1] }, a, b, c), "two-sided");
    assert.deepEqual(barycentric([0.25, 0.25, 0], a, b, c).map((v) => Math.round(v * 1000) / 1000), [0.5, 0.25, 0.25]);
  });
  it("uv -> texel: top-left origin, last texel at u=1, clamp vs wrap", () => {
    assert.deepEqual(uvToTexel([0, 0], 16, 16), [0, 0]);
    assert.deepEqual(uvToTexel([1, 1], 16, 16), [15, 15]);
    assert.deepEqual(uvToTexel([0.5, 0.5], 16, 16), [8, 8]);
    assert.deepEqual(uvToTexel([3 / 16, 5 / 16], 16, 16), [3, 5], "an exact texel border belongs to the texel to its right/below");
    assert.deepEqual(uvToTexel([-0.25, 1.5], 16, 16), [0, 15]);
    assert.deepEqual(uvToTexel([-0.25, 1.5], 16, 16, true), [12, 8]);
  });
  it("TRS, inverse and the orbit ray are consistent", () => {
    const m = m4FromTrs([1, 2, 3], [0, Math.SQRT1_2, 0, Math.SQRT1_2], [2, 2, 2]);
    assert.ok(nearV(apply4(m, [1, 0, 0]), [1, 2, 1]), "90 deg about y maps +x to -z");
    const inv = invert4(m)!;
    assert.ok(nearV(apply4(inv, apply4(m, [0.3, -2, 7])), [0.3, -2, 7], 1e-9));
    const cam = { yaw: 30, pitch: 20, dist: 3, target: [0.2, 0.1, 0] as V3, fov: 40 };
    const r = rayFromOrbit(cam, 50, 50, 101, 101);
    const eye = camEye(cam);
    const toT = [cam.target[0] - eye[0], cam.target[1] - eye[1], cam.target[2] - eye[2]].map((v) => v / 3);
    assert.ok(nearV(r.d, toT, 1e-9), "the centre pixel looks at the target");
  });
});

// ------------------------------------------------------------------------------------------------ display contexts
describe("display contexts: the matrices ARE the item model module's transforms", () => {
  const pts: V3[] = [[0, 0, 0], [16, 16, 16], [2.5, 1.5, 8], [8, 8, 8], [13.1, 3.7, 7.5], [5, 12, 8.5]];
  it("displayMatrix(t) * v == applyDisplay(t, v) for every vanilla category display and the gun", () => {
    const gun = displayFor("glock_9mm", render(GLOCK));
    const all = [...Object.values(HANDHELD_FULL), ...Object.values(BOW_FULL), ...Object.values(CROSSBOW_FULL), ...Object.values(GENERATED_FULL), ...Object.values(gun)];
    for (const t of all) { const M = displayMatrix(t); for (const p of pts) assert.ok(nearV(apply4(M, p), applyDisplay(t, p), 1e-9), JSON.stringify(t)); }
  });
  it("contexts come from stateDisplays (the pack's own numbers); studio and on_shelf are identity", () => {
    const tpl = gunTemplate();
    const idle = render(tpl.textures[0]);
    const d = stateDisplays(tpl.spec, idle);
    for (const c of PREVIEW_CONTEXTS) assert.deepEqual(contextTransform(d.idle, c.id), d.idle[c.display]);
    assert.deepEqual(contextTransform(d.aiming, "firstperson").translation, [-2, 4.5, -1], "per-state display override");
    assert.deepEqual(contextTransform(d.idle, "on_shelf"), IDENTITY_DISPLAY);
    assert.deepEqual(contextTransform(d.idle, "studio"), IDENTITY_DISPLAY);
    assert.deepEqual(VIEW_CONTEXTS.map((c) => c.id), ["studio", "gui", "ground", "firstperson", "thirdperson", "fixed", "head", "on_shelf"]);
  });
  it("first-person rig: model point -> world = FP_HAND + applyDisplay/16 (studios/held.ts convention); the fist sits at the vanilla anchor", () => {
    const t = HANDHELD_FULL.firstperson_righthand;
    const rig = contextRig("firstperson", t);
    for (const p of pts) { const a = applyDisplay(t, p); assert.ok(nearV(apply4(rig.model, p), [0.56 + a[0] / 16, -0.52 + a[1] / 16, -0.72 + a[2] / 16], 1e-9)); }
    const handle = apply4(rig.model, [TOOL_HANDLE[0], TOOL_HANDLE[1], 8]);
    assert.ok(nearV(handle, rig.hand!, 1e-9), "a vanilla tool's handle is exactly in the fist");
    const tp = contextRig("thirdperson", HANDHELD_FULL.thirdperson_righthand);
    assert.ok(nearV(apply4(tp.model, [TOOL_HANDLE[0], TOOL_HANDLE[1], 8]), tp.hand!, 1e-9));
    const a = applyDisplay(HANDHELD_FULL.thirdperson_righthand, [8, 8, 8]);
    assert.ok(nearV(apply4(tp.model, [8, 8, 8]), [-a[2] / 16, a[1] / 16, a[0] / 16], 1e-9), "third person = held.ts tpBasis");
  });
  it("grip_in_hand: vanilla categories pass with their own defaults; overrides that move the grip are caught", () => {
    const sw = swordTemplate(), bw = bowTemplate();
    for (const tpl of [sw, bw]) {
      const idle = render(tpl.textures[0]);
      const ref = gripReference(tpl.spec.category, idle);
      for (const c of gripChecks(stateDisplays(tpl.spec, idle), ref)) assert.equal(c.distance, 0, `${tpl.spec.name} ${c.state} ${c.view}`);
    }
    const moved = gripInHand({ ...HANDHELD_DISPLAY.thirdperson_righthand, translation: [0, 9, 0.5] }, TOOL_HANDLE, "thirdperson");
    assert.equal(moved.status, "fail"); assert.equal(moved.distance, 5);
    const fp = gripInHand({ ...HANDHELD_DISPLAY.firstperson_righthand, translation: [1.13, 9, 1.13] }, TOOL_HANDLE, "firstperson");
    assert.equal(fp.status, "warn", "first person is advisory: the game draws no arm while an item is held");
    assert.equal(fp.advisory, true);
  });
  it("grip_in_hand on the Cyrus gun defaults (UNVERIFIED in a client): measured against the vanilla tool fist", () => {
    const tpl = gunTemplate(), idle = render(tpl.textures[0]);
    const ref = gripReference("gun", idle);
