    const checks = gripChecks(stateDisplays(tpl.spec, idle), ref);
    const tp = checks.find((c) => c.state === "idle" && c.view === "thirdperson")!;
    const fp = checks.find((c) => c.state === "idle" && c.view === "firstperson")!;
    // these are the real numbers today; the docs + OWNER-ACTIONS report them (re-grip is computed under the gun rotation)
    assert.equal(tp.distance, 1.948); assert.equal(tp.status, "warn");
    assert.equal(fp.distance, 3.148); assert.equal(fp.status, "warn");
    assert.equal(gripSummary(checks).status, "warn");
    assert.equal(gripSummary([]).status, "not_run");
  });
