// ------------------------------------------------------------------------------------------------ scenes + golden picks
describe("scene + pick -> UV -> texel (golden cases)", () => {
  it("creature rest matrices equal the creature preview renderer's poseMatrices", () => {
    const spec = banshee();
    const a = restMatrices(spec), b = poseMatrices(spec);
    for (const bone of spec.bones) assert.ok(nearV(a.get(bone.name)!, b.get(bone.name)!, 1e-9), bone.name);
  });
  it("creature: a ray onto the centre of EVERY texel of EVERY cube face returns exactly that skin texel", () => {
    const spec = banshee();
    const lay = layoutSkin(spec);
    assert.ok(lay.ok);
    if (!lay.ok) return;
    const scene = sceneFromRig(spec, lay.layout);
    assert.equal(scene.tex.w, lay.layout.size);
    assert.equal(scene.triCount, lay.layout.cubes.length * 12);
    const mats = restMatrices(spec);
    let checked = 0, hidden = 0, wrong = 0;
    for (const cl of lay.layout.cubes) {
      const bone = spec.bones.find((b) => b.name === cl.bone)!, c = bone.cubes[cl.index], M = mul4([spec.scale, 0, 0, 0, 0, spec.scale, 0, 0, 0, 0, spec.scale, 0, 0, 0, 0, 1], mats.get(bone.name)!);
      const inf = c.inflate;
      const A: V3 = [c.from[0] - inf, c.from[1] - inf, c.from[2] - inf], B: V3 = [c.to[0] + inf, c.to[1] + inf, c.to[2] + inf];
      for (const f of ["north", "east", "south", "west", "up", "down"] as const) {
        const fc = cubeFaceCorners(f, A, B), r = cl.faces[f];
        const TL = apply4(M, fc.tl), TR = apply4(M, fc.tr), BL = apply4(M, fc.bl);
        const ex = TR.map((v, k) => v - TL[k]), ey = BL.map((v, k) => v - TL[k]);
        const n0 = [ex[1] * ey[2] - ex[2] * ey[1], ex[2] * ey[0] - ex[0] * ey[2], ex[0] * ey[1] - ex[1] * ey[0]];
        const nl = Math.hypot(...n0) || 1;
