describe("conflict rule: 3-way merge per layer + texel, human wins", () => {
  const mk = (): LayerSet => startLayers(null, 4, 4);
  const paint = (s: LayerSet, i: number, c: number[], id = "paint") => { const l = s.layers.find((x) => x.id === id)!; l.px.set(c, i * 4); return s; };
  it("disjoint changes merge; overlapping texels are listed and keep the human's colour", () => {
    const base = mk(), ours = paint(paint(mk(), 0, [1, 1, 1, 255]), 5, [7, 7, 7, 255]), theirs = paint(paint(mk(), 3, [2, 2, 2, 255]), 5, [9, 9, 9, 255]);
    const m = mergeLayerSets(base, ours, theirs);
    const l = m.set.layers[0];
    assert.deepEqual([...l.px.subarray(0, 4)], [1, 1, 1, 255]);
    assert.deepEqual([...l.px.subarray(12, 16)], [2, 2, 2, 255], "theirs' disjoint change merged in");
    assert.deepEqual([...l.px.subarray(20, 24)], [7, 7, 7, 255], "human wins the overlap");
    assert.deepEqual(m.overlaps, [{ layer: "paint", texels: 1, props: [] }]);
    const t = mergeLayerSets(base, ours, theirs, { prefer: "theirs" });
    assert.deepEqual([...t.set.layers[0].px.subarray(20, 24)], [9, 9, 9, 255]);
  });
  it("new layers on either side are kept; deleted-vs-changed is an overlap; Apply part takes only chosen layers", () => {
    const base = mk();
    const ours = mk(); ours.layers.push({ ...newLayer("mine", "Mine", "albedo", 4, 4) });
    const theirs = mk(); theirs.layers.push({ ...newLayer("ai", "AI", "emissive", 4, 4) }); paint(theirs, 2, [5, 5, 5, 255]);
    const m = mergeLayerSets(base, ours, theirs);
    assert.deepEqual(m.set.layers.map((l) => l.id), ["paint", "mine", "ai"]);
    const part = mergeLayerSets(base, ours, theirs, { only: new Set(["ai"]) });
    assert.deepEqual(part.set.layers.map((l) => l.id), ["paint", "mine", "ai"]);
    assert.deepEqual([...part.set.layers[0].px.subarray(8, 12)], [0, 0, 0, 0], "paint layer not taken");
    const del = { ...mk(), layers: [] }; const changedTheirs = paint(mk(), 1, [3, 3, 3, 255]);
    const d = mergeLayerSets(base, del, changedTheirs);
    assert.equal(d.set.layers.length, 0); assert.equal(d.overlaps[0].deleted, "ours");
    assert.equal(mergeLayerSets(base, del, changedTheirs, { prefer: "theirs" }).set.layers.length, 1);
  });
});

