describe("plan gate: the WHOLE plan x kind x op matrix, every Model Studio action, fail closed", () => {
  const RANK: Record<string, number> = { free: 0, katara: 1, saka: 2, all: 3 };
  const MIN: Record<string, number> = { sound: 2, texture: 3, model: 3, ui: 3 };
  it("canAsset: gated ops need the kind's plan; other ops always allowed; unknown plan denies only gated ops", () => {
    for (const plan of [...ASSET_PLANS, "yakko", "All Models", null, undefined, "", "gold", 42]) for (const kind of ASSET_KINDS) for (const op of ASSET_OPS) {
      const d = canAsset(plan, kind, op);
      const p = typeof plan === "string" ? ({ yakko: "all", "all models": "all" } as Record<string, string>)[plan.toLowerCase()] ?? plan : null;
      const known = p !== null && p in RANK;
      if (!GATED_OPS.includes(op)) { assert.equal(d.ok, true, `${plan} ${kind} ${op}`); continue; }
      if (!known) { assert.equal(d.ok, false); if (!d.ok) assert.equal(d.code, "plan_unknown"); continue; }
      assert.equal(d.ok, RANK[p!] >= MIN[kind], `${plan} ${kind} ${op}`);
      if (!d.ok) { assert.equal(d.code, "asset_locked"); assert.equal(d.needs, kind === "sound" ? "saka" : "all"); }
    }
  });
  it("canModelStudio: viewing/installing/exporting never gated; every create/edit action = top plan only", () => {
    const EDIT = ["paint", "fill", "decal", "layer", "draft", "save", "ai_edit"];
    for (const a of MODEL_STUDIO_ACTIONS) for (const plan of [...ASSET_PLANS, null, "nope"]) {
      const d = canModelStudio(plan, a);
      if (!EDIT.includes(a)) { assert.equal(d.ok, true, `${a} ${plan}`); continue; }
      assert.equal(MODEL_STUDIO_OP[a], "edit");
      assert.equal(d.ok, plan === "all", `${a} ${plan}`);
      if (!d.ok) assert.equal(d.code, plan === "free" || plan === "katara" || plan === "saka" ? "asset_locked" : "plan_unknown");
    }
    const u = canModelStudio("all", "teleport" as never);
    assert.equal(u.ok, false); if (!u.ok) assert.equal(u.code, "bad_request");
    assert.equal(studioPlanView("saka").edit.model.ok, false);
    assert.equal(studioPlanView("all").edit.model.ok, true);
    assert.ok(!PLAN_MATRIX.some((r) => "label" in r && r.label === "Model Studio"), "the flagged-off studio never leaks into the shared matrix");
    assert.equal(MODEL_STUDIO_MATRIX_ROW && "allowed" in MODEL_STUDIO_MATRIX_ROW && MODEL_STUDIO_MATRIX_ROW.allowed("all"), true);
  });
  it("visibility: studios gate AND (preview OR the model setting)", () => {
    for (const s of [true, false]) for (const p of [true, false]) for (const f of [true, false]) assert.equal(modelStudioOpen({ studiosOpen: s, previewUser: p, modelFlagOn: f }), s && (p || f));
  });
});

