describe("lossless channel layers", () => {
  it("rle1 round-trips random and sparse pixels exactly; base64 matches node", () => {
    let seed = 7; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
    for (const fill of [0, 0.02, 0.5, 1]) {
      const px = new Uint8ClampedArray(64 * 64 * 4);
      for (let i = 0; i < 64 * 64; i++) if (rnd() < fill) { px[i * 4] = (rnd() * 255) | 0; px[i * 4 + 1] = (rnd() * 4) | 0; px[i * 4 + 2] = 9; px[i * 4 + 3] = 1 + ((rnd() * 254) | 0); }
      assert.deepEqual(decodePixels(encodePixels(px), 64 * 64), px);
    }
    const empty = encodePixels(new Uint8ClampedArray(2048 * 2048 * 4));
    assert.ok(empty.length < 16, `an empty 2048^2 layer is ${empty.length} chars`);
    assert.equal(decodePixels(empty, 2048 * 2048 - 1), null, "wrong texel count is refused");
    assert.equal(decodePixels("!!!!", 4), null);
    const b = Uint8Array.from([1, 2, 3, 250, 0]);
    assert.equal(b64encode(b), Buffer.from(b).toString("base64"));
    assert.deepEqual(b64decode(Buffer.from(b).toString("base64")), b);
  });
  it("composite: integer blend maths, opacity, visibility, channel defaults; region composite equals full", () => {
    const set: LayerSet = { w: 2, h: 1, layers: [newLayer("a", "A", "albedo", 2, 1), newLayer("m", "M", "albedo", 2, 1)] };
    set.layers[0].px.set([200, 100, 50, 255, 10, 10, 10, 128]);
    set.layers[1].px.set([128, 128, 128, 255, 0, 0, 0, 0]);
    set.layers[1].blend = "multiply"; set.layers[1].opacity = 128;
    const base: Img = { w: 2, h: 1, px: Uint8ClampedArray.from([0, 0, 255, 255, 255, 255, 255, 255]) };
    const c = compositeChannel(set, "albedo", base);
    // texel 0: normal 200,100,50 full; then multiply by 128 at opacity 128/255
    const mulc = (d: number) => d + Math.round(((Math.round((d * 128) / 255) - d) * 255 * 128) / 65025);
    assert.deepEqual([...c.px.subarray(0, 4)], [mulc(200), mulc(100), mulc(50), 255]);
    // texel 1: normal 10 at alpha 128 over 255
    const nc = 255 + Math.round(((10 - 255) * 128 * 255) / 65025);
    assert.deepEqual([...c.px.subarray(4, 8)], [nc, nc, nc, 255]);
    set.layers[0].visible = false;
    assert.deepEqual([...compositeChannel(set, "albedo", base).px.subarray(4, 8)], [255, 255, 255, 255]);
    assert.deepEqual([...compositeChannel(set, "normal", null).px.subarray(0, 4)], CHANNEL_DEFAULT.normal);
    // region == full on a random 32^2 set
    const big: LayerSet = { w: 32, h: 32, layers: [newLayer("p", "P", "roughness", 32, 32), newLayer("q", "Q", "roughness", 32, 32)] };
    for (let i = 0; i < 32 * 32 * 4; i++) { big.layers[0].px[i] = (i * 37) & 255; big.layers[1].px[i] = (i * 91) & 255; }
    big.layers[1].blend = "overlay"; big.layers[1].opacity = 77;
    const full = compositeChannel(big, "roughness", null);
    const out: Img = { w: 32, h: 32, px: new Uint8ClampedArray(32 * 32 * 4) };
    compositeRegion(big, "roughness", null, { x: 0, y: 0, w: 32, h: 32 }, out);
    assert.deepEqual(out.px, full.px);
    assert.equal(paintedCount(big).total, 32 * 32 - 0 - [...Array(32 * 32).keys()].filter((i) => !big.layers[0].px[i * 4 + 3] && !big.layers[1].px[i * 4 + 3]).length);
  });
});

// ------------------------------------------------------------------------------------------------ paint engine
describe("paint engine: ops, determinism, undo/redo", () => {
  const W = 16;
  const blank = (): LayerSet => startLayers(null, W, W);
  it("footprints: square sizes 1-3, round 3 = plus, round 5 = disc", () => {
    assert.deepEqual(footprint(4, 4, 1, "square"), [[4, 4]]);
    assert.deepEqual(footprint(4, 4, 2, "square"), [[4, 4], [5, 4], [4, 5], [5, 5]]);
    assert.equal(footprint(4, 4, 3, "square").length, 9);
    assert.deepEqual(footprint(4, 4, 3, "round").map(([x, y]) => `${x},${y}`).sort(), ["3,4", "4,3", "4,4", "4,5", "5,4"]);
    assert.equal(footprint(4, 4, 5, "round").length, 21);
  });
  it("brush / erase / fill / decal / layer ops; replay is deterministic and equals step-by-step application", () => {
    const stamp = new Uint8ClampedArray(2 * 2 * 4); stamp.set([255, 0, 0, 255, 0, 255, 0, 128, 0, 0, 0, 0, 0, 0, 255, 255]);
    const ops: Op[] = [
      { t: "brush", layer: "paint", color: [10, 20, 30], size: 2, shape: "square", pts: [[0, 0], [8, 8]] },
      { t: "erase", layer: "paint", size: 1, shape: "square", pts: [[1, 1]] },
      { t: "layer.add", id: "rough", name: "Wear", channel: "roughness" },
      { t: "fill", layer: "rough", color: [40, 40, 40], spans: [[3, 2, 6], [4, 2, 6]] },
      { t: "decal", layer: "paint", x: 10, y: 10, stamp: { w: 2, h: 2, rle: encodePixels(stamp) } },
      { t: "layer.set", id: "rough", opacity: 100, blend: "multiply" },
      { t: "layer.move", id: "rough", to: 0 },
    ];
    for (const op of ops) assert.equal(checkOp(op, W, W), null, op.t);
    let step = blank();
    for (const op of ops) step = applyOp(step, op);
    const a = replay(blank(), ops), b = replay(blank(), ops);
    assert.equal(canonical(encodeLayers(a)), canonical(encodeLayers(b)));
    assert.equal(canonical(encodeLayers(a)), canonical(encodeLayers(step)));
    const p = a.layers.find((l) => l.id === "paint")!;
    assert.deepEqual([...p.px.subarray(0, 4)], [10, 20, 30, 255]);
    assert.deepEqual([...p.px.subarray((1 * W + 1) * 4, (1 * W + 1) * 4 + 4)], [0, 0, 0, 0], "erased");
    assert.deepEqual([...p.px.subarray((10 * W + 11) * 4, (10 * W + 11) * 4 + 4)], [0, 255, 0, 128], "decal keeps its alpha");
    assert.equal(a.layers[0].id, "rough"); assert.equal(a.layers[0].opacity, 100);
    assert.equal(a.layers[0].px[(3 * W + 2) * 4 + 3], 255);
    // ops on an unknown layer change nothing
    assert.equal(canonical(encodeLayers(applyOp(blank(), { t: "brush", layer: "nope", color: [1, 1, 1], size: 1, shape: "square", pts: [[1, 1]] }))), canonical(encodeLayers(blank())));
  });
  it("checkOp refuses junk (unknown fields, out-of-range colours, huge sizes, malformed stamps)", () => {
    const bad: unknown[] = [null, [], { t: "nuke" }, { t: "brush", layer: "paint", color: [300, 0, 0], size: 1, shape: "square", pts: [[0, 0]] },
      { t: "brush", layer: "paint", color: [1, 1, 1], size: 999, shape: "square", pts: [[0, 0]] }, { t: "brush", layer: "paint", color: [1, 1, 1], size: 1, shape: "square", pts: [], x: 1 },
      { t: "fill", layer: "paint", color: [1, 1, 1], spans: [[99, 0, 1]] }, { t: "decal", layer: "paint", x: 0, y: 0, stamp: { w: 2, h: 2, rle: "AAAA" } },
      { t: "layer.add", id: "Bad Id", name: "x", channel: "albedo" }, { t: "layer.set", id: "a", opacity: 256 }];
    for (const b of bad) assert.notEqual(checkOp(b, W, W), null, JSON.stringify(b));
  });
  it("flood fill (area mode) stays inside the region and the colour", () => {
    const img: Img = { w: 4, h: 4, px: new Uint8ClampedArray(64) };
    for (let i = 0; i < 16; i++) img.px.set(i % 4 < 2 ? [9, 9, 9, 255] : [1, 1, 1, 255], i * 4);
    assert.equal(spansCount(floodSpans(img, 0, 0, null)), 8);
    assert.equal(spansCount(floodSpans(img, 0, 0, [[0, 0, 4], [1, 0, 4]])), 4);
  });
  it("session: one op = one step; undo/redo replay from checkpoints; past MAX_STEPS the oldest fold into the base", () => {
    let s = sessionInit(blank());
    for (let i = 0; i < 40; i++) s = sessionPush(s, { t: "brush", layer: "paint", color: [i, 0, 0], size: 1, shape: "square", pts: [[i % W, Math.floor(i / W)]] });
    assert.equal(s.at, 40); assert.ok(canUndoS(s)); assert.ok(!canRedoS(s));
    const at40 = canonical(encodeLayers(sessionState(s)));
    for (let i = 0; i < 25; i++) s = sessionUndo(s);
    assert.equal(canonical(encodeLayers(sessionState(s))), canonical(encodeLayers(replay(blank(), s.ops.slice(0, 15)))));
    for (let i = 0; i < 25; i++) s = sessionRedo(s);
    assert.equal(canonical(encodeLayers(sessionState(s))), at40);
    s = sessionUndo(s);
    s = sessionPush(s, { t: "erase", layer: "paint", size: 1, shape: "square", pts: [[0, 0]] });
    assert.equal(s.ops.length, 40, "a new op after undo drops the redo branch");
    let f = sessionInit(blank());
    for (let i = 0; i < MAX_STEPS + 30; i++) f = sessionPush(f, { t: "brush", layer: "paint", color: [1, 2, 3], size: 1, shape: "square", pts: [[i % W, Math.floor(i / W) % W]] });
    assert.equal(f.ops.length, MAX_STEPS); assert.equal(f.folded, 30);
    assert.equal(appliedOps(f).length, MAX_STEPS);
  });
  it("stroke-to-pixel budget: one 16 px round dab + its region recomposite on a 2048^2 sheet (measured)", () => {
    const N = 2048;
    const set: LayerSet = { w: N, h: N, layers: [newLayer("paint", "Paint", "albedo", N, N), newLayer("wear", "Wear", "albedo", N, N)] };
    const base: Img = { w: N, h: N, px: new Uint8ClampedArray(N * N * 4).fill(200) };
    const out = compositeChannel(set, "albedo", base);
    const times: number[] = [];
    for (let k = 0; k < 20; k++) {
      const t0 = performance.now();
      const op: Op = { t: "brush", layer: "paint", color: [255, 0, 0], size: 16, shape: "round", pts: [[100 + k * 20, 900]] };
      applyOpMut(set, op);
      compositeRegion(set, "albedo", base, opRect(op)!, out);
      times.push(performance.now() - t0);
    }
    times.sort((a, b) => a - b);
    const median = times[10];
    console.log(`  stroke-to-pixel at 2048^2: median ${median.toFixed(2)} ms, worst ${times[19].toFixed(2)} ms (budget ${PERF_BUDGET.strokeMs} ms; GPU upload not included)`);
    assert.ok(median < PERF_BUDGET.strokeMs, `median ${median} ms`);
  });
});

