    const doc = docFor("banshee", layers, { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: c.spec });
    const before = s.store.mem.revs.length;
    const r = await saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, expectedHeadId: s.head(), log: ops });
    assert.equal(s.store.mem.revs.length, before + 1);
    const rev = s.store.mem.revs.at(-1)!;
    assert.equal(rev.kind, "asset");
    assert.ok(rev.manifest.some((e) => e.path === "assets/models/banshee.modeldoc.json"));
    assert.ok(rev.manifest.some((e) => e.path === "assets/creatures/banshee.json"), "the head's other files are kept");
    assert.equal(r.logVerified, true);
    const row = s.store.mem.assets.find((a) => a.id === r.assetId)!;
    assert.equal(row.mime, MODELDOC_MIME); assert.equal(row.kind, "model"); assert.equal(row.origin, "edited");
    assert.equal((row.provenance as { doc: ModelDoc }).doc.log!.ops, 2);
    const v2 = await modelsView(s.deps, "u1", "mb1");
    const c2 = v2.models[0]; if (c2.kind !== "creature") throw new Error();
    assert.equal(c2.paint!.assetId, r.assetId); assert.equal(c2.paint!.stale, null);
    assert.equal(canonical(decodeLayers(c2.paint!.doc)!.layers.map((l) => l.id)), canonical(["paint", "glow"]));
    // the same base again = 409 (someone saved since)
    await assert.rejects(saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, expectedHeadId: s.head() }), (e: { status: number; code: string }) => e.status === 409 && e.code === "stale_head");
    // an old head = 409
    await assert.rejects(saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: r.assetId, expectedHeadId: "rev1" }), (e: { status: number; code: string }) => e.status === 409 && e.code === "stale_head");
  });
  it("a log that does not replay to the saved pixels is refused (400 log_mismatch), nothing written", async () => {
    const s = await seeded();
    const c = (await modelsView(s.deps, "u1", "mb1")).models[0]; if (c.kind !== "creature") throw new Error();
    const layers = replay(startLayers(null, 64, 64), [{ t: "brush", layer: "paint", color: [1, 2, 3], size: 1, shape: "square", pts: [[5, 5]] }]);
    const doc = docFor("banshee", layers, { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: {} });
    const n = s.store.mem.revs.length;
    await assert.rejects(saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, expectedHeadId: s.head(), log: [{ t: "brush", layer: "paint", color: [9, 9, 9], size: 1, shape: "square", pts: [[5, 5]] }] }), (e: { code: string }) => e.code === "log_mismatch");
    assert.equal(s.store.mem.revs.length, n);
  });
  it("plan gate on save and drafts: Saka / Free / unknown are refused with nothing written; viewing a draft is not gated", async () => {
    for (const plan of ["saka", "free", "katara", null, "mystery"]) {
      const s = await seeded(plan);
      const c = (await modelsView(s.deps, "u1", "mb1")).models[0]; if (c.kind !== "creature") throw new Error();
      const doc = docFor("banshee", startLayers(null, 64, 64), { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: {} });
      const n = s.store.mem.revs.length;
      await assert.rejects(saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, expectedHeadId: s.head() }), (e: { status: number; code: string }) => e.status === 403 && (e.code === "asset_locked" || e.code === "plan_unknown"));
      await assert.rejects(putDraft(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, baseHeadId: null }), (e: { status: number }) => e.status === 403);
      assert.equal(s.store.mem.revs.length, n); assert.equal(s.drafts.rows.size, 0);
      assert.equal(await getDraft(s.deps, "u1", PID, "banshee"), null);
    }
    // planOf throwing = unknown = closed
    const s = await seeded(); s.deps.planOf = async () => { throw new Error("db down"); };
    const c = (await modelsView(s.deps, "u1", "mb1")).models[0]; if (c.kind !== "creature") throw new Error();
    await assert.rejects(saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc: docFor("banshee", startLayers(null, 64, 64), { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: {} }), baseAssetId: null, expectedHeadId: s.head() }), (e: { code: string }) => e.code === "plan_unknown");
  });
  it("item save: the albedo composite becomes the item's TextureDoc through the Texture Studio save (ships in the pack); layers reopen", async () => {
    const s = await seeded();
    const v = await modelsView(s.deps, "u1", "mb1");
    const m = v.models.find((x) => x.kind === "item3d")!; if (m.kind !== "item3d") throw new Error();
    const ops: Op[] = [{ t: "brush", layer: "paint", color: [201, 204, 214], size: 1, shape: "square", pts: [[10, 9], [11, 9], [12, 9]] }];
    const layers = replay(startLayers(null, 32, 32), ops);
    const doc = docFor("glock_9mm", layers, { type: "texture", key: "glock_9mm", assetId: m.texture.assetId, sha256: "b".repeat(64) }, "item3d");
    const r = await saveModel(s.deps, { userId: "u1", projectId: PID, key: "glock_9mm", doc, baseAssetId: m.texture.assetId, expectedHeadId: s.head(), log: ops });
    assert.equal(r.kind, "item3d"); assert.equal(r.logVerified, true);
    const row = s.store.mem.assets.find((a) => a.id === r.assetId)!;
    assert.equal(row.kind, "texture"); assert.equal(row.origin, "edited");
    const tdoc = (row.provenance as { doc: { paint: { set: number[]; colors: string[] } } }).doc;
    assert.equal(tdoc.paint.set.length / 2, 3); assert.deepEqual(tdoc.paint.colors, ["#c9ccd6"]);
    const pngPx = renderDoc((row.provenance as { doc: never }).doc);
    assert.deepEqual([...pngPx.px.subarray((9 * 32 + 11) * 4, (9 * 32 + 11) * 4 + 4)], [201, 204, 214, 255]);
    const v2 = await modelsView(s.deps, "u1", "mb1");
    const m2 = v2.models.find((x) => x.kind === "item3d")!; if (m2.kind !== "item3d") throw new Error();
    assert.ok(m2.paint, "the Model Studio layers reopen on the base they were painted on");
    assert.equal(m2.base.assetId, m.texture.assetId);
    // semi-transparent paint over a transparent texel is snapped (cutout), reported as a warning
    const semi = textureDocFromComposite(docFromSpec(GLOCK), (() => { const a = imgOf(render(GLOCK)); const px = new Uint8ClampedArray(a.px); px.set([255, 0, 0, 100], 0); return { ...a, px }; })());
    assert.equal(semi.snapped, 1);
  });
  it("drafts: autosave round trip, scoped per owner; save deletes the draft", async () => {
    const s = await seeded();
    const c = (await modelsView(s.deps, "u1", "mb1")).models[0]; if (c.kind !== "creature") throw new Error();
    const doc = docFor("banshee", startLayers(null, 64, 64), { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: {} });
    await putDraft(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, baseHeadId: s.head() });
    const d = await getDraft(s.deps, "u1", PID, "banshee");
    assert.ok(d); assert.equal(d!.baseHeadId, s.head());
    await assert.rejects(getDraft(s.deps, "u2", PID, "banshee"), (e: { status: number }) => e.status === 404, "another user's project is not found");
    await saveModel(s.deps, { userId: "u1", projectId: PID, key: "banshee", doc, baseAssetId: null, expectedHeadId: s.head() });
    assert.equal(await getDraft(s.deps, "u1", PID, "banshee"), null);
  });
  it("server preview: off = 503 renderer_off; a renderer is called once per distinct input (cache by key)", async () => {
    const off = await seeded();
    await assert.rejects(renderModelPreview(off.deps, { userId: "u1", projectId: PID, key: "banshee", preset: "front" }), (e: { status: number; code: string }) => e.status === 503 && e.code === "renderer_off");
    let calls = 0;
    const fake: PreviewRenderer = { id: "fake", render: async (req) => { calls++; assert.equal(checkPreviewRequest(req), null); return { ok: true, png: Uint8Array.from([0x89, 1, 2]), width: req.size, height: req.size, ms: 1, renderer: "fake", key: previewKey(req, "fake") }; } };
    const on = await seeded("free", fake);
    const a = await renderModelPreview(on.deps, { userId: "u1", projectId: PID, key: "banshee", preset: "front", size: 256 });
    const b = await renderModelPreview(on.deps, { userId: "u1", projectId: PID, key: "banshee", preset: "front", size: 256 });
    assert.equal(calls, 1); assert.equal(b.cached, true); assert.equal(a.key, b.key);
    await renderModelPreview(on.deps, { userId: "u1", projectId: PID, key: "glock_9mm", preset: "front", size: 256, context: "firstperson" });
    assert.equal(calls, 2, "viewing is not gated: a Free account gets previews");
  });
  it("preview request: shape checks, texture cap, renderer selection refuses a browser in production", () => {
    const spec = banshee(); const lay = layoutSkin(spec); if (!lay.ok) throw new Error();
    const scene = sceneFromRig(spec, lay.layout);
    const req = previewRequest(scene, { albedo: imgOf(render(skinTextureSpec(spec, lay.layout))) }, { preset: "three_quarter" });
    assert.equal(checkPreviewRequest(req), null);
    assert.notEqual(checkPreviewRequest({ ...req, size: 999 as never }), null);
    assert.notEqual(checkPreviewRequest({ ...req, triCount: 0 }), null);
    assert.equal(capImg({ w: 4096, h: 2048, px: new Uint8ClampedArray(4096 * 2048 * 4) }).w, 1024);
    assert.equal(selectPreviewRenderer({}).ok, false);
    assert.equal(selectPreviewRenderer({ CYRUS_MODEL_PREVIEW: "local", NODE_ENV: "production" }).ok, false);
    assert.equal(selectPreviewRenderer({ CYRUS_MODEL_PREVIEW: "warp" }).ok, false);
    const cache = memoryPreviewCache(2); cache.put("a", new Uint8Array(1)); cache.put("b", new Uint8Array(1)); cache.get("a"); cache.put("c", new Uint8Array(1));
    assert.equal(cache.get("b"), null); assert.ok(cache.get("a"));
    const r1: Raster = { size: 2, px: new Uint8ClampedArray(16) }, r2: Raster = { size: 2, px: new Uint8ClampedArray(16) }; r2.px[0] = 3;
    assert.equal(compareRasters(r1, r2, { channel: 2, maxFraction: 0.25 }).ok, true);
    assert.equal(compareRasters(r1, r2, { channel: 2, maxFraction: 0.1 }).ok, false);
  });
});

describe("/api/cyrus/models/v1 handlers", () => {
  const api = async (plan: unknown = "all", viewer: boolean = true) => {
    const s = await seeded(plan);
    const deps: MH.ModelApiDeps = { viewer: async () => (viewer ? { userId: "u1", preview: true } : null), service: s.deps, rateLimit: () => ({ ok: true }) };
    return { s, deps };
  };
  it("404 for anyone who may not see Model Studio (as if the route did not exist)", async () => {
    const { deps } = await api("all", false);
    assert.equal((await MH.handleModels(new Request("http://x/api/cyrus/models/v1/projects?root=mb1"), deps)).status, 404);
    assert.equal((await MH.handleSaveModel(new Request("http://x", { method: "POST", body: "{}" }), { projectId: PID, key: "banshee" }, deps)).status, 404);
  });
  it("list, save (201), stale save (409), locked plan (403), bad input (400), draft PUT/GET/DELETE, preview off (503)", async () => {
    const { s, deps } = await api();
    const v = await (await MH.handleModels(new Request("http://x/api/cyrus/models/v1/projects?root=mb1"), deps)).json();
    const c = v.models[0];
    const doc = docFor("banshee", startLayers(null, 64, 64), { type: "rigspec", assetId: c.assetId, sha256: c.sha256, spec: {} });
    const post = (body: unknown) => MH.handleSaveModel(new Request("http://x", { method: "POST", body: JSON.stringify(body) }), { projectId: PID, key: "banshee" }, deps);
    assert.equal((await post({ doc, baseAssetId: null, expectedHeadId: v.headRevisionId })).status, 201);
    assert.equal((await post({ doc, baseAssetId: null, expectedHeadId: v.headRevisionId })).status, 409);
    assert.equal((await post({ doc: { v: 1 }, baseAssetId: null, expectedHeadId: s.head() })).status, 400);
    assert.equal((await MH.handleSaveModel(new Request("http://x", { method: "POST", body: "{}" }), { projectId: "nope", key: "banshee" }, deps)).status, 400);
    const put = await MH.handleDraft(new Request("http://x", { method: "PUT", body: JSON.stringify({ doc, baseAssetId: null, baseHeadId: null }) }), { projectId: PID, key: "banshee" }, deps);
    assert.equal(put.status, 200);
    const got = await (await MH.handleDraft(new Request("http://x", { method: "GET" }), { projectId: PID, key: "banshee" }, deps)).json();
    assert.equal(got.draft.doc.name, "banshee");
    assert.equal((await MH.handleDraft(new Request("http://x", { method: "DELETE" }), { projectId: PID, key: "banshee" }, deps)).status, 200);
    assert.equal((await MH.handlePreview(new Request("http://x?preset=front"), { projectId: PID, key: "banshee" }, deps)).status, 503);
    assert.equal((await MH.handlePreview(new Request("http://x?preset=nope"), { projectId: PID, key: "banshee" }, deps)).status, 400);
    const locked = await api("saka");
    const lv = await (await MH.handleModels(new Request("http://x/api/cyrus/models/v1/projects?root=mb1"), locked.deps)).json();
    const ldoc = docFor("banshee", startLayers(null, 64, 64), { type: "rigspec", assetId: lv.models[0].assetId, sha256: lv.models[0].sha256, spec: {} });
    const lr = await MH.handleSaveModel(new Request("http://x", { method: "POST", body: JSON.stringify({ doc: ldoc, baseAssetId: null, expectedHeadId: lv.headRevisionId }) }), { projectId: PID, key: "banshee" }, locked.deps);
    assert.equal(lr.status, 403); assert.equal((await lr.json()).code, "asset_locked");
  });
});

