content.content:
/* Cyrus studios (R1b): Texture Studio, Sound Studio shell, locked states, the mod Assets tab, the Library browser.
   Ported from the approved mockups (/root/agent-notes/cyrus-designs/src/common.css + texture/locked/mod-assets),
   which copy the v5 tokens of app/dashboard/cyrus/studio.css. Everything hangs off .cys inside .cyrus-root and every
   class is cys-* (the portal's globals also define .glass / .btn / .kbd ...). One accent (violet); cyan only means
   "live"; green/amber/red only mean pass/warn/fail. Light theme follows the portal toggle (html[data-theme=light]). */

.cyrus-root .cys {
  --line-3: rgb(167 139 250 / 0.4);
  --accent-solid: #7c4dff; --on-accent: #fff;
  --accent-soft: rgb(167 139 250 / 0.14); --accent-line: rgb(167 139 250 / 0.5);
  --ok: #34e3a2; --warn: #ffb44f; --bad: #ff6b8a;
  --ok-soft: rgb(52 227 162 / 0.1); --warn-soft: rgb(255 180 79 / 0.1); --bad-soft: rgb(255 90 130 / 0.1);
  --pop-shadow: 0 26px 70px -20px rgb(0 0 0 / 0.9), 0 0 0 1px rgb(150 160 255 / 0.14);
  --check-a: #2b2545; --check-b: #221d3a; --well: rgb(7 4 18 / 0.55);
  --mono: var(--font-jb), ui-monospace, monospace; --display: var(--font-space), var(--font-inter), sans-serif;
  --r-sm: 7px; --r: 10px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px;
  position: absolute; inset: 0; display: flex; flex-direction: column; min-width: 0; overflow: hidden; isolation: isolate;
  color: var(--ink); font-size: 13px; line-height: 1.45; font-feature-settings: "ss01", "cv11";
}
html[data-theme="light"] .cyrus-root .cys {
  --line-3: rgb(91 33 182 / 0.32);
  --accent-solid: #7c3aed; --accent-soft: rgb(109 61 240 / 0.09); --accent-line: rgb(109 61 240 / 0.4);
  --ok: #047a52; --warn: #8a4b00; --bad: #c8204f;
  --ok-soft: rgb(4 122 82 / 0.08); --warn-soft: rgb(196 110 0 / 0.08); --bad-soft: rgb(200 32 79 / 0.07);
  --pop-shadow: 0 24px 60px -20px rgb(20 22 60 / 0.3), 0 0 0 1px rgb(30 36 90 / 0.1);
  --check-a: #ece8f6; --check-b: #f8f6fd; --well: #f6f3fd;
}
/* deep space: a faint aurora curtain + sparse stars (the mockup's .cyrus::before) */
.cyrus-root .cys::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(1px 1px at 12% 18%, rgb(255 255 255 / .55), transparent 60%), radial-gradient(1px 1px at 78% 12%, rgb(255 255 255 / .4), transparent 60%),
    radial-gradient(1px 1px at 64% 72%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 28% 84%, rgb(255 255 255 / .3), transparent 60%),
    radial-gradient(1px 1px at 91% 58%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 44% 30%, rgb(255 255 255 / .25), transparent 60%),
    linear-gradient(118deg, transparent 8%, rgb(40 200 170 / .07) 18%, transparent 28%, transparent 62%, rgb(124 77 255 / .07) 74%, transparent 86%),
    radial-gradient(120% 70% at 50% -10%, rgb(60 30 130 / .35), transparent 60%), var(--bg); }
html[data-theme="light"] .cyrus-root .cys::before { background: linear-gradient(118deg, transparent 8%, rgb(8 145 178 / .05) 18%, transparent 30%, transparent 60%, rgb(124 58 237 / .06) 74%, transparent 88%), radial-gradient(120% 70% at 50% -10%, rgb(124 58 237 / .07), transparent 60%), var(--bg); }
.cys :where(button, input, select, textarea) { font: inherit; color: inherit; }
.cys :where(button) { cursor: pointer; background: none; border: 0; padding: 0; text-align: inherit; }
.cys :where(a) { color: inherit; text-decoration: none; }
.cys :focus-visible { outline: 2px solid var(--accent-ink); outline-offset: 2px; border-radius: 6px; }
.cys * { scrollbar-width: thin; scrollbar-color: rgb(var(--glow) / .28) transparent; }
.cys .mono { font-family: var(--mono); }
.cys svg.cys-i { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }

/* surfaces */
.cys .cys-glass { background: linear-gradient(180deg, var(--surface-2), var(--surface)); backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%); border: 1px solid var(--line); box-shadow: var(--panel-shadow); }
.cys .cys-soft { background: var(--surface-soft); border: 1px solid var(--line); }
.cys .cys-hairline { position: relative; }
.cys .cys-hairline::before { content: ""; position: absolute; inset: 0 12% auto 12%; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgb(var(--glow) / .55), rgb(103 232 249 / .4), transparent); }
html[data-theme="light"] .cyrus-root .cys .cys-hairline::before { background: linear-gradient(90deg, transparent, rgb(124 58 237 / .3), rgb(8 145 178 / .25), transparent); }
.cys .cys-panel { border-radius: var(--r-lg); min-height: 0; display: flex; flex-direction: column; }
.cys .cys-ph { display: flex; align-items: center; gap: 8px; padding: 12px 14px 8px; }
.cys .cys-eyebrow { font: 600 10px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
.cys .cys-ph .cys-eyebrow { flex: 1; }
.cys .cys-sep { height: 1px; background: var(--line); margin: 4px 0; }
.cys .cys-hint { font-size: 11.5px; color: var(--muted); line-height: 1.45; }

/* top bar (TopBar.tsx anatomy) */
.cys .cys-top { height: 60px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 18px; position: relative; z-index: 5; }
.cys .cys-brand { display: flex; flex-direction: column; line-height: 1; }
.cys .cys-brand small { margin-top: 4px; font: 600 8px/1 var(--font-inter), sans-serif; letter-spacing: .36em; text-transform: uppercase; color: var(--muted); }
.cys .cys-crumbs { display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px; margin-left: 10px; min-width: 0; }
.cys .cys-crumb { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }
.cys a.cys-crumb:hover { color: var(--ink); background: rgb(var(--glow) / .07); }
.cys .cys-crumb.on { color: var(--ink); font-weight: 500; background: rgb(var(--glow) / .12); }
.cys .cys-crumb .core { width: 10px; height: 10px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--accent) 55%, var(--cyan)); box-shadow: 0 0 8px var(--accent); }
.cys .cys-crumbs > svg { font-size: 11px; color: var(--faint); }
.cys .cys-tbr { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.cys .cys-chip { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px; border-radius: 12px; font-size: 12.5px; font-weight: 500; color: var(--ink-2); white-space: nowrap; }
.cys .cys-chip:hover { color: var(--ink); border-color: var(--line-2); }
.cys .cys-chip.icon { width: 36px; padding: 0; justify-content: center; font-size: 16px; }
.cys .cys-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 12px; }
.cys .cys-seg > * { height: 28px; padding: 0 11px; border-radius: 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.cys .cys-seg > *:hover { color: var(--ink); }
.cys .cys-seg > .on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
.cys .cys-seg.sm > * { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; }
.cys .cys-kbd { font: 500 10px/1 var(--mono); padding: 3px 5px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); background: rgb(var(--glow) / .06); }

/* buttons / fields */
.cys .cys-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: var(--r); font-size: 12.5px; font-weight: 500; color: var(--ink); border: 1px solid var(--line-2); background: var(--surface-2); white-space: nowrap; transition: background .15s, border-color .15s; }
.cys .cys-btn:hover:not(:disabled) { background: rgb(var(--glow) / .14); border-color: var(--line-3); }
.cys .cys-btn.primary { color: var(--on-accent); border-color: transparent; background: var(--accent-solid); box-shadow: inset 0 1px 0 rgb(255 255 255 / .18), 0 8px 22px -12px rgb(124 77 255 / .9); }
.cys .cys-btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: var(--accent-solid); }
.cys .cys-btn.ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
.cys .cys-btn.ghost:hover:not(:disabled) { background: rgb(var(--glow) / .1); color: var(--ink); }
.cys .cys-btn.sm { height: 28px; padding: 0 10px; font-size: 12px; border-radius: 8px; }
.cys .cys-btn.xs { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; gap: 5px; }
.cys .cys-btn:disabled { opacity: .45; cursor: not-allowed; }
.cys .cys-ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: var(--muted); font-size: 16px; transition: color .15s, background .15s; }
.cys .cys-ib:hover:not(:disabled) { color: var(--ink); background: rgb(var(--glow) / .1); }
.cys .cys-ib:disabled { opacity: .4; cursor: not-allowed; }
.cys .cys-ib.on { color: var(--accent-ink); background: var(--accent-soft); }
.cys .cys-ib.sm { width: 24px; height: 24px; font-size: 14px; border-radius: 7px; }
.cys .cys-field { height: 32px; width: 100%; border-radius: var(--r); border: 1px solid var(--line-2); background: var(--well); padding: 0 10px; font-size: 12.5px; color: var(--ink); outline: none; }
.cys .cys-field:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }
.cys .cys-field::placeholder { color: var(--faint); }
.cys select.cys-field { appearance: none; -webkit-appearance: none; padding-right: 26px; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: calc(100% - 13px) 14px, calc(100% - 9px) 14px; background-size: 4px 4px; background-repeat: no-repeat; }

/* tags / status */
.cys .cys-tag { display: inline-flex; align-items: center; gap: 5px; font: 500 9.5px/1 var(--mono); letter-spacing: .08em; text-transform: uppercase; padding: 4px 6px; border-radius: 5px; color: var(--ink-2); border: 1px solid var(--line-2); white-space: nowrap; }
.cys .cys-tag.acc { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .cys-tag.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 40%, transparent); background: var(--ok-soft); }
.cys .cys-tag.warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
.cys .cys-tag.bad { color: var(--bad); border-color: color-mix(in srgb, var(--bad) 40%, transparent); background: var(--bad-soft); }
.cys .cys-tag.dim { color: var(--muted); }
.cys .cys-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--faint); }
.cys .cys-dot.ok { background: var(--ok); } .cys .cys-dot.warn { background: var(--warn); } .cys .cys-dot.bad, .cys .cys-dot.fail { background: var(--bad); }
.cys .cys-dot.live { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.cys .cys-chiprow { display: flex; flex-wrap: wrap; gap: 6px; }
.cys .cys-fchip { white-space: nowrap; flex: none; height: 26px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--line-2); font-size: 11.5px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.cys button.cys-fchip:hover { border-color: var(--line-3); color: var(--ink); }
.cys .cys-fchip.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .cys-fchip i { font-style: normal; font: 500 10px/1 var(--mono); color: var(--muted); }

/* tabs (inspector anatomy) */
.cys .cys-tabs { display: flex; gap: 2px; padding: 0 10px; border-bottom: 1px solid var(--line); flex: none; }
.cys .cys-tab { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); white-space: nowrap; }
.cys .cys-tab:hover { color: var(--ink); }
.cys .cys-tab.on { color: var(--ink); }
.cys .cys-tab.on::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--accent); box-shadow: 0 0 10px rgb(var(--glow) / .7); }

/* Cyrus Model Studio mockups (v3): shared pieces on top of kit.css + v2.css (the shipped shell and tokens). */
.ws.ms { grid-template-columns: 236px minmax(0, 1fr) 328px; }
.col.scroll > .panel { flex: none; }
.vp { position: relative; flex: 1; min-height: 0; border-radius: var(--r-lg); overflow: hidden; }
.vp canvas.main { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; }
.vp canvas.main.paint { cursor: crosshair; }
.vp::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(120% 90% at 50% 40%, rgb(var(--glow) / .10), transparent 62%), radial-gradient(60% 50% at 80% 100%, rgb(103 232 249 / .05), transparent 70%); }
:root[data-theme="light"] .vp::before { background: radial-gradient(120% 90% at 50% 40%, rgb(124 58 237 / .06), transparent 62%); }
.vp-bar { position: absolute; left: 10px; right: 10px; top: 10px; display: flex; align-items: center; gap: 8px; z-index: 2; pointer-events: none; }
.vp-bar > * { pointer-events: auto; }
.vp-bar .sp { flex: 1; pointer-events: none; }
.vp-foot { position: absolute; left: 10px; right: 10px; bottom: 10px; display: flex; align-items: flex-end; gap: 8px; z-index: 2; pointer-events: none; }
.vp-foot > * { pointer-events: auto; }
.vp-foot .sp { flex: 1; pointer-events: none; }
.float { border-radius: 12px; background: var(--surface-soft); border: 1px solid var(--line); box-shadow: 0 10px 30px -18px rgb(0 0 0 / .7); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }
:root[data-theme="light"] .float { box-shadow: 0 10px 30px -20px rgb(76 29 149 / .35); }
.tools { position: absolute; left: 10px; top: 58px; z-index: 2; display: flex; flex-direction: column; gap: 2px; padding: 4px; }
.tools .ib { width: 32px; height: 32px; }
.tools .sep { margin: 3px 4px; }
.stat-s { font: 500 10.5px/1 var(--mono); color: var(--muted); padding: 7px 9px; white-space: nowrap; }
.stat-s b { color: var(--ink-2); font-weight: 500; }
.chan { display: inline-flex; padding: 3px; gap: 2px; }
.chan button { height: 26px; padding: 0 9px; border-radius: 8px; font-size: 11.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.chan button:hover:not(:disabled) { color: var(--ink); }
.chan button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .3); }
.chan button:disabled { color: var(--faint); cursor: not-allowed; text-decoration: line-through; text-decoration-color: color-mix(in srgb, var(--faint) 60%, transparent); }
.chan .sw { width: 8px; height: 8px; border-radius: 2px; flex: none; }
.chan .lab { font: 600 9px/1 var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); padding: 0 6px 0 4px; display: inline-flex; align-items: center; }
.hdr { display: flex; align-items: center; gap: 10px; padding: 9px 10px 9px 12px; }
.hdr .nm { font: 500 13px/1 var(--mono); color: var(--ink); white-space: nowrap; }
.hdr .sp { flex: 1; }
.pill { font: 500 10.5px/1 var(--mono); color: var(--muted); padding: 4px 7px; border-radius: 6px; border: 1px solid var(--line-2); white-space: nowrap; }
/* tree (outliner) */
.tree { list-style: none; margin: 0; padding: 0 8px 10px; }
.tree li { display: flex; align-items: center; gap: 6px; height: 28px; padding: 0 6px; border-radius: 8px; font: 500 11.5px/1 var(--mono); color: var(--ink-2); white-space: nowrap; cursor: default; }
.tree li:hover { background: rgb(var(--glow) / .07); }
.tree li.on { background: rgb(var(--glow) / .14); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .25); color: var(--ink); }
.tree li .ind { flex: none; }
.tree li svg { font-size: 13px; color: var(--muted); flex: none; }
.tree li .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.tree li .tg { font: 600 8.5px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; padding: 3px 4px; border-radius: 4px; border: 1px solid var(--line-2); color: var(--muted); }
.tree li .eye { opacity: .55; }
.tree li.cube { color: var(--muted); }
.tree li .sw { width: 9px; height: 9px; border-radius: 3px; flex: none; box-shadow: inset 0 0 0 1px rgb(0 0 0 / .25); }
/* inspector fields */
.fgrp { padding: 4px 12px 10px; border-bottom: 1px solid var(--line); }
.fgrp:last-child { border-bottom: 0; }
.fgrp > .eyebrow { display: flex; align-items: center; gap: 6px; padding: 8px 0 8px; }
.fgrp > .eyebrow .sp { flex: 1; }
.xyz { display: grid; grid-template-columns: 54px repeat(3, minmax(0, 1fr)); gap: 5px; align-items: center; margin-bottom: 5px; }
.xyz > span { font-size: 11.5px; color: var(--muted); }
.ax { display: flex; align-items: center; height: 26px; border-radius: 7px; border: 1px solid var(--line-2); background: var(--well); overflow: hidden; }
.ax i { font: 600 9.5px/1 var(--mono); font-style: normal; width: 16px; text-align: center; color: var(--faint); align-self: stretch; display: grid; place-items: center; border-right: 1px solid var(--line); }
.ax.x i { color: #e0707f; } .ax.y i { color: #4fb57a; } .ax.z i { color: #6f8fe6; }
.ax input { flex: 1; min-width: 0; width: 100%; border: 0; background: transparent; font: 500 11px/1 var(--mono); color: var(--ink); text-align: right; padding: 0 6px; outline: none; }
.ax.chg { border-color: var(--accent-line); } .ax.chg input { color: var(--accent-ink); }
.ax.err { border-color: color-mix(in srgb, var(--bad) 60%, transparent); }
.frow { display: flex; align-items: center; gap: 8px; min-height: 30px; font-size: 11.5px; color: var(--muted); }
.frow > span:first-child { width: 72px; flex: none; }
.frow .grow { flex: 1; min-width: 0; }
.swatch { width: 18px; height: 18px; border-radius: 5px; box-shadow: inset 0 0 0 1px rgb(0 0 0 / .3); flex: none; }
.uvbox { position: relative; border-radius: 10px; border: 1px solid var(--line); background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 10px 10px; overflow: hidden; }
.uvbox canvas { display: block; width: 100%; image-rendering: pixelated; }
/* timeline */
.tl3 { display: flex; flex-direction: column; min-height: 0; }
.tl3-h { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--line); }
.tl3-h .sp { flex: 1; }
.tl3-b { display: grid; grid-template-columns: 172px minmax(0, 1fr); min-height: 0; flex: 1; overflow: hidden; position: relative; }
.tl3-names { border-right: 1px solid var(--line); overflow: hidden; }
.tl3-names div { height: 24px; display: flex; align-items: center; gap: 6px; padding: 0 10px; font: 500 10.5px/1 var(--mono); color: var(--ink-2); white-space: nowrap; border-bottom: 1px solid var(--line); }
.tl3-names div small { color: var(--faint); font: inherit; margin-left: auto; }
.tl3-names div.on { background: rgb(var(--glow) / .1); color: var(--ink); }
.tl3-lanes { position: relative; overflow: hidden; }
.tl3-lanes canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
/* rows: models list, slots, layers */
.mrow { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--r); color: var(--ink-2); width: 100%; text-align: left; }
.mrow:hover { background: rgb(var(--glow) / .07); }
.mrow.on { background: rgb(var(--glow) / .13); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); color: var(--ink); }
.mrow .tx { flex: 1; min-width: 0; }
.mrow .tx b { display: block; font: 500 12px/1.2 var(--mono); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mrow .tx small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mrow .th3 { width: 34px; height: 34px; border-radius: 9px; flex: none; background: radial-gradient(circle at 50% 40%, rgb(var(--glow) / .16), var(--well) 70%); border: 1px solid var(--line); overflow: hidden; }
.mrow .th3 canvas { width: 100%; height: 100%; display: block; }
.mrow .lk { color: var(--faint); font-size: 13px; }
.lay { display: flex; align-items: center; gap: 8px; padding: 6px 8px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); margin-bottom: 5px; font-size: 12px; color: var(--ink-2); }
.lay.on { border-color: var(--accent-line); background: var(--accent-soft); color: var(--ink); }
.lay .grow { flex: 1; min-width: 0; } .lay .grow b { display: block; font-weight: 500; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } .lay .grow small { display: block; font: 400 10px/1.3 var(--mono); color: var(--muted); margin-top: 2px; }
.lay .ib { width: 24px; height: 24px; font-size: 14px; }
.lay.off { opacity: .5; }
.lay .ch { width: 20px; height: 20px; border-radius: 6px; flex: none; box-shadow: inset 0 0 0 1px rgb(0 0 0 / .25); }
.lay.locked { border-style: dashed; }
/* in-game preview card */
.ig { position: relative; height: 196px; margin: 0 12px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); }
.ig canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.ctxs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; padding: 3px; margin: 0 12px 8px; border-radius: 11px; }
.ctxs button { height: 26px; border-radius: 8px; font-size: 11.5px; color: var(--muted); font-weight: 500; }
.ctxs button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
.states { display: flex; align-items: center; gap: 6px; padding: 8px 12px 4px; }
.states .eyebrow { margin-right: 4px; }
/* export targets */
.tgt { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 10px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); margin-bottom: 6px; align-items: center; }
.tgt.on { border-color: var(--accent-line); background: var(--accent-soft); }
.tgt .gi { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; font: 700 10px/1 var(--mono); color: var(--ink-2); background: rgb(var(--glow) / .1); border: 1px solid var(--line-2); grid-row: 1 / 3; }
.tgt b { font-size: 12.5px; font-weight: 600; color: var(--ink); }
.tgt small { font: 400 10.5px/1.35 var(--mono); color: var(--muted); grid-column: 2 / 4; }
.tgt .tag { justify-self: end; }
.legal { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border-radius: var(--r-md); border: 1px solid color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); font-size: 11.5px; line-height: 1.45; color: var(--ink-2); }
.legal > svg { color: var(--warn); font-size: 16px; flex: none; margin-top: 1px; }
.legal b { color: var(--ink); }
.lclass { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 8px; border-radius: 7px; font: 600 10px/1 var(--mono); letter-spacing: .06em; text-transform: uppercase; color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 45%, transparent); background: var(--warn-soft); white-space: nowrap; }
.lclass.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 45%, transparent); background: var(--ok-soft); }
.lclass svg { font-size: 12px; }
/* split viewport (3D | UV) */
.split2 { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: 12px; flex: 1; min-height: 0; }
.uvp { position: relative; border-radius: var(--r-lg); overflow: hidden; display: flex; flex-direction: column; }
.uvp .stage2 { position: relative; flex: 1; min-height: 0; margin: 0 10px 10px; border-radius: 10px; overflow: hidden; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 14px 14px; border: 1px solid var(--line); }
.uvp canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.strip { flex: none; flex-direction: row !important; display: flex; align-items: center; gap: 12px; padding: 9px 12px; border-radius: var(--r-lg); }
.strip .sp { flex: 1; }
.strip .eyebrow { white-space: nowrap; }

.strip .eyebrow { white-space: nowrap; }
.mini { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--muted); white-space: nowrap; }
.mini input[type=range] { width: 90px; }
.mini b { font: 500 11px/1 var(--mono); color: var(--ink); min-width: 34px; }
/* candidate strip (AI edit arrived mid-session) */
.candbar { display: flex; align-items: center; gap: 10px; padding: 8px 10px 8px 12px; border-radius: 12px; border: 1px dashed var(--accent-line); background: linear-gradient(90deg, rgb(var(--glow) / .12), rgb(var(--glow) / .03)); font-size: 12px; color: var(--ink-2); }
.candbar .av { width: 24px; height: 24px; border-radius: 8px; display: grid; place-items: center; background: rgb(var(--glow) / .16); }
.candbar .av img { width: 15px; }
.candbar b { color: var(--ink); }
.candbar .sp { flex: 1; }
/* save state chip */
.saved { display: inline-flex; align-items: center; gap: 6px; font: 500 10.5px/1 var(--mono); color: var(--muted); white-space: nowrap; }
.saved .dot { width: 6px; height: 6px; }
/* locked overlay */
.ro { position: absolute; top: 10px; left: 50%; transform: translateX(-50%); z-index: 3; }
/* library */
.lgrid { align-content: start; display: grid; grid-template-columns: repeat(auto-fill, minmax(176px, 1fr)); gap: 10px; padding: 0 12px 12px; }
.lcard { border-radius: 14px; border: 1px solid var(--line); background: var(--well); overflow: hidden; display: flex; flex-direction: column; text-align: left; }
.lcard:hover { border-color: var(--line-3); }
.lcard.on { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .14); }
.lcard .lth { position: relative; height: 118px; background: radial-gradient(circle at 50% 42%, rgb(var(--glow) / .16), transparent 70%); }
.lcard .lth canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.lcard .lth .tag { position: absolute; top: 8px; left: 8px; }
.lcard .lb { padding: 9px 10px 10px; border-top: 1px solid var(--line); }
.lcard .lb b { display: block; font: 500 12px/1.2 var(--mono); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lcard .lb small { display: block; font-size: 10.5px; color: var(--muted); margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.lcard .lb .chiprow { margin-top: 7px; gap: 4px; }
.lcard .lb .fchip { height: 20px; font-size: 10px; padding: 0 7px; }
.filters { display: flex; gap: 8px; padding: 0 12px 10px; flex-wrap: wrap; align-items: center; }
.sel { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--well); font-size: 12px; color: var(--ink-2); white-space: nowrap; }
.sel svg { font-size: 12px; color: var(--muted); }
.kvs { display: grid; grid-template-columns: auto 1fr; gap: 7px 12px; font-size: 11.5px; padding: 0 12px 12px; }
.kvs dt { color: var(--muted); } .kvs dd { margin: 0; color: var(--ink); text-align: right; font-family: var(--mono); font-size: 11px; }
.gate-row { display: grid; grid-template-columns: 18px 1fr auto; gap: 2px 10px; padding: 8px 0; border-bottom: 1px solid var(--line); align-items: start; }
.gate-row:last-child { border-bottom: 0; }
.gate-row .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; }
.gate-row.ok .ic { color: var(--ok); background: var(--ok-soft); } .gate-row.warn .ic { color: var(--warn); background: var(--warn-soft); } .gate-row.bad .ic { color: var(--bad); background: var(--bad-soft); } .gate-row.nr .ic { color: var(--faint); box-shadow: inset 0 0 0 1px var(--line-2); }
.gate-row b { font: 500 11.5px/1.3 var(--mono); color: var(--ink); } .gate-row .v { font: 500 10.5px/1.3 var(--mono); color: var(--muted); text-align: right; }
.gate-row .m { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.4; }
.check2 { display: flex; gap: 9px; align-items: flex-start; font-size: 11.5px; line-height: 1.45; color: var(--ink-2); padding: 6px 0; }
.check2 .bx { width: 16px; height: 16px; border-radius: 5px; border: 1px solid var(--line-3); flex: none; margin-top: 1px; display: grid; place-items: center; font-size: 11px; color: var(--on-accent); }
.check2 .bx.on { background: var(--accent-solid); border-color: transparent; }
/* prompt flow */
.flow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; flex: 1; min-height: 0; }
.fstep { display: flex; flex-direction: column; min-height: 0; border-radius: var(--r-lg); }
.fstep .ph .num { width: 20px; height: 20px; border-radius: 6px; display: grid; place-items: center; font: 600 10.5px/1 var(--mono); color: var(--accent-ink); background: var(--accent-soft); border: 1px solid var(--accent-line); }
.fstep.done .ph .num { color: var(--on-accent); background: var(--accent-solid); border-color: transparent; }
.fstep .fb { flex: 1; min-height: 0; overflow: auto; padding: 0 12px 12px; display: flex; flex-direction: column; gap: 8px; }
.code { font: 400 10px/1.5 var(--mono); color: var(--ink-2); background: var(--well); border: 1px solid var(--line); border-radius: 10px; padding: 9px 10px; white-space: pre-wrap; word-break: break-word; overflow: hidden; }
