.can3 { position: relative; height: 210px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / .14), var(--well) 72%); }
.can3 canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.cando { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.cando div { border-radius: 10px; border: 1px solid var(--line); padding: 8px 9px; font-size: 11px; line-height: 1.45; color: var(--ink-2); background: var(--well); }
.cando div b { display: block; font: 600 9.5px/1 var(--mono); letter-spacing: .12em; text-transform: uppercase; margin-bottom: 5px; }
.cando .y b { color: var(--ok); } .cando .n b { color: var(--bad); }
.fixlist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.fixlist li { display: grid; grid-template-columns: 18px 1fr auto; gap: 8px; align-items: center; padding: 7px 8px; border-radius: 9px; border: 1px solid var(--line); background: var(--well); font-size: 11.5px; color: var(--ink-2); }
