.fixlist li code { font: 500 10px/1 var(--mono); color: var(--faint); }
.revs { display: flex; flex-direction: column; gap: 4px; }
.revs div { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--ink-2); padding: 6px 8px; border-radius: 8px; }
.revs div.on { background: rgb(var(--glow) / .12); color: var(--ink); }
.revs div code { font: 500 10.5px/1 var(--mono); color: var(--muted); width: 26px; }
.revs div small { margin-left: auto; font: 400 10px/1 var(--mono); color: var(--faint); }
