.n-view { position: relative; height: 250px; border-top: 1px solid var(--line); background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / .16), transparent 70%); }
.n-view canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.n-view .tag { position: absolute; top: 10px; left: 12px; }
.n-view .hint { position: absolute; bottom: 8px; left: 0; right: 0; text-align: center; }
.n-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; color: var(--ink-2); }
.n-list li { display: flex; gap: 8px; } .n-list li code { font: 500 11px/1.4 var(--mono); color: var(--accent-ink); flex: none; }
