// Client calls of the Cyrus Model Studio API (/api/cyrus/models/v1). The UI talks to nothing else (host seam).
import type { ModelsView, SaveModelResult, DraftView, ModelEntry, CreatureModel, ItemModel } from "@/lib/cyrus/modelstudio/service";
import type { ModelDoc } from "@/lib/cyrus/modelstudio/doc";
import type { Op } from "@/lib/cyrus/modelstudio/paint";
import { ApiError } from "./api";

export type { ModelsView, SaveModelResult, DraftView, ModelEntry, CreatureModel, ItemModel };
export const MODEL_API = "/api/cyrus/models/v1";

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(MODEL_API + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
