    call<{ updatedAt: string }>(`${m(projectId, key)}/draft`, { method: "PUT", body: JSON.stringify(body) }),
  dropDraft: (projectId: string, key: string) => call<{ ok: true }>(`${m(projectId, key)}/draft`, { method: "DELETE" }),
  previewUrl: (projectId: string, key: string, q: { preset?: string; size?: number; source?: "saved" | "draft"; context?: string; state?: string }) =>
    `${MODEL_API}${m(projectId, key)}/preview?${new URLSearchParams(Object.entries(q).filter(([, v]) => v !== undefined).map(([k, v]) => [k, String(v)])).toString()}`,
};
