"use client";
// Cyrus Model Studio: the three.js VIEWPORT (client only, imperative, no React). three.js (MIT) is imported
// dynamically, so its chunk loads only on the Model Studio route. It DRAWS; every pixel decision (which triangle is
// under the brush, which texel) is the pure, tested lib/cyrus/modelstudio/pick.ts on the same scene arrays, with the
// camera ray from lib/cyrus/modelstudio/math.ts rayFromOrbit (identical to the PerspectiveCamera below).
// Budget (lib/cyrus/modelstudio/budget.ts): renders on demand (no idle loop), DPR capped (2 desktop / 1.5 phone),
// nearest filtering + no mipmaps for the pixel profile, one geometry + at most 5 channel textures per model.
import type * as THREE_NS from "three";
import { camEye, rayFromOrbit, type M4, type OrbitCam, type Ray, type V3 } from "@/lib/cyrus/modelstudio/math";
import type { ModelScene, Img } from "@/lib/cyrus/modelstudio/scene";
import type { ContextRig, Prop } from "@/lib/cyrus/modelstudio/contexts";
import { LIGHTING_PRESETS, PIXEL_MATERIAL, type LightingPreset } from "@/lib/cyrus/modelstudio/look";
import { dprCap } from "@/lib/cyrus/modelstudio/budget";
import type { PaintChannel } from "@/lib/cyrus/modelstudio/layers";

type T = typeof THREE_NS;
export type ViewMaps = { albedo: Img } & Partial<Record<Exclude<PaintChannel, "albedo">, Img>>;
/** lit = the PBR material; image = an unlit view of one image (a channel view or the UV checker) */
export type Display = { kind: "lit" } | { kind: "image"; img: Img };
export type CamPreset = "persp" | "front" | "side" | "top";
const PRESET: Record<CamPreset, { yaw: number; pitch: number }> = { persp: { yaw: -32, pitch: 20 }, front: { yaw: 0, pitch: 0 }, side: { yaw: -90, pitch: 0 }, top: { yaw: 0, pitch: 89 } };

export type ViewportEvents = {
  /** a pointer went down on the canvas with the paint button (left, no modifier); return true to keep the drag as a paint drag */
  onPaintStart?: (ray: Ray, e: PointerEvent) => boolean;
  onPaintMove?: (ray: Ray, e: PointerEvent) => void;
  onPaintEnd?: () => void;
  onHover?: (ray: Ray | null, e: PointerEvent | null) => void;
  onCamera?: (cam: OrbitCam) => void;
};

export async function loadThree(): Promise<T> { return import("three"); }

/** WebGL available at all (the phone view falls back to the server PNG when it is not). */
export function webglOk(): boolean {
  try { const c = document.createElement("canvas"); return !!(c.getContext("webgl2") || c.getContext("webgl")); } catch { return false; }
}

export class ModelViewport {
  private T: T;
  private renderer: THREE_NS.WebGLRenderer;
  private scene3 = new (null as unknown as T)["Scene"]();
  private camera: THREE_NS.PerspectiveCamera | THREE_NS.OrthographicCamera;
  private mesh: THREE_NS.Mesh | null = null;
  private wire: THREE_NS.Mesh | null = null;
  private props: THREE_NS.Group;
  private grid: THREE_NS.GridHelper | null = null;
  private lights: THREE_NS.Light[] = [];
  private tex: Partial<Record<PaintChannel, THREE_NS.DataTexture>> = {};
  private viewTex: THREE_NS.DataTexture | null = null;
  private lit: THREE_NS.MeshStandardMaterial;
  private flat: THREE_NS.MeshBasicMaterial;
  private pixel = true;
  private rig: ContextRig | null = null;
  private raf = 0;
  private ro: ResizeObserver;
  private drag: { mode: "orbit" | "pan" | "paint"; x: number; y: number; id: number } | null = null;
  private frames = 0;
  private fpsT0 = 0;
  /** measured frames per second while interacting (shown in the Checks tab) */
  fps = 0;
  cam: OrbitCam = { yaw: -32, pitch: 20, dist: 2, target: [0, 0, 0], fov: 30 };
  readOnly = false;
  events: ViewportEvents = {};

  private constructor(three: T, private canvas: HTMLCanvasElement, private o: { mobile: boolean; light: boolean; interactive: boolean }) {
    this.T = three;
    const THREE = three;
    this.scene3 = new THREE.Scene();
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: o.mobile ? "low-power" : "high-performance", preserveDrawingBuffer: false });
    this.renderer.setPixelRatio(dprCap(window.devicePixelRatio, o.mobile));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.NoToneMapping;
    this.renderer.setClearColor(0x000000, 0);
    this.camera = new THREE.PerspectiveCamera(30, 1, 0.01, 1000);
    this.props = new THREE.Group();
    this.scene3.add(this.props);
    this.lit = new THREE.MeshStandardMaterial({ side: THREE.DoubleSide, alphaTest: PIXEL_MATERIAL.alphaTest, roughness: 1, metalness: 0 });
    this.flat = new THREE.MeshBasicMaterial({ side: THREE.DoubleSide, alphaTest: PIXEL_MATERIAL.alphaTest });
    this.setLighting("studio");
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    if (o.interactive) this.bind();
    this.resize();
  }

  static async create(canvas: HTMLCanvasElement, o: { mobile: boolean; light: boolean; interactive?: boolean }): Promise<ModelViewport> {
    return new ModelViewport(await loadThree(), canvas, { ...o, interactive: o.interactive ?? true });
  }

  // ------------------------------------------------------------------ scene + textures
  setScene(s: ModelScene, maps: ViewMaps, o: { pixel: boolean; keepCamera?: boolean }) {
    const THREE = this.T;
    this.pixel = o.pixel;
    if (this.mesh) { this.scene3.remove(this.mesh); this.mesh.geometry.dispose(); }
    if (this.wire) { this.scene3.remove(this.wire); }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(new Float32Array(s.pos), 3));
    g.setAttribute("uv", new THREE.BufferAttribute(new Float32Array(s.uv), 2));
    g.computeVertexNormals();
    g.computeBoundingSphere();
    for (const t of Object.values(this.tex)) t?.dispose();
    this.tex = {};
    this.mesh = new THREE.Mesh(g, this.lit);
    this.wire = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ wireframe: true, color: this.o.light ? 0x5b21b6 : 0xc4b5fd, transparent: true, opacity: 0.35, depthTest: true }));
    this.wire.visible = false;
    this.scene3.add(this.mesh, this.wire);
    this.setMaps(maps);
    if (this.grid) { this.scene3.remove(this.grid); this.grid.dispose(); this.grid = null; }
    const b = s.bounds, size = Math.max(b.max[0] - b.min[0], b.max[2] - b.min[2], 1e-3) * 1.6;
    if (!this.rig) {
      this.grid = new THREE.GridHelper(size, 12, this.o.light ? 0xc9bdf2 : 0x3b3170, this.o.light ? 0xe3dcf7 : 0x241e48);
      this.grid.position.set((b.min[0] + b.max[0]) / 2, b.min[1] - 0.001 * size, (b.min[2] + b.max[2]) / 2);
      (this.grid.material as THREE_NS.Material).transparent = true; (this.grid.material as THREE_NS.Material).opacity = 0.7;
      this.scene3.add(this.grid);
    }
    if (!o.keepCamera) this.fit(s);
    this.requestRender();
  }

  private dataTex(img: Img, srgb: boolean): THREE_NS.DataTexture {
    const THREE = this.T;
    const t = new THREE.DataTexture(new Uint8Array(img.px.buffer.slice(img.px.byteOffset, img.px.byteOffset + img.px.byteLength)), img.w, img.h, THREE.RGBAFormat);
    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.magFilter = this.pixel ? THREE.NearestFilter : THREE.LinearFilter;
    t.minFilter = this.pixel ? THREE.NearestFilter : THREE.LinearMipmapLinearFilter;
    t.generateMipmaps = !this.pixel;
    t.flipY = false;
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.needsUpdate = true;
    return t;
  }

  /** Upload channel composites (albedo always; the others only when painted). */
  setMaps(maps: ViewMaps) {
    const THREE = this.T;
    for (const [k, img] of Object.entries(maps) as [PaintChannel, Img | undefined][]) {
      if (!img) continue;
      const cur = this.tex[k];
      if (cur && cur.image.width === img.w && cur.image.height === img.h) { (cur.image.data as Uint8Array).set(img.px); cur.needsUpdate = true; continue; }
      cur?.dispose();
      this.tex[k] = this.dataTex(img, k === "albedo" || k === "emissive");
    }
    const m = this.lit;
    m.map = this.tex.albedo ?? null;
    if (!this.pixel) {
      // roughness reads G and metalness B in three.js: the composites are grey, so every channel holds the value
      m.normalMap = this.tex.normal ?? null;
      m.roughnessMap = this.tex.roughness ?? null; m.roughness = 1;
      m.metalnessMap = this.tex.metallic ?? null; m.metalness = this.tex.metallic ? 1 : 0;
      m.emissiveMap = this.tex.emissive ?? null; m.emissive = new THREE.Color(this.tex.emissive ? 0xffffff : 0x000000);
    }
    m.needsUpdate = true;
    this.requestRender();
  }

  /** Lit PBR, or an unlit image (a channel view / UV checker) shown exactly as stored. */
  setDisplay(d: Display) {
    if (!this.mesh) return;
    if (d.kind === "lit") { this.mesh.material = this.lit; this.requestRender(); return; }
    const cur = this.viewTex;
    if (cur && cur.image.width === d.img.w && cur.image.height === d.img.h) { (cur.image.data as Uint8Array).set(d.img.px); cur.needsUpdate = true; }
    else { cur?.dispose(); this.viewTex = this.dataTex(d.img, true); }
    this.flat.map = this.viewTex; this.flat.needsUpdate = true;
    this.mesh.material = this.flat;
    this.requestRender();
  }

  setWire(on: boolean) { if (this.wire) this.wire.visible = on; this.requestRender(); }
  setTheme(light: boolean) { this.o.light = light; this.requestRender(); }

  setLighting(p: LightingPreset) {
    const THREE = this.T, L = LIGHTING_PRESETS[p];
    for (const l of this.lights) this.scene3.remove(l);
    const amb = new THREE.AmbientLight(L.ambient.color, L.ambient.intensity);
    const dirs = (["key", "fill", "rim"] as const).map((k) => { const d = new THREE.DirectionalLight(L[k].color, L[k].intensity); d.position.set(...L[k].dir); return d; });
    this.lights = [amb, ...dirs];
    this.scene3.add(...this.lights);
    this.requestRender();
  }

  // ------------------------------------------------------------------ camera
  private bounds(): { c: V3; r: number } {
    const s = this.mesh?.geometry.boundingSphere;
    if (!s) return { c: [0, 0, 0], r: 1 };
    const c = s.center.clone();
    if (this.rig) c.applyMatrix4(this.mesh!.matrix);
    return { c: [c.x, c.y, c.z], r: Math.max(1e-3, s.radius * (this.rig ? this.mesh!.matrix.getMaxScaleOnAxis() : 1)) };
  }
  fit(_s?: ModelScene) {
    if (this.rig) { this.applyRigCamera(); return; }
    const { c, r } = this.bounds();
    this.cam = { ...this.cam, target: c, dist: (r / Math.sin(((this.cam.fov / 2) * Math.PI) / 180)) * 1.1 };
    this.syncCamera();
  }
  preset(p: CamPreset) { this.cam = { ...this.cam, ...PRESET[p] }; this.syncCamera(); }
  zoom(k: number) { this.cam = { ...this.cam, dist: Math.max(0.05, Math.min(500, this.cam.dist * k)) }; this.syncCamera(); }

  private syncCamera() {
    const THREE = this.T;
    if (!(this.camera instanceof THREE.PerspectiveCamera)) this.camera = new THREE.PerspectiveCamera(this.cam.fov, 1, 0.01, 1000);
    const cam = this.camera as THREE_NS.PerspectiveCamera;
    const e = camEye(this.cam);
    cam.fov = this.cam.fov;
    cam.near = Math.max(0.001, this.cam.dist / 200); cam.far = this.cam.dist * 50 + 10;
    cam.position.set(e[0], e[1], e[2]);
    cam.up.set(0, 1, 0);
    cam.lookAt(this.cam.target[0], this.cam.target[1], this.cam.target[2]);
    this.resize();
    this.events.onCamera?.(this.cam);
  }

  /** The ray through a client point (same maths as the pure pick). */
  rayAt(clientX: number, clientY: number): Ray {
    const r = this.canvas.getBoundingClientRect();
    return rayFromOrbit(this.cam, clientX - r.left, clientY - r.top, r.width || 1, r.height || 1);
  }

  // ------------------------------------------------------------------ in-game context (read-only panel)
  setRig(rig: ContextRig | null, light: boolean) {
    const THREE = this.T;
    this.rig = rig;
    this.props.clear();
    if (this.grid) this.grid.visible = !rig;
    if (!this.mesh) return;
    if (!rig) { this.mesh.matrixAutoUpdate = true; this.mesh.matrix.identity(); this.mesh.position.set(0, 0, 0); this.mesh.updateMatrix(); if (this.wire) { this.wire.matrixAutoUpdate = true; } this.fit(); return; }
    const M = new THREE.Matrix4().fromArray(rig.model as M4);
    for (const m of [this.mesh, this.wire!]) { m.matrixAutoUpdate = false; m.matrix.copy(M); m.matrixWorldNeedsUpdate = true; }
    for (const p of rig.props) this.props.add(this.propMesh(p, light));
    this.applyRigCamera();
  }

  private propMesh(p: Prop, light: boolean): THREE_NS.Object3D {
    const THREE = this.T;
    const col: Record<Prop["kind"], number> = { glove: 0x6152b8, sleeve: 0x3a2f78, slot: light ? 0xb9b3cc : 0x3a3a48, frame: 0x8a5a32, shadow: 0x000000, head: 0x8676dc, body: 0x4a3e94, shelf: 0x7a5434 };
    const mat = new THREE.MeshStandardMaterial({ color: col[p.kind], roughness: 1, metalness: 0, transparent: p.kind === "shadow" || p.kind === "glove", opacity: p.kind === "shadow" ? 0.35 : p.kind === "glove" ? 0.92 : 1 });
    const g = p.kind === "shadow" ? new THREE.CylinderGeometry(p.size[0] / 2, p.size[0] / 2, 0.005, 24) : new THREE.BoxGeometry(...p.size);
    const m = new THREE.Mesh(g, mat);
    if (p.kind === "sleeve" && p.dir) {
      const d = new THREE.Vector3(...p.dir).normalize();
      m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
      m.position.set(p.center[0] + (d.x * p.size[1]) / 2, p.center[1] + (d.y * p.size[1]) / 2, p.center[2] + (d.z * p.size[1]) / 2);
    } else m.position.set(...p.center);
    return m;
  }

  private applyRigCamera() {
    const THREE = this.T, rig = this.rig!;
    const box = new THREE.Box3().setFromObject(this.mesh!);
    if (rig.proj === "persp") {
      this.cam = { ...rig.cam };
      this.syncCamera();
      return;
    }
    for (const c of this.props.children) box.expandByObject(c);
    const sphere = box.getBoundingSphere(new THREE.Sphere());
    const r = Math.max(1e-3, sphere.radius) * 1.08;
    const el = this.canvas.getBoundingClientRect();
    const asp = (el.width || 1) / (el.height || 1);
    const cam = new THREE.OrthographicCamera(-r * asp, r * asp, r, -r, 0.01, r * 20 + 10);
    const yaw = (rig.cam.yaw * Math.PI) / 180, pitch = (rig.cam.pitch * Math.PI) / 180;
    const dir = new THREE.Vector3(Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch), Math.cos(pitch) * Math.cos(yaw));
    cam.position.copy(sphere.center).addScaledVector(dir, r * 4 + 1);
    cam.lookAt(sphere.center);
    this.camera = cam;
    this.requestRender();
  }

  // ------------------------------------------------------------------ input
  private bind() {
    const c = this.canvas;
    c.addEventListener("contextmenu", (e) => e.preventDefault());
    c.addEventListener("pointerdown", (e) => {
      if (this.rig) return;
      c.setPointerCapture(e.pointerId);
      const paint = e.button === 0 && !e.altKey && !this.readOnly && !!this.events.onPaintStart && this.events.onPaintStart(this.rayAt(e.clientX, e.clientY), e);
      this.drag = { mode: paint ? "paint" : e.button === 1 || e.shiftKey ? "pan" : "orbit", x: e.clientX, y: e.clientY, id: e.pointerId };
      this.fpsT0 = performance.now(); this.frames = 0;
    });
    c.addEventListener("pointermove", (e) => {
      const d = this.drag;
      if (!d) { this.events.onHover?.(this.rig ? null : this.rayAt(e.clientX, e.clientY), e); return; }
      if (d.id !== e.pointerId) return;
      if (d.mode === "paint") { this.events.onPaintMove?.(this.rayAt(e.clientX, e.clientY), e); this.events.onHover?.(this.rayAt(e.clientX, e.clientY), e); return; }
      const dx = e.clientX - d.x, dy = e.clientY - d.y;
      d.x = e.clientX; d.y = e.clientY;
      if (d.mode === "orbit") this.cam = { ...this.cam, yaw: this.cam.yaw - dx * 0.45, pitch: Math.max(-89, Math.min(89, this.cam.pitch + dy * 0.45)) };
      else {
        const k = this.cam.dist / 600, y = (this.cam.yaw * Math.PI) / 180;
        const right: V3 = [Math.cos(y), 0, -Math.sin(y)];
        this.cam = { ...this.cam, target: [this.cam.target[0] - right[0] * dx * k, this.cam.target[1] + dy * k, this.cam.target[2] - right[2] * dx * k] };
      }
      this.syncCamera();
    });
    const end = (e: PointerEvent) => {
      const d = this.drag;
      if (!d || d.id !== e.pointerId) return;
      if (d.mode === "paint") this.events.onPaintEnd?.();
      this.drag = null;
      const ms = performance.now() - this.fpsT0;
      if (ms > 250 && this.frames > 2) this.fps = Math.round((this.frames * 1000) / ms);
    };
    c.addEventListener("pointerup", end);
    c.addEventListener("pointercancel", end);
    c.addEventListener("pointerleave", () => { if (!this.drag) this.events.onHover?.(null, null); });
    c.addEventListener("wheel", (e) => { if (this.rig) return; e.preventDefault(); this.zoom(Math.exp(e.deltaY * 0.0012)); }, { passive: false });
  }

  // ------------------------------------------------------------------ render
  private resize() {
    const r = this.canvas.getBoundingClientRect();
    const w = Math.max(1, Math.floor(r.width)), h = Math.max(1, Math.floor(r.height));
    this.renderer.setSize(w, h, false);
    if (this.camera instanceof this.T.PerspectiveCamera) { this.camera.aspect = w / h; this.camera.updateProjectionMatrix(); }
    else if (this.rig) { this.applyRigCamera(); return; }
    this.requestRender();
  }
  requestRender() {
    if (this.raf) return;
    this.raf = requestAnimationFrame(() => {
      this.raf = 0;
      this.frames++;
      this.renderer.render(this.scene3, this.camera);
    });
  }
  /** A PNG of the current view (thumbnails). */
  snapshot(): string { this.renderer.render(this.scene3, this.camera); return this.canvas.toDataURL("image/png"); }
  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.mesh?.geometry.dispose();
    for (const t of Object.values(this.tex)) t?.dispose();
    this.viewTex?.dispose();
    this.renderer.dispose();
  }
}

