"use client";
// Cyrus MODEL STUDIO, Layer 1 (viewport + paint), full page. Layout and anatomy follow the v3 paint mockup
// (/root/agent-notes/cyrus-designs/v3-model-studio/viewport-paint.html; NOT yet reviewed by the owner): left = this
// mod's models, the UV texture, layers; centre = the 3D viewport with the tool rail, channel bar, palette strip and
// prompt dock; right = "In game" contexts + states and the Checks / Paint / History tabs. Phones get a read-only
// orbit preview + Approve / Reject of the autosaved draft. Pure logic: lib/cyrus/modelstudio/* (unit-tested);
// drawing: ./model-viewport.ts (three.js, lazy). Viewing is never gated; painting/saving follows the server's gate.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { textureQuality } from "@/lib/cyrus/textures/quality";
import { renderDoc } from "@/lib/cyrus/studios/paint";
import { previewDisplays } from "@/lib/cyrus/itemmodel/preview";
import { pickScene, mirrorHit, regionOf, type Hit } from "@/lib/cyrus/modelstudio/pick";
import { sceneFromItem, SCENE_FACES, type Img, type ModelScene } from "@/lib/cyrus/modelstudio/scene";
import { CHANNEL_LABEL, compositeChannel, compositeRegion, opRect, paintedCount, PAINT_CHANNELS, type LayerSet, type PaintChannel, type BlendMode, BLEND_MODES } from "@/lib/cyrus/modelstudio/layers";
import { applyOpMut, appliedOps, canRedoS, canUndoS, floodSpans, OP_LABEL, sessionInit, sessionPush, sessionRedo, sessionState, sessionUndo, type BrushShape, type Op, type Px, type Session } from "@/lib/cyrus/modelstudio/paint";
import { encodeLayers, startLayers, type ModelDoc } from "@/lib/cyrus/modelstudio/doc";
import { channelImage, channelUntouched, paintChannels, uvChecker, viewModes, type ViewMode } from "@/lib/cyrus/modelstudio/channels";
import { contextRig, contextTransform, gripChecks, gripReference, gripSummary, VIEW_CONTEXTS, type GripCheck, type ViewContext } from "@/lib/cyrus/modelstudio/contexts";
import { PERF_BUDGET, sceneBudget } from "@/lib/cyrus/modelstudio/budget";
import { mergeLayerSets } from "@/lib/cyrus/modelstudio/merge";
import { canonical, sha256Text } from "@/lib/cyrus/modelstudio/hash";
import { LIGHTING_PRESETS, type LightingPreset } from "@/lib/cyrus/modelstudio/look";
import { ApiError } from "./api";
import { modelApi, type ModelsView, type ModelEntry, type DraftView } from "./model-api";
import { hexOf, imgOf, makeStamp, prepare, rasterOf, rgbOf, STAMPS, stampRows, type AnyEntry, type Prepared, type SampleEntry, type StampId } from "./model-helpers";
import { ModelViewport, webglOk, type CamPreset, type ViewMaps } from "./model-viewport";
import { SI } from "./icons";
import { paintRaster, RasterCanvas } from "./raster";
import { StudioShell, studioHref, useToast, type StudioMod } from "./StudioShell";
import "./model-studio.css";

type Tool = "brush" | "erase" | "fill" | "pick" | "decal" | "orbit";
const TOOLS: { id: Tool; icon: string; label: string; key: string }[] = [
  { id: "brush", icon: "pencil", label: "Brush", key: "B" }, { id: "erase", icon: "eraser", label: "Erase to base", key: "E" },
  { id: "fill", icon: "facefill", label: "Fill face", key: "G" }, { id: "pick", icon: "picker", label: "Pick colour", key: "I" },
  { id: "decal", icon: "stamp", label: "Decal stamp", key: "D" },
];
const MAX_LOG = 2000;

type Ed = {
  key: string;
  entry: AnyEntry;
  prep: Prepared;
  scene: ModelScene;
  session: Session;
  /** the layers after session.at ops (kept in sync while painting, without a replay) */
  live: LayerSet;
  /** the session started from the saved layers (false after a draft restore or a merge: the log is then not replayable from the save) */
  fromSaved: boolean;
  baseAssetId: string | null;
  headId: string | null;
  dirty: boolean;
  restored: string | null;
  merged: { overlaps: number; layers: number } | null;
};

const kindLabel = (m: AnyEntry) => (m.kind === "creature" ? "creature" : m.kind === "item3d" ? "3D item" : "mesh");
const subLine = (m: AnyEntry) => (m.kind === "creature" ? `creature · ${m.stats.bones} bones · ${m.stats.cubes} cubes` : m.kind === "item3d" ? `item · extruded · ${m.base.doc.size} px` : "sample glTF · not in this mod");

function edFor(m: AnyEntry, headId: string | null, draft?: DraftView | null): Ed {
  const prep = prepare(m);
  let start = prep.start, restored: string | null = null, fromSaved = true;
  if (draft && draft.baseAssetId === prep.baseAssetId && draft.doc.tex.w === prep.start.w) {
    const s = startLayers(draft.doc, prep.start.w, prep.start.h);
    start = s; restored = draft.updatedAt; fromSaved = false;
  }
  const session = sessionInit(start, prep.scene.tex.wrap);
  return { key: m.key, entry: m, prep, scene: prep.scene, session, live: sessionState(session), fromSaved, baseAssetId: prep.baseAssetId, headId: draft && !fromSaved ? draft.baseHeadId : headId, dirty: !!restored, restored, merged: null };
}

function docOf(ed: Ed): ModelDoc {
  const m = ed.entry, w = ed.live.w, h = ed.live.h;
  const ops = appliedOps(ed.session);
  const base: ModelDoc["base"] = m.kind === "creature" ? { type: "rigspec", assetId: m.assetId, sha256: m.sha256, spec: m.spec }
    : m.kind === "item3d" ? { type: "texture", key: m.key, assetId: m.texture.assetId, sha256: sha256Text(canonical(m.texture.doc)) }
    : { type: "gltf", sha256: "0".repeat(64), path: null };
  return {
    v: 1, kind: m.kind === "mesh" ? "mesh" : m.kind, name: m.key, base, tex: { w, h }, layers: encodeLayers(ed.live), symmetry: "none",
    log: { ops: ops.length, folded: ed.session.folded + (ed.fromSaved ? 0 : 1), sha256: sha256Text(canonical(ops)) },
  };
}

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const q = window.matchMedia(`(max-width: ${PERF_BUDGET.mobileBreakpointPx}px)`); const f = () => setN(q.matches); f(); q.addEventListener("change", f); return () => q.removeEventListener("change", f); }, []);
  return n;
}
function useLight() {
  const [l, setL] = useState(false);
  useEffect(() => { const f = () => setL(document.documentElement.getAttribute("data-theme") === "light"); f(); const mo = new MutationObserver(f); mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] }); return () => mo.disconnect(); }, []);
  return l;
}

export function ModelStudio({ mod, initialKey, samples }: { mod: StudioMod; initialKey: string | null; samples: boolean }) {
  return (
    <StudioShell mod={mod} current="Model Studio" studio="model" showModel>
      <Body mod={mod} initialKey={initialKey} samples={samples} />
    </StudioShell>
  );
}

function Body({ mod, initialKey, samples }: { mod: StudioMod; initialKey: string | null; samples: boolean }) {
  const [view, setView] = useState<ModelsView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const narrow = useNarrow();
  const load = useCallback(async () => { try { setView(await modelApi.models(mod.rootId)); } catch (e) { setErr((e as Error).message); } }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);
  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s models…</div>;
  const entries: AnyEntry[] = [...view.models, ...(samples ? [{ kind: "mesh", key: "sample_crate", label: "sample_crate", sample: true } as SampleEntry] : [])];
  if (!entries.length) {
    return (
      <main className="ms-ws ms-empty"><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
        <div className="cys-empty" style={{ maxWidth: 440 }}><SI n="cube" /><p><b>This mod has no models to paint yet.</b></p><p className="cys-hint">Model Studio paints the mod&apos;s animated creatures and held items. Ask Cyrus for a creature or a custom item in your next change.</p></div>
      </div></main>
    );
  }
  return narrow ? <Narrow mod={mod} view={view} entries={entries} initialKey={initialKey} reload={load} /> : <Editor mod={mod} view={view} entries={entries} initialKey={initialKey} reload={load} setView={setView} />;
}

// ======================================================================================================== editor

function Editor({ mod, view, entries, initialKey, reload, setView }: { mod: StudioMod; view: ModelsView; entries: AnyEntry[]; initialKey: string | null; reload: () => Promise<void>; setView: (v: ModelsView) => void }) {
  const toast = useToast();
  const light = useLight();
  const canEdit = view.access.edit.ok;
  const project = view.project;
  const [cur, setCur] = useState<string>(entries.find((e) => e.key === initialKey)?.key ?? entries[0].key);
  const [ed, setEd] = useState<Ed | null>(null);
  const edRef = useRef<Ed | null>(null);
  edRef.current = ed;
  const [ver, setVer] = useState(0); // bumps when live pixels change (UV canvas, checks)
  const [tool, setTool] = useState<Tool>("brush");
  const [color, setColor] = useState<[number, number, number]>([201, 204, 214]);
  const [size, setSize] = useState(1);
  const [shape, setShape] = useState<BrushShape>("square");
  const [mirror, setMirror] = useState(false);
  const [fillMode, setFillMode] = useState<"face" | "area">("face");
  const [stamp, setStamp] = useState<StampId>("star");
  const [activeLayer, setActiveLayer] = useState("paint");
  const [mode, setMode] = useState<ViewMode>("lit");
  const [wire, setWire] = useState(false);
  const [uvView, setUvView] = useState(false);
  const [lighting, setLighting] = useState<LightingPreset>("studio");
  const [camPreset, setCamPreset] = useState<CamPreset>("persp");
  const [ctx, setCtx] = useState<ViewContext>("firstperson");
  const [stateId, setStateId] = useState("idle");
  const [tab, setTab] = useState<"checks" | "paint" | "history">("checks");
  const [hover, setHover] = useState<{ hit: Hit; x: number; y: number } | null>(null);
  const [draftState, setDraftState] = useState<"idle" | "saving" | "saved" | "off">("idle");
  const [draftAt, setDraftAt] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [webgl] = useState(() => (typeof window === "undefined" ? true : webglOk()));

  const entry = entries.find((e) => e.key === cur)!;
  const isItem = entry.kind === "item3d";
  const profileChannels = useMemo(() => (ed ? paintChannels(ed.prep.profile) : []), [ed]);
  const modes = useMemo(() => (ed ? viewModes(ed.prep.profile) : []), [ed]);

  // ---------------------------------------------------------------- open a model (+ restore its draft)
  useEffect(() => {
    let off = false;
    (async () => {
      let draft: DraftView | null = null;
      if (project && !("sample" in entry)) draft = await modelApi.getDraft(project.id, entry.key).then((r) => r.draft, () => null);
      if (off) return;
      const e = edFor(entry, view.headRevisionId, draft);
      setEd(e); setActiveLayer(e.live.layers.find((l) => l.channel === "albedo")?.id ?? e.live.layers[0]?.id ?? "paint");
      setStateId("idle"); setMode("lit"); setDraftState(draft && e.restored ? "saved" : "idle"); setDraftAt(e.restored);
      const pal = entry.kind === "creature" ? Object.values(entry.spec.skin.palette) : entry.kind === "item3d" && entry.base.doc.spec ? Object.values(entry.base.doc.spec.palette) : [];
      if (pal[0]) setColor(rgbOf(pal.find((c, i) => i > 0) ?? pal[0]));
    })();
    return () => { off = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cur, view.headRevisionId]);

  // ---------------------------------------------------------------- composites
  const comps = useRef<Partial<Record<PaintChannel, Img>>>({});
  const recomposite = useCallback((e: Ed) => {
    const next: Partial<Record<PaintChannel, Img>> = {};
    for (const c of PAINT_CHANNELS) next[c] = compositeChannel(e.live, c, c === "albedo" ? e.prep.base : null);
    comps.current = next;
  }, []);
  const maps = useCallback((e: Ed): ViewMaps => {
    const out: ViewMaps = { albedo: comps.current.albedo! };
    if (!e.prep.profile) for (const c of ["normal", "roughness", "metallic", "emissive"] as const) if (!channelUntouched(e.live, c)) out[c] = comps.current[c];
    return out;
  }, []);

  // ---------------------------------------------------------------- the main viewport
  const cvRef = useRef<HTMLCanvasElement>(null);
  const vpRef = useRef<ModelViewport | null>(null);
  const [vpReady, setVpReady] = useState(false);
  useEffect(() => {
    if (!cvRef.current || !webgl) return;
    let dead = false;
    ModelViewport.create(cvRef.current, { mobile: false, light }).then((v) => { if (dead) { v.dispose(); return; } vpRef.current = v; setVpReady(true); });
    return () => { dead = true; vpRef.current?.dispose(); vpRef.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl]);
  useEffect(() => { vpRef.current?.setTheme(light); }, [light]);
  useEffect(() => {
    const v = vpRef.current;
    if (!v || !ed) return;
    recomposite(ed);
    v.setScene(ed.scene, maps(ed), { pixel: !!ed.prep.profile });
    v.preset(camPreset);
    setVer((x) => x + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vpReady, ed?.key, ed?.session.base]);
  // view mode / overlays
  useEffect(() => {
    const v = vpRef.current;
    if (!v || !ed) return;
    if (uvView) v.setDisplay({ kind: "image", img: uvChecker(ed.live.w, ed.live.h) });
    else if (mode === "lit" || mode === "ao") v.setDisplay({ kind: "lit" });
    else v.setDisplay({ kind: "image", img: channelImage(ed.live, mode, ed.prep.base) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, uvView, ver, vpReady]);
  useEffect(() => { vpRef.current?.setWire(wire); }, [wire, vpReady]);
  useEffect(() => { vpRef.current?.setLighting(lighting); }, [lighting, vpReady]);

  // ---------------------------------------------------------------- painting
  const stroke = useRef<{ op: Op; seen: Set<string>; last: { x: number; y: number } | null } | null>(null);
  const layerOf = (e: Ed, id: string) => e.live.layers.find((l) => l.id === id);
  const paintBlock = (e: Ed): string | null => {
    if (!canEdit) return view.access.edit.ok ? null : (view.access.edit as { reason: string }).reason;
    if ("sample" in e.entry) return null;
    const l = layerOf(e, activeLayer);
    if (!l) return "Pick a layer to paint on.";
    const pc = profileChannels.find((c) => c.channel === l.channel);
    if (pc && !pc.paintable) return pc.reason;
    return null;
  };
  const alphaAt = (x: number, y: number) => comps.current.albedo?.px[(y * comps.current.albedo.w + x) * 4 + 3] ?? 255;
  const valueColor = (e: Ed): [number, number, number] => { const l = layerOf(e, activeLayer); return l && (l.channel === "roughness" || l.channel === "metallic" || l.channel === "mask") ? [color[0], color[0], color[0]] : color; };

  /** Apply an op to the live layers now (no replay), update the touched region of the composite and the GPU texture. */
  const applyLive = (e: Ed, op: Op) => {
    applyOpMut(e.live, op, e.scene.tex.wrap);
    const r = opRect(op as never);
    const ch = "layer" in op ? layerOf(e, op.layer)?.channel : undefined;
    if (r && ch) compositeRegion(e.live, ch, ch === "albedo" ? e.prep.base : null, r, comps.current[ch]!);
    else recomposite(e);
    if (e.entry.kind === "item3d" && ch === "albedo") e.scene = sceneFromItem(e.key, comps.current.albedo!, e.scene.grip); // the silhouette may change
    vpRef.current?.setMaps(maps(e));
    if (e.entry.kind === "item3d") vpRef.current?.setScene(e.scene, maps(e), { pixel: true, keepCamera: true });
  };
  const commit = (e: Ed, op: Op, alreadyApplied: boolean) => {
    if (!alreadyApplied) applyLive(e, op);
    const session = sessionPush(e.session, op);
    const next: Ed = { ...e, session, dirty: true };
    setEd(next); setVer((x) => x + 1);
  };
  const texelsFor = (e: Ed, ray: Parameters<typeof pickScene>[1]): Hit[] => {
    const h = pickScene(e.scene, ray, { alphaAt });
    if (!h) return [];
    if (!mirror) return [h];
    const m = mirrorHit(e.scene, ray, { alphaAt });
    return m ? [h, m] : [h];
  };

  useEffect(() => {
    const v = vpRef.current;
    if (!v) return;
    v.readOnly = !canEdit && !(ed && "sample" in ed.entry);
    v.events = {
      onPaintStart: (ray) => {
        const e = edRef.current;
        if (!e || tool === "orbit") return false;
        const hits = texelsFor(e, ray);
        if (!hits.length) return false; // empty space = orbit
        const block = paintBlock(e);
        if (block && tool !== "pick") { toast(block, true); return false; }
        const h = hits[0];
        if (tool === "pick") {
          const l = layerOf(e, activeLayer);
          const img = comps.current[l?.channel ?? "albedo"];
          if (img) { const o = (h.texel[1] * img.w + h.texel[0]) * 4; if (img.px[o + 3]) setColor([img.px[o], img.px[o + 1], img.px[o + 2]]); }
          return true;
        }
        if (tool === "fill") {
          const spans = hits.flatMap((x) => { const region = regionOf(e.scene, x); const l = layerOf(e, activeLayer)!; return fillMode === "face" ? region : floodSpans(comps.current[l.channel]!, x.texel[0], x.texel[1], region); });
          if (spans.length) commit(e, { t: "fill", layer: activeLayer, color: valueColor(e), spans: dedupeSpans(spans) }, false);
          return true;
        }
        if (tool === "decal") {
          const st = makeStamp(stamp, valueColor(e));
          for (const x of hits) commit(edRef.current!, { t: "decal", layer: activeLayer, x: x.texel[0] - Math.floor(st.w / 2), y: x.texel[1] - Math.floor(st.h / 2), stamp: st, clip: regionOf(e.scene, x) }, false);
          return true;
        }
        const pts: Px[] = hits.map((x) => [x.texel[0], x.texel[1]]);
        const op: Op = tool === "erase" ? { t: "erase", layer: activeLayer, size, shape, pts } : { t: "brush", layer: activeLayer, color: valueColor(e), size, shape, pts };
        stroke.current = { op, seen: new Set(pts.map((p) => p.join(","))), last: null };
        applyLive(e, op);
        return true;
      },
      onPaintMove: (ray, ev) => {
        const e = edRef.current, s = stroke.current;
        if (!e || !s || (s.op.t !== "brush" && s.op.t !== "erase")) return;
        // sub-steps in screen space so fast drags do not skip texels (never interpolated across UV seams)
        const from = s.last ?? { x: ev.clientX, y: ev.clientY };
        const steps = Math.max(1, Math.ceil(Math.hypot(ev.clientX - from.x, ev.clientY - from.y) / 3));
        const fresh: Px[] = [];
        for (let k = 1; k <= steps; k++) {
          const x = from.x + ((ev.clientX - from.x) * k) / steps, y = from.y + ((ev.clientY - from.y) * k) / steps;
          for (const h of texelsFor(e, vpRef.current!.rayAt(x, y))) { const key = h.texel.join(","); if (!s.seen.has(key) && s.op.pts.length + fresh.length < 4000) { s.seen.add(key); fresh.push([h.texel[0], h.texel[1]]); } }
        }
        s.last = { x: ev.clientX, y: ev.clientY };
        void ray;
        if (!fresh.length) return;
        s.op.pts.push(...fresh);
        applyLive(e, { ...s.op, pts: fresh } as Op);
        setVer((x) => x + 1);
      },
      onPaintEnd: () => { const e = edRef.current, s = stroke.current; stroke.current = null; if (e && s && (s.op.t === "brush" || s.op.t === "erase")) commit(e, s.op, true); },
      onHover: (ray, ev) => {
        const e = edRef.current;
        if (!e || !ray || !ev) { setHover(null); return; }
        const h = pickScene(e.scene, ray, { alphaAt });
        const r = cvRef.current!.getBoundingClientRect();
        setHover(h ? { hit: h, x: ev.clientX - r.left, y: ev.clientY - r.top } : null);
      },
    };
  });

  // ---------------------------------------------------------------- undo / redo / history jump
  const moveTo = useCallback((f: (s: Session) => Session) => {
    const e = edRef.current;
    if (!e) return;
    const session = f(e.session);
    const live = sessionState(session);
    const next: Ed = { ...e, session, live, dirty: true };
    if (e.entry.kind === "item3d") { const a = compositeChannel(live, "albedo", e.prep.base); next.scene = sceneFromItem(e.key, a, e.scene.grip); }
    recomposite(next);
    vpRef.current?.setScene(next.scene, maps(next), { pixel: !!next.prep.profile, keepCamera: true });
    setEd(next); setVer((x) => x + 1);
  }, [recomposite, maps]);
  const undo = () => ed && canUndoS(ed.session) && moveTo(sessionUndo);
  const redo = () => ed && canRedoS(ed.session) && moveTo(sessionRedo);

  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement)?.closest?.("input, textarea, select")) return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); if (e.shiftKey) redo(); else undo(); return; }
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const t = TOOLS.find((x) => x.key.toLowerCase() === e.key.toLowerCase());
      if (t) setTool(t.id);
      else if (e.key.toLowerCase() === "x") setMirror((m) => !m);
      else if (e.key.toLowerCase() === "o") setTool("orbit");
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  });

  // ---------------------------------------------------------------- autosave (debounce 5 s idle, at most 30 s)
  const firstDirty = useRef<number | null>(null);
  useEffect(() => {
    if (!ed || !ed.dirty || !project || "sample" in ed.entry || !canEdit) return;
    firstDirty.current ??= Date.now();
    const wait = Math.max(0, Math.min(5000, 30000 - (Date.now() - firstDirty.current)));
    const t = window.setTimeout(async () => {
      const e = edRef.current;
      if (!e) return;
      setDraftState("saving");
      try {
        const r = await modelApi.putDraft(project.id, e.key, { doc: docOf(e), baseAssetId: e.baseAssetId, baseHeadId: e.headId });
        setDraftState("saved"); setDraftAt(r.updatedAt); firstDirty.current = null;
      } catch { setDraftState("off"); }
    }, wait);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ed?.session]);

  // ---------------------------------------------------------------- save revision (+ the conflict rule)
  const save = async () => {
    const e = edRef.current;
    if (!e || !project || saving) return;
    setSaving(true);
    try {
      const ops = appliedOps(e.session);
      const log = e.fromSaved && e.session.folded === 0 && ops.length <= MAX_LOG ? ops : undefined;
      const r = await modelApi.save(project.id, e.key, { doc: docOf(e), baseAssetId: e.baseAssetId, expectedHeadId: e.headId, log });
      toast(`Saved revision ${r.seq}${r.kind === "item3d" ? " · the item's texture is updated in the pack" : ""}`);
      for (const w of r.warnings.slice(0, 1)) toast(w);
      firstDirty.current = null;
      await reload();
    } catch (err) {
      if (err instanceof ApiError && err.code === "stale_head") {
        // someone (an AI edit or another tab) saved since this session started: 3-way merge, the human wins overlaps
        const fresh = await modelApi.models(mod.rootId);
        const theirsEntry = fresh.models.find((m) => m.key === e.key);
        if (!theirsEntry) { toast(err.message, true); return; }
        const theirs = prepare(theirsEntry).start;
        const mr = mergeLayerSets(e.session.base, e.live, theirs);
        setView(fresh);
        const session = sessionInit(mr.set, e.scene.tex.wrap);
        const merged: Ed = { ...edFor(theirsEntry, fresh.headRevisionId), session, live: sessionState(session), fromSaved: false, dirty: true, merged: { overlaps: mr.overlapTexels, layers: mr.overlaps.length } };
        recomposite(merged);
        setEd(merged);
        toast(mr.overlapTexels ? `This model changed while you painted. Merged; ${mr.overlapTexels} overlapping texels kept your paint. Save again to keep it.` : "This model changed while you painted. Your paint was merged on top; save again to keep it.");
      } else toast((err as Error).message, true);
    } finally { setSaving(false); }
  };

  // ---------------------------------------------------------------- layers
  const layerOp = (op: Op) => { const e = edRef.current; if (!e) return; if (!canEdit && !("sample" in e.entry)) { toast((view.access.edit as { reason?: string }).reason ?? "View only", true); return; } commit(e, op, false); };
  const addLayer = (channel: PaintChannel) => {
    const e = edRef.current; if (!e) return;
    let n = 1; while (e.live.layers.some((l) => l.id === `${channel}_${n}`)) n++;
    const id = `${channel}_${n}`;
    layerOp({ t: "layer.add", id, name: `${CHANNEL_LABEL[channel]} ${n}`, channel });
    setActiveLayer(id);
  };

  // ---------------------------------------------------------------- derived panels
  const painted = useMemo(() => (ed ? paintedCount(ed.live) : { total: 0, perLayer: {} as Record<string, number> }), [ed, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const itemDisplays = useMemo(() => (ed && entry.kind === "item3d" && comps.current.albedo ? previewDisplays(entry.preview, rasterOf(comps.current.albedo)) : null), [ed, entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const gripRef = useMemo(() => (entry.kind === "item3d" && comps.current.albedo ? gripReference(entry.preview.spec.category, rasterOf(comps.current.albedo)) : null), [entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const grips = useMemo<GripCheck[]>(() => (itemDisplays && gripRef ? gripChecks(itemDisplays, gripRef) : []), [itemDisplays, gripRef]);
  const quality = useMemo(() => (ed && entry.kind === "item3d" && comps.current.albedo ? textureQuality(rasterOf(comps.current.albedo)) : null), [ed, entry, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  const budget = useMemo(() => (ed ? sceneBudget(ed.scene, 1 + (ed.prep.profile ? 0 : ["normal", "roughness", "metallic", "emissive"].filter((c) => !channelUntouched(ed.live, c as PaintChannel)).length)) : []), [ed, ver]); // eslint-disable-line react-hooks/exhaustive-deps

  if (!ed) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Opening the model…</div>;
  const block = paintBlock(ed);
  const activeL = layerOf(ed, activeLayer);
  const swatches = (entry.kind === "creature" ? Object.values(entry.spec.skin.palette) : entry.kind === "item3d" && entry.base.doc.spec ? Object.values(entry.base.doc.spec.palette) : ["#7a5230", "#b07a46", "#d9a066", "#3b2a1a", "#c9ccd6", "#ff8a1f"]).slice(0, 12);
  const sampleOnly = "sample" in ed.entry;
  const tip = hover ? `${ed.scene.parts[hover.hit.part]?.name ?? ""} · ${hover.hit.face} · ${hover.hit.texel[0]}, ${hover.hit.texel[1]}` : null;

  return (
    <main className="ms-ws">
      {/* ---------------------------------------------------------------- left */}
      <section className="ms-col scroll">
        <div className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">Models</span><span className="ms-n">{entries.length}</span></div>
          <div className="ms-list">
            {entries.map((m) => (
              <button key={m.key} type="button" className={`ms-mrow ${m.key === cur ? "on" : ""}`} onClick={() => { if (ed.dirty && m.key !== cur && !window.confirm("You have unsaved paint on this model. It is kept as a draft; switch anyway?")) return; setCur(m.key); }}>
                <span className="th3">{m.kind === "item3d" ? <RasterCanvas raster={renderDoc(m.texture.doc)} className="pix" /> : <SI n="cube" />}</span>
                <span className="tx"><b>{m.key}</b><small>{subLine(m)}</small></span>
                {"sample" in m && <span className="cys-tag dim">dev</span>}
              </button>
            ))}
          </div>
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">UV texture</span><span className="cys-tag dim">{ed.live.w} × {ed.live.h}</span></div>
          <UvPanel ed={ed} comps={comps.current} channel={activeL?.channel ?? "albedo"} hover={hover?.hit ?? null} ver={ver} />
        </div>
        <div className="cys-panel cys-glass">
          <div className="cys-ph"><span className="cys-eyebrow">Layers</span>
            <select className="ms-add" aria-label="Add a layer" value="" disabled={!canEdit && !sampleOnly} onChange={(e) => { if (e.target.value) addLayer(e.target.value as PaintChannel); }}>
              <option value="">+ Layer</option>
              {profileChannels.map((c) => <option key={c.channel} value={c.channel} disabled={!c.paintable}>{CHANNEL_LABEL[c.channel]}{c.paintable ? "" : " (not in this game)"}</option>)}
            </select>
          </div>
          <div className="ms-layers">
            {[...ed.live.layers].reverse().map((l) => (
              <div key={l.id} className={`ms-lay ${l.id === activeLayer ? "on" : ""} ${l.visible ? "" : "off"}`}>
                <button type="button" className="cys-ib sm" aria-label={l.visible ? `Hide ${l.name}` : `Show ${l.name}`} onClick={() => layerOp({ t: "layer.set", id: l.id, visible: !l.visible })}><SI n={l.visible ? "eye" : "eyeoff"} /></button>
                <button type="button" className="grow" onClick={() => setActiveLayer(l.id)}>
                  <b>{l.name}</b><small>{CHANNEL_LABEL[l.channel]} · {painted.perLayer[l.id] ?? 0} px · {l.blend}{l.opacity < 255 ? ` · ${Math.round((l.opacity / 255) * 100)}%` : ""}</small>
                </button>
                {ed.live.layers.length > 1 && <button type="button" className="cys-ib sm" aria-label={`Delete ${l.name}`} onClick={() => layerOp({ t: "layer.del", id: l.id })}><SI n="trash" /></button>}
              </div>
            ))}
            <div className="ms-lay locked"><span className="cys-ib sm"><SI n="lock" /></span><span className="grow"><b>Generated base</b><small>{ed.entry.kind === "creature" ? "RigSpec skin · compiler" : ed.entry.kind === "item3d" ? "TextureSpec + earlier edits" : "sample albedo"}</small></span></div>
            {activeL && (
              <div className="ms-layprops">
                <label><span>Opacity</span><input type="range" min={0} max={255} value={activeL.opacity} disabled={!canEdit && !sampleOnly} onChange={(e) => layerOp({ t: "layer.set", id: activeL.id, opacity: Number(e.target.value) })} /><b>{Math.round((activeL.opacity / 255) * 100)}%</b></label>
                <label><span>Blend</span><select className="cys-field" value={activeL.blend} disabled={!canEdit && !sampleOnly} onChange={(e) => layerOp({ t: "layer.set", id: activeL.id, blend: e.target.value as BlendMode })}>{BLEND_MODES.map((b) => <option key={b}>{b}</option>)}</select></label>
              </div>
            )}
            <p className="cys-hint" style={{ margin: "6px 2px 0" }}>Strokes never change the spec. Saving stores the layers with the model as a new revision.</p>
          </div>
        </div>
      </section>

      {/* ---------------------------------------------------------------- centre */}
      <section className="ms-col">
        <div className="cys-panel cys-glass cys-hairline ms-hdr">
          <span className="ic"><SI n="cube" /></span><span className="nm">{ed.key}</span>
          <span className="ms-pill">{kindLabel(ed.entry)}</span>
          <span className="ms-pill">{ed.entry.kind === "creature" ? `${ed.entry.stats.cubes} cubes` : `${ed.scene.triCount.toLocaleString()} tris`}</span>
          <span className="sp" />
          <button type="button" className="cys-ib sm" aria-label="Undo (Ctrl Z)" title="Undo (Ctrl Z)" disabled={!canUndoS(ed.session)} onClick={undo}><SI n="undo" /></button>
          <button type="button" className="cys-ib sm" aria-label="Redo (Ctrl Shift Z)" title="Redo (Ctrl Shift Z)" disabled={!canRedoS(ed.session)} onClick={redo}><SI n="redo" /></button>
          <span className="ms-saved"><span className={`cys-dot ${draftState === "saved" ? "ok" : draftState === "off" ? "warn" : ""}`} />{sampleOnly ? "Sample: not saved" : !ed.dirty ? "No changes" : draftState === "saving" ? "Saving draft…" : draftState === "saved" ? "Draft saved" : draftState === "off" ? "Draft not saved" : "Unsaved"}</span>
          <button type="button" className="cys-btn sm primary" disabled={!canEdit || !ed.dirty || saving || sampleOnly} onClick={save}><SI n="check" />{saving ? "Saving…" : "Save revision"}</button>
        </div>
        {(ed.restored || ed.merged) && (
          <div className="ms-note cys-soft">
            <SI n="info" />
            {ed.merged ? <span>Merged with a newer version of this model: {ed.merged.overlaps} overlapping texels kept your paint ({ed.merged.layers} layers touched). Save to keep the result.</span>
              : <span>Restored your autosaved draft from {new Date(ed.restored!).toLocaleString()}.</span>}
            <span className="sp" />
            {ed.restored && project && <button type="button" className="cys-btn xs ghost" onClick={async () => { await modelApi.dropDraft(project.id, ed.key).catch(() => undefined); setEd(edFor(entry, view.headRevisionId, null)); }}>Discard draft</button>}
          </div>
        )}
        <div className="cys-panel cys-glass ms-vp" data-tool={tool}>
          {webgl ? <canvas ref={cvRef} className={`ms-cv ${tool === "orbit" || block ? "orbit" : "paint"}`} aria-label={`3D view of ${ed.key}`} /> : <ServerFallback ed={ed} projectId={project?.id ?? null} renderer={view.renderer} />}
          <div className="ms-tools cys-float" role="toolbar" aria-label="Paint tools">
            {TOOLS.map((t) => <button key={t.id} type="button" className={`cys-ib ${tool === t.id ? "on" : ""}`} aria-label={`${t.label} (${t.key})`} data-tip={`${t.label} (${t.key})`} disabled={!!block && t.id !== "pick"} onClick={() => setTool(t.id)}><SI n={t.icon} /></button>)}
            <div className="cys-sep" />
            <button type="button" className={`cys-ib tog ${mirror ? "on" : ""}`} aria-label="Mirror across the model (X)" data-tip="Mirror across the model (X)" aria-pressed={mirror} onClick={() => setMirror((m) => !m)}><SI n="mirror" /></button>
            <button type="button" className={`cys-ib ${tool === "orbit" ? "on" : ""}`} aria-label="Orbit (O, or right drag)" data-tip="Orbit (O, or right drag)" onClick={() => setTool("orbit")}><SI n="orbit" /></button>
          </div>
          <div className="ms-vpbar">
            <span className="cys-float ms-stat"><SI n="cube" /> {ed.prep.profile ? <>Minecraft Java · <b>pixel profile</b></> : <>glTF · <b>PBR</b></>}</span>
            <span className="sp" />
            <div className="cys-float ms-chan" aria-label="Overlays">
              <button type="button" className={wire ? "on" : ""} aria-pressed={wire} onClick={() => setWire((w) => !w)}><SI n="wire" />Wire</button>
              <button type="button" className={uvView ? "on" : ""} aria-pressed={uvView} onClick={() => setUvView((u) => !u)}><SI n="uvgrid" />UV</button>
            </div>
            <div className="cys-float ms-chan" aria-label="Camera">
              {(["persp", "front", "side", "top"] as CamPreset[]).map((p) => <button key={p} type="button" className={camPreset === p ? "on" : ""} onClick={() => { setCamPreset(p); vpRef.current?.preset(p); }}>{p === "persp" ? "Persp" : p[0].toUpperCase() + p.slice(1)}</button>)}
            </div>
          </div>
          {block && <span className="ms-ro cys-tag"><SI n="eye" />{!canEdit ? "View only" : "Not paintable"}</span>}
          <div className="ms-vpfoot">
            <div className="cys-float ms-chan" aria-label="Channel">
              <span className="lab">Channel</span>
              {modes.map((m) => <button key={m.id} type="button" className={mode === m.id && !uvView ? "on" : ""} disabled={!m.enabled} title={m.reason ?? m.label} onClick={() => { setMode(m.id); setUvView(false); }}>{m.label}</button>)}
            </div>
          </div>
          {tip && hover && <div className="ms-tip" style={{ left: hover.x + 14, top: hover.y + 14 }}><b>{tip.split(" · ")[0]}</b> · {tip.split(" · ").slice(1).join(" · ")}</div>}
          {hover && tool !== "orbit" && !block && <div className="ms-ring" style={{ left: hover.x, top: hover.y, width: 10 + size * 4, height: 10 + size * 4, marginLeft: -(5 + size * 2), marginTop: -(5 + size * 2) }} />}
        </div>
        <div className="cys-panel cys-glass ms-pal">
          <span className="cys-eyebrow">Palette</span>
          <div className="sws">
            {swatches.map((h) => <button key={h} type="button" style={{ background: h }} className={hexOf(color) === h.toLowerCase() ? "on" : ""} aria-label={h} onClick={() => setColor(rgbOf(h.toLowerCase()))} />)}
            <label className="ms-cpick" title="Any colour"><input type="color" value={hexOf(color)} onChange={(e) => setColor(rgbOf(e.target.value))} aria-label="Pick any colour" /><span style={{ background: hexOf(color) }} /></label>
          </div>
          <span className="vr" />
          <span className="cys-eyebrow">Brush</span>
          <div className="cys-seg sm cys-soft">{[1, 2, 3, 5, 8].map((n) => <button key={n} type="button" className={size === n ? "on" : ""} onClick={() => setSize(n)}>{n} px</button>)}</div>
          <div className="cys-seg sm cys-soft">{(["square", "round"] as BrushShape[]).map((s2) => <button key={s2} type="button" className={shape === s2 ? "on" : ""} onClick={() => setShape(s2)}>{s2}</button>)}</div>
          <span className="sp" />
          <span className="ms-mono">{painted.total} px painted</span>
        </div>
        <div className="cys-dock cys-glass ms-dock" aria-disabled="true">
          <span className="route"><SI n="edit" />Edit {ed.key}</span>
          <input disabled placeholder="Asking Cyrus to repaint a model arrives with model candidates (not built yet)" aria-label="Change request (not available yet)" />
          <button type="button" className="send" disabled aria-label="Send"><SI n="send" /></button>
        </div>
      </section>

      {/* ---------------------------------------------------------------- right */}
      <section className="ms-col">
        <div className="cys-panel cys-glass cys-hairline">
          <div className="cys-ph"><span className="cys-eyebrow">{isItem ? "In game" : "In world"}</span><span className="cys-tag dim">Approximate</span></div>
          {isItem ? (
            <InGame ed={ed} comps={comps.current} ver={ver} ctx={ctx} setCtx={setCtx} stateId={stateId} setStateId={setStateId} entries={entries} grips={grips} light={light} webgl={webgl} />
          ) : <p className="cys-hint" style={{ margin: "0 14px 12px" }}>{ed.entry.kind === "creature" ? "Creatures are drawn in game by the Nxeon-managed BetterModel plugin from the compiled .bbmodel. Hand and slot contexts apply to held items only." : "A glTF sample mesh: no game context."}</p>}
        </div>
        <div className="cys-panel cys-glass ms-rtabs">
          <div className="cys-tabs" role="tablist">
            {(["checks", "paint", "history"] as const).map((t) => <button key={t} type="button" role="tab" aria-selected={tab === t} className={`cys-tab ${tab === t ? "on" : ""}`} onClick={() => setTab(t)}><SI n={t === "checks" ? "check" : t === "paint" ? "pencil" : "history"} />{t[0].toUpperCase() + t.slice(1)}{t === "history" && <span className="ms-n">{ed.session.at}</span>}</button>)}
          </div>
          <div className="ms-tp">
            {tab === "checks" && <Checks ed={ed} quality={quality} grips={grips} budget={budget} fps={vpRef.current?.fps ?? 0} canEdit={canEdit} access={view.access} mod={mod} />}
            {tab === "paint" && (
              <div className="ms-paint">
                <div className="ms-row"><span>Fill</span><div className="cys-seg sm cys-soft"><button type="button" className={fillMode === "face" ? "on" : ""} onClick={() => setFillMode("face")}>Whole face</button><button type="button" className={fillMode === "area" ? "on" : ""} onClick={() => setFillMode("area")}>Same colour</button></div></div>
                <div className="ms-row"><span>Decal</span><div className="ms-stamps">{STAMPS.map((s2) => <button key={s2} type="button" className={stamp === s2 ? "on" : ""} aria-label={s2} title={s2} onClick={() => { setStamp(s2); setTool("decal"); }}><StampIcon id={s2} /></button>)}</div></div>
                <div className="ms-row"><span>Mirror</span><button type="button" className={`cys-fchip ${mirror ? "on" : ""}`} onClick={() => setMirror((m) => !m)}>{mirror ? "On (X)" : "Off (X)"}</button></div>
                <div className="ms-row"><span>Light</span><div className="cys-seg sm cys-soft">{(Object.keys(LIGHTING_PRESETS) as LightingPreset[]).map((p) => <button key={p} type="button" className={lighting === p ? "on" : ""} onClick={() => setLighting(p)}>{LIGHTING_PRESETS[p].label}</button>)}</div></div>
                <div className="ms-row"><span>Layer</span><b className="ms-mono">{activeL ? `${activeL.name} · ${CHANNEL_LABEL[activeL.channel]}` : "none"}</b></div>
                <p className="cys-hint">Left drag on the model paints; right drag or empty space orbits; wheel zooms; Shift drag pans. B / E / G / I / D tools, X mirror, Ctrl Z / Ctrl Shift Z.</p>
              </div>
            )}
            {tab === "history" && (
              <div className="ms-hist">
                <button type="button" className={`ms-step ${ed.session.at === 0 ? "cur" : ""}`} onClick={() => moveTo((s) => ({ ...s, at: 0 }))}><span className="n">0</span>{ed.fromSaved ? "Opened the saved paint" : "Restored draft / merge"}{ed.session.folded ? ` (+${ed.session.folded} older steps folded)` : ""}</button>
                {ed.session.ops.map((op, i) => <button key={i} type="button" className={`ms-step ${i + 1 === ed.session.at ? "cur" : ""} ${i + 1 > ed.session.at ? "future" : ""}`} onClick={() => moveTo((s) => ({ ...s, at: i + 1 }))}><span className="n">{i + 1}</span>{OP_LABEL[op.t]}{"pts" in op ? ` · ${op.pts.length} px` : ""}</button>)}
              </div>
            )}
          </div>
        </div>
      </section>
    </main>
  );
}

const dedupeSpans = (sp: [number, number, number][]) => { const k = new Set<string>(); return sp.filter((s) => { const key = s.join(","); if (k.has(key)) return false; k.add(key); return true; }); };

function StampIcon({ id }: { id: StampId }) {
  const rows = stampRows(id);
  return <svg viewBox={`0 0 ${rows[0].length} ${rows.length}`} width="18" height="18" aria-hidden="true">{rows.flatMap((r, y) => [...r].map((c, x) => (c === "#" ? <rect key={`${x},${y}`} x={x} y={y} width="1" height="1" fill="currentColor" /> : null)))}</svg>;
}

// ------------------------------------------------------------------------------------------------ UV panel
function UvPanel({ ed, comps, channel, hover, ver }: { ed: Ed; comps: Partial<Record<PaintChannel, Img>>; channel: PaintChannel; hover: Hit | null; ver: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const cv = ref.current, img = channel === "albedo" ? comps.albedo : comps[channel] && channelImage(ed.live, channel as Exclude<ViewMode, "lit" | "ao">, null);
    if (!cv || !img) return;
    const k = Math.max(1, Math.floor(256 / img.w));
    paintRaster(cv, { size: img.w, px: img.px }, k);
    const c = cv.getContext("2d")!;
    const css = getComputedStyle(cv);
    c.strokeStyle = css.getPropertyValue("--uv-line") || "rgba(167,139,250,.35)"; c.lineWidth = 1;
    if (ed.scene.kind !== "mesh") for (const sp of Object.values(ed.scene.regions)) {
      if (!sp.length) continue;
      const y0 = sp[0][0], y1 = sp[sp.length - 1][0] + 1, x0 = Math.min(...sp.map((s) => s[1])), x1 = Math.max(...sp.map((s) => s[2]));
      if (ed.scene.kind === "creature") c.strokeRect(x0 * k + 0.5, y0 * k + 0.5, (x1 - x0) * k - 1, (y1 - y0) * k - 1);
    }
    if (hover) {
      const sp = regionOf(ed.scene, hover);
      if (sp.length && ed.scene.kind === "creature") { const y0 = sp[0][0], y1 = sp[sp.length - 1][0] + 1, x0 = Math.min(...sp.map((s) => s[1])), x1 = Math.max(...sp.map((s) => s[2])); c.strokeStyle = css.getPropertyValue("--uv-hi") || "#a78bfa"; c.lineWidth = 2; c.strokeRect(x0 * k, y0 * k, (x1 - x0) * k, (y1 - y0) * k); }
      c.fillStyle = "#fff"; c.fillRect(hover.texel[0] * k, hover.texel[1] * k, k, k);
    }
  }, [ed, comps, channel, hover, ver]);
  return (
    <div className="ms-uv">
      <div className="ms-uvbox"><canvas ref={ref} aria-label={`The ${CHANNEL_LABEL[channel]} texture`} /></div>
      <p className="cys-hint" style={{ margin: "8px 0 0" }}>Painting on the model writes these pixels. The highlighted rectangle is the face under the brush.</p>
    </div>
  );
}

// ------------------------------------------------------------------------------------------------ in game
function InGame({ ed, comps, ver, ctx, setCtx, stateId, setStateId, entries, grips, light, webgl }: { ed: Ed; comps: Partial<Record<PaintChannel, Img>>; ver: number; ctx: ViewContext; setCtx: (c: ViewContext) => void; stateId: string; setStateId: (s: string) => void; entries: AnyEntry[]; grips: GripCheck[]; light: boolean; webgl: boolean }) {
  const m = ed.entry;
  const ref = useRef<HTMLCanvasElement>(null);
  const vp = useRef<ModelViewport | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (!ref.current || !webgl) return;
    let dead = false;
    ModelViewport.create(ref.current, { mobile: false, light, interactive: false }).then((v) => { if (dead) { v.dispose(); return; } vp.current = v; setReady(true); });
    return () => { dead = true; vp.current?.dispose(); vp.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl]);
  const states = m.kind === "item3d" ? m.preview.states : [];
  const st = states.find((s) => s.id === stateId) ?? states[0];
  // the state's own texture (idle = the live paint; other states = that texture as saved)
  const stateImg = useMemo(() => {
    if (!st || st.texture === m.key) return comps.albedo ?? null;
    const other = entries.find((e) => e.key === st.texture);
    return other && other.kind === "item3d" ? imgOf(renderDoc(other.texture.doc)) : comps.albedo ?? null;
  }, [st, m.key, comps, entries, ver]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    const v = vp.current;
    if (!v || m.kind !== "item3d" || !stateImg || !comps.albedo) return;
    const displays = previewDisplays(m.preview, rasterOf(comps.albedo));
    const full = displays[st?.id ?? "idle"] ?? displays.idle;
    const ref2 = gripReference(m.preview.spec.category, rasterOf(comps.albedo));
    const scene = sceneFromItem(st?.texture ?? m.key, stateImg);
    v.setScene(scene, { albedo: stateImg }, { pixel: true });
    v.setRig(contextRig(ctx, contextTransform(full, ctx), ref2.anchor), light);
  }, [ready, ctx, st, stateImg, ver, light]); // eslint-disable-line react-hooks/exhaustive-deps
  const ctxGrip = grips.filter((g) => g.state === (st?.id ?? "idle") && (ctx === "firstperson" || ctx === "thirdperson") && g.view === ctx)[0];
  const caption: Record<ViewContext, string> = {
    studio: "", gui: "Hotbar slot with the gui transform.", ground: "Dropped, with the ground transform.",
    firstperson: "First person, right hand, the pack's display numbers. The game draws no arm while an item is held; the glove marks where vanilla tools sit.",
    thirdperson: "Third person, right hand, the pack's display numbers. The fist is where the game holds tools.",
    fixed: "In an item frame, with the fixed transform.", head: "Worn on the head, with the head transform.",
    on_shelf: "On a shelf (1.21.9+). Cyrus writes no on_shelf transform, so the game uses none (unverified).",
  };
  return (
    <>
      <div className="ms-ctxs cys-soft" role="tablist" aria-label="Game context">
        {VIEW_CONTEXTS.filter((c) => c.id !== "studio").map((c) => <button key={c.id} type="button" role="tab" aria-selected={ctx === c.id} title={c.hint} className={ctx === c.id ? "on" : ""} onClick={() => setCtx(c.id)}>{c.label}</button>)}
      </div>
      <div className={`ms-ig ${ctx === "gui" ? "gui" : ctx === "firstperson" || ctx === "thirdperson" || ctx === "ground" ? "sky" : "room"}`}>{webgl ? <canvas ref={ref} aria-label={`In game: ${ctx}`} /> : <p className="cys-hint">WebGL is off in this browser.</p>}</div>
      {states.length > 1 && (
        <div className="ms-states"><span className="cys-eyebrow">State</span>
          <div className="cys-seg sm cys-soft">{states.map((s) => <button key={s.id} type="button" className={(st?.id ?? "idle") === s.id ? "on" : ""} onClick={() => setStateId(s.id)}>{s.label}</button>)}</div>
        </div>
      )}
      <p className="cys-hint ms-cap">{caption[ctx]}{ctxGrip ? <> Grip: <b className={ctxGrip.status === "pass" ? "ok" : ctxGrip.status === "warn" ? "warn" : "bad"}>{ctxGrip.distance}/16 block from the hand</b>.</> : null}</p>
    </>
  );
}

// ------------------------------------------------------------------------------------------------ checks
function Checks({ ed, quality, grips, budget, fps, canEdit, access, mod }: { ed: Ed; quality: ReturnType<typeof textureQuality> | null; grips: GripCheck[]; budget: ReturnType<typeof sceneBudget>; fps: number; canEdit: boolean; access: ModelsView["access"]; mod: StudioMod }) {
  const g = gripSummary(grips);
  const fails = (quality?.verdict === "fail" ? 1 : 0) + budget.filter((b) => b.status === "fail").length;
  const warns = (quality?.verdict === "warn" ? 1 : 0) + (g.status === "warn" || g.status === "fail" ? 1 : 0) + budget.filter((b) => b.status === "warn").length;
  const row = (status: string, title: string, value: string, msg: string) => (
    <div className={`ms-gate ${status === "pass" ? "ok" : status === "warn" ? "warn" : status === "fail" ? "bad" : "nr"}`} key={title}>
      <span className="ic"><SI n={status === "pass" ? "check" : status === "not_run" ? "minus" : "warn"} /></span><b>{title}</b><span className="v">{value}</span><span className="m">{msg}</span>
    </div>
  );
  return (
    <div className="ms-checks">
      {!canEdit && (
        <div className="ms-lockcard">
          <SI n="lock" /><div><b>View only on {access.planLabel}</b><p>{(access.edit as { reason?: string }).reason}</p><Link className="cys-btn xs" href={studioHref(mod, "plans", "?studio=texture")}>See plans</Link></div>
        </div>
      )}
      <div className={`ms-ready ${fails ? "bad" : warns ? "warn" : "ok"}`}>
        <span className={`cys-dot ${fails ? "bad" : warns ? "warn" : "ok"}`} /><div><b>{fails ? "Fix before saving" : "Ready to save"}</b><small>{fails ? `${fails} check${fails > 1 ? "s" : ""} fail.` : warns ? `${warns} warning${warns > 1 ? "s" : ""}. Nothing blocks.` : "Every check that ran passes."}</small></div>
      </div>
      {quality && row(quality.verdict, "texture quality", quality.verdict, `The item's composite through the tq-1 bar: ${quality.checks.filter((c) => c.status !== "pass" && c.status !== "not_run").map((c) => c.id).join(", ") || "all checks pass"}.`)}
      {ed.entry.kind === "item3d" && row(g.status, "grip_in_hand", g.worst ? `${g.worst.distance}/16` : "-", g.worst ? `Worst: ${g.worst.state}, ${g.worst.view.replace("person", " person")}${g.worst.advisory ? " (advisory: no arm in first person)" : ""}. Within 1.5/16 of the hand passes; checked against ${gripReference(ed.entry.preview.spec.category).basis}.` : "")}
      {budget.map((b) => row(b.status, b.id, `${b.value.toLocaleString()} / ${b.limit.toLocaleString()}`, b.message))}
      {row(fps ? (fps >= PERF_BUDGET.fpsDesktop * 0.9 ? "pass" : "warn") : "not_run", "frame rate", fps ? `${fps} fps` : "not measured", fps ? "Measured during your last orbit or stroke." : "Orbit the model once to measure.")}
      {ed.prep.profile && row("pass", "channels", "albedo", "Minecraft Java ships albedo only; the other channels are disabled with the reason.")}
      {row("not_run", "real client", "not run", ed.entry.kind === "creature" ? "Painted creature skins are stored as revisions; compiling them into the delivered skin is the next step (not built)." : "Display transforms are approximate until a person checks them in a real client (Test Flight).")}
      <p className="cys-hint" style={{ marginTop: 8 }}>{SCENE_FACES.length && ed.scene.triCount.toLocaleString()} triangles · {ed.live.w}² texture · {ed.live.layers.length} layer{ed.live.layers.length > 1 ? "s" : ""}.</p>
    </div>
  );
}

// ------------------------------------------------------------------------------------------------ fallbacks + narrow
function ServerFallback({ ed, projectId, renderer }: { ed: Ed; projectId: string | null; renderer: string | null }) {
  if (!projectId || !renderer || "sample" in ed.entry) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>This browser cannot show 3D (WebGL is off), and the server preview is not switched on here.</p></div>;
  // eslint-disable-next-line @next/next/no-img-element
  return <img className="ms-fallback" alt={`${ed.key}, server preview`} src={modelApi.previewUrl(projectId, ed.key, { preset: "three_quarter", size: 512, source: "draft" })} />;
}

function Narrow({ mod, view, entries, initialKey, reload }: { mod: StudioMod; view: ModelsView; entries: AnyEntry[]; initialKey: string | null; reload: () => Promise<void> }) {
  const toast = useToast();
  const light = useLight();
  const real = entries.filter((e) => !("sample" in e)) as ModelEntry[];
  const [cur, setCur] = useState(real.find((e) => e.key === initialKey)?.key ?? real[0]?.key ?? null);
  const m = real.find((e) => e.key === cur) ?? null;
  const [draft, setDraft] = useState<DraftView | null | undefined>(undefined);
  const [ctx, setCtx] = useState<ViewContext>("firstperson");
  const [busy, setBusy] = useState(false);
  const [webgl] = useState(() => (typeof window === "undefined" ? true : webglOk()));
  const ref = useRef<HTMLCanvasElement>(null);
  const vp = useRef<ModelViewport | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => { if (!m || !view.project) return; setDraft(undefined); modelApi.getDraft(view.project.id, m.key).then((r) => setDraft(r.draft), () => setDraft(null)); }, [m, view.project]);
  useEffect(() => {
    if (!ref.current || !webgl) return;
    let dead = false;
    ModelViewport.create(ref.current, { mobile: true, light }).then((v) => { if (dead) { v.dispose(); return; } v.readOnly = true; vp.current = v; setReady(true); });
    return () => { dead = true; vp.current?.dispose(); vp.current = null; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl]);
  const ed = useMemo(() => (m ? edFor(m, view.headRevisionId, draft ?? null) : null), [m, draft, view.headRevisionId]);
  useEffect(() => {
    const v = vp.current;
    if (!v || !ed) return;
    const albedo = compositeChannel(ed.live, "albedo", ed.prep.base);
    if (ed.entry.kind === "item3d" && ctx !== "studio") {
      const d = previewDisplays(ed.entry.preview, rasterOf(albedo));
      v.setScene(sceneFromItem(ed.key, albedo), { albedo }, { pixel: true });
      v.setRig(contextRig(ctx, contextTransform(d.idle, ctx), gripReference(ed.entry.preview.spec.category, rasterOf(albedo)).anchor), light);
    } else { v.setRig(null, light); v.setScene(ed.entry.kind === "item3d" ? sceneFromItem(ed.key, albedo) : ed.scene, { albedo }, { pixel: true }); }
  }, [ready, ed, ctx, light]);
  if (!m || !ed) return <main className="ms-narrow"><div className="cys-empty">This mod has no models yet.</div></main>;
  const canEdit = view.access.edit.ok;
  const changed = draft && ed.restored ? paintedCount(ed.live).total - paintedCount(prepare(m).start).total : 0;
  const approve = async () => {
    if (!view.project || !draft || !ed) return;
    setBusy(true);
    try { const r = await modelApi.save(view.project.id, m.key, { doc: docOf(ed), baseAssetId: draft.baseAssetId, expectedHeadId: draft.baseHeadId }); toast(`Approved: revision ${r.seq}`); await reload(); setDraft(null); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const reject = async () => { if (!view.project) return; setBusy(true); try { await modelApi.dropDraft(view.project.id, m.key); toast("Draft discarded"); setDraft(null); } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); } };
  return (
    <main className="ms-narrow">
      {real.length > 1 && <div className="cys-seg sm cys-soft ms-nsel">{real.map((e) => <button key={e.key} type="button" className={e.key === cur ? "on" : ""} onClick={() => setCur(e.key)}>{e.key}</button>)}</div>}
      <div className="cys-panel cys-glass ms-ncard">
        <div className="ms-nh"><span className="ic"><SI n="cube" /></span><div><h1>{m.key}</h1><small>{kindLabel(m)} model · revision {view.revisionSeq[view.headRevisionId ?? ""] ?? "-"}{draft ? " · draft" : ""}</small></div><span className={`cys-tag ${canEdit ? "ok" : "dim"}`}>{canEdit ? "can approve" : "view only"}</span></div>
        <div className="ms-nview">
          <span className="cys-tag ms-nro"><SI n="eye" />Read only</span>
          {webgl ? <canvas ref={ref} aria-label={`3D preview of ${m.key}`} /> : view.project && view.renderer ? /* eslint-disable-next-line @next/next/no-img-element */ <img alt={`${m.key}, server preview`} src={modelApi.previewUrl(view.project.id, m.key, { preset: "three_quarter", size: 512, source: draft ? "draft" : "saved" })} /> : <p className="cys-hint">3D needs WebGL, and the server preview is not switched on here.</p>}
          <span className="cys-hint ms-nhint">Drag to turn</span>
        </div>
        <div className="ms-nsec"><span className="cys-eyebrow">What changed</span>
          <ul className="ms-nlist">{draft === undefined ? <li>Checking for a draft…</li> : draft && ed.restored ? <><li><code>paint</code>{Math.max(0, changed)} px painted in the draft ({ed.live.layers.length} layer{ed.live.layers.length > 1 ? "s" : ""})</li><li><code>model</code>unchanged ({m.kind === "creature" ? `${m.stats.cubes} cubes` : "extruded item"})</li></> : <li>Nothing waiting: paint on a computer, then approve the draft here.</li>}</ul>
        </div>
        {m.kind === "item3d" && <div className="ms-nsec"><span className="cys-eyebrow">In game</span><div className="cys-seg sm cys-soft">{(["firstperson", "thirdperson", "gui"] as ViewContext[]).map((c) => <button key={c} type="button" className={ctx === c ? "on" : ""} onClick={() => setCtx(c)}>{VIEW_CONTEXTS.find((x) => x.id === c)!.label}</button>)}</div></div>}
        <div className="ms-nsec ms-ninfo"><SI n="info" /><span>Preview is approximate. Not verified in a real Minecraft client.</span></div>
        <div className="ms-nact">
          <button type="button" className="cys-btn" disabled={!canEdit || !draft || busy} onClick={reject}>Reject</button>
          <button type="button" className="cys-btn primary" disabled={!canEdit || !draft || busy} onClick={approve}><SI n="check" />Approve revision</button>
        </div>
      </div>
    </main>
  );
}

