input.content:
/* Cyrus Model Studio (Layer 1): viewport + paint. Ported from the v3 mockup ms.css
   (/root/agent-notes/cyrus-designs/v3-model-studio/src/ms.css) onto the studios' own tokens (studios.css .cys). One accent
   (violet); cyan = "now"; green/amber/red = pass/warn/fail. Light theme follows html[data-theme=light]. Every class is ms-*. */
.cys .ms-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 240px minmax(0, 1fr) 330px; gap: 12px; padding: 0 14px 14px; }
.cys .ms-ws.ms-empty { grid-template-columns: 1fr; }
.cys .ms-col { display: flex; flex-direction: column; gap: 12px; min-height: 0; min-width: 0; }
.cys .ms-col.scroll { overflow-y: auto; padding-right: 2px; }
.cys .ms-col.scroll > .cys-panel { flex: none; }
.cys .ms-n { font: 500 10px/1 var(--mono); color: var(--muted); padding: 3px 6px; border-radius: 6px; border: 1px solid var(--line-2); }
.cys .cys-float { border-radius: 12px; background: var(--surface-soft); border: 1px solid var(--line); box-shadow: 0 10px 30px -18px rgb(0 0 0 / .7); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }
html[data-theme="light"] .cyrus-root .cys .cys-float { box-shadow: 0 10px 30px -20px rgb(76 29 149 / .35); }
.cys .ms-mono { font: 500 10.5px/1 var(--mono); color: var(--muted); white-space: nowrap; }

/* left: models, uv, layers */
.cys .ms-list { padding: 0 8px 8px; display: flex; flex-direction: column; gap: 2px; }
.cys .ms-mrow { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--r); color: var(--ink-2); width: 100%; text-align: left; }
.cys .ms-mrow:hover { background: rgb(var(--glow) / .07); }
.cys .ms-mrow.on { background: rgb(var(--glow) / .13); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); color: var(--ink); }
.cys .ms-mrow .tx { flex: 1; min-width: 0; }
.cys .ms-mrow .tx b { display: block; font: 500 12px/1.2 var(--mono); color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .ms-mrow .tx small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .ms-mrow .th3 { width: 34px; height: 34px; border-radius: 9px; flex: none; display: grid; place-items: center; font-size: 16px; color: var(--accent-ink); background: radial-gradient(circle at 50% 40%, rgb(var(--glow) / .16), var(--well) 70%); border: 1px solid var(--line); overflow: hidden; }
.cys .ms-mrow .th3 canvas.pix { width: 26px; height: 26px; image-rendering: pixelated; }
.cys .ms-uv { padding: 0 12px 10px; }
.cys .ms-uvbox { --uv-line: rgba(167, 139, 250, .38); --uv-hi: #a78bfa; position: relative; aspect-ratio: 1 / 1; border-radius: 10px; border: 1px solid var(--line); background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 10px 10px; overflow: hidden; }
html[data-theme="light"] .cyrus-root .cys .ms-uvbox { --uv-line: rgba(91, 33, 182, .35); --uv-hi: #7c3aed; }
.cys .ms-uvbox canvas { position: absolute; inset: 0; width: 100%; height: 100%; image-rendering: pixelated; }
.cys .ms-add { height: 24px; border-radius: 7px; border: 1px solid var(--line-2); background: var(--well); color: var(--ink-2); font-size: 11.5px; padding: 0 6px; }
.cys .ms-layers { padding: 0 10px 10px; }
.cys .ms-lay { display: flex; align-items: center; gap: 6px; padding: 5px 6px; border-radius: var(--r); border: 1px solid var(--line); background: var(--well); margin-bottom: 5px; font-size: 12px; color: var(--ink-2); }
.cys .ms-lay.on { border-color: var(--accent-line); background: var(--accent-soft); color: var(--ink); }
.cys .ms-lay.off { opacity: .55; }
.cys .ms-lay.locked { border-style: dashed; }
.cys .ms-lay .grow { flex: 1; min-width: 0; text-align: left; }
.cys .ms-lay .grow b { display: block; font-weight: 500; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .ms-lay .grow small { display: block; font: 400 10px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .ms-layprops { display: grid; gap: 6px; padding: 6px 2px 2px; }
.cys .ms-layprops label { display: grid; grid-template-columns: 54px 1fr auto; align-items: center; gap: 8px; font-size: 11.5px; color: var(--muted); }
.cys .ms-layprops label b { font: 500 10.5px/1 var(--mono); color: var(--ink); min-width: 32px; text-align: right; }
.cys .ms-layprops input[type=range] { width: 100%; accent-color: var(--accent-solid); }
.cys .ms-layprops .cys-field { height: 26px; font-size: 11.5px; grid-column: 2 / 4; }

/* centre: header, viewport, palette, dock */
.cys .ms-hdr { display: flex; align-items: center; gap: 10px; padding: 9px 10px 9px 12px; flex: none; flex-direction: row; }
.cys .ms-hdr .ic { color: var(--accent-ink); display: flex; font-size: 16px; }
.cys .ms-hdr .nm { font: 500 13px/1 var(--mono); color: var(--ink); white-space: nowrap; }
.cys .ms-hdr .sp { flex: 1; }
.cys .ms-pill { font: 500 10.5px/1 var(--mono); color: var(--muted); padding: 4px 7px; border-radius: 6px; border: 1px solid var(--line-2); white-space: nowrap; }
.cys .ms-saved { display: inline-flex; align-items: center; gap: 6px; font: 500 10.5px/1 var(--mono); color: var(--muted); white-space: nowrap; }
.cys .ms-note { display: flex; align-items: center; gap: 10px; padding: 8px 10px 8px 12px; border-radius: 12px; border-style: dashed; border-color: var(--accent-line); font-size: 12px; color: var(--ink-2); flex: none; }
.cys .ms-note > svg { color: var(--accent-ink); }
.cys .ms-note .sp { flex: 1; }
.cys .ms-vp { position: relative; flex: 1; min-height: 0; border-radius: var(--r-lg); overflow: hidden; }
.cys .ms-vp::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(120% 90% at 50% 40%, rgb(var(--glow) / .10), transparent 62%), radial-gradient(60% 50% at 80% 100%, rgb(103 232 249 / .05), transparent 70%); }
html[data-theme="light"] .cyrus-root .cys .ms-vp::before { background: radial-gradient(120% 90% at 50% 40%, rgb(124 58 237 / .06), transparent 62%); }
.cys .ms-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.cys .ms-cv.paint { cursor: crosshair; } .cys .ms-cv.orbit { cursor: grab; }
.cys .ms-fallback { position: absolute; inset: 0; margin: auto; max-width: 100%; max-height: 100%; object-fit: contain; }
.cys .ms-tools { position: absolute; left: 10px; top: 58px; z-index: 2; display: flex; flex-direction: column; gap: 2px; padding: 4px; }
.cys .ms-tools .cys-ib { width: 32px; height: 32px; font-size: 16px; position: relative; }
.cys .ms-tools .cys-ib.on { color: var(--on-accent); background: var(--accent-solid); box-shadow: 0 6px 16px -8px rgb(124 77 255 / .9); }
.cys .ms-tools .cys-ib.tog.on { color: var(--accent-ink); background: var(--accent-soft); box-shadow: inset 0 0 0 1px var(--accent-line); }
.cys .ms-tools .cys-sep { width: 22px; margin: 3px auto; }
.cys .ms-tools .cys-ib[data-tip]:hover::after { content: attr(data-tip); position: absolute; left: 40px; top: 50%; transform: translateY(-50%); white-space: pre; padding: 5px 8px; border-radius: 7px; background: var(--solid); box-shadow: var(--pop-shadow); font: 500 11.5px/1 var(--font-inter), sans-serif; color: var(--ink); z-index: 4; }
.cys .ms-vpbar, .cys .ms-vpfoot { position: absolute; left: 10px; right: 10px; display: flex; align-items: center; gap: 8px; z-index: 2; pointer-events: none; }
.cys .ms-vpbar { top: 10px; } .cys .ms-vpfoot { bottom: 10px; align-items: flex-end; }
.cys .ms-vpbar > *, .cys .ms-vpfoot > * { pointer-events: auto; }
.cys .ms-vpbar .sp { flex: 1; pointer-events: none; }
.cys .ms-stat { display: inline-flex; align-items: center; gap: 6px; font: 500 10.5px/1 var(--mono); color: var(--muted); padding: 7px 9px; white-space: nowrap; margin-left: 52px; }
.cys .ms-stat b { color: var(--ink-2); font-weight: 500; }
.cys .ms-chan { display: inline-flex; padding: 3px; gap: 2px; flex-wrap: wrap; }
.cys .ms-chan button { height: 26px; padding: 0 9px; border-radius: 8px; font-size: 11.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
.cys .ms-chan button:hover:not(:disabled) { color: var(--ink); }
.cys .ms-chan button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .3); }
.cys .ms-chan button:disabled { color: var(--faint); cursor: not-allowed; text-decoration: line-through; text-decoration-color: color-mix(in srgb, var(--faint) 60%, transparent); }
.cys .ms-chan .lab { font: 600 9px/1 var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--faint); padding: 0 6px 0 4px; display: inline-flex; align-items: center; }
.cys .ms-ro { position: absolute; top: 56px; left: 50%; transform: translateX(-50%); z-index: 3; background: var(--surface-soft); }
.cys .ms-tip { position: absolute; z-index: 3; pointer-events: none; font: 500 10.5px/1 var(--mono); padding: 5px 7px; border-radius: 7px; background: var(--solid); color: var(--ink-2); border: 1px solid var(--line-2); white-space: nowrap; }
.cys .ms-tip b { color: var(--ink); font-weight: 500; }
.cys .ms-ring { position: absolute; z-index: 2; pointer-events: none; border-radius: 4px; box-shadow: 0 0 0 1.5px var(--solid), 0 0 0 3px var(--accent); }
.cys .ms-pal { flex: none; flex-direction: row; display: flex; align-items: center; gap: 12px; padding: 9px 12px; border-radius: var(--r-lg); flex-wrap: wrap; }
.cys .ms-pal .sws { display: flex; gap: 3px; align-items: center; }
.cys .ms-pal .sws > button { width: 24px; height: 24px; border-radius: 6px; box-shadow: inset 0 0 0 1px rgb(255 255 255 / .1); }
.cys .ms-pal .sws > button.on { box-shadow: 0 0 0 2px var(--solid), 0 0 0 4px var(--accent); }
.cys .ms-pal .vr { width: 1px; height: 24px; background: var(--line-2); }
.cys .ms-pal .sp { flex: 1; }
.cys .ms-cpick { position: relative; width: 24px; height: 24px; border-radius: 6px; overflow: hidden; cursor: pointer; box-shadow: inset 0 0 0 1px var(--line-3); background: conic-gradient(red, yellow, lime, cyan, blue, magenta, red); }
.cys .ms-cpick span { position: absolute; inset: 6px; border-radius: 3px; box-shadow: 0 0 0 1px rgb(0 0 0 / .4); }
.cys .ms-cpick input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.cys .ms-dock { opacity: .8; }
.cys .ms-dock input:disabled { cursor: not-allowed; }

/* right: in game, tabs */
.cys .ms-ctxs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px; padding: 3px; margin: 0 12px 8px; border-radius: 11px; }
.cys .ms-ctxs button { height: 26px; border-radius: 8px; font-size: 11px; color: var(--muted); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0 4px; }
.cys .ms-ctxs button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
.cys .ms-ig { position: relative; height: 196px; margin: 0 12px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); }
.cys .ms-ig canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.cys .ms-ig.sky { background: linear-gradient(180deg, #1b2350 0%, #2b2a5c 62%, #2e4a2c 62.5%, #1d321c 100%); }
.cys .ms-ig.gui { background: radial-gradient(circle at 50% 50%, #241a48, #0b0718 75%); }
.cys .ms-ig.room { background: linear-gradient(180deg, #2a2340, #17122a); }
html[data-theme="light"] .cyrus-root .cys .ms-ig.sky { background: linear-gradient(180deg, #cfe3f7 0%, #e8f0fa 62%, #8bb36b 62.5%, #6e9452 100%); }
html[data-theme="light"] .cyrus-root .cys .ms-ig.gui { background: radial-gradient(circle at 50% 50%, #f1ecfb, #d9d2ee 80%); }
html[data-theme="light"] .cyrus-root .cys .ms-ig.room { background: linear-gradient(180deg, #ece6f8, #d8cfee); }
.cys .ms-states { display: flex; align-items: center; gap: 8px; padding: 8px 12px 0; }
.cys .ms-cap { margin: 8px 14px 12px; }
.cys .ms-cap b.ok { color: var(--ok); } .cys .ms-cap b.warn { color: var(--warn); } .cys .ms-cap b.bad { color: var(--bad); }
.cys .ms-rtabs { flex: 1; min-height: 0; }
.cys .ms-rtabs .cys-tab .ms-n { margin-left: 2px; }
.cys .ms-tp { flex: 1; min-height: 0; overflow-y: auto; padding: 10px 12px 12px; }
.cys .ms-ready { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border-radius: var(--r-md); border: 1px solid var(--line-2); background: var(--well); margin-bottom: 6px; }
.cys .ms-ready .cys-dot { margin-top: 5px; }
.cys .ms-ready b { display: block; font-size: 12.5px; color: var(--ink); } .cys .ms-ready small { display: block; font-size: 11.5px; color: var(--muted); margin-top: 2px; }
.cys .ms-gate { display: grid; grid-template-columns: 18px 1fr auto; gap: 2px 10px; padding: 8px 0; border-bottom: 1px solid var(--line); align-items: start; }
.cys .ms-gate:last-of-type { border-bottom: 0; }
.cys .ms-gate .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; }
.cys .ms-gate.ok .ic { color: var(--ok); background: var(--ok-soft); } .cys .ms-gate.warn .ic { color: var(--warn); background: var(--warn-soft); } .cys .ms-gate.bad .ic { color: var(--bad); background: var(--bad-soft); } .cys .ms-gate.nr .ic { color: var(--faint); box-shadow: inset 0 0 0 1px var(--line-2); }
.cys .ms-gate b { font: 500 11.5px/1.3 var(--mono); color: var(--ink); } .cys .ms-gate .v { font: 500 10.5px/1.3 var(--mono); color: var(--muted); text-align: right; }
.cys .ms-gate .m { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.4; }
.cys .ms-lockcard { display: flex; gap: 10px; padding: 10px 12px; border-radius: var(--r-md); border: 1px solid var(--accent-line); background: var(--accent-soft); margin-bottom: 8px; font-size: 12px; color: var(--ink-2); }
.cys .ms-lockcard > svg { color: var(--accent-ink); font-size: 16px; flex: none; margin-top: 2px; }
.cys .ms-lockcard b { color: var(--ink); } .cys .ms-lockcard p { margin: 3px 0 8px; }
.cys .ms-paint { display: flex; flex-direction: column; gap: 10px; }
.cys .ms-row { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--muted); flex-wrap: wrap; }
.cys .ms-row > span:first-child { width: 48px; flex: none; }
.cys .ms-stamps { display: flex; gap: 4px; }
.cys .ms-stamps button { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--ink-2); border: 1px solid var(--line-2); }
.cys .ms-stamps button.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .ms-hist { display: flex; flex-direction: column; gap: 2px; }
.cys .ms-step { display: flex; align-items: center; gap: 8px; width: 100%; padding: 6px 8px; border-radius: 8px; font-size: 12px; color: var(--ink-2); text-align: left; }
.cys .ms-step:hover { background: rgb(var(--glow) / .07); }
.cys .ms-step .n { font: 500 10px/1 var(--mono); color: var(--faint); width: 22px; }
.cys .ms-step.cur { color: var(--ink); background: rgb(var(--glow) / .1); } .cys .ms-step.cur .n { color: var(--accent-ink); }
.cys .ms-step.future { opacity: .45; }

/* narrow: read-only preview + approve */
.cys .ms-narrow { display: block; padding: 0 14px 28px; overflow-y: auto; flex: 1; }
.cys .ms-nsel { margin: 0 0 10px; overflow-x: auto; max-width: 100%; }
.cys .ms-ncard { border-radius: var(--r-xl); overflow: hidden; }
.cys .ms-nh { display: flex; align-items: center; gap: 12px; padding: 14px; }
.cys .ms-nh .ic { width: 44px; height: 44px; border-radius: 12px; display: grid; place-items: center; font-size: 20px; color: var(--ink-2); border: 1px solid var(--line-2); flex: none; }
.cys .ms-nh h1 { margin: 0; font: 600 17px/1.2 var(--font-inter), sans-serif; color: var(--ink); }
.cys .ms-nh small { display: block; font-size: 12px; color: var(--muted); margin-top: 3px; }
.cys .ms-nh > div { flex: 1; min-width: 0; }
.cys .ms-nview { position: relative; height: 250px; border-top: 1px solid var(--line); background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / .16), transparent 70%); }
.cys .ms-nview canvas, .cys .ms-nview img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; touch-action: none; }
.cys .ms-nview .ms-nro { position: absolute; top: 10px; left: 12px; z-index: 2; }
.cys .ms-nview .ms-nhint { position: absolute; bottom: 8px; left: 0; right: 0; text-align: center; pointer-events: none; }
.cys .ms-nsec { padding: 12px 14px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 8px; }
.cys .ms-nlist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--ink-2); }
.cys .ms-nlist li { display: flex; gap: 8px; } .cys .ms-nlist li code { font: 500 11px/1.5 var(--mono); color: var(--accent-ink); flex: none; width: 44px; }
.cys .ms-ninfo { flex-direction: row; align-items: flex-start; font-size: 13px; color: var(--ink-2); } .cys .ms-ninfo > svg { flex: none; margin-top: 2px; }
.cys .ms-nact { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; padding: 12px 14px 14px; border-top: 1px solid var(--line); }
.cys .ms-nact .cys-btn { height: 40px; }
@media (max-width: 1180px) { .cys .ms-ws { grid-template-columns: 210px minmax(0, 1fr) 290px; } .cys .ms-stat { display: none; } }
@media (max-width: 760px) { .cys .ms-ws { display: none; } }

