    s=s.replace('import { studioContext } from "../../../studio-shared";','import { studioContext } from "../../../studio-shared";\nimport { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";')
    s=s.replace(f'return <{comp} mod={{mod}} ', f'const showModel = !!(await modelStudioViewer().catch(() => null));\n  return <{comp} mod={{mod}} showModel={{showModel}} ')
    open(p,'w').write(s)
p=base+'components/cyrus/studios/TextureStudio.tsx'; s=open(p).read()
s=s.replace('export function TextureStudio({ mod, initialKey }: { mod: StudioMod; initialKey: string | null }) {\n  return (\n    <StudioShell mod={mod} current="Texture Studio" studio="texture">','export function TextureStudio({ mod, initialKey, showModel = false }: { mod: StudioMod; initialKey: string | null; showModel?: boolean }) {\n  return (\n    <StudioShell mod={mod} current="Texture Studio" studio="texture" showModel={showModel}>')
open(p,'w').write(s)
p=base+'components/cyrus/studios/SoundStudio.tsx'; s=open(p).read()
s=s.replace('export function SoundStudio({ mod, initialSet, initialEvent }: { mod: StudioMod; initialSet: string | null; initialEvent: string | null }) {','export function SoundStudio({ mod, initialSet, initialEvent, showModel = false }: { mod: StudioMod; initialSet: string | null; initialEvent: string | null; showModel?: boolean }) {')
s=s.replace('<StudioShell mod={mod} current="Sound Studio" studio="sound">','<StudioShell mod={mod} current="Sound Studio" studio="sound" showModel={showModel}>')
open(p,'w').write(s)
