// Cyrus v2 screenshot harness (throwaway DB + local mock service on :7399, dev on :3149).
// usage: node shot.mjs <name> <path>
// env: ROUND=r1 VIEWS=desktop,wide,mobile THEMES=dark,light WAIT=ms FRAMES=n FRAMEGAP=ms ACT='async (page, view) => {}' RM=reduce
// Writes /root/agent-notes/cyrus-v2/<ROUND>/<name>-<view>[-light][-fNN].png
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const [, , name, path] = process.argv;
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? "/tank/nxeon-wt-cyrus/.cyrus-local/tokens.json", "utf8"));
const BASE = process.env.BASE ?? "http://localhost:3149";
const OUT = `/root/agent-notes/cyrus-v2/${process.env.ROUND ?? "r1"}`;
mkdirSync(OUT, { recursive: true });
const VIEWS = (process.env.VIEWS ?? "desktop").split(",");
const THEMES = (process.env.THEMES ?? "dark").split(",");
const views = { desktop: { width: 1440, height: 900, mobile: false }, wide: { width: 1920, height: 1080, mobile: false }, tablet: { width: 1024, height: 900, mobile: false }, mobile: { width: 390, height: 844, mobile: true } };
const browser = await chromium.launch({ args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream", "--enable-gpu-rasterization", "--ignore-gpu-blocklist"] });
for (const vt of VIEWS) for (const theme of THEMES) {
  const v = views[vt];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme, reducedMotion: process.env.RM ?? "no-preference", permissions: ["microphone", "clipboard-read", "clipboard-write"] });
  await ctx.addCookies([{ name: tok.cookie, value: tok[process.env.TOK ?? "ownerTok"], url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyDebug", "1"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 240000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Close"]) {
    const b = page.getByRole("button", { name: label, exact: true });
    if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {});
  }
  if (process.env.ACT) { try { await eval(process.env.ACT)(page, vt); } catch (e) { errs.push("act " + e); } }
  await page.waitForTimeout(Number(process.env.WAIT ?? 3000));
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  const base = `${OUT}/${name}-${vt}${theme === "light" ? "-light" : ""}`;
  const frames = Number(process.env.FRAMES ?? 0);
  if (frames) {
    for (let i = 0; i < frames; i++) { await page.screenshot({ path: `${base}-f${String(i).padStart(2, "0")}.png` }); await page.waitForTimeout(Number(process.env.FRAMEGAP ?? 250)); }
  }
  await page.screenshot({ path: `${base}.png`, fullPage: process.env.FULL === "1" });
  if (process.env.FPS) {
    const fps = await page.evaluate(() => new Promise((r) => { let n = 0; const t0 = performance.now(); const f = () => { n++; if (performance.now() - t0 < 2000) requestAnimationFrame(f); else r(Math.round(n / ((performance.now() - t0) / 1000))); }; requestAnimationFrame(f); }));
    console.log("fps", fps);
  }
  console.log(`${base}.png`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 700) : "");
  await ctx.close();
}
await browser.close();
