// Cyrus Model Studio: the node-2 server preview renderer (headless Chromium + three.js on SwiftShader) against
// GOLDEN IMAGES. Runs only where Playwright's Chromium is installed (node-2; `devhost test`); elsewhere every case is
// skipped with the reason. Tolerance (plan section 5): at most 0.5 % of pixels off by more than 2/255.
// Regenerate after an intended look change: UPDATE_MODELSTUDIO_GOLDEN=1 devhost test test/cyrus-modelstudio-render.test.ts
// then `devhost pull test/fixtures/cyrus-modelstudio` and look at every PNG before committing it.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { checkRigSpec } from "../lib/cyrus/creature/spec";
import { layoutSkin, skinTextureSpec } from "../lib/cyrus/creature/compile";
import { render } from "../lib/cyrus/textures/render";
import { GLOCK } from "../lib/cyrus/textures/sample-glock";
import { gripPoint } from "../lib/cyrus/textures/display";
import { stateDisplays } from "../lib/cyrus/itemmodel/emit";
import { sceneFromItem, sceneFromRig, type Img } from "../lib/cyrus/modelstudio/scene";
import { contextRig, contextTransform, gripReference } from "../lib/cyrus/modelstudio/contexts";
import { previewRequest, type PreviewRequest } from "../lib/cyrus/modelstudio/preview/types";
import { playwrightRenderer } from "../lib/cyrus/modelstudio/preview/playwright";
import { compareRasters, decodePreviewPng, GOLDEN_TOLERANCE } from "../lib/cyrus/modelstudio/preview/golden";

const FX = path.join(__dirname, "fixtures");
const GOLD = path.join(FX, "cyrus-modelstudio");
const UPDATE = process.env.UPDATE_MODELSTUDIO_GOLDEN === "1";
const imgOf = (r: { size: number; px: Uint8ClampedArray }): Img => ({ w: r.size, h: r.size, px: r.px });

function cases(): { name: string; req: PreviewRequest }[] {
  const c = checkRigSpec(JSON.parse(fs.readFileSync(path.join(FX, "cyrus-creatures", "banshee.json"), "utf8")));
  if (!c.ok) throw new Error(c.error);
  const lay = layoutSkin(c.spec); if (!lay.ok) throw new Error(lay.error);
  const banshee = sceneFromRig(c.spec, lay.layout);
  const skin = imgOf(render(skinTextureSpec(c.spec, lay.layout)));
  const gl = render(GLOCK), glImg = imgOf(gl);
  const item = sceneFromItem("glock_9mm", glImg, gripPoint(gl, "handgun"));
  const disp = stateDisplays({ schemaVersion: 1, name: "glock_9mm", category: "gun" }, gl);
  const rig = contextRig("thirdperson", contextTransform(disp.idle, "thirdperson"), gripReference("gun", gl).anchor);
  return [
    { name: "banshee-three_quarter", req: previewRequest(banshee, { albedo: skin }, { preset: "three_quarter", size: 256 }) },
    { name: "banshee-back", req: previewRequest(banshee, { albedo: skin }, { preset: "back", size: 256 }) },
    { name: "glock-studio", req: previewRequest(item, { albedo: glImg }, { preset: "three_quarter", size: 256 }) },
    { name: "glock-thirdperson", req: previewRequest(item, { albedo: glImg }, { preset: "front", size: 256, model: rig.model, cam: { ...rig.cam, proj: rig.proj } }) },
  ];
}

describe("server preview renderer: golden images (node-2)", () => {
  const renderer = playwrightRenderer({ timeoutMs: 90_000 });
  let skip: string | null = null;
  it("renders a creature deterministically, inside the time budget", async (t) => {
    const [c] = cases();
    const a = await renderer.render(c.req);
    if (!a.ok && (a.code === "unavailable" || /Executable doesn't exist|browserType\.launch/i.test(a.error))) { skip = a.error; t.skip(`no Chromium here: ${a.error.slice(0, 120)}`); return; }
    assert.ok(a.ok, !a.ok ? `${a.code}: ${a.error}` : "");
    if (!a.ok) return;
    console.log(`  render ${c.name}: ${a.ms} ms, ${a.png.length} bytes`);
    assert.ok(a.ms < 60_000, `took ${a.ms} ms`);
    const b = await renderer.render(c.req);
    assert.ok(b.ok);
    if (!b.ok) return;
    const ra = decodePreviewPng(a.png, 256)!, rb = decodePreviewPng(b.png, 256)!;
    const d = compareRasters(ra, rb, { channel: 0, maxFraction: 0 });
    console.log(`  same input twice: ${d.off} pixels differ (max delta ${d.maxDelta})`);
    assert.ok(compareRasters(ra, rb).ok, "two renders of the same input agree within the golden tolerance");
    // not blank: the model covers a good part of the frame
    let fg = 0; for (let i = 0; i < 256 * 256; i++) if (Math.abs(ra.px[i * 4] - 18) + Math.abs(ra.px[i * 4 + 1] - 14) + Math.abs(ra.px[i * 4 + 2] - 38) > 24) fg++;
    assert.ok(fg > 256 * 256 * 0.08, `foreground ${fg} px`);
  });
  for (const name of ["banshee-three_quarter", "banshee-back", "glock-studio", "glock-thirdperson"]) {
    it(`matches the golden image: ${name}`, async (t) => {
      if (skip) { t.skip(skip.slice(0, 120)); return; }
      const c = cases().find((x) => x.name === name)!;
      const r = await renderer.render(c.req);
      if (!r.ok && r.code === "unavailable") { t.skip(r.error); return; }
      assert.ok(r.ok, !r.ok ? `${r.code}: ${r.error}` : "");
      if (!r.ok) return;
      const file = path.join(GOLD, `golden-${name}.png`);
      if (UPDATE || !fs.existsSync(file)) {
        if (!UPDATE) assert.fail(`no golden image ${path.basename(file)}: run with UPDATE_MODELSTUDIO_GOLDEN=1 and review it`);
        fs.mkdirSync(GOLD, { recursive: true }); fs.writeFileSync(file, r.png); console.log(`  wrote ${file}`); return;
      }
      const want = decodePreviewPng(fs.readFileSync(file), 256)!, got = decodePreviewPng(r.png, 256)!;
      const d = compareRasters(got, want, GOLDEN_TOLERANCE);
      console.log(`  ${name}: ${(d.fraction * 100).toFixed(3)} % pixels off by > ${GOLDEN_TOLERANCE.channel}/255 (max delta ${d.maxDelta}), ${r.ms} ms`);
      assert.ok(d.ok, `${(d.fraction * 100).toFixed(3)} % of pixels differ (limit ${GOLDEN_TOLERANCE.maxFraction * 100} %)`);
    });
  }
  it("refuses a request over budget before launching anything", async () => {
    const [c] = cases();
    const r = await renderer.render({ ...c.req, triCount: 200_000 });
    assert.equal(r.ok, false);
    if (!r.ok) assert.equal(r.code, "bad_request");
  });
});

