// Cyrus Model Studio: extend the devhost studio fixtures (scripts/cyrus/studio-fixtures.ts, run that first) with what
// Model Studio paints: the Banshee creature (a real RigSpec row, as a build's asset sync records it) for the All models
// and Saka accounts, a saved paint session on the creature and on the pistol (through the real save path), and an
// autosaved draft on the pistol (the phone's approve view). Refuses anything but devhost's wt_* database.
//   devhost run -- npx tsx scripts/cyrus/modelstudio-fixtures.ts
import fs from "node:fs";
import path from "node:path";
import { db } from "../../lib/db";
import { canonicalJson, sha256Hex } from "../../lib/cyrus/assets/textures";
import { addRevision, recordAsset } from "../../lib/cyrus/engine-core/store";
import { RIG_SPEC_MIME } from "../../lib/cyrus/creature/portal";
import { chainOf, prismaModelDraftStore, prismaStudioStore } from "../../lib/cyrus/studios/store-prisma";
import { modelsView, saveModel, type ModelServiceDeps } from "../../lib/cyrus/modelstudio/service";
import { encodeLayers, startLayers, type ModelDoc } from "../../lib/cyrus/modelstudio/doc";
import { replay, type Op } from "../../lib/cyrus/modelstudio/paint";
import { encodePixels } from "../../lib/cyrus/modelstudio/layers";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const RAW = JSON.parse(fs.readFileSync(path.join(process.cwd(), "test/fixtures/cyrus-creatures/banshee.json"), "utf8"));

async function addCreature(userId: string) {
  const build = await db.modBuild.findFirst({ where: { userId, rootBuildId: null }, orderBy: { createdAt: "asc" } });
  if (!build) throw new Error(`no studio fixture for ${userId}: run scripts/cyrus/studio-fixtures.ts first`);
  const project = (await db.cyrusProject.findUnique({ where: { rootBuildId: build.id } }))!;
  const sha = sha256Hex(canonicalJson(RAW));
  const rev = await addRevision(project.id, { kind: "generated", status: "passed", modBuildId: build.id, expectedHeadId: project.headRevisionId, message: "animated creature banshee", manifest: [{ path: "assets/creatures/banshee.json", sha256: sha, role: "asset" }] });
  await recordAsset(project.id, { revisionId: rev.id, assetKey: "banshee", kind: "model", sha256: sha, size: canonicalJson(RAW).length, origin: "generated", mime: RIG_SPEC_MIME, path: "assets/creatures/banshee.json", provenance: { generator: "cyrus-rigspec", compiler: "rig-c1", spec: RAW, modBuildId: build.id, kept: false } });
  return { build, project };
}

(async () => {
  await db.setting.upsert({ where: { key: "cyrus_model_studio_enabled" }, update: { value: "false" }, create: { key: "cyrus_model_studio_enabled", value: "false" } });
  for (const u of ["usr_studio_saka", "usr_studio_katara", "usr_studio_unknown"]) await addCreature(u);
  const { build, project } = await addCreature("usr_studio_all");
  const deps: ModelServiceDeps = { store: prismaStudioStore, planOf: async () => "all", chain: chainOf, deliveryOn: () => false, drafts: prismaModelDraftStore, renderer: () => null };
  const v = await modelsView(deps, "usr_studio_all", build.id);
  const banshee = v.models.find((m) => m.key === "banshee");
  const glock = v.models.find((m) => m.key === "glock_9mm");
  if (!banshee || banshee.kind !== "creature" || !glock || glock.kind !== "item3d") throw new Error("models missing");
  // 1. the creature: a worn hem on the robe + a ring decal on the chest (front = north faces)
  const n = banshee.layout.size;
  const front = (bone: string) => banshee.layout.cubes.find((c) => c.bone === bone)?.faces.north;
  const body = front("body") ?? banshee.layout.cubes[0].faces.north, head = front("head") ?? banshee.layout.cubes[0].faces.north;
  const ring = new Uint8ClampedArray(5 * 5 * 4);
  [".###.", "#...#", "#...#", "#...#", ".###."].forEach((r, y) => [...r].forEach((c, x) => { if (c === "#") ring.set([167, 139, 250, 255], (y * 5 + x) * 4); }));
  const ops: Op[] = [
    { t: "brush", layer: "paint", color: [196, 205, 230], size: 1, shape: "square", pts: Array.from({ length: body.w }, (_, i) => [body.x + i, body.y + body.h - 2] as [number, number]).filter((_, i) => i % 3 !== 1) },
    { t: "decal", layer: "paint", x: body.x + Math.floor(body.w / 2) - 2, y: body.y + 2, stamp: { w: 5, h: 5, rle: encodePixels(ring) } },
    { t: "brush", layer: "paint", color: [124, 77, 255], size: 1, shape: "square", pts: [[head.x + 2, head.y + 3], [head.x + head.w - 3, head.y + 3]] },
  ];
  const cl = replay(startLayers(null, n, n), ops);
  const cdoc: ModelDoc = { v: 1, kind: "creature", name: "banshee", base: { type: "rigspec", assetId: banshee.assetId, sha256: banshee.sha256, spec: RAW }, tex: { w: n, h: n }, layers: encodeLayers(cl), symmetry: "none" };
  const r1 = await saveModel(deps, { userId: "usr_studio_all", projectId: project.id, key: "banshee", doc: cdoc, baseAssetId: null, expectedHeadId: v.headRevisionId, log: ops });
  // 2. the pistol: a worn silver edge along the top of the slide (the mockup's 51 px "worn edge")
  const head2 = (await db.cyrusProject.findUnique({ where: { id: project.id } }))!.headRevisionId;
  const edge: [number, number][] = [];
  for (let x = 5; x < 28; x++) if (x % 4 !== 2) edge.push([x, 9]);
  for (let x = 8; x < 27; x += 3) edge.push([x, 10]);
  const gops: Op[] = [{ t: "brush", layer: "paint", color: [201, 204, 214], size: 1, shape: "square", pts: edge }];
  const gl = replay(startLayers(null, 32, 32), gops);
  const gdoc: ModelDoc = { v: 1, kind: "item3d", name: "glock_9mm", base: { type: "texture", key: "glock_9mm", assetId: glock.texture.assetId, sha256: "0".repeat(64) }, tex: { w: 32, h: 32 }, layers: encodeLayers(gl), symmetry: "none" };
  const r2 = await saveModel(deps, { userId: "usr_studio_all", projectId: project.id, key: "glock_9mm", doc: gdoc, baseAssetId: glock.texture.assetId, expectedHeadId: head2, log: gops });
  // 3. an autosaved draft on the pistol: the orange front sight brightened + grip wear (waiting for approval)
  const v3 = await modelsView(deps, "usr_studio_all", build.id);
  const g3 = v3.models.find((m) => m.key === "glock_9mm");
  if (!g3 || g3.kind !== "item3d") throw new Error("glock missing");
  const start = startLayers(g3.paint?.doc ?? null, 32, 32);
  const dl = replay(start, [{ t: "brush", layer: "paint", color: [255, 176, 64], size: 1, shape: "square", pts: [[27, 8], [26, 8]] }, { t: "brush", layer: "paint", color: [80, 85, 94], size: 1, shape: "square", pts: [[7, 20], [8, 22], [9, 24], [10, 26]] }]);
  const ddoc: ModelDoc = { ...gdoc, base: { ...gdoc.base, assetId: g3.texture.assetId } as ModelDoc["base"], layers: encodeLayers(dl) };
  await prismaModelDraftStore.put({ projectId: project.id, ownerRef: "usr_studio_all", assetKey: "glock_9mm", baseAssetId: g3.texture.assetId, baseHeadId: v3.headRevisionId, doc: ddoc });
  console.log(JSON.stringify({ buildId: build.id, projectId: project.id, creatureRevision: r1.seq, itemRevision: r2.seq, itemLogVerified: r2.logVerified, creatureLogVerified: r1.logVerified }));
  await db.$disconnect();
})().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

