input.content:
// Cyrus Model Studio screenshots (run ON node-2 against `devhost dev`; WebGL via SwiftShader). Not part of the app.
//   devhost run -- node scripts/cyrus/modelstudio-shots.mjs   (env: BASE, TOKENS, OUT)
// Writes <OUT>/modelstudio-*.png and prints page errors + horizontal overflow per shot.
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch({ args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const path = (who, q = "") => `/dashboard/cyrus/${tok[who].buildId}/studio/model${q}`;

async function shot(name, who, url, { view = "desktop", theme = "dark", act } = {}) {
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} if (t === "light") document.documentElement.setAttribute("data-theme", "light"); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + url, { waitUntil: "networkidle", timeout: 300000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {}); }
  await page.waitForTimeout(2500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1200);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png` });
  console.log(`${name}.png`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}

// paint a short stroke across the middle of the main viewport (a real pointer drag through the app)
const stroke = async (page, dx = 120) => {
  const box = await page.locator("canvas.ms-cv").boundingBox();
  if (!box) throw new Error("no viewport canvas");
  const x = box.x + box.width / 2 - dx / 2, y = box.y + box.height / 2;
  await page.mouse.move(x, y); await page.mouse.down();
  for (let i = 1; i <= 12; i++) await page.mouse.move(x + (dx * i) / 12, y + Math.sin(i / 2) * 6);
  await page.mouse.up();
  await page.mouse.move(x + dx / 2, y - 4);
};
const click = (name) => async (page) => { await page.getByRole("button", { name, exact: true }).first().click(); };

await shot("modelstudio-desktop-dark-item", "all", path("all", "?model=glock_9mm"));
await shot("modelstudio-desktop-dark-item-thirdperson", "all", path("all", "?model=glock_9mm"), { act: async (p) => { await click("Third person")(p); } });
await shot("modelstudio-desktop-dark-creature", "all", path("all", "?model=banshee"), { act: async (p) => { await stroke(p); } });
await shot("modelstudio-desktop-dark-creature-uv", "all", path("all", "?model=banshee"), { act: async (p) => { await p.getByRole("button", { name: "UV", exact: true }).click(); await p.getByRole("tab", { name: /History/ }).click(); } });
await shot("modelstudio-desktop-dark-mesh-pbr", "all", path("all", "?model=sample_crate"), { act: async (p) => { await p.locator("select.ms-add").selectOption("roughness"); await stroke(p, 160); await p.getByRole("button", { name: "Rough", exact: true }).click(); } });
await shot("modelstudio-desktop-light-item", "all", path("all", "?model=glock_9mm"), { theme: "light", act: async (p) => { await click("First person")(p); } });
