// Cyrus Model Studio: the PLAYBACK CLOCK and scene-time API (game-agnostic hook points for animation and effects:
// creature walk cycles, a gun's cock / fire / reload, vehicle doors, explosions, fire, water...). Pure + client-safe,
// deterministic: time only moves when tick() / seek() say so (the viewport ticks it from requestAnimationFrame while
// playing; tests and the server preview set it directly), so "the scene at time t" is reproducible everywhere.
// Nothing here animates anything: providers (a rig's clips, an effect) plug in through ./pose.ts.
export type ClockState = { time: number; playing: boolean; speed: number; loop: boolean; start: number; end: number };
export type ClockListener = (s: Readonly<ClockState>) => void;

export class PlaybackClock {
  private s: ClockState;
  private subs = new Set<ClockListener>();
  constructor(o: Partial<ClockState> = {}) {
    this.s = { time: 0, playing: false, speed: 1, loop: true, start: 0, end: 1, ...o };
    this.s.time = this.clamp(this.s.time);
  }
  get state(): Readonly<ClockState> { return this.s; }
  /** current scene time in seconds */
  get time() { return this.s.time; }
  get duration() { return this.s.end - this.s.start; }
  private clamp(t: number) { return Math.max(this.s.start, Math.min(this.s.end, t)); }
  private emit() { for (const f of this.subs) f(this.s); }
  subscribe(f: ClockListener): () => void { this.subs.add(f); return () => this.subs.delete(f); }
  play() { if (!this.s.playing) { if (!this.s.loop && this.s.time >= this.s.end) this.s.time = this.s.start; this.s = { ...this.s, playing: true }; this.emit(); } }
  pause() { if (this.s.playing) { this.s = { ...this.s, playing: false }; this.emit(); } }
  /** scrub: jump to time t (clamped to the range) */
  seek(t: number) { this.s = { ...this.s, time: this.clamp(t) }; this.emit(); }
  setSpeed(k: number) { this.s = { ...this.s, speed: Math.max(-8, Math.min(8, k)) }; this.emit(); }
  setLoop(loop: boolean) { this.s = { ...this.s, loop }; this.emit(); }
  /** the playable range in seconds (a clip's length, an effect's duration) */
  setRange(start: number, end: number) { this.s = { ...this.s, start, end: Math.max(start, end) }; this.s.time = this.clamp(this.s.time); this.emit(); }
  /** advance by dt seconds of wall time (x speed) while playing; loops or stops at the ends */
  tick(dt: number) {
    if (!this.s.playing || !dt) return;
    const len = this.duration;
    let t = this.s.time + dt * this.s.speed;
    let playing = true;
    if (this.s.loop && len > 0) t = this.s.start + ((((t - this.s.start) % len) + len) % len);
    else if (t >= this.s.end || t <= this.s.start) { t = this.clamp(t); playing = false; }
    this.s = { ...this.s, time: t, playing };
    this.emit();
  }
}

