// Cyrus Model Studio: per-NODE transform overrides driven by scene time (the hook point animation and effects plug
// into; nothing here is game-specific). Pure + client-safe.
//   PoseProvider  anything that can say, at time t, how some scene parts (nodes) move: a creature clip, a gun's
//                 slide-back on reload, a vehicle door. Returns model-space matrices per part index.
//   evalPose      merges providers at time t (later providers compose on top of earlier ones)
//   posedScene    the scene with the overrides baked into its positions, so the PURE pick (./pick.ts) still hits
//                 the right texel while the model is posed or playing
// The viewport applies the same overrides to per-part meshes (components/cyrus/studios/model-viewport.ts
// setPartOverrides), and the server preview takes them in the request (preview/types.ts `overrides`, `time`), so the
// live view and the deterministic render agree at any time t.
import { apply4, mul4, type M4 } from "./math";
import type { ModelScene } from "./scene";

export type PartOverrides = Map<number, M4>;
export interface PoseProvider {
  readonly id: string;
  /** seconds; 0 = a static pose */
  readonly duration: number;
  poseAt(t: number, scene: ModelScene): PartOverrides;
}

/** Merge providers at time t: for a part several providers move, the matrices compose in provider order. */
export function evalPose(providers: readonly PoseProvider[], t: number, scene: ModelScene): PartOverrides {
  const out: PartOverrides = new Map();
  for (const p of providers) for (const [part, m] of p.poseAt(t, scene)) out.set(part, out.has(part) ? mul4(m, out.get(part)!) : m);
  return out;
}

/** A copy of the scene with each overridden part's triangles transformed (bounds recomputed). */
export function posedScene(s: ModelScene, o: PartOverrides): ModelScene {
  if (!o.size) return s;
  const pos = new Float32Array(s.pos);
  for (let t = 0; t < s.triCount; t++) {
    const m = o.get(s.part[t]);
    if (!m) continue;
    for (let k = 0; k < 3; k++) {
      const i = t * 9 + k * 3;
      const p = apply4(m, [pos[i], pos[i + 1], pos[i + 2]]);
      pos[i] = p[0]; pos[i + 1] = p[1]; pos[i + 2] = p[2];
    }
  }
  const min: [number, number, number] = [Infinity, Infinity, Infinity], max: [number, number, number] = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < pos.length; i += 3) for (let k = 0; k < 3; k++) { min[k] = Math.min(min[k], pos[i + k]); max[k] = Math.max(max[k], pos[i + k]); }
  return { ...s, pos, bounds: { min, max } };
}

/** Overrides as plain JSON (part index -> 16 numbers) for the server preview request. */
export const overridesJson = (o: PartOverrides): Record<string, number[]> => Object.fromEntries([...o].sort((a, b) => a[0] - b[0]).map(([k, m]) => [String(k), m.map((v) => Math.round(v * 1e6) / 1e6)]));

/** A provider from a function (tests, simple effects). */
export const poseProvider = (id: string, duration: number, f: (t: number, s: ModelScene) => PartOverrides): PoseProvider => ({ id, duration, poseAt: f });

