rep("""  // ------------------------------------------------------------------ render
  private resize() {""","""  // ------------------------------------------------------------------ scene time: overrides + overlays (animation / effects hooks)
  /** Pose providers (a rig clip, a gun's reload slide...) evaluated at the clock's time; replaces the list. */
  setPoseProviders(p: PoseProvider[]) { this.providers = p; const d = Math.max(0, ...p.map((x) => x.duration)); this.clock.setRange(0, d || 1); this.applyTime(); }
  /** Fixed per-node transform overrides (model space, part index -> matrix); empty map = rest pose. */
  setPartOverrides(o: PartOverrides) {
    for (const m of this.parts) { const k = m.userData.part as number; const x = o.get(k); if (x) m.matrix.fromArray(x); else m.matrix.identity(); m.matrixWorldNeedsUpdate = true; }
    this.requestRender();
  }
  /** Attach an overlay layer (particles, helper gizmos, decal previews) driven by the clock. Same id = replaced. */
  addOverlay(o: Overlay) { this.removeOverlay(o.id); const g = new this.T.Group(); g.name = o.id; this.overlayRoot.add(g); o.attach(this.T, g); this.overlays.set(o.id, { ...o, group: g } as Overlay & { group: THREE_NS.Group }); this.applyTime(); }
  removeOverlay(id: string) { const o = this.overlays.get(id) as (Overlay & { group?: THREE_NS.Group }) | undefined; if (!o) return; o.dispose?.(); if (o.group) this.overlayRoot.remove(o.group); this.overlays.delete(id); this.requestRender(); }
  /** The posed scene at the clock's time (for the pure pick while posed / playing). */
  posed(): ModelScene | null { return this.shown && this.providers.length ? posedScene(this.shown, evalPose(this.providers, this.clock.time, this.shown)) : this.shown; }
  private applyTime() {
    const t = this.clock.time;
    if (this.shown && this.providers.length) this.setPartOverrides(evalPose(this.providers, t, this.shown));
    for (const o of this.overlays.values()) o.update?.(t);
    this.requestRender();
  }
  /** Render the scene exactly at time t (pauses the clock): thumbnails, frame grabs, comparisons with the server preview. */
  renderAt(t: number): string { this.clock.pause(); this.clock.seek(t); this.applyTime(); return this.snapshot(); }

  // ------------------------------------------------------------------ render
  private resize() {""")
